# Cloudflare Workers Builds 배포 가이드 (Vite + Bun)

이 문서는 Cloudflare의 **Workers Builds (Unified UI)** 환경에서 Vite 프로젝트를 배포하는 방법을 설명합니다. 모든 프로젝트가 Worker로 관리되며, `npx wrangler deploy`가 배포 명령으로 사용됩니다.

## 1. 프로젝트 설정 (`wrangler.json`)

프로젝트 루트의 `wrangler.json`이 빌드 결과물(`dist`) 서빙 및 커스텀 도메인 바인딩을 담당합니다.

```json
{
  "name": "my-resume",
  "compatibility_date": "2026-01-07",
  "assets": {
    "directory": "dist",
    "not_found_handling": "single-page-application"
  },
  "routes": [
    {
      "pattern": "resume.shinkeonkim.com",
      "custom_domain": true
    }
  ],
  "observability": {
    "enabled": true
  }
}
```

- `assets.directory`: Vite 빌드 산출물(`dist`)을 그대로 서빙
- `assets.not_found_handling`: SPA fallback (`single-page-application`)
- `routes[].custom_domain`: `wrangler deploy` 시 커스텀 도메인을 자동으로 바인딩 (zone이 Cloudflare에 있어야 함)

## 2. variant 빌드 (`bun run build:site`)

import { globalIgnores } from 'eslint/config'
import { defineConfigWithVueTs, vueTsConfigs } from '@vue/eslint-config-typescript'
import pluginVue from 'eslint-plugin-vue'
import skipFormatting from '@vue/eslint-config-prettier/skip-formatting'

// To allow more languages other than `ts` in `.vue` files, uncomment the following lines:
// import { configureVueProject } from '@vue/eslint-config-typescript'
// configureVueProject({ scriptLangs: ['ts', 'tsx'] })
// More info at https://github.com/vuejs/eslint-config-typescript/#advanced-setup

export default defineConfigWithVueTs(
  {
    name: 'app/files-to-lint',
    files: ['**/*.{vue,ts,mts,tsx}'],
  },

globalIgnores(['**/dist/**', '**/dist-ssr/**', '**/coverage/**']),

...pluginVue.configs['flat/essential'],
  vueTsConfigs.recommended,

skipFormatting,
)

import { build } from 'vite'
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs'
import { resolve } from 'node:path'
import { validateResumeVariant } from '../src/resume/variants/schema'

const ROOT = resolve(__dirname, '..')
const VARIANTS_DIR = resolve(ROOT, 'src', 'resume', 'variants')
const CONFIG_FILE = resolve(ROOT, 'vite.config.ts')
const OUT_BASE = resolve(ROOT, 'dist')
const OUT_VARIANT = resolve(ROOT, '.variant-build')

interface VariantEntry {
  id: string
}

/**
 * public variant만 대상으로, 유효하지 않은 variant.json은 건너뛰되
 * public으로 선언된 variant가 잘못된 경우에는 배포 누락을 방지하기 위해 실패시킨다.
 */
function listPublicVariants(): VariantEntry[] {
  if (!existsSync(VARIANTS_DIR)) return []
  const entries: VariantEntry[] = []
  for (const id of readdirSync(VARIANTS_DIR)) {
    const dir = resolve(VARIANTS_DIR, id)
    if (!statSync(dir).isDirectory()) continue
    const file = resolve(dir, 'variant.json')
    if (!existsSync(file)) continue

let raw: unknown
    try {
      raw = JSON.parse(readFileSync(file, 'utf-8'))
    } catch (err) {
      console.warn(`[build-site] ${id}: variant.json 파싱 실패 — skip (${(err as Error).message})`)
      continue
    }

const rawVisibility = (raw as { meta?: { visibility?: string } })?.meta?.visibility
    const result = validateResumeVariant(raw)
    if (!result.ok) {
      const message = `[build-site] ${id}: schema 오류\n  - ${result.errors.join('\n  - ')}`
      if (rawVisibility === 'public') {
        throw new Error(message)
      }
      console.warn(message)
      continue
    }
    if (result.variant.meta.visibility === 'public') {
      entries.push({ id: result.variant.id })
    }
  }
  return entries
}

async function main(): Promise<void> {
  // 1. base build (dist)
  delete process.env.VARIANT_ID
  await build({ configFile: CONFIG_FILE })
  console.log('[build-site] base build 완료 -> dist/')

// 2. public variant build + dist/v/<id>/ 병합
  const variants = listPublicVariants()
  console.log(
    `[build-site] public variant: ${variants.length > 0 ? variants.map((v) => v.id).join(', ') : '(없음)'}`,
  )
  for (const { id } of variants) {
    process.env.VARIANT_ID = id
    const variantOut = resolve(OUT_VARIANT, id)
    rmSync(variantOut, { recursive: true, force: true })
    await build({ configFile: CONFIG_FILE, outDir: variantOut })
    const target = resolve(OUT_BASE, 'v', id)
    mkdirSync(target, { recursive: true })
    cpSync(variantOut, target, { recursive: true })
    console.log(`[build-site] variant ${id} 병합 완료 -> dist/v/${id}/`)
  }
  rmSync(OUT_VARIANT, { recursive: true, force: true })
  console.log('[build-site] 완료')
}

main().catch((err) => {
  console.error('[build-site] 실패:', err)
  process.exit(1)
})

function parseCli(argv: string[]): CliOptions {
  const opts: CliOptions = {
    outPath: null,
    useStdout: false,
    minify: false,
    locale: 'both',
    showHelp: false,
  }
  for (const arg of argv) {
    if (arg === '--help' || arg === '-h') opts.showHelp = true
    else if (arg === '--stdout') opts.useStdout = true
    else if (arg === '--minify') opts.minify = true
    else if (arg.startsWith('--out=')) opts.outPath = arg.slice('--out='.length)
    else if (arg.startsWith('--locale=')) {
      const raw = arg.slice('--locale='.length)
      if (raw === 'ko' || raw === 'en' || raw === 'both') opts.locale = raw
      else {
        process.stderr.write(`[export-resume-json] Unknown --locale value: ${raw}\n`)
        process.exit(2)
      }
    } else {
      process.stderr.write(`[export-resume-json] Unknown argument: ${arg}\n`)
      process.exit(2)
    }
  }
  return opts
}

function printHelp(): void {
  process.stdout.write(
    [
      'Usage: bun scripts/export-resume-json.ts [options]',
      '',
      'Options:',
      '  --out=<path>       Write JSON to <path> (default: ./resume-data.json)',
      '  --stdout           Write JSON to stdout instead of a file',
      '  --minify           Emit compact JSON (default: 2-space pretty print)',
      '  --locale=<ko|en|both>  Restrict locale-scoped fields (default: both)',
      '  -h, --help         Show this help',
      '',
    ].join('\n'),
  )
}

// ---------- Locale filtering ---------------------------------------------

type Localized<T> = Record<Locale, T>

function pickLocales<T>(data: Localized<T>, locale: Locale | 'both'): Partial<Localized<T>> {
  if (locale === 'both') return data
  return { [locale]: data[locale] } as Partial<Localized<T>>
}

// ---------- Snapshot assembly --------------------------------------------

function buildSnapshot(locale: Locale | 'both') {
  const experiences = experienceEntities.map((e) => ({
    id: e.id,
    company: pickLocales(e.company, locale),
    roleTitle: pickLocales(e.roleTitle, locale),
    period: e.period,
    techStack: e.techStack ?? [],
    details: pickLocales(e.details, locale),
  }))

const projects = projectEntities.map((p) => ({
    id: p.id,
    title: pickLocales(p.title, locale),
    period: p.period,
    techStack: p.techStack,
    details: pickLocales(p.details, locale),
    links: p.links ?? [],
  }))

return {
    schema: 'ResumeSnapshot.v1',
    generatedAt: new Date().toISOString(),
    source: {
      note: 'Auto-generated from src/resume/base/**/*.ts and src/composables/useLocale.ts. Do not edit by hand.',
      regenerate: 'bun scripts/export-resume-json.ts   # or: npx tsx scripts/export-resume-json.ts',
    },
    localeFilter: locale,
    profile: {
      text: pickLocales(profileText, locale),
      contact: profileContact,
    },
    labels: pickLocales(messages, locale),
    introductions: pickLocales(introductions, locale),
    timeline: {
      range: {
        minDate: timelineRange.minDate.toISOString(),
        maxDate: timelineRange.maxDate.toISOString(),
      },
      items: pickLocales(timelineItems, locale),
    },
    educations: pickLocales(educations, locale),
    skills: pickLocales(skills, locale),
    experiences,
    projects,
    activities: pickLocales(activities, locale),
    awards: pickLocales(awards, locale),
    certificates: pickLocales(certificates, locale),
    stats,
  }
}

// ---------- Main ---------------------------------------------------------

function main(): void {
  const opts = parseCli(process.argv.slice(2))
  if (opts.showHelp) {
    printHelp()
    return
  }

const snapshot = buildSnapshot(opts.locale)
  const json = opts.minify ? JSON.stringify(snapshot) : JSON.stringify(snapshot, null, 2)

if (opts.useStdout) {
    process.stdout.write(json)
    if (!opts.minify) process.stdout.write('\n')
    return
  }

const projectRoot = resolve(scriptDir, '..')
  const targetPath = opts.outPath
    ? resolve(process.cwd(), opts.outPath)
    : resolve(projectRoot, 'resume-data.json')

mkdirSync(dirname(targetPath), { recursive: true })
  writeFileSync(targetPath, json + (opts.minify ? '' : '\n'), 'utf-8')

import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { resolve, isAbsolute } from 'node:path'
import { validateResumeVariant, type ResumeVariantV1 } from '../src/resume/variants/schema'
import { experienceIds } from '../src/resume/base/experiences'
import { projectIds } from '../src/resume/base/projects'

const VARIANTS_DIR = resolve(__dirname, '..', 'src', 'resume', 'variants')

function fail(message: string): never {
  console.error(`[import-variant] ${message}`)
  process.exit(1)
}

function resolveBaseTargetIds(variant: ResumeVariantV1): string[] {
  const issues: string[] = []
  const expSet = new Set(experienceIds)
  const projSet = new Set(projectIds)
  const checkList = (
    field: string,
    ids: readonly string[] | undefined,
    targetSet: Set<string>,
  ) => {
    if (!ids) return
    for (const id of ids) {
      if (!targetSet.has(id)) issues.push(`${field}: unknown id "${id}"`)
    }
  }
  checkList('overrides.include.experienceIds', variant.overrides.include?.experienceIds, expSet)
  checkList('overrides.order.experienceIds', variant.overrides.order?.experienceIds, expSet)
  checkList('overrides.include.projectIds', variant.overrides.include?.projectIds, projSet)
  checkList('overrides.order.projectIds', variant.overrides.order?.projectIds, projSet)
  for (const cb of variant.overrides.customBullets ?? []) {
    const set = cb.targetType === 'experienceRole' ? expSet : projSet
    if (!set.has(cb.targetId)) {
      issues.push(`overrides.customBullets[${cb.targetType}:${cb.targetId}]: unknown base id`)
    }
  }
  return issues
}

const inputPath = process.argv[2]
if (!inputPath) fail('usage: bun run import-variant <path-to-variant.json>')
const absolute = isAbsolute(inputPath) ? inputPath : resolve(process.cwd(), inputPath)
if (!existsSync(absolute)) fail(`file not found: ${absolute}`)

let raw: unknown
try {
  raw = JSON.parse(readFileSync(absolute, 'utf-8'))
} catch (err) {
  fail(`invalid JSON: ${(err as Error).message}`)
}

const result = validateResumeVariant(raw)
if (!result.ok) fail(`schema errors:\n  - ${result.errors.join('\n  - ')}`)
const variant = result.variant

const baseIssues = resolveBaseTargetIds(variant)
if (baseIssues.length) fail(`base-id references invalid:\n  - ${baseIssues.join('\n  - ')}`)

const forceFlag = process.argv.includes('--force')
const visibilityFlag = process.argv.find((a) => a.startsWith('--visibility='))?.split('=')[1]
if (visibilityFlag === 'public' || visibilityFlag === 'private' || visibilityFlag === 'draft') {
  variant.meta.visibility = visibilityFlag
} else if (variant.meta.source === 'jd-helper' && variant.meta.visibility === 'public' && !forceFlag) {
  console.warn(
    `[import-variant] jd-helper source defaulted public → forced to draft (use --visibility=public --force to override)`,
  )
  variant.meta.visibility = 'draft'
}

const outDir = resolve(VARIANTS_DIR, variant.id)
mkdirSync(outDir, { recursive: true })
const outFile = resolve(outDir, 'variant.json')
writeFileSync(outFile, JSON.stringify(variant, null, 2) + '\n', 'utf-8')

import { experienceEntities } from '../src/resume/base/experiences'
import { projectEntities } from '../src/resume/base/projects'

const args = process.argv.slice(2)
const format = args.find((a) => a.startsWith('--format='))?.split('=')[1] ?? 'json'

const payload = {
  schema: 'ResumeBaseIds.v1',
  experiences: experienceEntities.map((e) => ({
    id: e.id,
    company: e.company,
    roleTitle: e.roleTitle,
    period: e.period,
  })),
  projects: projectEntities.map((p) => ({
    id: p.id,
    title: p.title,
    period: p.period,
  })),
}

if (format === 'ids') {
  process.stdout.write(
    [...payload.experiences.map((e) => e.id), ...payload.projects.map((p) => p.id)].join('\n'),
  )
} else {
  process.stdout.write(JSON.stringify(payload, null, 2))
}

function listVariants(): Entry[] {
  if (!existsSync(VARIANTS_DIR)) return []
  const dirs = readdirSync(VARIANTS_DIR).filter((name) => {
    const p = resolve(VARIANTS_DIR, name)
    return statSync(p).isDirectory()
  })
  const entries: Entry[] = []
  for (const id of dirs) {
    const file = resolve(VARIANTS_DIR, id, 'variant.json')
    if (!existsSync(file)) continue
    let raw: unknown
    try {
      raw = JSON.parse(readFileSync(file, 'utf-8'))
    } catch (err) {
      console.error(`[list-variants] ${id}: invalid JSON — ${(err as Error).message}`)
      continue
    }
    const result = validateResumeVariant(raw)
    if (!result.ok) {
      console.error(`[list-variants] ${id}: schema errors:\n  - ${result.errors.join('\n  - ')}`)
      continue
    }
    if (result.variant.id !== id) {
      console.error(`[list-variants] dir name "${id}" must match variant.id "${result.variant.id}"`)
      continue
    }
    entries.push({
      id: result.variant.id,
      label: result.variant.meta.label,
      locale: result.variant.meta.locale,
      visibility: result.variant.meta.visibility,
      path: `v/${result.variant.id}/`,
    })
  }
  return entries
}

const args = process.argv.slice(2)
const visibilityFilter = args.find((a) => a.startsWith('--visibility='))?.split('=')[1] ?? null
const format = args.find((a) => a.startsWith('--format='))?.split('=')[1] ?? 'json'

const all = listVariants()
const filtered = visibilityFilter
  ? all.filter((e) => visibilityFilter.split(',').includes(e.visibility))
  : all

if (format === 'matrix') {
  process.stdout.write(JSON.stringify({ include: filtered.map((e) => ({ variant_id: e.id })) }))
} else if (format === 'ids') {
  process.stdout.write(filtered.map((e) => e.id).join('\n'))
} else {
  process.stdout.write(JSON.stringify(filtered, null, 2))
}

.resume-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.print-controls {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
}

.a4-page {
  width: var(--a4-width);
  min-height: var(--a4-min-height);
  background: white;
  padding: 0; /* Layout handled inside ResumeContent */
  margin: 0 auto;
  box-shadow:
    0 0.5em 1em -0.125em rgba(10, 10, 10, 0.1),
    0 0px 0 1px rgba(10, 10, 10, 0.02);
}

@media screen and (max-width: 768px) {
  .a4-page {
    width: 100% !important;
    max-width: 100% !important;
    box-shadow: none;
    border-radius: 0;
  }
}

@media print {
  .a4-page {
    box-shadow: none;
    width: 100%;
    min-height: auto;
  }
}
</style>

@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css');
@import 'bulma/css/bulma.css';

*, *::before, *::after {
  box-sizing: border-box;
  overflow-wrap: break-word; /* Ensure text wraps */
  word-wrap: break-word;
}

:root {
  --a4-width: 210mm;
  --a4-min-height: 297mm;
  --bulma-text-strong: #0a0a0a; /* Force strong text to be black/very dark */
  --bulma-size-small: 0.82rem;
  --resume-bg: #525659;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  overflow-x: hidden;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--resume-bg);
  color: #000;
  font-family:
    'Pretendard',
    -apple-system,
    BlinkMacSystemFont,
    system-ui,
    Roboto,
    'Helvetica Neue',
    'Segoe UI',
    'Apple SD Gothic Neo',
    'Noto Sans KR',
    'Malgun Gothic',
    'Apple Color Emoji',
    'Segoe UI Emoji',
    'Segoe UI Symbol',
    sans-serif;
}

#app {
  display: block; /* Simpler than flex for root relative positioning */
  min-height: 100vh;
  padding: 2rem 0;
  width: 100%;
}

@media screen and (max-width: 768px) {
  #app {
    padding: 0;
    background-color: white;
  }
}

/* Override Bulma strong text explicitly if var doesn't catch all */
strong {
  color: #0a0a0a !important;
  font-weight: 600;
}

/* Print controls */
.print-only {
  display: none;
}

@page {
  size: A4;
  margin: 12mm 17mm; /* Global margin for EVERY page */
}

@media print {
  html,
  body {
    overflow: visible !important;
    height: auto !important;
  }

body {
    background-color: white;
    width: 210mm;
    /* height: 297mm;  Removing fixed height allows natural paging */
  }
  #app {
    padding: 0;
    display: block;
    width: 210mm;
    margin: 0 auto;
    overflow: visible !important;
    height: auto !important;
  }
  .resume-content {
    padding: 0 !important; /* Managed by @page margins now */
    width: 100%;
    max-width: 210mm;
    box-shadow: none !important;
  }

.no-print {
    display: none !important;
  }
  .print-only {
    display: block;
  }

/* Reset colors for print */
  .title,
  .subtitle,
  .content,
  .has-text-grey,
  .has-text-grey-light,
  .has-text-grey-dark {
    color: #000 !important;
  }

/* ensure strong remains black in print */
  strong {
    color: #000 !important;
  }

/* Ensure links are black */
  a {
    color: #000 !important;
    text-decoration: none !important;
  }

.page-break {
    break-before: page;
    page-break-before: always; /* Legacy support */
  }
}

