  color: #b5b5b5;
  font-size: 0.72rem;
}

.plain-subs {
  margin: 0.05rem 0 0.05rem 1rem !important;
  padding-top: 0 !important;
  list-style: circle;
  line-height: 1.3;
  font-size: 0.82rem;
}

