/**
 * Cloudflare Workers 정적 에셋 개별 파일 한도 (wrangler deploy 시 실패함)
 * @see https://developers.cloudflare.com/workers/platform/limits/
 */
const MAX_ASSET_BYTES = 25 * 1024 * 1024 // 25 MiB

/** 이 크기 이상의 PDF만 압축 대상으로 처리 (한도 대비 여유 유지) */
const COMPRESS_THRESHOLD_BYTES = 20 * 1024 * 1024 // 20 MiB

/** 기본/fallback 다운샘플 해상도 (dpi) */
const DEFAULT_DPI = 150
const FALLBACK_DPI = 100

const ROOT = resolve(__dirname, '..')
const PUBLIC_DOCS = resolve(ROOT, 'public', 'docs')
const ORIGINALS_DIR = resolve(ROOT, 'docs-originals')

const GB = 1024 * 1024 * 1024
const MB = 1024 * 1024

function formatBytes(bytes: number): string {
  if (bytes >= GB) return `${(bytes / GB).toFixed(2)} GiB`
  if (bytes >= MB) return `${(bytes / MB).toFixed(2)} MiB`
  return `${(bytes / 1024).toFixed(1)} KiB`
}

function checkTool(cmd: string, args: string[], hint: string): boolean {
  const res = spawnSync(cmd, args, { stdio: 'pipe' })
  if (res.status !== 0) {
    console.error(`[compress-docs] '${cmd}'를 찾을 수 없습니다. ${hint}`)
  }
  return res.status === 0
}

/** 페이지 수 조회 (poppler) */
function pageCount(pdfPath: string): number | null {
  const res = spawnSync('pdfinfo', [pdfPath], { stdio: 'pipe' })
  if (res.status !== 0) return null
  const match = res.stdout.toString().match(/^Pages:\s+(\d+)/m)
  return match ? Number(match[1]) : null
}

/**
 * 이미지 드롭 검증 (poppler pdfimages 기반).
 * PDFSETTINGS 계열 압축의 대표 결함은 ICC+smask 이미지를 통째로 버려
 * 페이지가 공백이 되는 것. 페이지별 "image" 타입 객체 수를 원본/압축본에서
 * 비교해, 원본에 이미지가 있는데 압축본에 없으면 해당 페이지 번호를 반환한다.
 * 실패(도구 부재 등) 시 null 반환 (검증 생략).
 */
function findBlankPages(origPdf: string, compPdf: string): number[] | null {
  function pageImageCounts(pdf: string): Map<number, number> | null {
    const res = spawnSync('pdfimages', ['-list', pdf], { stdio: 'pipe' })
    if (res.status !== 0) return null
    const counts = new Map<number, number>()
    // 출력 형식: "page   num  type   width height ..." — 첫 컬럼이 페이지 번호
    for (const line of res.stdout.toString().split('\n')) {
      const m = line.match(/^\s*(\d+)\s+\d+\s+image\b/)
      if (m) {
        const pg = Number(m[1])
        counts.set(pg, (counts.get(pg) ?? 0) + 1)
      }
    }
    return counts
  }

const orig = pageImageCounts(origPdf)
  const comp = pageImageCounts(compPdf)
  if (orig === null || comp === null) return null

const blank: number[] = []
  for (const [pg, origCount] of orig) {
    if (origCount > 0 && (comp.get(pg) ?? 0) === 0) blank.push(pg)
  }
  return blank
}

/** 압축 대상 PDF 목록: docs-originals/ 우선, 없으면 public/docs/ 사용 */
function listPdfSources(): { name: string; path: string; size: number }[] {
  const sourceDir = existsSync(ORIGINALS_DIR) ? ORIGINALS_DIR : PUBLIC_DOCS
  return readdirSync(sourceDir)
    .filter((name) => extname(name).toLowerCase() === '.pdf')
    .map((name) => {
      const path = join(sourceDir, name)
      return { name, path, size: statSync(path).size }
    })
    .sort((a, b) => b.size - a.size)
}

function main(): void {
  if (!checkTool('gs', ['--version'], '설치 후 다시 실행하세요. macOS: brew install ghostscript')) process.exit(1)
  // poppler 계열 도구는 --version 대신 -v 사용
  if (!checkTool('pdfinfo', ['-v'], '설치 후 다시 실행하세요. macOS: brew install poppler')) process.exit(1)

const sources = listPdfSources()
  if (sources.length === 0) {
    console.error(`[compress-docs] ${PUBLIC_DOCS}에 PDF가 없습니다.`)
    process.exit(1)
  }

let failed = false
  let compressedCount = 0
  for (const { name, path, size } of sources) {
    if (size <= COMPRESS_THRESHOLD_BYTES) {
      console.log(`[compress-docs] skip ${name} (${formatBytes(size)} — 압축 불필요)`)
      continue
    }

console.log(`[compress-docs] 압축 시작: ${name} (${formatBytes(size)})`)
    const tmp = join(PUBLIC_DOCS, `${name}.tmp`)
    const out = join(PUBLIC_DOCS, name)

// 원본 페이지 수 기록 (사후 검증 기준)
    const beforePages = pageCount(path)
    if (beforePages === null) {
      console.error(`[compress-docs] ${name} 페이지 수를 확인할 수 없습니다.`)
      failed = true
      continue
    }

let ok = false
    let dpiUsed = DEFAULT_DPI
    for (const dpi of [DEFAULT_DPI, FALLBACK_DPI]) {
      rmSync(tmp, { force: true })
      if (!compressPdf(path, tmp, dpi)) {
        console.error(`[compress-docs] ${name} 압축 실패 (${dpi}dpi)`)
        continue
      }
      const tmpSize = statSync(tmp).size
      if (tmpSize >= MAX_ASSET_BYTES) {
        console.log(`[compress-docs] ${dpi}dpi 결과 ${formatBytes(tmpSize)} — 한도 초과, 다음 단계 시도`)
        continue
      }
      const afterPages = pageCount(tmp)
      if (afterPages !== beforePages) {
        console.error(
          `[compress-docs] ${name} 페이지 수 불일치 (${beforePages} → ${afterPages ?? '?'}) — ${dpi}dpi 실패`,
        )
        continue
      }
      const blankPages = findBlankPages(path, tmp)
      if (blankPages === null) {
        console.warn('[compress-docs] 빈 페이지 검증 생략 (python3/PIL 없음)')
      } else if (blankPages.length > 0) {
        console.error(
          `[compress-docs] ${name} 렌더링 검증 실패: ${blankPages.length}개 페이지가 공백 (${blankPages.join(', ')}) — 이미지 드롭 결함`,
        )
        continue
      }
      dpiUsed = dpi
      ok = true
      break
    }

if (!ok) {
      console.error(
        `[compress-docs] ${name} 압축 실패: 모든 해상도가 한도(25 MiB)·페이지 수·빈 페이지 검증을 통과하지 못했습니다. 원본 PDF를 분할/가공해야 합니다.`,
      )
      rmSync(tmp, { force: true })
      failed = true
      continue
    }

const finalSize = statSync(tmp).size
    renameSync(tmp, out)
    compressedCount += 1
    console.log(
      `[compress-docs] 완료: ${name} ${formatBytes(size)} → ${formatBytes(finalSize)} (${dpiUsed}dpi, ` +
        `${Math.round((1 - finalSize / size) * 100)}% 감소, ${beforePages}쪽)`,
    )
  }

if (failed) {
    console.error('[compress-docs] 일부 PDF 압축에 실패했습니다.')
    process.exit(1)
  }
  console.log(`[compress-docs] 완료 — ${compressedCount}개 압축`)
}

main()

def load_projects() -> list[tuple[str, list[dict]]]:
    out: list[tuple[str, list[dict]]] = []
    if not PROJECTS_DIR.exists():
        return out
    for path in sorted(PROJECTS_DIR.glob("*.ts")):
        if path.name == "index.ts":
            continue
        raw = path.read_text(encoding="utf-8")
        slug_match = re.search(r"slug:\s*['\"]([^'\"]+)['\"]", raw)
        if not slug_match:
            continue
        slug = slug_match.group(1)
        urls = extract_github_links(raw)
        repos = [{"url": u, "track": True} for u in urls]
        if not repos:
            continue
        out.append((slug, repos))
    return out

def load_json_file(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}

def save_json_file(path: Path, data: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def is_fresh(timestamp: str | None, max_age_hours: int) -> bool:
    if not isinstance(timestamp, str):
        return False
    try:
        ts = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
    except ValueError:
        return False
    age = datetime.now(timezone.utc) - ts
    return age.total_seconds() < max_age_hours * 3600

def github_headers(token: str | None) -> dict:
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "shinkeonkim-portfolio-stats-fetch",
    }
    if token:
        headers["Authorization"] = f"Bearer {token}"
    return headers

def _retry_after(res: httpx.Response, default: float) -> float:
    val = res.headers.get("retry-after")
    if val:
        try:
            return float(val)
        except ValueError:
            pass
    reset = res.headers.get("x-ratelimit-reset")
    if reset:
        try:
            return max(default, float(reset) - time.time())
        except ValueError:
            pass
    return default

def gh_get_cached(
    client: httpx.Client,
    etags: dict,
    key: str,
    url: str,
    *,
    params: dict | None = None,
    has_fallback: bool = True,
) -> httpx.Response:
    extra = {}
    if has_fallback and key in etags:
        extra["If-None-Match"] = etags[key]
    res = gh_get(client, url, params=params, extra_headers=extra or None)
    if res.status_code == 304 and not has_fallback:
        etags.pop(key, None)
        res = gh_get(client, url, params=params)
    if res.status_code == 200:
        new_etag = res.headers.get("etag")
        if new_etag:
            etags[key] = new_etag
    return res

def parse_link_last_page(header: str | None) -> int:
    if not header:
        return 0
    for chunk in header.split(","):
        if 'rel="last"' in chunk:
            m = re.search(r"[?&]page=(\d+)", chunk)
            if m:
                return int(m.group(1))
    return 0

def fetch_stats_endpoint(
    client: httpx.Client,
    url: str,
    *,
    retries: int = 3,
    delay: float = 5.0,
) -> object | None:
    for attempt in range(retries):
        res = gh_get(client, url)
        if res.status_code == 200:
            try:
                return res.json()
            except ValueError:
                return None
        if res.status_code == 202 and attempt < retries - 1:
            time.sleep(delay)
            continue
        return None
    return None

def warmup_stats(
    client: httpx.Client,
    targets: list[tuple[str, str]],
    pacing_seconds: float = WARMUP_PACING_SECONDS,
) -> None:
    for owner, repo in targets:
        for endpoint in ("stats/contributors", "stats/commit_activity"):
            try:
                client.get(f"{GITHUB_API}/repos/{owner}/{repo}/{endpoint}", timeout=15.0)
            except httpx.HTTPError:
                pass
            if pacing_seconds > 0:
                time.sleep(pacing_seconds)

def fetch_languages(
    client: httpx.Client,
    etags: dict,
    owner: str,
    repo: str,
    existing: dict | None,
) -> list[dict]:
    key = f"{owner}/{repo}:languages"
    res = gh_get_cached(
        client,
        etags,
        key,
        f"{GITHUB_API}/repos/{owner}/{repo}/languages",
        has_fallback=existing is not None,
    )
    if res.status_code == 304 and existing:
        return existing.get("languages") or []
    if res.status_code != 200:
        return (existing or {}).get("languages") or []
    raw = res.json() if isinstance(res.json(), dict) else {}
    total = sum(raw.values())
    if total == 0:
        return []
    out = [
        {"name": name, "bytes": value, "percent": round(value / total * 100)}
        for name, value in sorted(raw.items(), key=lambda kv: -kv[1])
    ]
    return out

def fetch_contributor_stats(
    client: httpx.Client,
    owner: str,
    repo: str,
    username: str,
    existing: dict | None,
) -> tuple[int, int, str | None, bool]:
    contrib_data = fetch_stats_endpoint(
        client, f"{GITHUB_API}/repos/{owner}/{repo}/stats/contributors"
    )
    if not isinstance(contrib_data, list):
        if existing is not None:
            return (
                int(existing.get("additions", 0) or 0),
                int(existing.get("deletions", 0) or 0),
                existing.get("firstCommitDate"),
                False,
            )
        return 0, 0, None, False
    additions = 0
    deletions = 0
    first_commit_date: str | None = None
    for c in contrib_data:
        if c.get("author", {}).get("login", "").lower() != username.lower():
            continue
        for w in c.get("weeks", []):
            additions += w.get("a", 0)
            deletions += w.get("d", 0)
            if w.get("c", 0) > 0:
                w_date = datetime.fromtimestamp(w["w"], tz=timezone.utc).isoformat()
                if first_commit_date is None or w_date < first_commit_date:
                    first_commit_date = w_date
    return additions, deletions, first_commit_date, True

project_plan: list[tuple[str, list[dict], dict | None]] = []
    for slug, repos in projects:
        existing = cache.get(slug)
        if not force and existing and is_fresh(existing.get("fetchedAt"), max_age_hours):
            typer.echo(f"skip (fresh): {slug}")
            continue
        project_plan.append((slug, repos, existing))

if not project_plan:
        typer.echo("nothing to refresh")
        return

warmup_targets: list[tuple[str, str]] = []
    for slug, repos, existing in project_plan:
        existing_by_key = {
            (s.get("owner"), s.get("repo")): s
            for s in (existing or {}).get("repos", [])
        }
        for r in repos:
            parsed = parse_repo_url(r["url"])
            if not parsed:
                continue
            owner, repo = parsed
            existing_stat = existing_by_key.get((owner, repo))
            needs_stats = (
                force
                or force_stats
                or existing_stat is None
                or not is_fresh(
                    existing_stat.get("_statsFetchedAt"), max_age_stats_hours
                )
            )
            if needs_stats:
                warmup_targets.append((owner, repo))

for slug, repos, existing in project_plan:
            typer.echo(f"refresh: {slug}")
            existing_by_key = {
                (s.get("owner"), s.get("repo")): s
                for s in (existing or {}).get("repos", [])
            }
            repo_stats: list[dict] = []
            for r in repos:
                parsed = parse_repo_url(r["url"])
                if not parsed:
                    typer.echo(f"  invalid url: {r['url']}", err=True)
                    continue
                owner, repo = parsed
                existing_stat = existing_by_key.get((owner, repo))
                try:
                    stat, status = fetch_repo_stats(
                        client,
                        etags,
                        owner,
                        repo,
                        username,
                        existing_stat,
                        max_age_stats_hours=max_age_stats_hours,
                        force_stats=force or force_stats,
                    )
                    repo_stats.append(stat)
                    typer.echo(
                        f"  {owner}/{repo}: my {stat['myCommits']} / total "
                        f"{stat['totalCommits']} [{status}]"
                    )
                except httpx.HTTPStatusError as e:
                    body = e.response.text[:120]
                    typer.echo(
                        f"  {owner}/{repo}: HTTP {e.response.status_code} {body}",
                        err=True,
                    )
                    fallback = existing_stat or {
                        "url": r["url"],
                        "owner": owner,
                        "repo": repo,
                        "totalCommits": 0,
                        "myCommits": 0,
                    }
                    repo_stats.append(
                        {**fallback, "error": f"HTTP {e.response.status_code}"}
                    )
            cache[slug] = {
                "repos": repo_stats,
                "fetchedAt": datetime.now(timezone.utc).isoformat(),
            }
            save_json_file(CACHE_PATH, cache)
            save_json_file(ETAG_PATH, etags)

typer.echo(f"wrote {CACHE_PATH.relative_to(REPO_ROOT)}")

if __name__ == "__main__":
    sys.exit(typer.run(main) or 0)

const invalidContributionFixtures: readonly { slug: string; value: unknown }[] = [
  { slug: 'fixture-missing-title', value: { summary: 'summary' } },
  { slug: 'fixture-empty-summary', value: { title: 'Title', summary: ' ' } },
  {
    slug: 'fixture-invalid-items',
    value: { title: 'Title', summary: 'summary', items: ['valid', 42] },
  },
]

function assertContributionShape(
  value: unknown,
  slug: string,
  index = 0,
): asserts value is ProjectContribution {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`[${slug}] contribution ${index} must be an object`)
  }

const contribution = value as Record<string, unknown>
  if (typeof contribution.title !== 'string' || !contribution.title.trim()) {
    throw new Error(`[${slug}] contribution ${index} requires a title`)
  }
  if (typeof contribution.summary !== 'string' || !contribution.summary.trim()) {
    throw new Error(`[${slug}] contribution ${index} requires a summary`)
  }
  if (
    contribution.items !== undefined &&
    (!Array.isArray(contribution.items) ||
      contribution.items.some((item) => typeof item !== 'string' || !item.trim()))
  ) {
    throw new Error(`[${slug}] contribution ${index} items must be non-empty strings`)
  }
}

