type Area = "overview" | "company" | "people" | "resume" | "interview" | "technical" | "topics"
type Posting = {
  id: string
  title: string
  companyName: string
  teamName: string | null
  versionNumber: number | null
  currentVersionId: string | null
}
type Application = { id: string; jobPostId: string; stageName: string; appliedAt: string | null }
type Interview = { id: string; scheduledAt: string; kind: string }

const props = defineProps<{ area: Area }>()
const route = useRoute()
const settings = useSettingsStore()
const copy = (key: string) => translate(settings.locale, `workspace.${key}`)
const controller = new AbortController()
const postings = ref<Posting[]>([])
const applications = ref<Application[]>([])
const interviews = ref<Interview[]>([])
const postId = computed(() => String(route.params["postId"] ?? ""))
const posting = computed(() => postings.value.find((item) => item.id === postId.value) ?? null)
const application = computed(
  () => applications.value.find((item) => item.jobPostId === postId.value) ?? null
)
const areas: readonly Area[] = [
  "overview",
  "company",
  "people",
  "resume",
  "interview",
  "technical",
  "topics"
]
const workflow = computed(
  () =>
    (
      ({
        resume: "resume_feedback",
        interview: "interview_prep",
        technical: "technical_prep",
        topics: "topic_answers"
      }) as const
    )[props.area as "resume" | "interview" | "technical" | "topics"]
)

const load = async () => {
  const [postResponse, applicationResponse] = await Promise.all([
    fetch("/api/postings", { signal: controller.signal }),
    fetch("/api/applications", { signal: controller.signal })
  ])
  postings.value = ((await postResponse.json()) as { postings: Posting[] }).postings
  applications.value = (
    (await applicationResponse.json()) as { applications: Application[] }
  ).applications
  if (application.value) {
    const response = await fetch(`/api/applications/${application.value.id}/history`, {
      signal: controller.signal
    })
    if (response.ok)
      interviews.value = ((await response.json()) as { interviews: Interview[] }).interviews
  }
}
onMounted(() => void load().catch(() => toast.error(copy("failed"))))
onBeforeUnmount(() => controller.abort())
</script>

const props = withDefaults(
  defineProps<{
    workflowPreset?: Workflow
    embedded?: boolean
  }>(),
  { workflowPreset: "cover_letter", embedded: false }
)

const route = useRoute()
const settings = useSettingsStore()
const copy = (key: string) => translate(settings.locale, `preparation.${key}`)
const controller = new AbortController()
const postings = ref<Posting[]>([])
const documents = ref<Document[]>([])
const providers = ref<Provider[]>([])
const workflow = ref<Workflow>(props.workflowPreset)
const providerId = ref("")
const documentVersionId = ref("none")
const practiceAnswer = ref("")
const generationKey = ref(crypto.randomUUID())
const preview = ref<{ manifest: Manifest; authorizationToken: string } | null>(null)
const revision = ref<Revision | null>(null)
const running = ref(false)
const posting = computed(() => postings.value.find((item) => item.id === route.params["postId"]))
const inputs = computed(() => {
  const values: Array<Record<string, string>> = []
  if (posting.value?.currentVersionId)
    values.push({ kind: "job_post_version", jobPostVersionId: posting.value.currentVersionId })
  if (documentVersionId.value !== "none")
    values.push({ kind: "document_version", documentVersionId: documentVersionId.value })
  return values
})
const workflowLabels: Array<[Workflow, string]> = [
  ["cover_letter", "coverLetter"],
  ["resume_feedback", "resumeFeedback"],
  ["interview_prep", "interviewPrep"],
  ["technical_prep", "technicalPrep"],
  ["topic_answers", "topicAnswers"],
  ["company_questions", "companyQuestions"]
]
const csrf = async () =>
  ((await (await fetch("/api/security/csrf")).json()) as { csrfToken: string }).csrfToken
const post = async (path: string, body: unknown) => {
  const response = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-CSRF-Token": await csrf() },
    body: JSON.stringify(body)
  })
  if (!response.ok) throw new Error("request")
  return response
}
const requestBody = () => ({
  workflow: workflow.value,
  providerId: providerId.value,
  seriesId: revision.value?.seriesId ?? null,
  inputs: inputs.value,
  practiceAnswer: practiceAnswer.value.trim() || null,
  generationKey: generationKey.value
})
const load = async () => {
  const [postingsResponse, documentsResponse, providersResponse] = await Promise.all([
    fetch("/api/postings", { signal: controller.signal }),
    fetch("/api/documents", { signal: controller.signal }),
    fetch("/api/providers/status", { signal: controller.signal })
  ])
  postings.value = ((await postingsResponse.json()) as { postings: Posting[] }).postings
  documents.value = (
    (await documentsResponse.json()) as { documents: Document[] }
  ).documents.filter((item) => item.state === "active" && item.currentVersionId)
  providers.value = (
    (await providersResponse.json()) as { providers: Provider[] }
  ).providers.filter((item) => item.configured)
  providerId.value = providers.value[0]?.id ?? ""
}
const review = async () => {
  try {
    preview.value = (await (await post("/api/workflows/preview", requestBody())).json()) as {
      manifest: Manifest
      authorizationToken: string
    }
  } catch {
    toast.error(copy("failed"))
  }
}
const generate = async () => {
  if (!preview.value) return
  running.value = true
  try {
    const confirmation = (await (
      await post("/api/disclosures/confirm", {
        authorizationToken: preview.value.authorizationToken
      })
    ).json()) as { id: string }
    revision.value = (await (
      await post("/api/workflows/run", { ...requestBody(), disclosureId: confirmation.id })
    ).json()) as Revision
    preview.value = null
  } catch {
    toast.error(copy("failed"))
  } finally {
    running.value = false
    generationKey.value = crypto.randomUUID()
  }
}
const copyResult = async () => {
  if (revision.value) {
    await navigator.clipboard.writeText(JSON.stringify(revision.value.content, null, 2))
    toast.success(copy("copied"))
  }
}
const exportResult = () => {
  if (!revision.value) return
  window.open(
    `/api/artifacts/revisions/${revision.value.id}/export`,
    "_blank",
    "noopener,noreferrer"
  )
}
const viewProvenance = () => {
  if (!revision.value) return
  window.open(
    `/api/artifacts/revisions/${revision.value.id}/provenance`,
    "_blank",
    "noopener,noreferrer"
  )
}
onMounted(() => void load().catch(() => toast.error(copy("failed"))))
onBeforeUnmount(() => controller.abort())
</script>

type SubjectType = "company" | "executive" | "team_lead" | "team_member"
const props = withDefaults(
  defineProps<{
    subjectTypePreset?: SubjectType
    subjectNamePreset?: string
    organizationPreset?: string
    embedded?: boolean
  }>(),
  {
    subjectTypePreset: "company",
    subjectNamePreset: "",
    organizationPreset: "",
    embedded: false
  }
)
type RecordSummary = {
  id: string
  subjectType: SubjectType
  subjectName: string
  parentRecordId: string | null
  identityStatus: "confirmed" | "ambiguous" | "not_found"
  createdAt: string
}
type ResearchRecord = RecordSummary & {
  analysis: {
    fitAssessment: { label: "advisory"; summary: string; strengths: string[]; risks: string[] }
  }
  identityCandidates: Array<{
    name: string
    role: string | null
    organization: string | null
    sourceIds: string[]
  }>
  claims: Array<{
    id: string
    statement: string
    classification: "fact" | "inference" | "advisory" | "unverified"
    sourceIds: string[]
    confidence: string
  }>
  sources: Array<{ id: string; url: string; title: string; excerpt: string; status: string }>
}
const route = useRoute()
const settings = useSettingsStore()
const copy = (key: string) => translate(settings.locale, `research.${key}`)
const subjectType = ref<SubjectType>(props.subjectTypePreset)
const subjectName = ref(props.subjectNamePreset)
const organization = ref(props.organizationPreset)
const roleHint = ref("")
const urls = ref("")
const records = ref<RecordSummary[]>([])
const current = ref<ResearchRecord | null>(null)
const running = ref(false)
const loadController = new AbortController()
const jobPostId = computed(() => {
  const value = route.params["postId"]
  return typeof value === "string" ? value : null
})
const csrf = async () =>
  ((await (await fetch("/api/security/csrf")).json()) as { csrfToken: string }).csrfToken
const sourceUrls = () =>
  urls.value
    .split("\n")
    .map((url) => url.trim())
    .filter(Boolean)
    .slice(0, 8)
const load = async () => {
  const query = jobPostId.value === null ? "" : `?jobPostId=${encodeURIComponent(jobPostId.value)}`
  const response = await fetch(`/api/research${query}`, { signal: loadController.signal })
  if (!response.ok) return
  records.value = ((await response.json()) as { records: RecordSummary[] }).records
}
watch(
  () => [props.subjectNamePreset, props.organizationPreset] as const,
  ([name, company]) => {
    if (subjectName.value === "") subjectName.value = name
    if (organization.value === "") organization.value = company
  }
)
const submit = async (parentRecordId: string | null = null) => {
  running.value = true
  try {
    const path =
      parentRecordId === null ? "/api/research" : `/api/research/${parentRecordId}/refresh`
    const body =
      parentRecordId === null
        ? {
            subjectType: subjectType.value,
            subjectName: subjectName.value,
            organization: organization.value || null,
            roleHint: roleHint.value || null,
            jobPostId: jobPostId.value,
            sourceUrls: sourceUrls(),
            parentRecordId: null
          }
        : { sourceUrls: sourceUrls() }
    const response = await fetch(path, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-CSRF-Token": await csrf() },
      body: JSON.stringify(body)
    })
    if (!response.ok) throw new Error("research")
    current.value = (await response.json()) as ResearchRecord
    await load()
  } catch {
    toast.error(copy("failed"))
  } finally {
    running.value = false
  }
}
const openRecord = async (id: string) => {
  const response = await fetch(`/api/research/${id}`)
  if (response.ok) current.value = (await response.json()) as ResearchRecord
}
const identityLabel = (status: ResearchRecord["identityStatus"]) =>
  copy(status === "not_found" ? "notFound" : status)
onMounted(load)
onBeforeUnmount(() => loadController.abort())
</script>

