import { createHash, randomBytes } from "node:crypto"

import { RUNNER_PROTOCOL_VERSION, RunnerInboundMessageSchema, type RunnerClaim } from "./protocol"
import type { RunnerExecutionResult } from "./process-executor"

export type RunnerCredentials = { readonly runnerId: string; readonly token: string }
export type RunnerSocket = {
  readonly send: (data: string) => void
  readonly close: () => void
}
export type RunnerClaimExecutor = {
  readonly execute: (claim: RunnerClaim, signal?: AbortSignal) => Promise<RunnerExecutionResult>
}
export type OutboundWebSocket = RunnerSocket & {
  onopen: (() => void) | null
  onmessage: ((event: { readonly data: string }) => void) | null
  onerror: (() => void) | null
  binaryType: string
}
export type OutboundWebSocketFactory = (url: string) => OutboundWebSocket

type ActiveRun = { readonly leaseId: string; readonly controller: AbortController }
type TerminalRun = { readonly leaseId: string; readonly messages: readonly string[] }

export class RunnerConnection {
  private socket: RunnerSocket | null = null
  private readonly active = new Map<string, ActiveRun>()
  private readonly terminal = new Map<string, TerminalRun>()

constructor(
    private readonly credentials: RunnerCredentials,
    private readonly executor: RunnerClaimExecutor
  ) {}

attach(socket: RunnerSocket): void {
    this.socket = socket
    this.send({
      version: RUNNER_PROTOCOL_VERSION,
      type: "authenticate",
      runnerId: this.credentials.runnerId,
      token: this.credentials.token,
      nonce: randomBytes(18).toString("base64url")
    })
  }

async receive(raw: string): Promise<void> {
    const message = RunnerInboundMessageSchema.parse(JSON.parse(raw))
    if (message.type === "pair_accepted") return
    if (message.type === "cancel") {
      const active = this.active.get(message.runId)
      if (active?.leaseId === message.leaseId) active.controller.abort()
      return
    }
    await this.execute(message)
  }

private async execute(claim: RunnerClaim): Promise<void> {
    const completed = this.terminal.get(claim.runId)
    if (completed !== undefined) {
      if (completed.leaseId !== claim.leaseId) throw new RunnerConnectionError("lease_conflict")
      for (const message of completed.messages) this.socket?.send(message)
      return
    }
    const existing = this.active.get(claim.runId)
    if (existing !== undefined) {
      if (existing.leaseId !== claim.leaseId) throw new RunnerConnectionError("lease_conflict")
      this.sendBase("ack", claim)
      return
    }
    const controller = new AbortController()
    this.active.set(claim.runId, { leaseId: claim.leaseId, controller })
    this.sendBase("ack", claim)
    const result = await this.executor.execute(claim, controller.signal)
    const messages = this.resultMessages(claim, result)
    this.active.delete(claim.runId)
    this.terminal.set(claim.runId, { leaseId: claim.leaseId, messages })
    for (const message of messages) this.socket?.send(message)
  }

private sendBase(type: "ack", claim: RunnerClaim): void {
    this.send({
      version: RUNNER_PROTOCOL_VERSION,
      type,
      runId: claim.runId,
      leaseId: claim.leaseId
    })
  }

private send(value: unknown): void {
    if (this.socket === null) throw new RunnerConnectionError("not_connected")
    this.socket.send(JSON.stringify(value))
  }
}

export const connectOutboundRunner = (
  endpoint: string,
  connection: RunnerConnection,
  createSocket: OutboundWebSocketFactory = (url) =>
    new WebSocket(url) as unknown as OutboundWebSocket
): OutboundWebSocket => {
  const url = new URL(endpoint)
  if (
    !["ws:", "wss:"].includes(url.protocol) ||
    !["localhost", "127.0.0.1", "[::1]", "::1"].includes(url.hostname)
  )
    throw new RunnerConnectionError("endpoint_denied")
  const socket = createSocket(url.toString())
  socket.binaryType = "blob"
  socket.onopen = () => connection.attach(socket)
  socket.onmessage = (event) => {
    void connection.receive(event.data).catch(() => socket.close())
  }
  socket.onerror = () => socket.close()
  return socket
}

const chunkOutput = (value: string): readonly string[] => {
  const chunks: string[] = []
  for (let offset = 0; offset < value.length; offset += 65_536)
    chunks.push(value.slice(offset, offset + 65_536))
  return chunks
}

export class RunnerConnectionError extends Error {
  override readonly name = "RunnerConnectionError"
  constructor(readonly code: "endpoint_denied" | "lease_conflict" | "not_connected") {
    super(`RUNNER_CONNECTION_${code.toUpperCase()}`)
  }
}

import { z } from "zod"

export type NormalizedCliEvent =
  | { readonly kind: "text"; readonly text: string }
  | {
      readonly kind: "usage"
      readonly inputTokens: number
      readonly outputTokens: number
      readonly cacheTokens: number
    }

const ClaudeStreamSchema = z
  .object({
    type: z.literal("stream_event"),
    event: z.object({
      type: z.string(),
      delta: z.object({ type: z.string(), text: z.string().optional() }).passthrough()
    })
  })
  .passthrough()
const ClaudeResultSchema = z
  .object({
    type: z.literal("result"),
    usage: z
      .object({
        input_tokens: z.number().int().nonnegative(),
        output_tokens: z.number().int().nonnegative(),
        cache_read_input_tokens: z.number().int().nonnegative().optional(),
        cache_creation_input_tokens: z.number().int().nonnegative().optional()
      })
      .optional()
  })
  .passthrough()
const CodexMessageSchema = z
  .object({
    type: z.literal("item.completed"),
    item: z.object({ type: z.literal("agent_message"), text: z.string() }).passthrough()
  })
  .passthrough()
const CodexUsageSchema = z
  .object({
    type: z.literal("turn.completed"),
    usage: z.object({
      input_tokens: z.number().int().nonnegative(),
      output_tokens: z.number().int().nonnegative(),
      cached_input_tokens: z.number().int().nonnegative().optional()
    })
  })
  .passthrough()

export const normalizeCliOutputLine = (
  provider: "claude-cli" | "codex-cli",
  line: string
): NormalizedCliEvent | null => {
  let value: unknown
  try {
    value = JSON.parse(line)
  } catch {
    throw new CliOutputError("malformed")
  }
  if (provider === "claude-cli") {
    const stream = ClaudeStreamSchema.safeParse(value)
    if (stream.success)
      return stream.data.event.delta.type === "text_delta" &&
        stream.data.event.delta.text !== undefined
        ? { kind: "text", text: stream.data.event.delta.text }
        : null
    const result = ClaudeResultSchema.safeParse(value)
    if (!result.success || result.data.usage === undefined) return null
    const cacheTokens =
      (result.data.usage.cache_read_input_tokens ?? 0) +
      (result.data.usage.cache_creation_input_tokens ?? 0)
    return {
      kind: "usage",
      inputTokens: result.data.usage.input_tokens,
      outputTokens: result.data.usage.output_tokens,
      cacheTokens
    }
  }
  const message = CodexMessageSchema.safeParse(value)
  if (message.success) return { kind: "text", text: message.data.item.text }
  const usage = CodexUsageSchema.safeParse(value)
  return usage.success
    ? {
        kind: "usage",
        inputTokens: usage.data.usage.input_tokens,
        outputTokens: usage.data.usage.output_tokens,
        cacheTokens: usage.data.usage.cached_input_tokens ?? 0
      }
    : null
}

export class CliOutputError extends Error {
  override readonly name = "CliOutputError"
  constructor(readonly code: "malformed") {
    super("CLI_OUTPUT_MALFORMED")
  }
}

export type CliKind = "claude" | "codex"
export type ProbeCommand = {
  readonly executable: CliKind
  readonly argv: readonly string[]
  readonly stdin?: string
}
export type ProbeCommandResult = {
  readonly exitCode: number
  readonly stdout: string
  readonly stderr: string
}
export type ProbeCommandRunner = (command: ProbeCommand) => Promise<ProbeCommandResult>
export type CliProbeResult =
  | {
      readonly kind: "healthy"
      readonly version: string
      readonly capabilities: readonly string[]
    }
  | {
      readonly kind: "unavailable"
      readonly code:
        | "missing"
        | "unsupported_version"
        | "missing_flag"
        | "unauthenticated"
        | "minimal_run_failed"
    }

const requiredFlags: Record<CliKind, readonly string[]> = {
  claude: [
    "--output-format",
    "--verbose",
    "--include-partial-messages",
    "--no-session-persistence",
    "--permission-mode"
  ],
  codex: ["--json", "--ephemeral", "--sandbox"]
}

export class CliProbe {
  constructor(private readonly run: ProbeCommandRunner = runProbeCommand) {}

async inspect(kind: CliKind): Promise<CliProbeResult> {
    const version = await this.safe({ executable: kind, argv: ["--version"] })
    if (version === null) return { kind: "unavailable", code: "missing" }
    const versionText = `${version.stdout}\n${version.stderr}`.trim()
    if (version.exitCode !== 0 || !/\d+\.\d+(?:\.\d+)?/.test(versionText))
      return { kind: "unavailable", code: "unsupported_version" }
    const help = await this.safe({
      executable: kind,
      argv: kind === "claude" ? ["--help"] : ["exec", "--help"]
    })
    if (
      help === null ||
      help.exitCode !== 0 ||
      requiredFlags[kind].some((flag) => !`${help.stdout}\n${help.stderr}`.includes(flag))
    )
      return { kind: "unavailable", code: "missing_flag" }
    const auth = await this.safe({
      executable: kind,
      argv: kind === "claude" ? ["auth", "status"] : ["login", "status"]
    })
    if (auth === null || auth.exitCode !== 0)
      return { kind: "unavailable", code: "unauthenticated" }
    const minimal = await this.safe(minimalCommand(kind))
    if (
      minimal === null ||
      minimal.exitCode !== 0 ||
      !`${minimal.stdout}\n${minimal.stderr}`.toLowerCase().includes("ok")
    )
      return { kind: "unavailable", code: "minimal_run_failed" }
    return {
      kind: "healthy",
      version: versionText.slice(0, 128),
      capabilities: [
        ...requiredFlags[kind],
        ...(help.stdout.includes("--skip-git-repo-check") ? ["--skip-git-repo-check"] : []),
        ...(help.stdout.includes("--bare") ? ["--bare"] : [])
      ]
    }
  }

private async safe(command: ProbeCommand): Promise<ProbeCommandResult | null> {
    try {
      return await this.run(command)
    } catch {
      return null
    }
  }
}

const minimalCommand = (kind: CliKind): ProbeCommand =>
  kind === "claude"
    ? {
        executable: "claude",
        argv: [
          "-p",
          "--output-format",
          "json",
          "--no-session-persistence",
          "--permission-mode",
          "dontAsk"
        ],
        stdin: "Reply with exactly OK. Do not use tools."
      }
    : {
        executable: "codex",
        argv: ["exec", "--json", "--ephemeral", "--sandbox", "read-only", "-"],
        stdin: "Reply with exactly OK. Do not use tools."
      }

const runProbeCommand: ProbeCommandRunner = async ({ executable, argv, stdin }) => {
  const child = Bun.spawn([executable, ...argv], {
    stdin: "pipe",
    stdout: "pipe",
    stderr: "pipe"
  })
  if (stdin !== undefined) child.stdin.write(stdin)
  child.stdin.end()
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited
  ])
  return { exitCode, stdout, stderr }
}

export type RunnerProcessOptions = {
  readonly capabilities: RunnerCliCapabilities
  readonly environment?: Readonly<Record<string, string | undefined>>
  readonly temporaryRoot?: string
  readonly outputBytes?: number
  readonly timeoutMilliseconds?: number
}

export class RunnerProcessExecutor {
  constructor(private readonly options: RunnerProcessOptions) {}

async execute(claim: RunnerClaim, signal?: AbortSignal): Promise<RunnerExecutionResult> {
    const cwd = mkdtempSync(join(this.options.temporaryRoot ?? tmpdir(), "interview-runner-"))
    try {
      const command = commandForClaim(claim, this.options.capabilities)
      const environment = sanitizedEnvironment(this.options.environment ?? process.env)
      if (command.requiresGitInit) {
        const initialized = Bun.spawnSync(["git", "init", "--quiet"], {
          cwd,
          env: environment,
          stderr: "pipe",
          stdout: "pipe"
        })
        if (initialized.exitCode !== 0) return { kind: "failed", code: "spawn_failed" }
      }
      let child: Bun.Subprocess<"pipe", "pipe", "pipe">
      try {
        child = Bun.spawn([command.executable, ...command.argv], {
          cwd,
          detached: true,
          env: environment,
          stdin: "pipe",
          stdout: "pipe",
          stderr: "pipe"
        })
      } catch {
        return { kind: "failed", code: "spawn_failed" }
      }
      child.stdin.write(command.stdin)
      child.stdin.end()
      const timeout = AbortSignal.timeout(this.options.timeoutMilliseconds ?? 120_000)
      const combined = signal === undefined ? timeout : AbortSignal.any([signal, timeout])
      const terminate = (): void => terminateProcessGroup(child)
      combined.addEventListener("abort", terminate, { once: true })
      try {
        const limit = this.options.outputBytes ?? 4 * 1024 * 1024
        const [stdout, stderr, exitCode] = await Promise.all([
          readBounded(child.stdout, limit),
          readBounded(child.stderr, limit),
          child.exited
        ])
        if (stdout === null || stderr === null) {
          terminate()
          return { kind: "failed", code: "output_limit" }
        }
        if (combined.aborted)
          return { kind: "failed", code: timeout.aborted ? "timeout" : "cancelled" }
        return exitCode === 0
          ? { kind: "completed", stdout, stderr }
          : { kind: "failed", code: "cli_failed" }
      } finally {
        combined.removeEventListener("abort", terminate)
      }
    } finally {
      rmSync(cwd, { recursive: true, force: true })
    }
  }
}

const sanitizedEnvironment = (
  source: Readonly<Record<string, string | undefined>>
): Record<string, string> =>
  Object.fromEntries(
    ALLOWED_ENVIRONMENT.flatMap((key) => {
      const value = source[key]
      return value === undefined ? [] : [[key, value]]
    })
  )

const readBounded = async (
  stream: ReadableStream<Uint8Array>,
  maximumBytes: number
): Promise<string | null> => {
  const reader = stream.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  try {
    for (;;) {
      const next = await reader.read()
      if (next.done) break
      size += next.value.byteLength
      if (size > maximumBytes) return null
      chunks.push(next.value)
    }
  } finally {
    reader.releaseLock()
  }
  const output = new Uint8Array(size)
  let offset = 0
  for (const chunk of chunks) {
    output.set(chunk, offset)
    offset += chunk.byteLength
  }
  return new TextDecoder().decode(output)
}

const terminateProcessGroup = (child: Bun.Subprocess<"pipe", "pipe", "pipe">): void => {
  try {
    process.kill(-child.pid, "SIGTERM")
  } catch {
    child.kill("SIGTERM")
  }
}

