  temporaryDirectories.push(directory)
  return directory
}
const createJobPost = (persistence: Persistence) =>
  persistence.repositories.domain.createJobPost({
    id: crypto.randomUUID(),
    title: "Engineer",
    companyName: "Example"
  })

afterEach(() => {
