      persistence.repositories.domain.createApplication({
        id: crypto.randomUUID(),
        jobPostId: crypto.randomUUID(),
        idempotencyKey: crypto.randomUUID()
      })
    ).toThrow()
    expect(() =>
      persistence.repositories.domain.addJobPostVersion({
