export type ProviderId = z.output<typeof ProviderIdSchema>
export type ToolId = z.output<typeof ToolIdSchema>
export type ProviderDescriptor = z.output<typeof ProviderDescriptorSchema>
export type ProviderHealth = z.output<typeof ProviderHealthSchema>
export type NeutralMessage = z.output<typeof NeutralMessageSchema>
export type ProviderUsage = {
  readonly inputTokens: number
  readonly outputTokens: number
  readonly cacheTokens: number
  readonly totalTokens: number
}
export type ProviderCost = { readonly currency: "USD"; readonly microunits: number } | null
export type ProviderErrorCode =
  | "provider_unavailable"
  | "disabled"
  | "tool_denied"
  | "invalid_output"
  | "timeout"
  | "cancelled"
  | "limit_exceeded"
  | "provider_failure"
export type ProviderError = { readonly code: ProviderErrorCode; readonly retryable: boolean }
export type ProviderOutput =
  { readonly kind: "text" } | { readonly kind: "structured"; readonly schema: z.ZodType }
export type ProviderInvocation = z.output<typeof InvocationShapeSchema> & {
  readonly output: ProviderOutput
  readonly signal?: AbortSignal
}
export type ProviderEvent =
  | { readonly kind: "started"; readonly providerId: ProviderId; readonly model: string }
  | { readonly kind: "text_delta"; readonly text: string }
  | { readonly kind: "tool_started"; readonly toolId: ToolId }
  | { readonly kind: "tool_result"; readonly toolId: ToolId; readonly status: "success" | "error" }
  | { readonly kind: "usage"; readonly usage: ProviderUsage }
  | {
      readonly kind: "completed"
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }
  | {
      readonly kind: "failed"
      readonly error: ProviderError
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }
  | {
      readonly kind: "cancelled"
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }
export type ProviderResult =
  | {
      readonly kind: "completed"
      readonly text: string
      readonly structured: unknown | null
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }
  | {
      readonly kind: "failed"
      readonly error: ProviderError
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }
  | {
      readonly kind: "cancelled"
      readonly usage: ProviderUsage | null
      readonly cost: ProviderCost
    }

export const assertNever = (value: never): never => {
  throw new Error(`Unexpected variant: ${JSON.stringify(value)}`)
}

import type { ProviderError, ProviderEvent, ProviderResult, ProviderUsage } from "./contracts"

export const terminalFailure = async function* (
  code: ProviderError["code"],
  retryable: boolean,
  usage: ProviderUsage | null
): AsyncGenerator<ProviderEvent, ProviderResult, undefined> {
  const error = { code, retryable }
  yield { kind: "failed", error, usage, cost: null }
  return { kind: "failed", error, usage, cost: null }
}

export const terminalCancelled = async function* (
  usage: ProviderUsage | null
): AsyncGenerator<ProviderEvent, ProviderResult, undefined> {
  yield { kind: "cancelled", usage, cost: null }
  return { kind: "cancelled", usage, cost: null }
}

export class ProviderKernel {
  constructor(
    private readonly dependencies: {
      readonly providers: ProviderRegistry
      readonly tools: ToolRegistry
    }
  ) {}
  descriptor(id: string): ProviderDescriptor | null {
    return this.dependencies.providers.get(id)?.descriptor ?? null
  }
  async *stream(
    input: ProviderInvocation
  ): AsyncGenerator<ProviderEvent, ProviderResult, undefined> {
    let timeoutId: ReturnType<typeof setTimeout> | null = null
    try {
      const shape = InvocationShapeSchema.parse({
        providerId: input.providerId,
        messages: input.messages,
        toolIds: input.toolIds,
        ...(input.timeoutMilliseconds === undefined
          ? {}
          : { timeoutMilliseconds: input.timeoutMilliseconds })
      })
      if (input.signal?.aborted) return yield* terminalCancelled(null)
      const provider = this.dependencies.providers.get(shape.providerId)
      yield {
        kind: "started",
        providerId: shape.providerId,
        model: provider?.descriptor.model.id ?? "unavailable"
      }
      if (provider === null) return yield* terminalFailure("provider_unavailable", false, null)
      if (!provider.enabled) return yield* terminalFailure("disabled", false, null)
      if (
        !provider.descriptor.capabilities.generation ||
        (input.output.kind === "structured" && !provider.descriptor.capabilities.structuredOutput)
      )
        return yield* terminalFailure("provider_unavailable", false, null)
      const health = await provider.health()
      if (health.kind === "unavailable")
        return yield* terminalFailure(
          health.code === "disabled" ? "disabled" : "provider_unavailable",
          health.code !== "disabled",
          null
        )
      let tools
      try {
        tools = this.dependencies.tools.select(shape.toolIds)
      } catch (error) {
        if (error instanceof ProviderRegistryError)
          return yield* terminalFailure("tool_denied", false, null)
        throw error
      }
      if (
        !provider.descriptor.capabilities.citedResearch &&
        this.dependencies.tools.requiresCitedResearch(shape.toolIds)
      )
        return yield* terminalFailure("provider_unavailable", false, null)
      const timeout = new AbortController()
      timeoutId = setTimeout(() => timeout.abort("timeout"), input.timeoutMilliseconds ?? 60_000)
      const signal =
        input.signal === undefined
          ? timeout.signal
          : AbortSignal.any([input.signal, timeout.signal])
      const agent = new Agent({
        model: provider.createModel(),
        tools: [...tools],
        printer: false,
        contextManager: false,
        retryStrategy: null,
        toolExecutor: "sequential"
      })
      const structuredToolUses = new Set<string>()
      let structuredFailures = 0
      const messages = shape.messages.map(
        (message) =>
          new Message({
            role: message.role,
            content: message.content.map((block) => new TextBlock(block.text))
          })
      )
      let text = ""
      let usage: ProviderUsage | null = null
      const toolUses = new Map<string, ReturnType<typeof ToolIdSchema.safeParse>["data"]>()
      try {
        const result = yield* consume(agent, messages, input.output, signal, (event) => {
          if (
            event.type === "beforeToolCallEvent" &&
            event.toolUse.name === "strands_structured_output"
          )
            structuredToolUses.add(event.toolUse.toolUseId)
          if (
            event.type === "toolResultEvent" &&
            structuredToolUses.has(event.result.toolUseId) &&
            event.result.status === "error"
          ) {
            structuredFailures += 1
            if (structuredFailures > 1) throw new StructuredRepairLimitError()
          }
          const normalized = normalize(event, toolUses)
          if (normalized?.kind === "text_delta") text += normalized.text
          if (normalized?.kind === "usage") usage = normalized.usage
          return normalized
        })
        if (signal.aborted || result.stopReason === "cancelled") {
          if (timeout.signal.aborted) return yield* terminalFailure("timeout", true, usage)
          const event = { kind: "cancelled", usage, cost: null } as const
          yield event
          return { kind: "cancelled", usage, cost: null }
        }
        if (input.output.kind === "structured" && result.structuredOutput === undefined)
          return yield* terminalFailure("invalid_output", false, usage)
        if (isLimitStopReason(result.stopReason))
          return yield* terminalFailure("limit_exceeded", false, usage)
        const structured = input.output.kind === "structured" ? result.structuredOutput : null
        yield { kind: "completed", usage, cost: null }
        return { kind: "completed", text, structured, usage, cost: null }
      } catch (error) {
        if (signal.aborted) {
          const code = timeout.signal.aborted ? "timeout" : "cancelled"
          if (code === "cancelled") {
            yield { kind: "cancelled", usage, cost: null }
            return { kind: "cancelled", usage, cost: null }
          }
          return yield* terminalFailure(code, true, usage)
        }
        return yield* terminalFailure(errorCode(error), error instanceof ModelThrottledError, usage)
      }
    } catch (error) {
      return yield* terminalFailure(errorCode(error), false, null)
    } finally {
      if (timeoutId !== null) clearTimeout(timeoutId)
    }
  }
}
const consume = async function* (
  agent: Agent,
  messages: readonly Message[],
  output: ProviderInvocation["output"],
  signal: AbortSignal,
  map: (event: AgentStreamEvent) => ProviderEvent | null
): AsyncGenerator<ProviderEvent, AgentResult, undefined> {
  const options = {
    cancelSignal: signal,
    limits: {
      turns: output.kind === "structured" ? 3 : 4,
      outputTokens: 4096,
      totalTokens: 16_384
    },
    ...(output.kind === "structured" ? { structuredOutputSchema: output.schema } : {})
  }
  const stream = agent.stream([...messages], options)
  let next = await stream.next()
  while (!next.done) {
    const event = map(next.value)
    if (event !== null) yield event
    next = await stream.next()
  }
  return next.value
}
const normalize = (
  event: AgentStreamEvent,
  toolUses: Map<string, ReturnType<typeof ToolIdSchema.safeParse>["data"]>
): ProviderEvent | null => {
  switch (event.type) {
    case "modelStreamUpdateEvent":
      switch (event.event.type) {
        case "modelContentBlockDeltaEvent":
          return event.event.delta.type === "textDelta"
            ? { kind: "text_delta", text: event.event.delta.text }
            : null
        case "modelMetadataEvent":
          return event.event.usage === undefined
            ? null
            : { kind: "usage", usage: normalizeUsage(event.event.usage) }
        default:
          return null
      }
    case "beforeToolCallEvent": {
      if (event.toolUse.name === "strands_structured_output") return null
      const parsed = ToolIdSchema.safeParse(event.toolUse.name)
      if (!parsed.success) return null
      toolUses.set(event.toolUse.toolUseId, parsed.data)
      return { kind: "tool_started", toolId: parsed.data }
    }
    case "toolResultEvent": {
      const toolId = toolUses.get(event.result.toolUseId)
      return toolId === undefined
        ? null
        : { kind: "tool_result", toolId, status: event.result.status }
    }
    default:
      return null
  }
}
const normalizeUsage = (usage: {
  readonly inputTokens: number
  readonly outputTokens: number
  readonly totalTokens: number
}): ProviderUsage => ({
  inputTokens: usage.inputTokens,
  outputTokens: usage.outputTokens,
  cacheTokens:
    "cacheTokens" in usage && typeof usage.cacheTokens === "number" ? usage.cacheTokens : 0,
  totalTokens: usage.totalTokens
})
const errorCode = (error: unknown): ProviderError["code"] => {
  if (error instanceof StructuredRepairLimitError) return "invalid_output"
  if (error instanceof StructuredOutputError) return "invalid_output"
  if (error instanceof MaxTokensError) return "limit_exceeded"
  if (error instanceof ModelThrottledError) return "provider_failure"
  if (error instanceof ModelError) return "provider_failure"
  return "provider_failure"
}
const isLimitStopReason = (reason: string): boolean =>
  reason === "maxTokens" || reason === "modelContextWindowExceeded" || reason.startsWith("limit")
class StructuredRepairLimitError extends Error {
  override readonly name = "StructuredRepairLimitError"
  constructor() {
    super("STRUCTURED_REPAIR_LIMIT")
  }
}

import { createHash } from "node:crypto"
import { z } from "zod"

import type { ProviderInvocation } from "./contracts"

const canonical = (value: unknown): string => {
  if (value === null || typeof value !== "object") return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  return `{${Object.entries(value)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, child]) => `${JSON.stringify(key)}:${canonical(child)}`)
    .join(",")}}`
}

export class ProviderInvokeCoordinator<Terminal> {
  private readonly pending = new Map<string, Terminal | null>()

register(jobId: string): void {
    this.pending.set(jobId, null)
  }
  report(jobId: string, terminal: Terminal): void {
    if (this.pending.has(jobId)) this.pending.set(jobId, terminal)
  }
  take(jobId: string): Terminal | undefined {
    const terminal = this.pending.get(jobId)
    this.pending.delete(jobId)
    return terminal ?? undefined
  }
  get size(): number {
    return this.pending.size
  }
}

const ProviderInvokePayloadSchema = z
  .object({
    runId: ProviderRunIdSchema,
    providerId: ProviderIdSchema,
    mode: ProviderModeSchema,
    model: z.string().trim().min(1).max(128),
    requestHash: ProviderRequestHashSchema,
    disclosureId: z.string().uuid().optional()
  })
  .strict()
type ProviderInvokePayload = z.output<typeof ProviderInvokePayloadSchema>
export type ProviderInvokeAuthorization = {
  readonly consume: (payload: ProviderInvokePayload) => boolean
}
export type ProviderRequestSource = {
  readonly resolve: (payload: ProviderInvokePayload) => ProviderInvocation | null
}
export const unavailableProviderRequestSource: ProviderRequestSource = { resolve: () => null }
export type ProviderInvokeJobDefinition = JobDefinition & { readonly pendingCount: () => number }
export const createProviderInvokeJobDefinition = (dependencies: {
  readonly kernel: ProviderKernel
  readonly providerRuns: ProviderArtifactRepository
  readonly jobs: JobsRepository
  readonly requests: ProviderRequestSource
  readonly authorization?: ProviderInvokeAuthorization
}): ProviderInvokeJobDefinition => {
  const outcomes = new ProviderInvokeCoordinator<ProviderTerminal>()
  const complete = (context: JobTerminalContext): void => {
    const payload = ProviderInvokePayloadSchema.parse(context.job.payload)
    const outcome = outcomes.take(context.job.id)
    const existing = dependencies.providerRuns.getProviderRun(payload.runId)
    if (existing === null || existing.status !== "running") return
    const terminal = terminalFor(context, outcome)
    dependencies.providerRuns.transitionInTransaction(payload.runId, terminal)
  }
  const reconcile = (job: Job): void => {
    const state = job.state
    if (state !== "succeeded" && state !== "failed" && state !== "cancelled") return
    dependencies.providerRuns.transaction(() => complete({ job, state, reason: "interrupted" }))
  }
  return {
    kind: "provider-invoke",
    retryClass: "external",
    maxAttempts: 1,
    pendingCount: () => outcomes.size,
    terminal: complete,
    reconcile,
    run: async ({ job, signal }) => {
      outcomes.register(job.id)
      const payload = ProviderInvokePayloadSchema.parse(job.payload)
      dependencies.providerRuns.createRunning({
        id: payload.runId,
        providerKind: payload.providerId,
        mode: "completion",
        model: payload.model,
        requestHash: payload.requestHash
      })
      const descriptor = dependencies.kernel.descriptor(payload.providerId)
      if (
        descriptor === null ||
        descriptor.mode !== payload.mode ||
        descriptor.model.id !== payload.model
      ) {
        outcomes.report(job.id, unavailableTerminal())
        throw new ProviderInvokeJobError()
      }
      const request = dependencies.requests.resolve(payload)
      if (request === null) {
        outcomes.report(job.id, unavailableTerminal())
        throw new ProviderInvokeJobError()
      }
      if (request.providerId !== payload.providerId) {
        outcomes.report(job.id, unavailableTerminal())
        throw new ProviderInvokeJobError()
      }
      if (providerInvocationHash(request) !== payload.requestHash) {
        outcomes.report(job.id, unavailableTerminal())
        throw new ProviderInvokeJobError()
      }
      if (dependencies.authorization?.consume(payload) !== true) {
        outcomes.report(job.id, unavailableTerminal())
        throw new ProviderInvokeJobError()
      }
      const completed = await collectProviderStream(
        dependencies.kernel.stream({ ...request, signal })
      )
      for (const event of completed.events) {
        if (
          event.kind === "started" ||
          event.kind === "text_delta" ||
          event.kind === "usage" ||
          event.kind === "tool_started" ||
          event.kind === "tool_result"
        )
          dependencies.jobs.appendProgress({
            id: job.id,
            payload: { provider: payload.providerId, phase: event.kind },
            now: new Date().toISOString()
          })
      }
      switch (completed.result.kind) {
        case "completed":
          outcomes.report(job.id, {
            status: "succeeded",
            usage: completed.result.usage,
            cost: completed.result.cost,
            error: null
          })
          return
        case "cancelled":
          outcomes.report(job.id, cancelledTerminal(completed.result.usage, completed.result.cost))
          return
        case "failed":
          outcomes.report(job.id, failedTerminal(completed.result))
          throw new ProviderInvokeJobError()
        default:
          return assertNever(completed.result)
      }
    }
  }
}
type ProviderTerminal = {
  readonly status: "succeeded" | "failed" | "cancelled"
  readonly usage: ProviderRun["usage"]
  readonly cost: ProviderRun["cost"]
  readonly error: ProviderRun["error"]
}
const unavailableTerminal = (): ProviderTerminal => ({
  status: "failed",
  usage: null,
  cost: null,
  error: { category: "provider_unavailable", retryable: false }
})
const cancelledTerminal = (
  usage: ProviderRun["usage"],
  cost: ProviderRun["cost"]
): ProviderTerminal => ({
  status: "cancelled",
  usage,
  cost,
  error: { category: "cancelled", retryable: false }
})
const failedTerminal = (
  result: Extract<Awaited<ReturnType<typeof collectProviderStream>>["result"], { kind: "failed" }>
): ProviderTerminal => ({
  status: "failed",
  usage: result.usage,
  cost: result.cost,
  error: {
    category:
      result.error.code === "invalid_output"
        ? "invalid_output"
        : result.error.code === "timeout"
          ? "timeout"
          : "provider_failure",
    retryable: result.error.retryable
  }
})
const terminalFor = (
  context: JobTerminalContext,
  outcome: ProviderTerminal | undefined
): ProviderTerminal => {
  if (context.state === "cancelled")
    return cancelledTerminal(outcome?.usage ?? null, outcome?.cost ?? null)
  if (context.state === "succeeded" && outcome?.status === "succeeded") return outcome
  if (context.reason === "timeout")
    return {
      status: "failed",
      usage: null,
      cost: null,
      error: { category: "timeout", retryable: false }
    }
  return outcome?.status === "failed" ? outcome : unavailableTerminal()
}
const assertNever = (value: never): never => {
  throw new Error(`Unexpected provider result ${JSON.stringify(value)}`)
}
export class ProviderInvokeJobError extends Error {
  override readonly name = "ProviderInvokeJobError"
  constructor() {
    super("PROVIDER_INVOKE_FAILED")
  }
}

import type { ProviderEvent, ProviderResult } from "./contracts"

export const collectProviderStream = async (
  stream: AsyncGenerator<ProviderEvent, ProviderResult, undefined>
): Promise<{ readonly events: readonly ProviderEvent[]; readonly result: ProviderResult }> => {
  const events: ProviderEvent[] = []
  let next = await stream.next()
  while (!next.done) {
    events.push(next.value)
    next = await stream.next()
  }
  return { events, result: next.value }
}

export type ProviderRegistration = {
  readonly descriptor: ProviderDescriptor
  readonly enabled: boolean
  readonly createModel: () => Model
  readonly health: () => Promise<ProviderHealth>
}
export type ServerTool = {
  readonly id: ToolId
  readonly schema: z.ZodType
  readonly requiresCitedResearch?: boolean
  readonly execute: (
    input: unknown,
    context: { readonly signal: AbortSignal }
  ) => unknown | Promise<unknown>
}
export class ProviderRegistry {
  private readonly providers = new Map<ProviderId, ProviderRegistration>()
  constructor(registrations: readonly ProviderRegistration[]) {
    for (const registration of registrations) {
      if (this.providers.has(registration.descriptor.id))
        throw new ProviderRegistryError("duplicate")
      this.providers.set(registration.descriptor.id, registration)
    }
  }
  get(id: string): ProviderRegistration | null {
    return this.providers.get(ProviderIdSchema.parse(id)) ?? null
  }
  list(): readonly ProviderRegistration[] {
    return [...this.providers.values()]
  }
  async health(id: string): Promise<ProviderHealth> {
    const provider = this.get(id)
    if (provider === null) return { kind: "unavailable", code: "unconfigured" }
    if (!provider.enabled) return { kind: "unavailable", code: "disabled" }
    return provider.health()
  }
}
export class ToolRegistry {
  private readonly tools = new Map<ToolId, ServerTool>()
  constructor(tools: readonly ServerTool[]) {
    for (const entry of tools) {
      if (this.tools.has(entry.id)) throw new ProviderRegistryError("duplicate")
      this.tools.set(entry.id, entry)
    }
  }
  select(ids: readonly string[]): readonly InvokableTool<unknown, unknown>[] {
    return ids.map((rawId) => {
      const id = ToolIdSchema.parse(rawId)
      const entry = this.tools.get(id)
      if (entry === undefined) throw new ProviderRegistryError("tool_denied")
      return tool({
        name: id,
        description: "Server-approved tool",
        inputSchema: entry.schema,
        callback: (input, context) =>
          entry.execute(input, { signal: context?.cancelSignal ?? new AbortController().signal })
      })
    })
  }
  requiresCitedResearch(ids: readonly string[]): boolean {
    return ids.some((rawId) => {
      const entry = this.tools.get(ToolIdSchema.parse(rawId))
      return entry?.requiresCitedResearch === true
    })
  }
}
export class ProviderRegistryError extends Error {
  override readonly name = "ProviderRegistryError"
  constructor(readonly code: "duplicate" | "tool_denied") {
    super(code)
  }
}

export const createApp = ({
  dataDirectory = "./data",
  resolver,
  security = defaultLocalSecuritySettings(),
  transport,
  csrfSecret,
  disclosureSecret,
  persistence: providedPersistence,
  jobDefinitions = [],
  jobRuntime,
  providerRegistry = new ProviderRegistry([]),
  providerRequests = unavailableProviderRequestSource,
  promptTemplates = defaultPromptTemplateRevisionRegistry,
  runnerPairing,
  researchAnalyzer = localEvidenceAnalyzer,
  preparationExecutor,
  chatExecutor
}: AppOptions = {}): Hono => {
  const app = new Hono()
  const csrf = createCsrfProtection(csrfSecret)
  const persistence = providedPersistence ?? createPersistence({ dataDirectory })
  const disclosures = new DisclosureService({
    database: persistence.database,
    providers: providerRegistry,
    secret: disclosureSecret ?? randomBytes(32)
  })
  const kernel = new ProviderKernel({ providers: providerRegistry, tools: new ToolRegistry([]) })
  const providerDefinition = createProviderInvokeJobDefinition({
    kernel,
    providerRuns: persistence.repositories.providerArtifacts,
    jobs: persistence.repositories.jobs,
    requests: providerRequests,
    authorization: { consume: (payload) => disclosures.consumeForProviderRun(payload) }
  })
  const definitions = jobDefinitions.some(
    (definition) => definition.kind === providerDefinition.kind
  )
    ? jobDefinitions
    : [...jobDefinitions, providerDefinition]
  const jobs =
    jobRuntime ?? new JobRuntime(persistence.repositories.jobs, createJobRegistry(definitions))

app.use("*", localSecurityMiddleware(security, csrf))
  app.use(
    "/api/*",
    bodyLimit({
      maxSize: security.requestBytes,
      onError: (context) => context.json({ error: { code: "REQUEST_TOO_LARGE" } }, 413)
    })
  )
  app.get("/api/health", (context) => context.json(HEALTH_STATUS))
  app.get("/api/security/csrf", csrf.issue)
  app.route(
    "/api/preview",
    createPreviewRoutes({ dataDirectory, limits: security, resolver, transport })
  )
  app.route(
    "/api",
    createApplicationRoutes(
      new ApplicationService(persistence, dataDirectory, security, resolver, transport)
    )
  )
  app.route(
    "/api/research",
    createResearchRoutes(
      new ResearchService(persistence, security, researchAnalyzer, resolver, transport)
    )
  )
  app.route("/api/jobs", createJobsRoutes(jobs))
  app.route(
    "/api/settings",
    createSettingsRoutes({
      operations: persistence.repositories.operations,
      providers: providerRegistry
    })
  )
  app.route(
    "/api/providers",
    createProviderStatusRoutes({
      operations: persistence.repositories.operations,
      providers: providerRegistry
    })
  )
  app.route("/api/disclosures", createDisclosureRoutes(disclosures))
  app.route(
    "/api/documents",
    createDocumentRoutes(new DocumentLibraryService(persistence, dataDirectory, security))
  )
  if (runnerPairing !== undefined) app.route("/api/runners", createRunnerRoutes(runnerPairing))
  const artifacts = new DraftArtifactService(
    new DraftArtifactRepository(persistence.database),
    new CurrentGenerationContextResolver({
      providers: {
        get: (providerId) => {
          const provider = providerRegistry.get(providerId)
          return provider === null
            ? null
            : { descriptor: provider.descriptor, enabled: provider.enabled }
        }
      },
      settings: {
        get: (providerId) =>
          persistence.repositories.operations.getProviderSettings(
            ProviderKindSchema.parse(providerId)
          )
      },
      prompts: promptTemplates
    }),
    persistence.database
  )
  app.route("/api/artifacts", createArtifactRoutes(artifacts))
  const strandsPreparationExecutor = new StrandsPreparationExecutor({
    kernel,
    providers: providerRegistry,
    providerRuns: persistence.repositories.providerArtifacts,
    disclosures,
    sources: new WorkflowSourceContentResolver(persistence.database)
  })
  const activePreparationExecutor = preparationExecutor ?? strandsPreparationExecutor
  app.route(
    "/api/workflows",
    createWorkflowRoutes(
      new PreparationWorkflowService(artifacts, activePreparationExecutor),
      preparationExecutor === undefined ? strandsPreparationExecutor : undefined
    )
  )
  app.route(
    "/api/conversations",
    (() => {
      const strandsChatExecutor = new StrandsChatExecutor({
        kernel,
        providers: providerRegistry,
        providerRuns: persistence.repositories.providerArtifacts,
        disclosures,
        conversations: persistence.repositories.researchConversations,
        sources: new WorkflowSourceContentResolver(persistence.database)
      })
      const activeChatExecutor = chatExecutor ?? strandsChatExecutor
      return createChatRoutes(
        new ChatWorkflowService(
          persistence.repositories.researchConversations,
          activeChatExecutor,
          persistence.database
        ),
        chatExecutor === undefined ? strandsChatExecutor : undefined
      )
    })()
  )
  app.use("/assets/*", serveStatic({ root: "./server/public" }))
  app.get("/", serveStatic({ root: "./server/public" }))
  app.notFound(async (context) => {
    if (context.req.path.startsWith("/api/")) return context.json({ error: "Not found" }, 404)

const index = Bun.file("./server/public/index.html")
    return new Response(index, { headers: { "content-type": "text/html; charset=UTF-8" } })
  })

return app
}

import type { Database } from "bun:sqlite"
import { z } from "zod"

const Id = z.string().uuid()
const Timestamp = z.string().datetime()
const JsonObject = z.record(z.string(), z.json())
export const OutcomeSchema = z.enum(["offered", "rejected", "withdrawn"])

export type PipelineStage = z.output<typeof StageRow>
export type JobPosting = z.output<typeof PostRow>
export type JobPostingVersion = z.output<typeof VersionRow>
export type HiringApplication = z.output<typeof ApplicationRow>

export class ApplicationRepository {
  constructor(private readonly database: Database) {}

stages(): readonly PipelineStage[] {
    return this.database
      .query<unknown, []>(
        "SELECT id,stage_key key,name,position,outcome,is_system system FROM pipeline_stages ORDER BY position"
      )
      .all()
      .map((row) => StageRow.parse(row))
  }
  createStage(input: { id: string; key: string; name: string; createdAt: string }): PipelineStage {
    const position =
      this.database
        .query<{ value: number }, []>(
          "SELECT COALESCE(MAX(position),0)+1 value FROM pipeline_stages"
        )
        .get()?.value ?? 1
    this.database.run(
      "INSERT INTO pipeline_stages (id,stage_key,name,position,is_system,created_at) VALUES (?,?,?,?,0,?)",
      [
        Id.parse(input.id),
        z.string().trim().min(1).max(64).parse(input.key),
        z.string().trim().min(1).max(80).parse(input.name),
        position,
        Timestamp.parse(input.createdAt)
      ]
    )
    return StageRow.parse(
      this.database
        .query<unknown, [string]>(
          "SELECT id,stage_key key,name,position,outcome,is_system system FROM pipeline_stages WHERE id=?"
        )
        .get(input.id)
    )
  }
  renameStage(id: string, name: string): void {
    if (
      this.database.run("UPDATE pipeline_stages SET name=? WHERE id=?", [
        z.string().trim().min(1).max(80).parse(name),
        Id.parse(id)
      ]).changes !== 1
    )
      throw new ApplicationDomainError("stage_not_found")
  }
  reorderStages(ids: readonly string[]): void {
    const parsed = z.array(Id).min(1).parse(ids)
    const current = this.stages().map((stage) => stage.id)
    if (new Set(parsed).size !== current.length || current.some((id) => !parsed.includes(id)))
      throw new ApplicationDomainError("invalid_stage_order")
    this.database
      .transaction(() => {
        this.database.run("UPDATE pipeline_stages SET position=position+10000")
        parsed.forEach((id, index) =>
          this.database.run("UPDATE pipeline_stages SET position=? WHERE id=?", [index + 1, id])
        )
      })
      .immediate()
  }
  deleteStage(id: string): void {
    const parsed = Id.parse(id)
    this.database
      .transaction(() => {
        const changed = this.database.run(
          "DELETE FROM pipeline_stages WHERE id=? AND is_system=0",
          [parsed]
        ).changes
        if (changed !== 1) throw new ApplicationDomainError("stage_not_deletable")
        const remaining = this.stages()
        this.database.run("UPDATE pipeline_stages SET position=position+10000")
        remaining.forEach((stage, index) =>
          this.database.run("UPDATE pipeline_stages SET position=? WHERE id=?", [
            index + 1,
            stage.id
          ])
        )
      })
      .immediate()
  }

createPost(input: {
    id: string
    title: string
    companyName: string
    teamName: string | null
    canonicalUrl: string | null
    metadata: Record<string, unknown>
    createdAt: string
  }): void {
    this.database.run(
      "INSERT INTO job_posts (id,title,company_name,team_name,canonical_url,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)",
      [
        Id.parse(input.id),
        z.string().trim().min(1).max(200).parse(input.title),
        z.string().trim().min(1).max(200).parse(input.companyName),
        z.string().trim().min(1).max(200).nullable().parse(input.teamName),
        z.string().url().nullable().parse(input.canonicalUrl),
        JSON.stringify(JsonObject.parse(input.metadata)),
        Timestamp.parse(input.createdAt)
      ]
    )
  }
  posts(): readonly JobPosting[] {
    return this.database
      .query<unknown, []>(
        `SELECT p.id,p.title,p.company_name companyName,p.team_name teamName,p.canonical_url canonicalUrl,p.metadata_json metadata,p.state,p.current_version_id currentVersionId,v.version_number versionNumber,v.source_kind sourceKind,p.created_at createdAt FROM job_posts p LEFT JOIN job_post_versions v ON v.id=p.current_version_id WHERE p.state!='deleted' ORDER BY p.created_at DESC`
      )
      .all()
      .map((row) => PostRow.parse(row))
  }
  post(id: string): JobPosting | null {
    return this.posts().find((post) => post.id === Id.parse(id)) ?? null
  }
  addPostVersion(input: {
    id: string
    postId: string
    sourceKind: "manual" | "file" | "url"
    bodyBlobHash: string
    content: Record<string, unknown>
    createdAt: string
  }): void {
    this.database
      .transaction(() => {
        const number =
          this.database
            .query<{ value: number }, [string]>(
              "SELECT COALESCE(MAX(version_number),0)+1 value FROM job_post_versions WHERE job_post_id=?"
            )
            .get(Id.parse(input.postId))?.value ?? 1
        this.database.run(
          "INSERT INTO job_post_versions (id,job_post_id,version_number,source_kind,body_blob_hash,structured_content,created_at) VALUES (?,?,?,?,?,?,?)",
          [
            Id.parse(input.id),
            input.postId,
            number,
            input.sourceKind,
            z
              .string()
              .regex(/^[a-f0-9]{64}$/)
              .parse(input.bodyBlobHash),
            JSON.stringify(JsonObject.parse(input.content)),
            Timestamp.parse(input.createdAt)
          ]
        )
        if (
          this.database.run(
            "UPDATE job_posts SET current_version_id=? WHERE id=? AND state='active'",
            [input.id, input.postId]
          ).changes !== 1
        )
          throw new ApplicationDomainError("post_unavailable")
      })
      .immediate()
  }
  versions(postId: string): readonly JobPostingVersion[] {
    return this.database
      .query<unknown, [string]>(
        "SELECT id,job_post_id postId,version_number versionNumber,source_kind sourceKind,body_blob_hash bodyBlobHash,structured_content content,created_at createdAt FROM job_post_versions WHERE job_post_id=? ORDER BY version_number DESC"
      )
      .all(Id.parse(postId))
      .map((row) => VersionRow.parse(row))
  }
  archivePost(id: string, at: string): void {
    if (
      this.database.run(
        "UPDATE job_posts SET state='archived',archived_at=? WHERE id=? AND state='active'",
        [Timestamp.parse(at), Id.parse(id)]
      ).changes !== 1
    )
      throw new ApplicationDomainError("post_unavailable")
  }

applications(): readonly HiringApplication[] {
    return this.database
      .query<unknown, []>(
        `SELECT a.id,a.job_post_id jobPostId,a.idempotency_key idempotencyKey,a.status,a.current_stage_id stageId,s.name stageName,s.position stagePosition,a.applied_at appliedAt,a.outcome_at outcomeAt,a.created_at createdAt,a.archived_at archivedAt FROM applications a JOIN pipeline_stages s ON s.id=a.current_stage_id ORDER BY a.created_at DESC`
      )
      .all()
      .map((row) => ApplicationRow.parse(row))
  }
  application(id: string): HiringApplication | null {
    return this.applications().find((item) => item.id === Id.parse(id)) ?? null
  }
  applicationByKey(key: string): HiringApplication | null {
    return this.applications().find((item) => item.idempotencyKey === Id.parse(key)) ?? null
  }
  createApplication(input: {
    id: string
    postId: string
    idempotencyKey: string
    createdAt: string
  }): HiringApplication {
    const existing = this.applicationByKey(input.idempotencyKey)
    if (existing !== null) {
      if (existing.jobPostId !== input.postId)
        throw new ApplicationDomainError("idempotency_conflict")
      return existing
    }
    const saved = this.stages().find((stage) => stage.key === "saved")
    if (saved === undefined || this.post(input.postId)?.state !== "active")
      throw new ApplicationDomainError("post_unavailable")
    this.database
      .transaction(() => {
        this.database.run(
          "INSERT INTO applications (id,job_post_id,status,idempotency_key,current_stage_id,created_at) VALUES (?,?,?,?,?,?)",
          [
            Id.parse(input.id),
            input.postId,
            "saved",
            Id.parse(input.idempotencyKey),
            saved.id,
            Timestamp.parse(input.createdAt)
          ]
        )
        this.appendEventUnsafe(input.id, "created", { stageId: saved.id }, input.createdAt)
      })
      .immediate()
    return this.requireApplication(input.id)
  }
  transition(input: { applicationId: string; stageId: string; at: string }): HiringApplication {
    const application = this.application(input.applicationId)
    const target = this.stages().find((stage) => stage.id === Id.parse(input.stageId))
    if (application === null || target === undefined || application.archivedAt !== null)
      throw new ApplicationDomainError("transition_denied")
    const current = this.stages().find((stage) => stage.id === application.stageId)
    if (current?.outcome !== null || target.id === application.stageId)
      throw new ApplicationDomainError("transition_denied")
    const status =
      target.outcome ??
      (target.key === "saved" || target.key === "applied" || target.key === "interviewing"
        ? target.key
        : "interviewing")
    this.database
      .transaction(() => {
        this.database.run(
          "UPDATE applications SET current_stage_id=?,status=?,applied_at=CASE WHEN ?='applied' AND applied_at IS NULL THEN ? ELSE applied_at END,outcome_at=CASE WHEN ? IS NOT NULL THEN ? ELSE outcome_at END WHERE id=?",
          [target.id, status, target.key, input.at, target.outcome, input.at, application.id]
        )
        this.appendEventUnsafe(
          application.id,
          "stage_changed",
          { fromStageId: application.stageId, toStageId: target.id, outcome: target.outcome },
          input.at
        )
      })
      .immediate()
    return this.requireApplication(application.id)
  }
  addNote(applicationId: string, text: string, at: string): void {
    this.requireApplication(applicationId)
    this.appendEventUnsafe(
      applicationId,
      "note_added",
      { text: z.string().trim().min(1).max(10_000).parse(text) },
      at
    )
  }
  scheduleInterview(input: {
    id: string
    applicationId: string
    scheduledAt: string
    endedAt: string | null
    kind: string
    location: string | null
    notes: string
    createdAt: string
  }): void {
    this.requireApplication(input.applicationId)
    this.database
      .transaction(() => {
        this.database.run(
          "INSERT INTO application_interviews (id,application_id,scheduled_at,ended_at,interview_kind,location,notes,created_at) VALUES (?,?,?,?,?,?,?,?)",
          [
            Id.parse(input.id),
            input.applicationId,
            Timestamp.parse(input.scheduledAt),
            Timestamp.nullable().parse(input.endedAt),
            z.string().trim().min(1).max(80).parse(input.kind),
            z.string().trim().max(500).nullable().parse(input.location),
            z.string().max(10_000).parse(input.notes),
            Timestamp.parse(input.createdAt)
          ]
        )
        this.appendEventUnsafe(
          input.applicationId,
          "interview_scheduled",
          { interviewId: input.id, scheduledAt: input.scheduledAt, kind: input.kind },
          input.createdAt
        )
      })
      .immediate()
  }
  interviews(applicationId: string) {
    this.requireApplication(applicationId)
    return this.database
      .query<unknown, [string]>(
        "SELECT id,application_id applicationId,scheduled_at scheduledAt,ended_at endedAt,interview_kind kind,location,notes,created_at createdAt FROM application_interviews WHERE application_id=? ORDER BY scheduled_at,id"
      )
      .all(applicationId)
      .map((row) => InterviewRow.parse(row))
  }
  events(applicationId: string) {
    this.requireApplication(applicationId)
    return this.database
      .query<unknown, [string]>(
        "SELECT id,sequence,event_kind kind,payload,created_at createdAt FROM application_events WHERE application_id=? ORDER BY sequence"
      )
      .all(applicationId)
      .map((row) => EventRow.parse(row))
  }
  archiveApplication(id: string, at: string): void {
    if (
      this.database.run(
        "UPDATE applications SET archived_at=? WHERE id=? AND archived_at IS NULL",
        [Timestamp.parse(at), Id.parse(id)]
      ).changes !== 1
    )
      throw new ApplicationDomainError("application_unavailable")
  }
  private requireApplication(id: string) {
    const application = this.application(id)
    if (application === null) throw new ApplicationDomainError("application_unavailable")
    return application
  }
  private appendEventUnsafe(
    applicationId: string,
    kind: string,
    payload: Record<string, unknown>,
    at: string
  ): void {
    const sequence =
      this.database
        .query<{ value: number }, [string]>(
          "SELECT COALESCE(MAX(sequence),0)+1 value FROM application_events WHERE application_id=?"
        )
        .get(applicationId)?.value ?? 1
    this.database.run(
      "INSERT INTO application_events (id,application_id,sequence,event_kind,payload,created_at) VALUES (?,?,?,?,?,?)",
      [
        crypto.randomUUID(),
        applicationId,
        sequence,
        kind,
        JSON.stringify(JsonObject.parse(payload)),
        Timestamp.parse(at)
      ]
    )
  }
}

export class ApplicationDomainError extends Error {
  override readonly name = "ApplicationDomainError"
  constructor(
    readonly code:
      | "application_unavailable"
      | "idempotency_conflict"
      | "invalid_stage_order"
      | "post_unavailable"
      | "stage_not_deletable"
      | "stage_not_found"
      | "transition_denied"
  ) {
    super(`APPLICATION_${code.toUpperCase()}`)
  }
}

export class ApplicationService {
  readonly repository: ApplicationRepository
  constructor(
    private readonly persistence: Persistence,
    private readonly dataDirectory: string,
    private readonly limits: LocalSecuritySettings,
    private readonly resolver?: Resolver,
    private readonly transport?: PinnedTransport,
    private readonly now: () => string = () => new Date().toISOString()
  ) {
    this.repository = new ApplicationRepository(persistence.database)
  }

async createManual(input: PostMetadata & { readonly text: string }) {
    return this.persistPost(input, "manual", input.text, null)
  }
  async createFile(input: PostMetadata & { readonly file: File }) {
    const extracted = await previewFile({
      dataDirectory: this.dataDirectory,
      file: input.file,
      limits: this.limits
    })
    return this.persistPost(input, "file", extracted.text, null)
  }
  async createUrl(input: PostMetadata & { readonly url: string }) {
    const fetched = await fetchPublicText({
      limits: this.limits,
      resolver: this.resolver,
      transport: this.transport,
      url: input.url
    })
    return this.persistPost(input, "url", fetched.text, fetched.url)
  }
  async addManualVersion(postId: string, text: string) {
    return this.persistVersion(postId, "manual", text)
  }
  async addFileVersion(postId: string, file: File) {
    const extracted = await previewFile({
      dataDirectory: this.dataDirectory,
      file,
      limits: this.limits
    })
    return this.persistVersion(postId, "file", extracted.text)
  }
  async addUrlVersion(postId: string, url: string) {
    const fetched = await fetchPublicText({
      limits: this.limits,
      resolver: this.resolver,
      transport: this.transport,
      url
    })
    return this.persistVersion(postId, "url", fetched.text, fetched.url)
  }
  private async persistPost(
    metadata: PostMetadata,
    sourceKind: "manual" | "file" | "url",
    text: string,
    canonicalUrl: string | null
  ) {
    const postId = crypto.randomUUID()
    const at = this.now()
    this.repository.createPost({
      id: postId,
      title: metadata.title,
      companyName: metadata.companyName,
      teamName: metadata.teamName,
      canonicalUrl,
      metadata: {
        location: metadata.location ?? null,
        employmentType: metadata.employmentType ?? null
      },
      createdAt: at
    })
    await this.persistVersion(postId, sourceKind, text, canonicalUrl)
    return this.repository.post(postId)
  }
  private async persistVersion(
    postId: string,
    sourceKind: "manual" | "file" | "url",
    text: string,
    sourceUrl: string | null = null
  ) {
    const normalized = text.trim()
    if (normalized.length === 0) throw new ApplicationServiceError("content_required")
    const blob = await this.persistence.blobs.put(
      new Blob([normalized]),
      "text/plain;charset=utf-8"
    )
    this.persistence.repositories.blobs.register(blob)
    this.repository.addPostVersion({
      id: crypto.randomUUID(),
      postId,
      sourceKind,
      bodyBlobHash: blob.sha256,
      content: { text: normalized, sourceUrl },
      createdAt: this.now()
    })
    return this.repository.post(postId)
  }
}

export class ApplicationServiceError extends Error {
  override readonly name = "ApplicationServiceError"
  constructor(readonly code: "content_required") {
    super(`APPLICATION_${code.toUpperCase()}`)
  }
}

import { createHash } from "node:crypto"

import type { ProviderDescriptor } from "../agents/contracts"
import { containsSecretLikeData } from "../jobs/types"
import {
  PromptTemplateRevisionRegistry,
  type PromptTemplateRevision
} from "../prompts/prompt-template-revisions"

const canonical = (value: unknown): string => {
  if (value === null || typeof value !== "object") return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  return `{${Object.entries(value)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, child]) => `${JSON.stringify(key)}:${canonical(child)}`)
    .join(",")}}`
}
const digest = (value: unknown): string =>
  createHash("sha256").update(canonical(value)).digest("hex")

export type CurrentProviderContext = {
  readonly providerId: string
  readonly mode: "api" | "runner" | "test"
  readonly model: string
  readonly capabilityRevision: string
}
export type ProviderContextResolution =
  | { readonly kind: "current"; readonly context: CurrentProviderContext }
  | { readonly kind: "disabled" }
  | { readonly kind: "unavailable" }
  | { readonly kind: "changed"; readonly context: CurrentProviderContext }

export type CurrentProviderRegistration = {
  readonly descriptor: ProviderDescriptor
  readonly enabled: boolean
}
export type CurrentProviderSettings = {
  readonly selectedModel: string | null
  readonly enabled: boolean
  readonly capabilities: Record<string, unknown>
}
export type CurrentProviderSource = {
  readonly get: (providerId: string) => CurrentProviderRegistration | null
}
export type CurrentProviderSettingsSource = {
  readonly get: (providerId: string) => CurrentProviderSettings | null
}
export type CurrentGenerationContextResolverDependencies = {
  readonly providers: CurrentProviderSource
  readonly settings: CurrentProviderSettingsSource
  readonly prompts: PromptTemplateRevisionRegistry
}

export class CurrentGenerationContextResolver {
  constructor(private readonly dependencies: CurrentGenerationContextResolverDependencies) {}

resolveProvider(providerId: string): ProviderContextResolution {
    const provider = this.dependencies.providers.get(providerId)
    if (provider === null) return { kind: "unavailable" }
    const setting = this.dependencies.settings.get(providerId)
    if (setting === null || containsSecretLikeData(setting.capabilities))
      return { kind: "unavailable" }
    if (!provider.enabled || !setting.enabled) return { kind: "disabled" }
    const context = {
      providerId: provider.descriptor.id,
      mode: provider.descriptor.mode,
      model: provider.descriptor.model.id,
      capabilityRevision: digest({
        descriptorCapabilities: provider.descriptor.capabilities,
        settingCapabilities: setting.capabilities
      })
    } satisfies CurrentProviderContext
    return setting.selectedModel === null || setting.selectedModel === provider.descriptor.model.id
      ? { kind: "current", context }
      : { kind: "changed", context }
  }
  resolvePrompt(templateId: string): PromptTemplateRevision | null {
    return this.dependencies.prompts.get(templateId)
  }
}

const canonical = (value: unknown): string => {
  if (value === null || typeof value !== "object") return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  return `{${Object.entries(value)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, child]) => `${JSON.stringify(key)}:${canonical(child)}`)
    .join(",")}}`
}
const now = (): string => new Date().toISOString()

export class DraftArtifactRepository {
  constructor(private readonly database: Database) {}

createSeries(input: z.input<typeof SeriesCreateSchema>): DraftArtifactSeries {
    const value = SeriesCreateSchema.parse(input)
    this.database.run(
      "INSERT INTO draft_artifact_series (id,kind,status,created_at) VALUES (?,?,?,?)",
      [value.id, value.kind, "draft", now()]
    )
    return { ...value, status: "draft" }
  }
  createRevision(input: z.input<typeof RevisionCreateSchema>): DraftArtifactRevision {
    const value = RevisionCreateSchema.parse(input)
    return this.database
      .transaction(() => {
        const series = this.getSeries(value.seriesId)
        if (series === null || series.status !== "draft")
          throw new DraftArtifactError("ARTIFACT_SERIES_UNAVAILABLE")
        const number =
          this.database
            .query<{ readonly number: number }, [string]>(
              "SELECT COALESCE(MAX(revision_number),0)+1 number FROM draft_artifact_revisions WHERE series_id=?"
            )
            .get(value.seriesId)?.number ?? 1
        const createdAt = now()
        const contentHash = createHash("sha256").update(canonical(value.content)).digest("hex")
        const contentJson = JSON.stringify(value.content)
        this.database.run(
          "INSERT INTO draft_artifact_content_hashes (content_hash,content_json) VALUES (?,?) ON CONFLICT(content_hash) DO NOTHING",
          [contentHash, contentJson]
        )
        this.database.run(
          "INSERT INTO draft_artifact_revisions (id,series_id,revision_number,provider_run_id,disclosure_id,provider_id,provider_mode,provider_model,provider_capability_revision,prompt_template_id,prompt_template_revision,content_hash,content_json,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
          [
            value.id,
            value.seriesId,
            number,
            value.providerRunId,
            value.disclosureId,
            value.providerId,
            value.providerMode,
            value.providerModel,
            value.providerCapabilityRevision,
            value.promptTemplateId,
            value.promptTemplateRevision,
            contentHash,
            contentJson,
            createdAt
          ]
        )
        for (const input of value.inputs) {
          this.database.run(
            "INSERT INTO draft_artifact_inputs (revision_id,input_kind,input_ref_json,source_hash,source_label,source_version,parent_current_id) VALUES (?,?,?,?,?,?,?)",
            [
              value.id,
              input.kind,
              JSON.stringify(input.ref),
              input.hash,
              input.label,
              input.version,
              input.parentCurrentId
            ]
          )
        }
        return RevisionSchema.parse({
          id: value.id,
          seriesId: value.seriesId,
          providerRunId: value.providerRunId,
          disclosureId: value.disclosureId,
          providerId: value.providerId,
          providerMode: value.providerMode,
          providerModel: value.providerModel,
          providerCapabilityRevision: value.providerCapabilityRevision,
          promptTemplateId: value.promptTemplateId,
          promptTemplateRevision: value.promptTemplateRevision,
          number,
          contentHash,
          content: value.content,
          createdAt
        })
      })
      .immediate()
  }
  getSeries(id: string): DraftArtifactSeries | null {
    const row = this.database
      .query<unknown, [string]>("SELECT id,kind,status FROM draft_artifact_series WHERE id=?")
      .get(id)
    return row === null ? null : SeriesSchema.parse(row)
  }
  getRevision(id: string): DraftArtifactRevision | null {
    const row = this.database.query<unknown, [string]>(`${revisionSelect} WHERE id=?`).get(id)
    return row === null ? null : this.revision(row)
  }
  listRevisions(seriesId: string): readonly DraftArtifactRevision[] {
    return this.database
      .query<unknown, [string]>(`${revisionSelect} WHERE series_id=? ORDER BY revision_number`)
      .all(seriesId)
      .map((row) => this.revision(row))
  }
  getStoredProvenance(id: string): DraftArtifactStoredProvenance {
    const revision = this.getRevision(id)
    if (revision === null) throw new DraftArtifactError("ARTIFACT_REVISION_NOT_FOUND")
    const inputs = this.database
      .query<unknown, [string]>(
        "SELECT input_kind kind,input_ref_json ref,source_hash hash,source_label label,source_version version,parent_current_id parentCurrentId FROM draft_artifact_inputs WHERE revision_id=? ORDER BY input_kind,input_ref_json"
      )
      .all(id)
      .map((row) => StoredInputSchema.parse(row))
    return { ...revision, inputs }
  }
  archive(id: string): void {
    this.database.run(
      "UPDATE draft_artifact_series SET status='archived',archived_at=? WHERE id=?",
      [now(), id]
    )
  }
  logicalDelete(id: string): void {
    this.database.run("UPDATE draft_artifact_series SET status='deleted',deleted_at=? WHERE id=?", [
      now(),
      id
    ])
  }
  private revision(row: unknown): DraftArtifactRevision {
    const raw = z.object({ ...RevisionSchema.shape, content: z.string() }).parse(row)
    return RevisionSchema.parse({ ...raw, content: JSON.parse(raw.content) })
  }
}

const revisionSelect =
  "SELECT id,series_id seriesId,revision_number number,provider_run_id providerRunId,disclosure_id disclosureId,provider_id providerId,provider_mode providerMode,provider_model providerModel,provider_capability_revision providerCapabilityRevision,prompt_template_id promptTemplateId,prompt_template_revision promptTemplateRevision,content_hash contentHash,content_json content,created_at createdAt FROM draft_artifact_revisions"

export class DraftArtifactError extends Error {
  override readonly name = "DraftArtifactError"
  constructor(readonly code: "ARTIFACT_SERIES_UNAVAILABLE" | "ARTIFACT_REVISION_NOT_FOUND") {
    super(code)
  }
}

import { z } from "zod"

import {
  DisclosureInputRefSchema,
  DisclosureSourceError,
  DisclosureSourceResolver
} from "../disclosures/sources"
import type { DisclosureInputRef } from "../disclosures/sources"
import type {
  CurrentGenerationContextResolver,
  ProviderContextResolution
} from "./current-generation-context"
import type {
  DraftArtifactRepository,
  DraftArtifactRevision,
  DraftArtifactSeries
} from "./draft-artifact-repository"

export class DraftArtifactService {
  private readonly sources: DisclosureSourceResolver
  constructor(
    private readonly repository: DraftArtifactRepository,
    private readonly current: CurrentGenerationContextResolver,
    database: ConstructorParameters<typeof DisclosureSourceResolver>[0]
  ) {
    this.sources = new DisclosureSourceResolver(database)
  }
  createSeries(input: {
    readonly id: string
    readonly kind: DraftArtifactSeries["kind"]
  }): DraftArtifactSeries {
    return this.repository.createSeries(input)
  }
  getSeries(id: string): DraftArtifactSeries | null {
    return this.repository.getSeries(id)
  }
  validateInputs(inputs: readonly DisclosureInputRef[]): void {
    for (const input of inputs) this.sources.resolve(input)
  }
  createRevision(input: DraftArtifactRevisionInput): DraftArtifactRevision {
    const value = RevisionCreateSchema.parse(input)
    const provider = this.current.resolveProvider(value.providerId)
    if (provider.kind !== "current") throw new CurrentGenerationContextError(provider.kind)
    const prompt = this.current.resolvePrompt(value.promptTemplateId)
    if (prompt === null) throw new CurrentGenerationContextError("prompt_missing")
    return this.repository.createRevision({
      ...value,
      providerId: provider.context.providerId,
      providerMode: provider.context.mode,
      providerModel: provider.context.model,
      providerCapabilityRevision: provider.context.capabilityRevision,
      promptTemplateId: prompt.id,
      promptTemplateRevision: prompt.revision,
      inputs: value.inputs.map((ref) => {
        const resolved = this.sources.resolve(ref)
        return {
          kind: ref.kind,
          ref,
          hash: resolved.hash,
          label: resolved.label,
          version: resolved.version,
          parentCurrentId: resolved.parentCurrentId
        }
      })
    })
  }
  getRevision(id: string): DraftArtifactRevision | null {
    return this.repository.getRevision(id)
  }
  listRevisions(seriesId: string): readonly DraftArtifactRevision[] {
    return this.repository.listRevisions(seriesId)
  }
  getProvenance(id: string): DraftArtifactProvenance {
    const stored = this.repository.getStoredProvenance(id)
    const reasons = new Set<DraftArtifactStaleReason>()
    for (const input of stored.inputs) {
      const ref = DisclosureInputRefSchema.parse(input.ref)
      try {
        const current = this.sources.resolve(ref)
        if (current.hash !== input.hash) reasons.add("source_content_changed")
        if (current.parentCurrentId !== input.parentCurrentId)
          reasons.add("source_current_version_changed")
      } catch (error) {
        if (error instanceof DisclosureSourceError) reasons.add("source_unavailable")
        else throw error
      }
    }
    this.addProviderReasons({ stored, reasons })
    const prompt = this.current.resolvePrompt(stored.promptTemplateId)
    if (prompt === null) reasons.add("prompt_missing")
    else if (prompt.revision !== stored.promptTemplateRevision) reasons.add("prompt_changed")
    return {
      ...stored,
      inputs: stored.inputs.map((input) => ({
        ref: DisclosureInputRefSchema.parse(input.ref),
        hash: input.hash,
        label: input.label,
        version: input.version
      })),
      staleReasons: [...reasons].sort()
    }
  }
  archive(id: string): void {
    this.repository.archive(id)
  }
  logicalDelete(id: string): void {
    this.repository.logicalDelete(id)
  }
  private addProviderReasons(input: {
    readonly stored: DraftArtifactRevision
    readonly reasons: Set<DraftArtifactStaleReason>
  }): void {
    const resolution = this.current.resolveProvider(input.stored.providerId)
    if (resolution.kind === "disabled") input.reasons.add("provider_disabled")
    if (resolution.kind === "unavailable") input.reasons.add("provider_unavailable")
    if (resolution.kind === "changed") this.addChangedProviderReasons({ ...input, resolution })
    if (resolution.kind === "current") this.addCurrentProviderReasons({ ...input, resolution })
  }
  private addChangedProviderReasons(input: {
    readonly stored: DraftArtifactRevision
    readonly resolution: Extract<ProviderContextResolution, { readonly kind: "changed" }>
    readonly reasons: Set<DraftArtifactStaleReason>
  }): void {
    this.addCurrentProviderReasons(input)
    input.reasons.add("provider_changed")
  }
  private addCurrentProviderReasons(input: {
    readonly stored: DraftArtifactRevision
    readonly resolution: Extract<ProviderContextResolution, { readonly context: unknown }>
    readonly reasons: Set<DraftArtifactStaleReason>
  }): void {
    if (input.resolution.context.mode !== input.stored.providerMode)
      input.reasons.add("mode_changed")
    if (input.resolution.context.model !== input.stored.providerModel)
      input.reasons.add("model_changed")
    if (input.resolution.context.capabilityRevision !== input.stored.providerCapabilityRevision)
      input.reasons.add("provider_changed")
  }
}

export class CurrentGenerationContextError extends Error {
  override readonly name = "CurrentGenerationContextError"
  constructor(readonly code: "disabled" | "unavailable" | "changed" | "prompt_missing") {
    super(`CURRENT_GENERATION_CONTEXT_${code.toUpperCase()}`)
  }
}

const formatIssue = (issue: StartupConfigurationIssue): string => `${issue.field}: ${issue.code}`

export class StartupConfigurationError extends Error {
  override readonly name = "StartupConfigurationError"

constructor(readonly issues: readonly StartupConfigurationIssue[]) {
    super(`CONFIGURATION_ERROR: ${issues.map(formatIssue).join(", ")}`)
  }
}

type SchemaIssue = {
  readonly path: readonly PropertyKey[]
}

const toStartupConfigurationIssue = (
  issue: SchemaIssue,
  environment: RawEnvironment
): StartupConfigurationIssue => {
  const field = issue.path[0] === "PORT" ? "PORT" : "DATA_DIR"

return {
    field,
    code: environment[field] === undefined ? "missing" : "invalid"
  }
}

export const parseServerConfig = (environment: RawEnvironment): ServerConfig => {
  const parsed = ServerEnvironmentSchema.safeParse(environment)

if (!parsed.success) {
    throw new StartupConfigurationError(
      parsed.error.issues.map((issue) => toStartupConfigurationIssue(issue, environment))
    )
  }

const security = (() => {
    try {
      return parseLocalSecuritySettings(environment, parsed.data.PORT)
    } catch (error) {
      if (error instanceof LocalSecurityConfigurationError)
        throw new StartupConfigurationError([{ field: "SECURITY", code: "invalid" }])
      throw error
    }
  })()

return {
    port: parsed.data.PORT,
    dataDirectory: resolve(parsed.data.DATA_DIR),
    security
  }
}

export const ensureDataDirectoryIsWritable = ({ dataDirectory }: ServerConfig): void => {
  try {
    mkdirSync(dataDirectory, { recursive: true })
    accessSync(dataDirectory, constants.W_OK)
  } catch (error) {
    if (error instanceof Error) {
      throw new StartupConfigurationError([{ field: "DATA_DIR", code: "unavailable" }])
    }

throw error
  }
}

