  .string()
  .transform((value, context) => {
    try {
      return JSON.parse(value)
    } catch {
      context.addIssue({ code: "custom", message: "Invalid JSON object" })
      return z.NEVER
    }
  })
  .pipe(JsonObjectSchema)
