            )
            .get(value.applicationId)?.sequence ?? 1
        this.database.run(
          "INSERT INTO application_events (id,application_id,sequence,event_kind,payload,created_at) VALUES (?,?,?,?,?,?)",
          [
            value.id,
            value.applicationId,
            sequence,
            value.kind,
