const assertNever = (value: never): never => {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`)
}

export const jobPostIdForScope = (scope: ResearchScope): JobPostId | null => {
  switch (scope.kind) {
    case "global":
      return null
    case "job_post":
      return scope.jobPostId
    default:
      return assertNever(scope)
  }
