const error = (context: Context, value: unknown) => {
  if (value instanceof IngestionError)
    return context.json(
      safeErrorCode(value, value.code),
      value.code === "FILE_TOO_LARGE" ? 413 : 422
    )
  if (value instanceof DocumentServiceError || value instanceof DocumentLibraryError)
    return context.json(
      safeErrorCode(value, value.code.toUpperCase()),
      value.code === "not_found" ? 404 : 409
    )
  return context.json(safeErrorCode(value, "DOCUMENT_OPERATION_FAILED"), 400)
}

export const createDocumentRoutes = (documents: DocumentLibraryService): Hono => {
  const routes = new Hono()
  routes.get("/", (context) => context.json({ documents: documents.list() }))
  routes.get("/context", (context) => context.json({ documents: documents.selectedContext() }))
  routes.post("/upload", async (context) => {
    try {
      const form = await context.req.formData()
      const files = form.getAll("files").filter((value): value is File => value instanceof File)
      const kind = DocumentKindSchema.parse(form.get("kind"))
      if (files.length === 0) return context.json({ error: { code: "FILE_REQUIRED" } }, 400)
      const uploaded = []
      for (const file of files) uploaded.push(await documents.upload({ file, kind }))
      return context.json({ documents: uploaded }, 201)
    } catch (value) {
      return error(context, value)
    }
  })
  routes.post("/manual", async (context) => {
    try {
      return context.json(await documents.manual(ManualSchema.parse(await context.req.json())), 201)
    } catch (value) {
      return error(context, value)
    }
  })
  routes.get("/:id", (context) => {
    const document = documents.get(context.req.param("id"))
    return document === null
      ? context.json({ error: { code: "NOT_FOUND" } }, 404)
      : context.json(document)
  })
  routes.get("/:id/versions", (context) => {
    try {
      return context.json({ versions: documents.versions(context.req.param("id")) })
    } catch (value) {
      return error(context, value)
    }
  })
  routes.post("/:id/versions", async (context) => {
    try {
      const current = documents.get(context.req.param("id"))
      if (current === null) return context.json({ error: { code: "NOT_FOUND" } }, 404)
      const form = await context.req.formData()
      const file = form.get("file")
      if (!(file instanceof File)) return context.json({ error: { code: "FILE_REQUIRED" } }, 400)
      return context.json(
        await documents.upload({ file, kind: current.kind, documentId: current.id }),
        201
      )
    } catch (value) {
      return error(context, value)
    }
  })
  routes.get("/:id/preview", (context) => {
    try {
      return context.json(documents.preview(context.req.param("id")))
    } catch (value) {
      return error(context, value)
    }
  })
  routes.get("/:id/download", (context) => {
    try {
      const download = documents.download(context.req.param("id"))
      return new Response(download.file, {
        headers: {
          "Content-Type": download.mediaType,
          "Content-Disposition": `attachment; filename*=UTF-8''${encodeURIComponent(download.name)}`,
          "X-Content-Type-Options": "nosniff"
        }
      })
    } catch (value) {
      return error(context, value)
    }
  })
  routes.put("/:id/selection", (context) => {
    try {
      documents.repository.select(context.req.param("id"), true, new Date().toISOString())
      return context.body(null, 204)
    } catch (value) {
      return error(context, value)
    }
  })
  routes.delete("/:id/selection", (context) => {
    try {
      documents.repository.select(context.req.param("id"), false, new Date().toISOString())
      return context.body(null, 204)
    } catch (value) {
      return error(context, value)
    }
  })
  for (const [path, state] of [
    ["archive", "archived"],
    ["delete", "deleted"]
  ] as const)
    routes.post(`/:id/${path}`, (context) => {
      try {
        documents.repository.transition(context.req.param("id"), state, new Date().toISOString())
        return context.body(null, 204)
      } catch (value) {
        return error(context, value)
      }
    })
  return routes
}

export class JobSseSession {
  private readonly buffered: JobEvent[] = []
  private readonly pending: JobEvent[] = []
  private lastEventId: string | null
  private latestSequence: number
  private overflowed = false
  private replaying = true
  private stopped = false
  private terminal = false
  private writing = false

constructor(
    private readonly writer: JobSseWriter,
    private readonly options: JobSseSessionOptions
  ) {
    this.lastEventId = options.initialEventId
    this.latestSequence = options.initialSequence
  }

get isTerminal(): boolean {
    return this.terminal
  }

get isStopped(): boolean {
    return this.stopped
  }

get pendingEventCount(): number {
    return this.buffered.length + this.pending.length
  }

receive(event: JobEvent): void {
    if (this.terminal || this.overflowed) return
    const target = this.replaying ? this.buffered : this.pending
    if (target.length >= this.options.maxBufferedEvents) {
      this.overflow()
      return
    }
    target.push(event)
    if (!this.replaying) void this.drain()
  }

async replay(events: readonly JobEvent[]): Promise<void> {
    for (const event of events) {
      if (this.overflowed || this.terminal) return
      await this.writeEvent(event)
    }
    while (this.buffered.length > 0 && !this.overflowed && !this.terminal) {
      const buffered = this.buffered.splice(0).sort((left, right) => left.sequence - right.sequence)
      for (const event of buffered) await this.writeEvent(event)
    }
    this.replaying = false
  }

async heartbeat(): Promise<void> {
    if (this.overflowed || this.terminal || this.writing || this.pending.length > 0) return
    this.writing = true
    try {
      await this.writer.write(": heartbeat\n\n")
    } finally {
      this.writing = false
    }
  }

private async drain(): Promise<void> {
    if (this.writing || this.overflowed || this.terminal) return
    this.writing = true
    try {
      while (this.pending.length > 0 && !this.overflowed && !this.terminal) {
        const event = this.pending.shift()
        if (event !== undefined) await this.send(event)
      }
    } finally {
      this.writing = false
    }
  }

private overflow(): void {
    this.overflowed = true
    this.pending.splice(0)
    this.buffered.splice(0)
    const signal = { code: "EVENT_REPLAY_REQUIRED", lastEventId: this.lastEventId } as const
    this.options.onOverflow(signal)
    if (this.writing) {
      this.stop()
      return
    }
    this.writing = true
    void this.writer
      .writeSSE({ event: "replay_required", data: JSON.stringify(signal) })
      .then(() => {
        this.stop()
      })
  }

private async writeEvent(event: JobEvent): Promise<void> {
    this.writing = true
    try {
      await this.send(event)
    } finally {
      this.writing = false
    }
  }

private async send(event: JobEvent): Promise<void> {
    if (event.sequence <= this.latestSequence) return
    this.latestSequence = event.sequence
    await this.writer.writeSSE({ id: event.id, event: event.kind, data: JSON.stringify(event) })
    this.lastEventId = event.id
    if (isTerminalJobState(event.kind)) {
      this.terminal = true
      this.options.onTerminal()
    }
  }

private stop(): void {
    if (this.stopped) return
    this.stopped = true
    this.options.onStop()
  }
}

const waitForHeartbeat = (signal: AbortSignal, milliseconds: number): Promise<void> =>
  new Promise((resolve) => {
    const timer = setTimeout(done, milliseconds)
    const cancel = (): void => {
      clearTimeout(timer)
      done()
    }
    function done(): void {
      signal.removeEventListener("abort", cancel)
      resolve()
    }
    signal.addEventListener("abort", cancel, { once: true })
  })

export const createJobsRoutes = (runtime: JobRuntime, options: JobsRouteOptions = {}): Hono => {
  const app = new Hono()
  const heartbeatMilliseconds = options.heartbeatMilliseconds ?? 15_000
  const maxBufferedEvents = options.maxBufferedEvents ?? 64

app.post("/", async (context) => {
    if (!hasJsonContentType(context.req.header("content-type")))
      return error("JOB_CONTENT_TYPE_INVALID", 400)
    let payload: unknown
    try {
      payload = await context.req.json()
    } catch {
      return error("JOB_REQUEST_MALFORMED", 400)
    }
    if (hasInput(payload)) {
      try {
        assertSecretFreeJobInput(payload.input)
      } catch (caught) {
        if (caught instanceof JobInputSecretError) return error(caught.message, 400)
        throw caught
      }
    }
    const body = EnqueueSchema.safeParse(payload)
    if (!body.success) return error("JOB_REQUEST_INVALID", 400)
    try {
      return context.json(runtime.enqueue(body.data), 201)
    } catch (caught) {
      if (caught instanceof JobInputSecretError) return error(caught.message, 400)
      if (caught instanceof UnknownJobKindError) return error("UNKNOWN_JOB_KIND", 400)
      if (caught instanceof IdempotencyConflictError) return error("IDEMPOTENCY_CONFLICT", 409)
      throw caught
    }
  })

app.get("/", (context) => context.json(runtime.repository.list()))
  app.get("/:id", (context) => {
    const job = runtime.repository.get({ id: context.req.param("id") })
    return job === null ? error("JOB_NOT_FOUND", 404) : context.json(job)
  })
  app.post("/:id/cancel", (context) => {
    try {
      return context.json(runtime.cancel(context.req.param("id")))
    } catch (caught) {
      if (caught instanceof JobTransitionError) return error(caught.code, 404)
      throw caught
    }
  })
  app.get("/:id/events", (context) => {
    const id = context.req.param("id")
    const job = runtime.repository.get({ id })
    if (job === null) return error("JOB_NOT_FOUND", 404)
    const transport = TransportSchema.safeParse(context.req.query("transport") ?? "sse")
    if (!transport.success) return error("EVENT_TRANSPORT_INVALID", 400)
    const rawLastEventId = context.req.header("last-event-id")
    const lastEventId =
      rawLastEventId === undefined ? null : LastEventIdSchema.safeParse(rawLastEventId)
    if (lastEventId !== null && !lastEventId.success) return error("LAST_EVENT_ID_INVALID", 400)
    const eventId = lastEventId === null ? null : lastEventId.data
    if (transport.data === "poll") {
      const replay = runtime.repository.eventsAfter({ id, eventId })
      return replay.kind === "reset"
        ? error(replay.code, 409)
        : context.json({ events: replay.events })
    }

const replay = runtime.repository.eventsAfter({ id, eventId })
    if (replay.kind === "reset") return error(replay.code, 409)
    const cursor =
      eventId === null
        ? null
        : runtime.repository.events({ id }).find((event) => event.id === eventId)
    const initialEventId = cursor?.id ?? null
    const initialSequence = cursor?.sequence ?? 0
    if (isTerminalJobState(job.state))
      return streamSSE(context, async (stream) => {
        const session = new JobSseSession(stream, {
          initialEventId,
          initialSequence,
          maxBufferedEvents,
          onOverflow: (signal) => options.onOverflow?.(id, signal),
          onStop: () => undefined,
          onTerminal: () => undefined
        })
        await session.replay(replay.events)
      })

const buffered: JobEvent[] = []
    let session: JobSseSession | null = null
    const unsubscribe = runtime.subscribe(id, (event) => {
      if (session === null) buffered.push(event)
      else session.receive(event)
    })
    options.onSubscribe?.(id)
    const liveReplay = runtime.repository.eventsAfter({ id, eventId })
    if (liveReplay.kind === "reset") {
      unsubscribe()
      return error(liveReplay.code, 409)
    }
    return streamSSE(context, async (stream) => {
      const wake = new AbortController()
      let cleaned = false
      const cleanup = (): void => {
        if (cleaned) return
        cleaned = true
        unsubscribe()
        options.onUnsubscribe?.(id)
      }
      stream.onAbort(() => {
        wake.abort()
        cleanup()
      })
      session = new JobSseSession(stream, {
        initialEventId,
        initialSequence,
        maxBufferedEvents,
        onOverflow: (signal) => options.onOverflow?.(id, signal),
        onStop: () => {
          wake.abort()
          cleanup()
        },
        onTerminal: () => wake.abort()
      })
      for (const event of buffered) session.receive(event)
      try {
        options.afterReplaySnapshot?.(id)
        await session.replay(liveReplay.events)
        while (!stream.aborted && !session.isStopped && !session.isTerminal) {
          await session.heartbeat()
          await waitForHeartbeat(wake.signal, heartbeatMilliseconds)
        }
      } finally {
        wake.abort()
        cleanup()
      }
    })
  })
  return app
}

const readUrl = async (request: Request): Promise<string | undefined> => {
  try {
    const payload: unknown = await request.json()
    if (
      typeof payload !== "object" ||
      payload === null ||
      !("url" in payload) ||
      typeof payload.url !== "string"
    )
      return undefined
    return payload.url
  } catch {
    return undefined
  }
}

export const createPreviewRoutes = ({
  dataDirectory,
  limits,
  resolver,
  transport
}: PreviewRouteDependencies): Hono => {
  const app = new Hono()

app.post("/file", async (context) => {
    const form = await context.req.formData()
    const file = form.get("file")
    if (!(file instanceof File)) return context.json(safeErrorCode(undefined, "FILE_REQUIRED"), 400)
    try {
      return context.json(await previewFile({ dataDirectory, file, limits }))
    } catch (error) {
      if (error instanceof IngestionError)
        return context.json(safeErrorCode(error, error.code), statusForIngestionError(error))
      return context.json(safeErrorCode(error, "EXTRACTION_FAILED"), 422)
    }
  })

