      if (error instanceof FetchBoundaryError)
        return context.json(
          safeErrorCode(error, error.code),
          error.code === "FETCH_TOO_LARGE" ? 413 : 422
        )
      return context.json(safeErrorCode(error, "FETCH_FAILED"), 422)
    }
  })

return app
}

