import {
  CompletionSchema,
  FailureSchema,
  HeartbeatSchema,
  OutputSchema,
  type RunnerClaim
} from "@interview-helper/runner"

type RunnerOutput = {
  readonly sequence: number
  readonly stream: "stdout" | "stderr"
  readonly chunk: string
}
export type RunnerLeaseSnapshot = {
  readonly claim: RunnerClaim
  readonly state: "claimed" | "running" | "completed" | "failed" | "cancelled"
  readonly outputs: readonly RunnerOutput[]
}

export class RunnerLeaseLedger {
  private readonly leases = new Map<string, RunnerLeaseSnapshot>()

claim(claim: RunnerClaim): RunnerLeaseSnapshot {
    const existing = this.leases.get(claim.runId)
    if (existing !== undefined) {
      if (
        existing.claim.leaseId !== claim.leaseId ||
        existing.claim.requestHash !== claim.requestHash
      )
        throw new RunnerLeaseError("claim_conflict")
      return existing
    }
    const snapshot = { claim, state: "claimed", outputs: [] } as const
    this.leases.set(claim.runId, snapshot)
    return snapshot
  }

acknowledge(message: unknown): RunnerLeaseSnapshot {
    const heartbeat = HeartbeatSchema.safeParse(message)
    if (!heartbeat.success) throw new RunnerLeaseError("invalid_message")
    const current = this.active(heartbeat.data.runId, heartbeat.data.leaseId)
    return this.replace(current, { ...current, state: "running" })
  }

output(message: unknown): RunnerLeaseSnapshot {
    const value = OutputSchema.parse(message)
    const current = this.active(value.runId, value.leaseId)
    const expected = current.outputs.length + 1
    if (value.sequence !== expected) {
      const duplicate = current.outputs[value.sequence - 1]
      if (
        duplicate?.sequence === value.sequence &&
        duplicate.stream === value.stream &&
        duplicate.chunk === value.chunk
      )
        return current
      throw new RunnerLeaseError("sequence_conflict")
    }
    return this.replace(current, {
      ...current,
      state: "running",
      outputs: [
        ...current.outputs,
        { sequence: value.sequence, stream: value.stream, chunk: value.chunk }
      ]
    })
  }

complete(message: unknown): RunnerLeaseSnapshot {
    const value = CompletionSchema.parse(message)
    const current = this.active(value.runId, value.leaseId)
    return this.replace(current, { ...current, state: "completed" })
  }

fail(message: unknown): RunnerLeaseSnapshot {
    const value = FailureSchema.parse(message)
    const current = this.active(value.runId, value.leaseId)
    return this.replace(current, {
      ...current,
      state: value.code === "cancelled" ? "cancelled" : "failed"
    })
  }

reconnect(runId: string, leaseId: string): RunnerLeaseSnapshot {
    const current = this.leases.get(runId)
    if (current === undefined || current.claim.leaseId !== leaseId)
      throw new RunnerLeaseError("lease_denied")
    return current
  }

private active(runId: string, leaseId: string): RunnerLeaseSnapshot {
    const current = this.reconnect(runId, leaseId)
    if (["completed", "failed", "cancelled"].includes(current.state))
      throw new RunnerLeaseError("terminal")
    return current
  }

private replace(
    current: RunnerLeaseSnapshot,
    replacement: RunnerLeaseSnapshot
  ): RunnerLeaseSnapshot {
    this.leases.set(current.claim.runId, replacement)
    return replacement
  }
}

export class RunnerLeaseError extends Error {
  override readonly name = "RunnerLeaseError"
  constructor(
    readonly code:
      "claim_conflict" | "invalid_message" | "lease_denied" | "sequence_conflict" | "terminal"
  ) {
    super(`RUNNER_LEASE_${code.toUpperCase()}`)
  }
}

export class RunnerPairingService {
  private readonly pending = new Map<string, PendingPairing>()
  private readonly operations: OperationsRepositories

constructor(
    private readonly database: Database,
    private readonly now: () => number = Date.now
  ) {
    this.operations = new OperationsRepositories(database)
  }

issueCode(): { readonly code: string; readonly expiresAt: string } {
    const code = randomBytes(4).toString("hex").toUpperCase()
    const expiresAt = this.now() + 5 * 60_000
    this.pending.set(digest(code), { hash: digest(code), expiresAt })
    return { code: PairingCodeSchema.parse(code), expiresAt: new Date(expiresAt).toISOString() }
  }

pair(input: {
    readonly code: string
    readonly runnerName: string
    readonly capabilities: unknown
  }): { readonly runnerId: string; readonly token: string } {
    const code = PairingCodeSchema.parse(input.code)
    const pairingHash = digest(code)
    const pending = this.pending.get(pairingHash)
    this.pending.delete(pairingHash)
    if (pending === undefined || pending.expiresAt < this.now())
      throw new RunnerPairingError("pairing_denied")
    const token = randomBytes(32).toString("base64url")
    const runnerId = crypto.randomUUID()
    const timestamp = new Date(this.now()).toISOString()
    const registration = this.operations.upsertRunnerRegistration({
      id: runnerId,
      runnerName: RunnerNameSchema.parse(input.runnerName),
      tokenHash: digest(token),
      capabilities: RunnerCapabilitiesSchema.parse(input.capabilities),
      status: "active",
      registeredAt: timestamp,
      lastSeenAt: timestamp,
      revokedAt: null
    })
    return { runnerId: registration.id, token }
  }

authenticate(input: { readonly runnerId: string; readonly token: string }): boolean {
    return this.authorize(input) !== null
  }

authorize(input: {
    readonly runnerId: string
    readonly token: string
  }): { readonly capabilities: z.output<typeof RunnerCapabilitiesSchema> } | null {
    const row = this.database
      .query<
        { readonly tokenHash: string; readonly status: string; readonly capabilities: string },
        [string]
      >(
        "SELECT token_hash tokenHash,status,capability_json capabilities FROM runner_registrations WHERE id=?"
      )
      .get(z.string().uuid().parse(input.runnerId))
    if (row === null || row.status !== "active") return null
    const actual = Buffer.from(digest(input.token), "hex")
    const expected = Buffer.from(row.tokenHash, "hex")
    if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) return null
    this.touch(input.runnerId)
    return { capabilities: RunnerCapabilitiesSchema.parse(JSON.parse(row.capabilities)) }
  }

touch(runnerId: string): void {
    this.database.run(
      "UPDATE runner_registrations SET last_seen_at=? WHERE id=? AND status='active'",
      [new Date(this.now()).toISOString(), z.string().uuid().parse(runnerId)]
    )
  }

revoke(runnerName: string): void {
    const timestamp = new Date(this.now()).toISOString()
    this.database.run(
      "UPDATE runner_registrations SET status='revoked',revoked_at=?,last_seen_at=? WHERE runner_name=? AND status='active'",
      [timestamp, timestamp, RunnerNameSchema.parse(runnerName)]
    )
  }
}

const digest = (value: string): string => createHash("sha256").update(value).digest("hex")

export class RunnerPairingError extends Error {
  override readonly name = "RunnerPairingError"
  constructor(readonly code: "pairing_denied") {
    super("RUNNER_PAIRING_DENIED")
  }
}

export class RunnerWebSocketHub implements CliRunnerTransport {
  private readonly sockets = new Set<HubSocket>()
  private readonly pending = new Map<string, PendingRun>()
  private readonly leases = new RunnerLeaseLedger()

constructor(private readonly pairing: RunnerPairingService) {}

connected(provider: CliProviderId): boolean {
    return [...this.sockets].some(
      (socket) => socket.data.runnerId !== null && socket.data.capabilities.has(provider)
    )
  }

open(socket: HubSocket): void {
    this.sockets.add(socket)
  }

close(socket: HubSocket): void {
    this.sockets.delete(socket)
  }

async message(socket: HubSocket, raw: string): Promise<void> {
    let value: unknown
    try {
      value = JSON.parse(raw)
    } catch {
      socket.close(1008, "invalid_protocol")
      return
    }
    if (socket.data.runnerId === null) {
      const pair = PairRequestSchema.safeParse(value)
      if (pair.success) {
        const accepted = this.pairing.pair({
          code: pair.data.pairingCode,
          runnerName: pair.data.runnerName,
          capabilities: { protocolVersion: 1, ...pair.data.capabilities }
        })
        socket.data.runnerId = accepted.runnerId
        socket.data.capabilities = providerCapabilities(pair.data.capabilities)
        socket.send(
          JSON.stringify({
            version: RUNNER_PROTOCOL_VERSION,
            type: "pair_accepted",
            ...accepted,
            expiresAt: null
          })
        )
        return
      }
      const auth = AuthenticateSchema.safeParse(value)
      const authenticated = auth.success ? this.pairing.authorize(auth.data) : null
      if (!auth.success || authenticated === null) {
        socket.close(1008, "authentication_failed")
        return
      }
      socket.data.runnerId = auth.data.runnerId
      socket.data.capabilities = providerCapabilities(authenticated.capabilities)
      for (const pending of this.pending.values())
        if (pending.runnerId === auth.data.runnerId) socket.send(JSON.stringify(pending.claim))
      return
    }
    const message = RunnerOutboundMessageSchema.safeParse(value)
    if (
      !message.success ||
      message.data.type === "pair_request" ||
      message.data.type === "authenticate"
    ) {
      socket.close(1008, "invalid_protocol")
      return
    }
    const data = message.data
    if (data.type === "ack" || data.type === "heartbeat") {
      this.leases.acknowledge({ ...data, type: "heartbeat" })
      this.pairing.touch(socket.data.runnerId)
      return
    }
    const pending = this.pending.get(data.runId)
    if (pending === undefined) return
    if (data.type === "output") {
      this.leases.output(data)
      if (pending.processedSequences.has(data.sequence)) return
      pending.processedSequences.add(data.sequence)
      if (data.stream === "stdout") {
        pending.stdoutBuffer += data.chunk
        const lines = pending.stdoutBuffer.split("\n")
        pending.stdoutBuffer = lines.pop() ?? ""
        for (const line of lines.filter(Boolean)) {
          const normalized = normalizeCliOutputLine(pending.claim.provider, line)
          if (normalized !== null) pending.queue.push(normalized)
        }
      }
      return
    }
    if (data.type === "completion") {
      this.leases.complete(data)
      if (pending.stdoutBuffer.length > 0) {
        const normalized = normalizeCliOutputLine(pending.claim.provider, pending.stdoutBuffer)
        if (normalized !== null) pending.queue.push(normalized)
      }
      pending.queue.end()
    } else if (data.type === "failure") {
      this.leases.fail(data)
      pending.queue.fail(new RunnerHubError(data.code))
    }
    this.pending.delete(data.runId)
  }

async *stream(input: {
    readonly provider: CliProviderId
    readonly model: string
    readonly prompt: string
    readonly signal?: AbortSignal
  }): AsyncIterable<CliTransportEvent> {
    const socket = [...this.sockets].find(
      (candidate) =>
        candidate.data.runnerId !== null && candidate.data.capabilities.has(input.provider)
    )
    if (socket === undefined) throw new RunnerHubError("runner_unavailable")
    const runnerId = socket.data.runnerId
    if (runnerId === null) throw new RunnerHubError("runner_unavailable")
    const claim = {
      version: RUNNER_PROTOCOL_VERSION,
      type: "claim",
      runId: crypto.randomUUID(),
      leaseId: crypto.randomUUID(),
      provider: input.provider,
      model: input.model,
      prompt: input.prompt,
      requestHash: createHash("sha256").update(input.prompt).digest("hex"),
      deadline: new Date(Date.now() + 120_000).toISOString()
    } satisfies RunnerClaim
    const queue = new AsyncEventQueue()
    this.leases.claim(claim)
    this.pending.set(claim.runId, {
      claim,
      queue,
      runnerId,
      processedSequences: new Set(),
      stdoutBuffer: ""
    })
    const cancel = (): void =>
      socket.send(
        JSON.stringify({
          version: RUNNER_PROTOCOL_VERSION,
          type: "cancel",
          runId: claim.runId,
          leaseId: claim.leaseId
        })
      )
    input.signal?.addEventListener("abort", cancel, { once: true })
    socket.send(JSON.stringify(claim))
    try {
      yield* queue
    } finally {
      input.signal?.removeEventListener("abort", cancel)
      this.pending.delete(claim.runId)
    }
  }
}

push(value: CliTransportEvent): void {
    this.values.push(value)
    this.waiters.shift()?.()
  }
  end(): void {
    this.done = true
    this.waiters.shift()?.()
  }
  fail(error: Error): void {
    this.error = error
    this.waiters.shift()?.()
  }
  async *[Symbol.asyncIterator](): AsyncIterator<CliTransportEvent> {
    for (;;) {
      const value = this.values.shift()
      if (value !== undefined) yield value
      else if (this.error !== null) throw this.error
      else if (this.done) return
      else await new Promise<void>((resolve) => this.waiters.push(resolve))
    }
  }
}

export class RunnerHubError extends Error {
  override readonly name = "RunnerHubError"
  constructor(readonly code: string) {
    super(`RUNNER_HUB_${code.toUpperCase()}`)
  }
}

const parseHosts = (configuredHosts: string | undefined, port: number): readonly string[] => {
  const hosts = configuredHosts === undefined ? defaultHosts(port) : configuredHosts.split(",")
  const normalizedHosts = hosts.map((host) => host.trim().toLowerCase())
  if (
    normalizedHosts.length === 0 ||
    normalizedHosts.some((host) => !LocalHostSchema.test(host)) ||
    new Set(normalizedHosts).size !== normalizedHosts.length
  )
    throw new LocalSecurityConfigurationError()
  return normalizedHosts
}

export const parseLocalSecuritySettings = (
  environment: Readonly<Record<string, string | undefined>>,
  port: number
): LocalSecuritySettings => {
  const parsed = SecurityEnvironmentSchema.safeParse(environment)
  if (!parsed.success || parsed.data.FILE_MAX_BYTES > parsed.data.REQUEST_MAX_BYTES)
    throw new LocalSecurityConfigurationError()

const requestHost = (context: Context): string | null => {
  const url = new URL(context.req.url)
  const forwardedHeaders = ["forwarded", "x-forwarded-host", "x-forwarded-proto"]
  if (forwardedHeaders.some((header) => context.req.header(header) !== undefined)) return null
  const hostHeader = context.req.header("host")
  if (hostHeader !== undefined && hostHeader.toLowerCase() !== url.host.toLowerCase()) return null
  return url.host.toLowerCase()
}

const requestOriginIsAllowed = (context: Context, host: string): boolean => {
  const origin = context.req.header("origin")
  if (origin !== undefined) return origin === `http://${host}`
  const fetchSite = context.req.header("sec-fetch-site")
  return fetchSite === undefined || fetchSite === "none" || fetchSite === "same-origin"
}

const readCookie = (cookieHeader: string | undefined, name: string): string | undefined => {
  if (cookieHeader === undefined) return undefined
  for (const segment of cookieHeader.split(";")) {
    const [cookieName, ...value] = segment.trim().split("=")
    if (cookieName === name) return value.join("=")
  }
  return undefined
}

export type CsrfProtection = {
  readonly issue: (context: Context) => Response
  readonly isValid: (context: Context) => boolean
}

const equal = (left: string, right: string): boolean =>
  left.length === right.length && timingSafeEqual(Buffer.from(left), Buffer.from(right))

export const createCsrfProtection = (secret: Uint8Array = randomBytes(32)): CsrfProtection => {
  const signingKey = Buffer.from(secret)
  const signed = (token: string): string =>
    `${token}.${createHmac("sha256", signingKey).update(token).digest("base64url")}`
  return {
    issue: (context) => {
      const csrfToken = randomBytes(32).toString("base64url")
      context.header("Cache-Control", "no-store")
      context.header(
        "Set-Cookie",
        `${CsrfCookieName}=${signed(csrfToken)}; HttpOnly; Path=/; SameSite=Strict`
      )
      return context.json({ csrfToken })
    },
    isValid: (context) => {
      const cookie = readCookie(context.req.header("cookie"), CsrfCookieName)
      const header = context.req.header("x-csrf-token")
      if (cookie === undefined || header === undefined) return false
      return equal(cookie, signed(header))
    }
  }
}

export const localSecurityMiddleware =
  (settings: LocalSecuritySettings, csrf: CsrfProtection): MiddlewareHandler =>
  async (context, next) => {
    setSecurityHeaders(context)
    const host = requestHost(context)
    if (host === null || !settings.allowedHosts.includes(host))
      return errorResponse(context, "HOST_NOT_ALLOWED", 421)
    if (!requestOriginIsAllowed(context, host))
      return errorResponse(context, "ORIGIN_NOT_ALLOWED", 403)
    if (MutationMethods.has(context.req.method) && !csrf.isValid(context))
      return errorResponse(context, "CSRF_INVALID", 403)
    return next()
  }

import { createHash, randomUUID } from "node:crypto"
import {
  existsSync,
  mkdirSync,
  openSync,
  closeSync,
  fsyncSync,
  readdirSync,
  unlinkSync,
  linkSync
} from "node:fs"
import { open, rm } from "node:fs/promises"
import { relative, resolve } from "node:path"

const HashSchema = /^[a-f0-9]{64}$/
export type BlobRecord = {
  readonly sha256: string
  readonly byteSize: number
  readonly mediaType: string
}

export class BlobPathError extends Error {
  override readonly name = "BlobPathError"
  constructor() {
    super("BLOB_PATH_ERROR")
  }
}
export class BlobIntegrityError extends Error {
  override readonly name = "BlobIntegrityError"
  constructor() {
    super("BLOB_INTEGRITY_ERROR")
  }
}

const assertContained = (directory: string, candidate: string): string => {
  const relativePath = relative(directory, candidate)
  if (relativePath === "" || relativePath.startsWith("..") || relativePath.includes("../"))
    throw new BlobPathError()
  return candidate
}

export class BlobStore {
  readonly directory: string
  constructor(dataDirectory: string) {
    this.directory = resolve(dataDirectory, "blobs")
    mkdirSync(this.directory, { recursive: true, mode: 0o700 })
  }

pathFor(sha256: string): string {
    if (!HashSchema.test(sha256)) throw new BlobPathError()
    return assertContained(this.directory, resolve(this.directory, sha256))
  }

exists(sha256: string): boolean {
    return existsSync(this.pathFor(sha256))
  }

async put(source: Blob | ReadableStream<Uint8Array>, mediaType: string): Promise<BlobRecord> {
    const temporaryPath = assertContained(
      this.directory,
      resolve(this.directory, `.tmp-${randomUUID()}`)
    )
    const file = await open(temporaryPath, "wx", 0o600)
    const hash = createHash("sha256")
    let byteSize = 0
    try {
      const reader = (source instanceof Blob ? source.stream() : source).getReader()
      for (;;) {
        const result = await reader.read()
        if (result.done) break
        hash.update(result.value)
        byteSize += result.value.byteLength
        await file.write(result.value)
      }
      await file.sync()
      await file.close()
      const sha256 = hash.digest("hex")
      const finalPath = this.pathFor(sha256)
      let created = true
      try {
        linkSync(temporaryPath, finalPath)
      } catch (error) {
        if (!(error instanceof Error) || !error.message.includes("EEXIST")) throw error
        created = false
      }
      unlinkSync(temporaryPath)
      if (!created) await this.verify(finalPath, sha256, byteSize)
      const directoryHandle = openSync(this.directory, "r")
      fsyncSync(directoryHandle)
      closeSync(directoryHandle)
      return { sha256, byteSize, mediaType }
    } catch (error) {
      await file.close()
      await rm(temporaryPath, { force: true })
      throw error
    }
  }

private async verify(path: string, expectedHash: string, expectedSize: number): Promise<void> {
    const hash = createHash("sha256")
    let byteSize = 0
    const reader = Bun.file(path).stream().getReader()
    for (;;) {
      const result = await reader.read()
      if (result.done) break
      hash.update(result.value)
      byteSize += result.value.byteLength
    }
    if (hash.digest("hex") !== expectedHash || byteSize !== expectedSize)
      throw new BlobIntegrityError()
  }

remove(sha256: string): void {
    if (this.exists(sha256)) unlinkSync(this.pathFor(sha256))
  }
  temporaryFiles(): readonly string[] {
    return readdirSync(this.directory).filter((name) => name.startsWith(".tmp-"))
  }
}

export type ChatExecutor = {
  readonly execute: (input: {
    readonly conversationId: string | null
    readonly applicationId: string
    readonly message: string
    readonly providerId: string
    readonly disclosureId: string
    readonly turnKey: string
    readonly inputs: readonly DisclosureInputRef[]
    readonly signal: AbortSignal
  }) => Promise<{ readonly output: unknown; readonly providerRunId: string }>
}

export class ChatWorkflowService {
  private readonly sources: DisclosureSourceResolver
  constructor(
    private readonly repository: ResearchConversationRepository,
    private readonly executor: ChatExecutor,
    database: Database
  ) {
    this.sources = new DisclosureSourceResolver(database)
  }

async send(raw: unknown, signal: AbortSignal) {
    const request = ChatRequestSchema.parse(raw)
    const existing =
      request.conversationId === null
        ? null
        : this.repository.getConversation(request.conversationId)
    if (
      request.conversationId !== null &&
      (existing === null ||
        existing.archivedAt !== null ||
        existing.applicationId !== request.applicationId)
    )
      throw new ChatWorkflowError("conversation_unavailable")
    for (const input of request.inputs) this.sources.resolve(input)
    const execution = await this.executor.execute({
      conversationId: request.conversationId,
      applicationId: request.applicationId,
      message: request.message,
      providerId: request.providerId,
      disclosureId: request.disclosureId,
      turnKey: request.turnKey,
      inputs: request.inputs,
      signal
    })
    if (signal.aborted) throw new ChatWorkflowError("cancelled")
    const output = ChatOutputSchema.parse(execution.output)
    const allowed = new Set(request.inputs.map(referenceId))
    if (output.citations.some((citation) => !allowed.has(citation.sourceId)))
      throw new ChatWorkflowError("citation_missing")
    const conversation =
      existing ??
      this.repository.createConversation({
        id: crypto.randomUUID(),
        applicationId: request.applicationId,
        title: request.title
      })
    const user = this.repository.appendMessage({
      id: crypto.randomUUID(),
      conversationId: conversation.id,
      role: "user",
      content: { text: request.message, inputRefs: request.inputs },
      bodyBlobHash: null,
      providerRunId: null
    })
    const assistant = this.repository.appendMessage({
      id: crypto.randomUUID(),
      conversationId: conversation.id,
      role: "assistant",
      content: output,
      bodyBlobHash: null,
      providerRunId: execution.providerRunId
    })
    return { conversation, messages: [user, assistant] }
  }

list(applicationId: string) {
    return this.repository.listConversations(ApplicationIdSchema.parse(applicationId))
  }

messages(conversationId: string) {
    return this.repository.listMessages(ConversationIdSchema.parse(conversationId))
  }
}

