  },
  "elements": [
    {
      "type": "text",
      "id": "title-text",
      "rotation": 0,
      "x": 450,
      "y": 28,
      "content": "GPU 의 SIMT 실행 모델, 한 명령으로 N 개의 thread 가 동시 작업",
      "fontSize": 18,
      "fontWeight": 700,
      "color": "#18181b",
