// Minimal service worker for shinkeonkim.com.
// Strategy:
// - Static assets (_astro, fonts, images, json): cache-first.
// - HTML navigations: stale-while-revalidate, falling back to /offline/.
// - Versioned cache name lets a new SW evict the old cache on activate.

const VERSION = 'v1-2026-06-15';
const STATIC_CACHE = `static-${VERSION}`;
const RUNTIME_CACHE = `runtime-${VERSION}`;
const OFFLINE_URL = '/offline/';
const STATIC_PRECACHE = [OFFLINE_URL];

const STATIC_EXT_RE = /\.(?:css|js|woff2?|ttf|otf|svg|png|jpe?g|gif|webp|avif|ico|json|xml)$/i;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) => cache.addAll(STATIC_PRECACHE).catch(() => undefined)),
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k !== STATIC_CACHE && k !== RUNTIME_CACHE)
          .map((k) => caches.delete(k)),
      );
      await self.clients.claim();
    })(),
  );
});

async function cacheFirst(request) {
  const cache = await caches.open(STATIC_CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone()).catch(() => undefined);
    return response;
  } catch (err) {
    if (cached) return cached;
    throw err;
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone()).catch(() => undefined);
      return response;
    })
    .catch(() => null);
  if (cached) {
    network.catch(() => undefined);
    return cached;
  }
  const fresh = await network;
  if (fresh) return fresh;
  const offline = await cache.match(OFFLINE_URL);
  if (offline) return offline;
  return new Response('Offline', { status: 503, statusText: 'Offline' });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

if (req.mode === 'navigate' || req.headers.get('accept')?.includes('text/html')) {
    event.respondWith(staleWhileRevalidate(req));
    return;
  }
  if (STATIC_EXT_RE.test(url.pathname)) {
    event.respondWith(cacheFirst(req));
  }
});

def derive_series(item: "MigrationItem") -> tuple[str, int] | None:
    name = item.source.stem
    if item.dest_dir == "css-battle":
        match = CSS_BATTLE_NUM_RE.search(name)
        if match:
            return "CSS Battle", int(match.group(1))
    if item.dest_dir == "mentoring":
        match = MENTORING_NUM_RE.search(name)
        if match:
            return "소프트웨어 특기자 멘토링", int(match.group(1))
    if item.dest_dir == "problem-solving/boj":
        match = BOJ_NUM_RE.search(name)
        if match:
            return "BOJ 풀이", int(match.group(1))
    return None

@dataclass(frozen=True)
class MigrationItem:
    source: Path
    dest_dir: str
    dest_name: str | None = None

def plan() -> list[MigrationItem]:
    items: list[MigrationItem] = []

for folder in ("css-battle", "TIL", "mentoring"):
        src = LEGACY_ROOT / folder
        if not src.exists():
            continue
        for path in sorted(src.glob("*.md")):
            items.append(MigrationItem(path, folder))

boj_src = LEGACY_ROOT / "boj"
    if boj_src.exists():
        for path in sorted(boj_src.glob("*.md")):
            items.append(MigrationItem(path, "problem-solving/boj"))

for filename in (
        "2020-01-01-goodbye-2019.md",
        "2021-12-09-goodbye-2021.md",
        "2022-10-30-goodbye-2022.md",
    ):
        src = LEGACY_ROOT / filename
        if src.exists():
            items.append(MigrationItem(src, "my-life"))

for filename in (
        "2021-09-21-python-spread-operator.md",
        "2021-10-01-detect-intersection-two-circle.md",
    ):
        src = LEGACY_ROOT / filename
        if src.exists():
            items.append(MigrationItem(src, ""))

return items

def split_frontmatter(raw: str) -> tuple[dict, str]:
    if not raw.startswith("---"):
        return {}, raw
    closing = raw.find("\n---", 3)
    if closing < 0:
        return {}, raw
    fm_text = raw[3:closing].strip("\n")
    body_start = closing + len("\n---")
    if body_start < len(raw) and raw[body_start] == "\n":
        body_start += 1
    body = raw[body_start:]
    try:
        data = yaml.safe_load(fm_text) or {}
        if not isinstance(data, dict):
            data = {}
    except yaml.YAMLError:
        data = {}
    return data, body

def derive_date(item: MigrationItem, existing: object) -> str | None:
    if isinstance(existing, str) and existing.strip():
        return existing.strip()
    if existing is not None and not isinstance(existing, str):
        return str(existing)
    match = FILENAME_DATE_RE.match(item.source.name)
    if match:
        return match.group(1)
    return None

def strip_inline_html(text: str) -> str:
    text = re.sub(r"<[^>]+>", " ", text)
    text = WIKILINK_RE.sub(lambda m: (m.group(2) or m.group(1)).strip(), text)
    text = MD_LINK_RE.sub(r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    text = re.sub(r"\*\*([^*]+)\*\*", r"\1", text)
    text = re.sub(r"\*([^*]+)\*", r"\1", text)
    return text

def is_skippable_paragraph(raw: str) -> bool:
    text = raw.strip()
    if not text:
        return True
    if MD_LINK_RE.fullmatch(text):
        return True
    inner = MD_LINK_RE.sub(r"\1", text).strip()
    if URL_ONLY_RE.match(inner):
        return True
    return False

def synthesize_description(body: str, max_len: int = 140) -> str:
    cleaned_body = SCRIPT_BLOCK_RE.sub("", STYLE_BLOCK_RE.sub("", body))
    in_fence = False
    raw_paragraphs: list[str] = []
    current: list[str] = []

def push() -> None:
        if current:
            raw_paragraphs.append(" ".join(current).strip())
            current.clear()

for line in cleaned_body.splitlines():
        stripped = line.strip()
        if stripped.startswith("```"):
            in_fence = not in_fence
            push()
            continue
        if in_fence:
            continue
        if not stripped:
            push()
            continue
        if HEADING_RE.match(stripped):
            push()
            continue
        if IMAGE_RE.search(stripped):
            cleaned = IMAGE_RE.sub("", stripped).strip()
            if not cleaned:
                continue
            stripped = cleaned
        if stripped.startswith(">"):
            stripped = stripped.lstrip("> ").strip()
            if not stripped:
                continue
        current.append(stripped)
    push()

for raw_p in raw_paragraphs:
        if is_skippable_paragraph(raw_p):
            continue
        cleaned = strip_inline_html(raw_p)
        text = re.sub(r"\s+", " ", cleaned).strip()
        if not text:
            continue
        if len(text) > max_len:
            truncated = text[:max_len].rsplit(" ", 1)[0]
            if not truncated:
                truncated = text[:max_len]
            text = truncated.rstrip(",.;:") + "…"
        return text
    return ""

def build_astro_frontmatter(data: dict, item: MigrationItem) -> dict:
    out: dict = {}
    title = data.get("title")
    if isinstance(title, str):
        out["title"] = title.strip()
    if "description" in data and isinstance(data["description"], str) and data["description"].strip():
        out["description"] = data["description"].strip()
    date_value = derive_date(item, data.get("date"))
    if date_value:
        out["date"] = date_value
    if "updated" in data and data["updated"]:
        out["updated"] = data["updated"]
    tags = data.get("tags")
    if isinstance(tags, list):
        cleaned = [str(t).strip() for t in tags if str(t).strip()]
        if cleaned:
            out["tags"] = cleaned
    elif isinstance(tags, str) and tags.strip():
        out["tags"] = [tags.strip()]
    series = derive_series(item)
    if series and "series" not in data:
        out["series"] = series[0]
        out["seriesOrder"] = series[1]
    for key, value in data.items():
        if key in DROP_KEYS or key in {"title", "description", "date", "updated", "tags", "series", "seriesOrder"}:
            continue
        out[key] = value
    if "series" in data and isinstance(data["series"], str):
        out["series"] = data["series"]
    if "seriesOrder" in data:
        out["seriesOrder"] = data["seriesOrder"]
    return out

def serialize_frontmatter(fm: dict) -> str:
    text = yaml.safe_dump(
        fm,
        allow_unicode=True,
        sort_keys=False,
        default_flow_style=False,
        width=10_000,
    )
    return text.strip("\n")

def migrate(item: MigrationItem, dry_run: bool) -> tuple[Path, bool]:
    raw = item.source.read_text(encoding="utf-8")
    fm, body = split_frontmatter(raw)
    new_fm = build_astro_frontmatter(fm, item)
    if not new_fm.get("description"):
        synthesized = synthesize_description(body)
        if synthesized:
            new_fm["description"] = synthesized
    ordered: dict = {}
    for key in ("title", "description", "date", "updated", "tags", "series", "seriesOrder"):
        if key in new_fm:
            ordered[key] = new_fm[key]
    for key, value in new_fm.items():
        if key not in ordered:
            ordered[key] = value

def serialize_references(refs):
    """Serialize references list as YAML, prettily."""
    if not refs:
        return ""
    lines = ["references:"]
    for r in refs:
        if 'id' in r:
            lines.append(f"  - id: {r['id']}")
            if r.get('note'):
                note = r['note'].replace('"', '\\"')
                lines.append(f'    note: "{note}"')
        else:
            title = r.get('title', '').replace('"', '\\"')
            lines.append(f'  - title: "{title}"')
            if r.get('url'):
                lines.append(f'    url: "{r["url"]}"')
            if r.get('author'):
                author = r['author'].replace('"', '\\"')
                lines.append(f'    author: "{author}"')
            if r.get('note'):
                note = r['note'].replace('"', '\\"')
                lines.append(f'    note: "{note}"')
    return '\n'.join(lines)

new_section = '\n'.join(new_lines)
    new_body = body[:sec_body_start] + new_section + body[sec_end:]
    return new_body, external

def make_reference_from_link(text, url):
    """Given link text and URL, build a reference dict."""
    if should_skip(url):
        return None
    src_id, src_note = url_to_source(url, text)
    if src_id:
        ref = {'id': src_id}
        if src_note:
            ref['note'] = src_note
        else:
            # Use the link text as note if it has content
            stripped = text.strip()
            if stripped and stripped.lower() != url.lower():
                ref['note'] = stripped
        return ref
    # Inline reference
    # Try to extract author from text (e.g., "koosaga, DP 최적화 정리")
    author = None
    title = text.strip()
    return {'title': title, 'url': url}

def normalize_existing_inline_refs(refs):
    out = []
    for r in refs:
        if 'id' in r:
            out.append(r)
            continue
        url = r.get('url')
        if not url:
            out.append(r)
            continue
        src_id, src_note = url_to_source(url, r.get('title', ''))
        if not src_id:
            out.append(r)
            continue
        new_ref = {'id': src_id}
        note = src_note or r.get('note') or r.get('title')
        if note:
            new_ref['note'] = note
        out.append(new_ref)
    return out

def process_file(path: Path, dry_run=False):
