1. **Per-input guard** (works for a fixed set of named inputs, like the
   toolbar in `studio/main.ts:reflectState`):

```ts
   if (document.activeElement !== ui.titleInput) {
     ui.titleInput.value = def.title;
   }
   ```

2. **Capture/restore wrapper** (works for panels with many dynamic inputs,
   like `studio/properties.ts`). Use `studio-focus.ts`:

```ts
   import { captureFocusWithin, restoreFocusWithin } from './studio-focus';

function render(): void {
     if (!panelEl) return;
     const snap = captureFocusWithin(panelEl);
     renderInner();
     restoreFocusWithin(panelEl, snap);
   }
   ```

Inputs in the panel must carry a stable `data-prop-key` (or `id`) so
   the restore step can re-target the new DOM node.

import type { APIRoute } from 'astro';
import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { animationDefSchema, ID_RE } from '@/entities/animation/engine/schema';
import { ANIM_DIR } from '@/entities/animation/engine/loader';
import { errorResponse, jsonResponse, requireDev } from '@/dev-only/shared/api-utils';

export const prerender = false;

function pathFor(id: string): string {
  return join(ANIM_DIR, `${id}.json`);
}

function invalidId(): Response {
  return jsonResponse({ error: 'invalid id' }, { status: 400 });
}

export const GET: APIRoute = requireDev(async ({ params }) => {
  const id = params.id ?? '';
  if (!ID_RE.test(id)) return invalidId();
  try {
    const text = await readFile(pathFor(id), 'utf-8');
    const json = JSON.parse(text);
    const parsed = animationDefSchema.safeParse(json);
    if (!parsed.success) {
      return jsonResponse({ error: 'invalid stored animation', detail: parsed.error.message }, { status: 500 });
    }
    return jsonResponse({ def: parsed.data });
  } catch {
    return jsonResponse({ error: 'not found' }, { status: 404 });
  }
});

export const PUT: APIRoute = requireDev(async ({ params, request }) => {
  const id = params.id ?? '';
  if (!ID_RE.test(id)) return invalidId();
  try {
    await mkdir(ANIM_DIR, { recursive: true });
    const body = await request.json();
    const merged = { ...body, id };
    const parsed = animationDefSchema.safeParse(merged);
    if (!parsed.success) {
      return jsonResponse({ error: 'validation failed', detail: parsed.error.message }, { status: 400 });
    }
    if (!parsed.data.title || parsed.data.title.trim().length === 0) {
      parsed.data.title = id;
    }
    parsed.data.updatedAt = new Date().toISOString();
    await writeFile(pathFor(id), JSON.stringify(parsed.data, null, 2) + '\n', 'utf-8');
    return jsonResponse({ ok: true, def: parsed.data });
  } catch (err) {
    return errorResponse(err);
  }
});

export const DELETE: APIRoute = requireDev(async ({ params }) => {
  const id = params.id ?? '';
  if (!ID_RE.test(id)) return invalidId();
  try {
    await unlink(pathFor(id));
    return jsonResponse({ ok: true });
  } catch {
    return jsonResponse({ error: 'not found' }, { status: 404 });
  }
});

import type { APIRoute } from 'astro';
import { mkdir, readdir, readFile, stat, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { animationDefSchema, ID_RE } from '@/entities/animation/engine/schema';
import { ANIM_DIR } from '@/entities/animation/engine/loader';
import { errorResponse, jsonResponse, requireDev } from '@/dev-only/shared/api-utils';

export const prerender = false;

async function ensureDir(): Promise<void> {
  await mkdir(ANIM_DIR, { recursive: true });
}

async function fileExists(filePath: string): Promise<boolean> {
  try {
    await stat(filePath);
    return true;
  } catch {
    return false;
  }
}

interface AnimationSummary {
  id: string;
  title: string;
  description: string;
  updatedAt?: string;
}

async function loadSummary(fn: string): Promise<AnimationSummary | null> {
  let text: string;
  try {
    text = await readFile(join(ANIM_DIR, fn), 'utf-8');
  } catch {
    return null;
  }
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    return null;
  }
  const parsed = animationDefSchema.safeParse(json);
  if (!parsed.success) return null;
  return {
    id: parsed.data.id,
    title: parsed.data.title,
    description: parsed.data.description,
    updatedAt: parsed.data.updatedAt,
  };
}

export const GET: APIRoute = requireDev(async () => {
  try {
    await ensureDir();
    const entries = await readdir(ANIM_DIR);
    const jsonEntries = entries.filter((n) => n.endsWith('.json'));
    const summaries = (await Promise.all(jsonEntries.map(loadSummary))).filter(
      (s): s is AnimationSummary => s !== null,
    );
    summaries.sort((a, b) => a.title.localeCompare(b.title, 'ko'));
    return jsonResponse({ items: summaries });
  } catch (err) {
    return errorResponse(err);
  }
});

export const POST: APIRoute = requireDev(async ({ request }) => {
  try {
    await ensureDir();
    const body = await request.json();
    const id: unknown = body?.id;
    if (typeof id !== 'string' || !ID_RE.test(id)) {
      return jsonResponse({ error: 'invalid id (lowercase / digits / - / _ only)' }, { status: 400 });
    }
    const filePath = join(ANIM_DIR, `${id}.json`);
    if (await fileExists(filePath)) {
      return jsonResponse({ error: 'animation already exists' }, { status: 409 });
    }
    const initial = animationDefSchema.parse({
      id,
      title: typeof body?.title === 'string' && body.title ? body.title : id,
      description: typeof body?.description === 'string' ? body.description : '',
    });
    initial.updatedAt = new Date().toISOString();
    await writeFile(filePath, JSON.stringify(initial, null, 2) + '\n', 'utf-8');
    return jsonResponse({ ok: true, def: initial });
  } catch (err) {
    return errorResponse(err);
  }
});

import type { APIRoute } from 'astro';
import { notFoundResponse } from '@/dev-only/shared/api-utils';
import {
  COLLECTIONS,
  createFolder,
  deleteFile,
  deleteFolder,
  isCollection,
  moveFile,
  renameFile,
  renameFolder,
} from '@/dev-only/shared/path-utils';

export const prerender = false;

function devGuard(): Response | null {
  if (!import.meta.env.DEV) {
    return notFoundResponse();
  }
  return null;
}

function badRequest(message: string): Response {
  return new Response(JSON.stringify({ error: message }), {
    status: 400,
    headers: { 'Content-Type': 'application/json' },
  });
}

function ok(data: Record<string, unknown>): Response {
  return new Response(JSON.stringify({ ok: true, ...data }), {
    headers: { 'Content-Type': 'application/json' },
  });
}

interface OpsBody {
  action?: string;
  collection?: string;
  slug?: string;
  ext?: string;
  toSlug?: string;
  toExt?: string;
  toCollection?: string;
  folder?: string;
  toFolder?: string;
}

function parseExt(value: unknown): '.md' | '.mdx' {
  if (value === '.mdx') return '.mdx';
  return '.md';
}

export const POST: APIRoute = async ({ request }) => {
  const guard = devGuard();
  if (guard) return guard;

let body: OpsBody;
  try {
    body = (await request.json()) as OpsBody;
  } catch {
    return badRequest('invalid json');
  }

const { action, collection } = body;
  if (!collection || !isCollection(collection)) {
    return badRequest('valid collection required');
  }

try {
    switch (action) {
      case 'delete-file': {
        if (!body.slug) return badRequest('slug required');
        const result = deleteFile(collection, body.slug, parseExt(body.ext));
        return ok({ action, ...result });
      }
      case 'rename-file': {
        if (!body.slug || !body.toSlug) return badRequest('slug and toSlug required');
        const result = renameFile(
          collection,
          body.slug,
          parseExt(body.ext),
          body.toSlug,
          parseExt(body.toExt ?? body.ext),
        );
        return ok({ action, ...result });
      }
      case 'move-file': {
        if (!body.slug || !body.toSlug || !body.toCollection) {
          return badRequest('slug, toCollection, toSlug required');
        }
        if (!isCollection(body.toCollection)) return badRequest('valid toCollection required');
        const result = moveFile(
          collection,
          body.slug,
          parseExt(body.ext),
          body.toCollection,
          body.toSlug,
        );
        return ok({ action, ...result });
      }
      case 'create-folder': {
        if (!body.folder) return badRequest('folder required');
        const result = createFolder(collection, body.folder);
        return ok({ action, ...result });
      }
      case 'rename-folder': {
        if (!body.folder || !body.toFolder) return badRequest('folder and toFolder required');
        const result = renameFolder(collection, body.folder, body.toFolder);
        return ok({ action, ...result });
      }
      case 'delete-folder': {
        if (!body.folder) return badRequest('folder required');
        const result = deleteFolder(collection, body.folder);
        return ok({ action, ...result });
      }
      default:
        return badRequest(`unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return new Response(JSON.stringify({ error: msg }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }
};

export const GET: APIRoute = () => {
  const guard = devGuard();
  if (guard) return guard;
  return new Response(JSON.stringify({ collections: COLLECTIONS }), {
    headers: { 'Content-Type': 'application/json' },
  });
};

import type { APIRoute } from 'astro';
import { isCollection, loadFile, saveFile } from '@/dev-only/shared/path-utils';
import { notFoundResponse } from '@/dev-only/shared/api-utils';

export const prerender = false;

function devGuard(): Response | null {
  if (!import.meta.env.DEV) {
    return notFoundResponse();
  }
  return null;
}

export const GET: APIRoute = ({ url }) => {
  const guard = devGuard();
  if (guard) return guard;
  const collection = url.searchParams.get('collection') ?? '';
  const slug = url.searchParams.get('slug') ?? '';
  if (!isCollection(collection) || !slug) {
    return new Response(JSON.stringify({ error: 'collection and slug required' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }
  try {
    const loaded = loadFile(collection, slug);
    if (!loaded) {
      return new Response(JSON.stringify({ error: 'not found' }), {
        status: 404,
        headers: { 'Content-Type': 'application/json' },
      });
    }
    return new Response(JSON.stringify({ collection, slug, ...loaded }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return new Response(JSON.stringify({ error: msg }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }
};

