import type { APIRoute } from 'astro';
import fs from 'node:fs/promises';
import path from 'node:path';
import { FILE_UPLOAD_MAX_BYTES } from '@/shared/config';
import { errorResponse, jsonResponse, notFoundResponse } from '@/dev-only/shared/api-utils';

export const prerender = false;

const UPLOAD_DIR = path.resolve(process.cwd(), 'public/uploads');

const EXT_BY_TYPE: Record<string, string> = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'image/gif': '.gif',
  'image/webp': '.webp',
  'image/svg+xml': '.svg',
  'image/avif': '.avif',
};

function sanitize(raw: string): string {
  return raw
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/gi, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 40);
}

interface FetchBody {
  url?: string;
}

const tooLargeMessage = `너무 큽니다 (>${FILE_UPLOAD_MAX_BYTES / 1024 / 1024}MB)`;

export const POST: APIRoute = async ({ request }) => {
  if (!import.meta.env.DEV) return notFoundResponse();

let body: FetchBody;
  try {
    body = (await request.json()) as FetchBody;
  } catch {
    return errorResponse('invalid json', 400);
  }

const rawUrl = (body.url ?? '').trim();
  if (!rawUrl) return errorResponse('url required', 400);

let target: URL;
  try {
    target = new URL(rawUrl);
  } catch {
    return errorResponse('잘못된 URL', 400);
  }
  if (target.protocol !== 'http:' && target.protocol !== 'https:') {
    return errorResponse('http/https URL 만 허용', 400);
  }

try {
    const res = await fetch(target.toString(), {
      headers: { 'User-Agent': 'shinkeonkim-blog-dev-editor/1.0' },
      redirect: 'follow',
    });
    if (!res.ok) {
      return errorResponse(`원격 응답 ${res.status} ${res.statusText}`, 502);
    }
    const contentType =
      res.headers.get('content-type')?.split(';')[0].trim() ?? 'application/octet-stream';
    if (!contentType.startsWith('image/')) {
      return errorResponse(`이미지가 아닙니다 (${contentType})`, 415);
    }
    const len = Number(res.headers.get('content-length') ?? 0);
    if (len > FILE_UPLOAD_MAX_BYTES) return errorResponse(tooLargeMessage, 413);
    const buffer = Buffer.from(await res.arrayBuffer());
    if (buffer.length > FILE_UPLOAD_MAX_BYTES) return errorResponse(tooLargeMessage, 413);

const urlExt = path.extname(target.pathname).toLowerCase();
    const ext =
      (urlExt && /^\.[a-z0-9]+$/i.test(urlExt) ? urlExt : '') || EXT_BY_TYPE[contentType] || '.bin';
    const base = sanitize(path.basename(target.pathname, urlExt) || target.hostname);
    const timestamp = new Date().toISOString().slice(0, 19).replace(/[-:T]/g, '');
    const rand = Math.random().toString(36).slice(2, 8);
    const filename = `${timestamp}-${rand}${base ? '-' + base : ''}${ext}`;

await fs.mkdir(UPLOAD_DIR, { recursive: true });
    await fs.writeFile(path.join(UPLOAD_DIR, filename), buffer);

return jsonResponse({
      path: `/uploads/${filename}`,
      sourceUrl: target.toString(),
      size: buffer.length,
      type: contentType,
    });
  } catch (err) {
    return errorResponse(
      err instanceof Error ? '다운로드 실패: ' + err.message : '다운로드 실패',
      502,
    );
  }
};

import type { APIRoute } from 'astro';
import {
  amendCommit,
  checkoutBranch,
  commit,
  commitHunks,
  createBranch,
  fetchOrigin,
  getDiff,
  getFileHunks,
  getStatus,
  listBranches,
  pull,
  push,
  stashDrop,
  stashList,
  stashPop,
  stashPush,
} from '@/dev-only/shared/git-utils';
import { notFoundResponse } from '@/dev-only/shared/api-utils';

export const prerender = false;

function devGuard(): Response | null {
  if (!import.meta.env.DEV) {
    return notFoundResponse();
  }
  return null;
}

function jsonError(message: string, status = 400): Response {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

function jsonOk(data: Record<string, unknown>): Response {
  return new Response(JSON.stringify({ ok: true, ...data }), {
    headers: { 'Content-Type': 'application/json' },
  });
}

export const GET: APIRoute = async ({ url }) => {
  const guard = devGuard();
  if (guard) return guard;
  const action = url.searchParams.get('action') ?? 'status';
  try {
    if (action === 'status') {
      const status = await getStatus();
      return jsonOk({ status });
    }
    if (action === 'diff') {
      const file = url.searchParams.get('file');
      if (!file) return jsonError('file required');
      const diff = await getDiff(file);
      return jsonOk({ diff });
    }
    if (action === 'hunks') {
      const file = url.searchParams.get('file');
      if (!file) return jsonError('file required');
      const result = await getFileHunks(file);
      return jsonOk({ ...result });
    }
    if (action === 'branches') {
      const branches = await listBranches();
      return jsonOk({ branches });
    }
    if (action === 'stash-list') {
      const stashes = await stashList();
      return jsonOk({ stashes });
    }
    return jsonError(`unknown action: ${action}`);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return jsonError(msg, 500);
  }
};

interface GitBody {
  action?: string;
  files?: string[];
  message?: string;
  branch?: string;
  checkout?: boolean;
  stashIndex?: number;
  file?: string;
  hunkIndexes?: number[];
}

export const POST: APIRoute = async ({ request }) => {
  const guard = devGuard();
  if (guard) return guard;

let body: GitBody;
  try {
    body = (await request.json()) as GitBody;
  } catch {
    return jsonError('invalid json');
  }

try {
    if (body.action === 'commit') {
      const files = Array.isArray(body.files) ? body.files : [];
      const message = String(body.message ?? '').trim();
      if (!message) return jsonError('message required');
      if (files.length === 0) return jsonError('no files');
      const result = await commit(files, message);
      return jsonOk(result);
    }
    if (body.action === 'push') {
      const result = await push();
      return jsonOk(result);
    }
    if (body.action === 'fetch') {
      const result = await fetchOrigin();
      return jsonOk(result);
    }
    if (body.action === 'pull') {
      const result = await pull();
      return jsonOk(result);
    }
    if (body.action === 'amend') {
      const files = Array.isArray(body.files) ? body.files : [];
      const result = await amendCommit(files, body.message);
      return jsonOk(result);
    }
    if (body.action === 'checkout') {
      if (!body.branch) return jsonError('branch required');
      const result = await checkoutBranch(body.branch);
      return jsonOk(result);
    }
    if (body.action === 'createBranch') {
      if (!body.branch) return jsonError('branch required');
      const result = await createBranch(body.branch, body.checkout !== false);
      return jsonOk(result);
    }
    if (body.action === 'stash-push') {
      const result = await stashPush(body.message ?? '');
      return jsonOk(result);
    }
    if (body.action === 'stash-pop') {
      const result = await stashPop(body.stashIndex ?? 0);
      return jsonOk(result);
    }
    if (body.action === 'stash-drop') {
      if (typeof body.stashIndex !== 'number') return jsonError('stashIndex required');
      const result = await stashDrop(body.stashIndex);
      return jsonOk(result);
    }
    if (body.action === 'commit-hunks') {
      const file = body.file ?? '';
      const idxs = Array.isArray(body.hunkIndexes) ? body.hunkIndexes : [];
      const msg = String(body.message ?? '').trim();
      if (!file) return jsonError('file required');
      if (!msg) return jsonError('message required');
      if (idxs.length === 0) return jsonError('no hunks');
      const result = await commitHunks(file, idxs, msg);
      return jsonOk(result);
    }
    return jsonError(`unknown action: ${body.action}`);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return jsonError(msg, 500);
  }
};

import type { APIRoute } from 'astro';
import fs from 'node:fs';
import path from 'node:path';
import { COLLECTIONS, CONTENT_ROOT, type Collection } from '@/dev-only/shared/path-utils';
import { errorResponse, jsonResponse, notFoundResponse } from '@/dev-only/shared/api-utils';

export const prerender = false;

interface GrepBody {
  query?: string;
  regex?: boolean;
  caseSensitive?: boolean;
  maxResults?: number;
}

interface GrepMatch {
  collection: Collection;
  slug: string;
  ext: string;
  line: number;
  column: number;
  text: string;
}

const HARD_LIMIT = 500;

function walkFiles(dir: string, out: string[]): void {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.') || entry.name.startsWith('_')) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkFiles(full, out);
      continue;
    }
    if (/\.(md|mdx)$/.test(entry.name)) out.push(full);
  }
}

function buildRegex(query: string, isRegex: boolean, caseSensitive: boolean): RegExp | null {
  const flags = caseSensitive ? 'g' : 'gi';
  try {
    if (isRegex) return new RegExp(query, flags);
    return new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), flags);
  } catch {
    return null;
  }
}

export const POST: APIRoute = async ({ request }) => {
  if (!import.meta.env.DEV) return notFoundResponse();
  let body: GrepBody;
  try {
    body = (await request.json()) as GrepBody;
  } catch {
    return errorResponse('invalid json', 400);
  }
  const query = (body.query ?? '').trim();
  if (!query) return jsonResponse({ matches: [], truncated: false, scanned: 0 });
  const re = buildRegex(query, body.regex === true, body.caseSensitive === true);
  if (!re) return errorResponse('invalid regex', 400);
  const cap = Math.min(Math.max(1, body.maxResults ?? HARD_LIMIT), HARD_LIMIT);

try {
    const matches: GrepMatch[] = [];
    let scanned = 0;
    let truncated = false;
    outer: for (const collection of COLLECTIONS) {
      const files: string[] = [];
      walkFiles(path.join(CONTENT_ROOT, collection), files);
      for (const full of files) {
        scanned += 1;
        const content = fs.readFileSync(full, 'utf-8');
        const lines = content.split('\n');
        const m = /^(.+?)\.(md|mdx)$/.exec(path.basename(full));
        if (!m) continue;
        const ext = '.' + m[2];
        const rel = path
          .relative(path.join(CONTENT_ROOT, collection), full)
          .replace(/\\/g, '/');
        const slug = rel.replace(/\.(md|mdx)$/, '');
        for (let i = 0; i < lines.length; i += 1) {
          const line = lines[i];
          re.lastIndex = 0;
          const hit = re.exec(line);
          if (!hit) continue;
          matches.push({
            collection,
            slug,
            ext,
            line: i + 1,
            column: hit.index + 1,
            text: line.length > 200 ? line.slice(0, 200) + '…' : line,
          });
          if (matches.length >= cap) {
            truncated = true;
            break outer;
          }
        }
      }
    }
    return jsonResponse({ matches, truncated, scanned });
  } catch (err) {
    return errorResponse(err, 500);
  }
};

import type { APIRoute } from 'astro';
import { notFoundResponse } from '@/dev-only/shared/api-utils';
import { createMarkdownProcessor, parseFrontmatter } from '@astrojs/markdown-remark';
import { remarkAlert } from 'remark-github-blockquote-alert';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import remarkWikilink from '@/plugins/remark-wikilink.mjs';
import remarkMermaid from '@/plugins/remark-mermaid.mjs';
import remarkMathLenient from '@/plugins/remark-math-lenient.mjs';
import remarkUrlPreview from '@/plugins/remark-url-preview.mjs';
import remarkAnimation from '@/plugins/remark-animation.mjs';
import { preprocessMdx } from './mdx-preprocess';

export const prerender = false;

let processorPromise: Promise<Awaited<ReturnType<typeof createMarkdownProcessor>>> | null = null;
function getProcessor() {
  if (!processorPromise) {
    processorPromise = createMarkdownProcessor({
      gfm: true,
      smartypants: true,
      remarkPlugins: [
        remarkAnimation,
        remarkMermaid,
        remarkAlert,
        remarkWikilink,
        remarkMathLenient,
        remarkMath,
        remarkUrlPreview,
      ],
      rehypePlugins: [[rehypeKatex, { output: 'html', strict: 'ignore' }]],
      shikiConfig: {
        themes: { light: 'github-light', dark: 'one-dark-pro' },
        wrap: true,
      },
    });
  }
  return processorPromise;
}

interface RenderBody {
  content?: string;
  ext?: string;
}

export const POST: APIRoute = async ({ request }) => {
  if (!import.meta.env.DEV) {
    return notFoundResponse();
  }

let body: RenderBody;
  try {
    body = (await request.json()) as RenderBody;
  } catch {
    return new Response(JSON.stringify({ error: 'invalid json' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

const raw = typeof body.content === 'string' ? body.content : '';
  const ext = body.ext === '.mdx' ? '.mdx' : '.md';

try {
    const parsed = parseFrontmatter(raw, { frontmatter: 'empty-with-spaces' });
    const fm = parsed.frontmatter;
    let markdown = parsed.content;
    let componentNames: string[] = [];

if (ext === '.mdx') {
      const pre = await preprocessMdx(markdown);
      markdown = pre.transformed;
      componentNames = pre.componentNames;
    }

const processor = await getProcessor();
    const result = await processor.render(markdown);

return new Response(
      JSON.stringify({
        html: result.code,
        frontmatter: fm,
        componentNames,
        ext,
      }),
      { headers: { 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return new Response(
      JSON.stringify({ error: msg, stack: err instanceof Error ? err.stack : undefined }),
      { status: 500, headers: { 'Content-Type': 'application/json' } },
    );
  }
};

import { codeToHtml } from 'shiki';
import { escapeHtml, placeholderHtml } from './jsx-parser';

async function shiki(text: string, lang: string): Promise<string> {
  try {
    return await codeToHtml(text, {
      lang,
      themes: { light: 'github-light', dark: 'one-dark-pro' },
    });
  } catch {
    return `<pre><code>${escapeHtml(text)}</code></pre>`;
  }
}

interface Variant {
  label?: string;
  language?: string;
  code?: string;
}

interface CaseSpec {
  label?: string;
  input?: string;
  output?: string;
  inputLanguage?: string;
  inputLabel?: string;
  outputLanguage?: string;
  outputLabel?: string;
}

async function renderCodeWithOutput(attrs: Record<string, unknown>): Promise<string> {
  const variantsRaw = Array.isArray(attrs.variants)
    ? (attrs.variants as Variant[])
    : attrs.code !== undefined && attrs.language !== undefined
      ? [
          {
            code: String(attrs.code),
            language: String(attrs.language),
            label: typeof attrs.label === 'string' ? attrs.label : undefined,
          },
        ]
      : [];
  if (variantsRaw.length === 0) return placeholderHtml('CodeWithOutput', '');

const defaultOutputLanguage = String(attrs.outputLanguage ?? 'text');
  const defaultOutputLabel = String(attrs.outputLabel ?? '결과');
  const defaultInputLanguage = String(attrs.inputLanguage ?? 'text');
  const defaultInputLabel = String(attrs.inputLabel ?? 'stdin');
  const title = typeof attrs.title === 'string' ? attrs.title : null;
  const codeWidth = typeof attrs.codeWidth === 'number' ? attrs.codeWidth : null;

const casesRaw = Array.isArray(attrs.cases) ? (attrs.cases as CaseSpec[]) : null;
  const resolvedCases: CaseSpec[] =
    casesRaw && casesRaw.length > 0
      ? casesRaw
      : [
          {
            input: typeof attrs.input === 'string' ? attrs.input : undefined,
            output: typeof attrs.output === 'string' ? attrs.output : '',
            inputLanguage: defaultInputLanguage,
            inputLabel: defaultInputLabel,
            outputLanguage: defaultOutputLanguage,
            outputLabel: defaultOutputLabel,
          },
        ];
  const isMultiCase = resolvedCases.length > 1;

const variants = await Promise.all(
    variantsRaw.map(async (v) => {
      const code = String(v.code ?? '').trimEnd();
      const lang = String(v.language ?? 'text');
      return {
        label: v.label ?? lang,
        html: await shiki(code, lang),
      };
    }),
  );

const renderedCases = await Promise.all(
    resolvedCases.map(async (c, i) => {
      const rawInput = typeof c.input === 'string' ? c.input : null;
      const hasInput = rawInput !== null && rawInput.length > 0;
      const output = typeof c.output === 'string' ? c.output : '';
      return {
        label: c.label ?? (isMultiCase ? `예제 ${i + 1}` : null),
        showLabel: isMultiCase || typeof c.label === 'string',
        hasInput,
        inputLabel: c.inputLabel ?? defaultInputLabel,
        outputLabel: c.outputLabel ?? defaultOutputLabel,
        inputHtml: hasInput
          ? await shiki(rawInput!.trimEnd(), c.inputLanguage ?? defaultInputLanguage)
          : '',
        outputHtml: await shiki(output.trimEnd(), c.outputLanguage ?? defaultOutputLanguage),
      };
    }),
  );

const headerLeft =
    variants.length > 1
      ? `<div class="cwo-tabs" role="tablist">${variants
          .map(
            (v, i) =>
              `<button type="button" class="cwo-tab${i === 0 ? ' is-active' : ''}" data-cwo-tab="${i}" aria-selected="${i === 0}">${escapeHtml(v.label)}</button>`,
          )
          .join('')}</div>`
      : `<span class="cwo-label">${escapeHtml(variants[0].label)}</span>`;

const variantPanes = variants
    .map(
      (v, i) =>
        `<div class="cwo-variant${i === 0 ? ' is-active' : ''}" data-cwo-variant="${i}">${v.html}</div>`,
    )
    .join('');

const vertical = codeWidth !== null && codeWidth >= 99;
  const style =
    codeWidth !== null ? ` style="--cwo-code-pct:${Math.max(0, Math.min(100, codeWidth))}%"` : '';

export type ComponentRenderer = (attrs: Record<string, unknown>, inner?: string) => Promise<string>;

export const COMPONENT_RENDERERS: Record<string, ComponentRenderer> = {
  CodeWithOutput: renderCodeWithOutput,
};

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function summarizeAttrs(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return '';
  const stripped = trimmed.replace(/\s+/g, ' ');
  const escaped = escapeHtml(stripped);
  return escaped.length > 120 ? escaped.slice(0, 120) + '…' : escaped;
}

export function placeholderHtml(name: string, attrs: string, inner?: string): string {
  const attrSummary = summarizeAttrs(attrs);
  const header = `<div class="mdx-component-placeholder__header"><span class="mdx-component-placeholder__name">&lt;${escapeHtml(name)}&gt;</span>${attrSummary ? ` <span class="mdx-component-placeholder__attrs">${attrSummary}</span>` : ''}</div>`;
  const body =
    inner !== undefined && inner.trim()
      ? `<div class="mdx-component-placeholder__body">${escapeHtml(inner.trim())}</div>`
      : '';
  return `\n\n<div class="mdx-component-placeholder" data-component="${escapeHtml(name)}">${header}${body}</div>\n\n`;
}

export function findTagEnd(src: string, from: number): { end: number; selfClosing: boolean } | null {
  let i = from;
  let depth = 0;
  let inStr: string | null = null;
  while (i < src.length) {
    const c = src[i];
    const prev = i > 0 ? src[i - 1] : '';
    if (inStr) {
      if (c === inStr && prev !== '\\') inStr = null;
    } else {
      if (c === '"' || c === "'" || c === '`') inStr = c;
      else if (c === '{') depth++;
      else if (c === '}') depth--;
      else if (depth === 0) {
        if (c === '/' && src[i + 1] === '>') return { end: i + 2, selfClosing: true };
        if (c === '>') return { end: i + 1, selfClosing: false };
      }
    }
    i++;
  }
  return null;
}

function unescapeTemplate(s: string): string {
  const SENTINEL = '\uE000';
  return s
    .replace(/\\\\/g, SENTINEL)
    .replace(/\\`/g, '`')
    .replace(/\\\$/g, '$')
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t')
    .replace(new RegExp(SENTINEL, 'g'), '\\');
}

function interpretExpr(expr: string): unknown {
  const trimmed = expr.trim();
  if (trimmed === '') return undefined;
  if (trimmed.startsWith('`') && trimmed.endsWith('`')) {
    return unescapeTemplate(trimmed.slice(1, -1));
  }
  if (/^"(?:[^"\\]|\\.)*"$/.test(trimmed) || /^'(?:[^'\\]|\\.)*'$/.test(trimmed)) {
    return trimmed.slice(1, -1).replace(/\\(.)/g, '$1');
  }
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null' || trimmed === 'undefined') return null;
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    return parseArrayLiteral(trimmed);
  }
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
    return parseObjectLiteral(trimmed.slice(1, -1));
  }
  return trimmed;
}

function splitTopLevel(raw: string, separator: ',' | ';'): string[] {
  const out: string[] = [];
  let depth = 0;
  let inStr: string | null = null;
  let start = 0;
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    const prev = i > 0 ? raw[i - 1] : '';
    if (inStr) {
      if (c === inStr && prev !== '\\') inStr = null;
    } else {
      if (c === '"' || c === "'" || c === '`') inStr = c;
      else if (c === '{' || c === '[' || c === '(') depth++;
      else if (c === '}' || c === ']' || c === ')') depth--;
      else if (c === separator && depth === 0) {
        out.push(raw.slice(start, i));
        start = i + 1;
      }
    }
  }
  out.push(raw.slice(start));
  return out;
}

function parseArrayLiteral(raw: string): unknown[] {
  const inner = raw.slice(1, -1).trim();
  if (!inner) return [];
  return splitTopLevel(inner, ',')
    .map((s) => s.trim())
    .filter((s) => s.length > 0)
    .map(interpretExpr);
}

function parseObjectLiteral(inner: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  if (!inner.trim()) return result;
  const items = splitTopLevel(inner, ',');
  for (const item of items) {
    const trimmed = item.trim();
    if (!trimmed) continue;
    let keyEnd = -1;
    let depth = 0;
    let inStr: string | null = null;
    for (let i = 0; i < trimmed.length; i++) {
      const c = trimmed[i];
      const prev = i > 0 ? trimmed[i - 1] : '';
      if (inStr) {
        if (c === inStr && prev !== '\\') inStr = null;
      } else {
        if (c === '"' || c === "'" || c === '`') inStr = c;
        else if (c === '{' || c === '[' || c === '(') depth++;
        else if (c === '}' || c === ']' || c === ')') depth--;
        else if (c === ':' && depth === 0) {
          keyEnd = i;
          break;
        }
      }
    }
    if (keyEnd < 0) continue;
    let key = trimmed.slice(0, keyEnd).trim();
    if (/^["'].*["']$/.test(key)) key = key.slice(1, -1);
    const value = trimmed.slice(keyEnd + 1).trim();
    result[key] = interpretExpr(value);
  }
  return result;
}

export function parseJsxAttrs(raw: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  let i = 0;
  const len = raw.length;
  while (i < len) {
    while (i < len && /\s/.test(raw[i])) i++;
    if (i >= len) break;
    const nameStart = i;
    while (i < len && /[\w-]/.test(raw[i])) i++;
    const name = raw.slice(nameStart, i);
    if (!name) {
      i++;
      continue;
    }
    while (i < len && /\s/.test(raw[i])) i++;
    if (raw[i] !== '=') {
      result[name] = true;
      continue;
    }
    i++;
    while (i < len && /\s/.test(raw[i])) i++;
    const ch = raw[i];
    if (ch === '"' || ch === "'") {
      i++;
      let val = '';
      while (i < len && raw[i] !== ch) {
        if (raw[i] === '\\' && i + 1 < len) {
          val += raw[i + 1];
          i += 2;
        } else {
          val += raw[i++];
        }
      }
      result[name] = val;
      if (i < len) i++;
    } else if (ch === '{') {
      i++;
      const valStart = i;
      let depth = 1;
      let inStr: string | null = null;
      while (i < len && depth > 0) {
        const c = raw[i];
        const prev = i > 0 ? raw[i - 1] : '';
        if (inStr) {
          if (c === inStr && prev !== '\\') inStr = null;
        } else {
          if (c === '"' || c === "'" || c === '`') inStr = c;
          else if (c === '{') depth++;
          else if (c === '}') {
            depth--;
            if (depth === 0) break;
          }
        }
        i++;
      }
      result[name] = interpretExpr(raw.slice(valStart, i));
      if (i < len) i++;
    } else {
      break;
    }
  }
  return result;
}

import { findTagEnd, parseJsxAttrs, placeholderHtml } from './jsx-parser';
import { COMPONENT_RENDERERS } from './component-renderers';

const IMPORT_LINE_RE = /^\s*import\s+[\s\S]*?from\s+['"][^'"]+['"];?\s*$/gm;
const TAG_OPEN_RE = /<([A-Z][\w.]*)/;

async function transformJsx(src: string, seen: Set<string>): Promise<string> {
  const out: string[] = [];
  let cursor = 0;
  while (cursor < src.length) {
    const rest = src.slice(cursor);
    const m = TAG_OPEN_RE.exec(rest);
    if (!m) {
      out.push(rest);
      break;
    }
    const tagStart = cursor + (m.index ?? 0);
    out.push(src.slice(cursor, tagStart));
    const name = m[1];
    const afterName = tagStart + m[0].length;
    const tagEnd = findTagEnd(src, afterName);
    if (!tagEnd) {
      out.push(src.slice(tagStart));
      break;
    }
    const attrsRaw = src.slice(afterName, tagEnd.selfClosing ? tagEnd.end - 2 : tagEnd.end - 1);
    seen.add(name);

let innerRaw: string | undefined = undefined;
    let consumeEnd = tagEnd.end;

if (!tagEnd.selfClosing) {
      const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const closeRe = new RegExp(`</${escapedName}\\s*>`, 'g');
      closeRe.lastIndex = tagEnd.end;
      const close = closeRe.exec(src);
      if (close) {
        innerRaw = src.slice(tagEnd.end, close.index);
        consumeEnd = close.index + close[0].length;
      }
    }

const renderer = COMPONENT_RENDERERS[name];
    if (renderer) {
      try {
        const attrs = parseJsxAttrs(attrsRaw);
        out.push(await renderer(attrs, innerRaw));
      } catch {
        out.push(placeholderHtml(name, attrsRaw, innerRaw));
      }
    } else {
      out.push(placeholderHtml(name, attrsRaw, innerRaw));
    }
    cursor = consumeEnd;
  }
  return out.join('');
}

export async function preprocessMdx(
  content: string,
): Promise<{ transformed: string; componentNames: string[] }> {
  const seen = new Set<string>();
  const noImports = content.replace(IMPORT_LINE_RE, '');
  const transformed = await transformJsx(noImports, seen);
  return { transformed, componentNames: Array.from(seen) };
}

import type { APIRoute } from 'astro';
import { notFoundResponse } from '@/dev-only/shared/api-utils';
import fs from 'node:fs';
import path from 'node:path';
import { CONTENT_ROOT } from '@/dev-only/shared/path-utils';

export const prerender = false;

interface ParsedSource {
  id: string;
  title: string;
  type: string;
  author?: string;
  publisher?: string;
  year?: number;
  url?: string;
  aliases: string[];
  tags: string[];
}

function parseFrontmatter(raw: string): Record<string, unknown> {
  if (!raw.startsWith('---')) return {};
  const end = raw.indexOf('\n---', 3);
  if (end < 0) return {};
  const fm = raw.slice(3, end).trim();
  const data: Record<string, unknown> = {};
  let inList: string | null = null;
  for (const line of fm.split('\n')) {
    if (!line.trim()) continue;
    if (inList && /^\s*-\s+/.test(line)) {
      const value = line.replace(/^\s*-\s+/, '').replace(/^["']|["']$/g, '');
      const arr = data[inList];
      if (Array.isArray(arr)) arr.push(value);
      continue;
    }
    inList = null;
    const m = line.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (!m) continue;
    const key = m[1];
    const raw = m[2].trim();
    if (raw === '' || raw === '[]') {
      if (raw === '[]') data[key] = [];
      else {
        inList = key;
        data[key] = [];
      }
      continue;
    }
    if (raw.startsWith('[') && raw.endsWith(']')) {
      data[key] = raw
        .slice(1, -1)
        .split(',')
        .map((s) => s.trim().replace(/^["']|["']$/g, ''))
        .filter(Boolean);
      continue;
    }
    if (/^-?\d+(\.\d+)?$/.test(raw)) {
      data[key] = Number(raw);
      continue;
    }
    if (raw === 'true' || raw === 'false') {
      data[key] = raw === 'true';
      continue;
    }
    data[key] = raw.replace(/^["']|["']$/g, '');
  }
  return data;
}

function listSources(): ParsedSource[] {
  const dir = path.join(CONTENT_ROOT, 'sources');
  if (!fs.existsSync(dir)) return [];
  const out: ParsedSource[] = [];
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop()!;
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      if (entry.name.startsWith('.') || entry.name.startsWith('_')) continue;
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) {
        stack.push(full);
        continue;
      }
      const m = entry.name.match(/^(.+?)\.md$/);
      if (!m) continue;
      const rel = path.relative(dir, full).replace(/\\/g, '/');
      const id = rel.replace(/\.md$/, '');
      try {
        const raw = fs.readFileSync(full, 'utf-8');
        const fm = parseFrontmatter(raw);
        const aliases = Array.isArray(fm.aliases) ? (fm.aliases as string[]) : [];
        const tags = Array.isArray(fm.tags) ? (fm.tags as string[]) : [];
        out.push({
          id,
          title: typeof fm.title === 'string' ? fm.title : id,
          type: typeof fm.type === 'string' ? fm.type : 'other',
          author: typeof fm.author === 'string' ? fm.author : undefined,
          publisher: typeof fm.publisher === 'string' ? fm.publisher : undefined,
          year: typeof fm.year === 'number' ? fm.year : undefined,
          url: typeof fm.url === 'string' ? fm.url : undefined,
          aliases,
          tags,
        });
      } catch {
        out.push({ id, title: id, type: 'other', aliases: [], tags: [] });
      }
    }
  }
  out.sort((a, b) => a.title.localeCompare(b.title, 'ko'));
  return out;
}

export const GET: APIRoute = () => {
  if (!import.meta.env.DEV) {
    return notFoundResponse();
  }
  return new Response(JSON.stringify({ sources: listSources() }), {
    headers: { 'Content-Type': 'application/json' },
  });
};

import type { APIRoute } from 'astro';
import fs from 'node:fs/promises';
import path from 'node:path';
import { FILE_UPLOAD_MAX_BYTES } from '@/shared/config';
import { errorResponse, jsonResponse, notFoundResponse } from '@/dev-only/shared/api-utils';

export const prerender = false;

const UPLOAD_DIR = path.resolve(process.cwd(), 'public/uploads');

const EXT_BY_TYPE: Record<string, string> = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'image/gif': '.gif',
  'image/webp': '.webp',
  'image/svg+xml': '.svg',
  'image/avif': '.avif',
  'application/pdf': '.pdf',
};

function sanitizeName(raw: string): string {
  return raw
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9가-힣ㄱ-ㅎㅏ-ㅣ_-]+/gi, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 40);
}

export const POST: APIRoute = async ({ request }) => {
  if (!import.meta.env.DEV) return notFoundResponse();

let formData: FormData;
  try {
    formData = await request.formData();
  } catch {
    return errorResponse('multipart 요청이 아닙니다', 400);
  }

const file = formData.get('file');
  if (!(file instanceof File)) return errorResponse('file 필드가 필요합니다', 400);
  if (file.size === 0) return errorResponse('빈 파일', 400);
  if (file.size > FILE_UPLOAD_MAX_BYTES) {
    return errorResponse(`파일이 너무 큽니다 (>${FILE_UPLOAD_MAX_BYTES / 1024 / 1024}MB)`, 413);
  }

const originalExt = path.extname(file.name).toLowerCase();
  const guessedExt = EXT_BY_TYPE[file.type] ?? '';
  const ext = originalExt || guessedExt || '.bin';
  const base = path.basename(file.name, originalExt);
  const safe = sanitizeName(base);
  const timestamp = new Date()
    .toISOString()
    .slice(0, 19)
    .replace(/[-:T]/g, '')
    .replace(/\d{6}$/, (s) => s);
  const rand = Math.random().toString(36).slice(2, 8);
  const filename = `${timestamp}-${rand}${safe ? '-' + safe : ''}${ext}`;

await fs.mkdir(UPLOAD_DIR, { recursive: true });
  await fs.writeFile(path.join(UPLOAD_DIR, filename), Buffer.from(await file.arrayBuffer()));

return jsonResponse({
    path: `/uploads/${filename}`,
    name: file.name,
    size: file.size,
    type: file.type,
  });
};

import type { APIRoute } from 'astro';
import { notFoundResponse } from '@/dev-only/shared/api-utils';
import ogs from 'open-graph-scraper';
import fs from 'node:fs/promises';
import path from 'node:path';

export const prerender = false;

const CACHE_PATH = path.resolve(process.cwd(), 'src/data/url-previews.json');

interface CachedPreview {
  url: string;
  title?: string;
  description?: string;
  image?: string;
  favicon?: string;
  siteName?: string;
  fetchedAt: string;
  error?: string;
}

function cacheKey(url: string): string {
  try {
    const u = new URL(url);
    u.hash = '';
    return u.toString();
  } catch {
    return url;
  }
}

function pickFavicon(url: string, result: Record<string, unknown>): string | undefined {
  const fav = result.favicon;
  if (typeof fav !== 'string' || fav.length === 0) return undefined;
  if (/^https?:/.test(fav)) return fav;
  try {
    return new URL(fav, url).toString();
  } catch {
    return undefined;
  }
}

async function loadCache(): Promise<Record<string, CachedPreview>> {
  try {
    return JSON.parse(await fs.readFile(CACHE_PATH, 'utf-8')) as Record<string, CachedPreview>;
  } catch {
    return {};
  }
}

async function saveCache(cache: Record<string, CachedPreview>): Promise<void> {
  await fs.mkdir(path.dirname(CACHE_PATH), { recursive: true });
  await fs.writeFile(CACHE_PATH, JSON.stringify(cache, null, 2) + '\n', 'utf-8');
}

export const GET: APIRoute = async ({ url }) => {
  if (!import.meta.env.DEV) return notFoundResponse();
  const target = url.searchParams.get('url');
  if (!target) {
    return new Response(JSON.stringify({ error: 'url required' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }
  let parsed: URL;
  try {
    parsed = new URL(target);
  } catch {
    return new Response(JSON.stringify({ error: 'invalid url' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return new Response(JSON.stringify({ error: 'http/https only' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

const force = url.searchParams.get('force') === '1';
  const cache = await loadCache();
  const key = cacheKey(target);
  if (!force && cache[key] && !cache[key].error) {
    return new Response(JSON.stringify({ preview: cache[key], cached: true }), {
      headers: { 'Content-Type': 'application/json' },
    });
  }

try {
    const { error, result } = await ogs({
      url: target,
      timeout: 12000,
      onlyGetOpenGraphInfo: false,
      fetchOptions: {
        headers: { 'User-Agent': 'shinkeonkim-blog-dev-editor/1.0' },
      },
    });
    if (error)
      throw new Error(
        typeof (result as { error?: unknown })?.error === 'string'
          ? (result as { error?: string }).error!
          : 'ogs failed',
      );
    const ogResult = result as Record<string, unknown>;
    const ogImage = Array.isArray(ogResult.ogImage)
      ? (ogResult.ogImage[0] as { url?: string } | undefined)?.url
      : (ogResult.ogImage as { url?: string } | undefined)?.url;
    const preview: CachedPreview = {
      url: target,
      title:
        (ogResult.ogTitle as string | undefined) ?? (ogResult.twitterTitle as string | undefined),
      description:
        (ogResult.ogDescription as string | undefined) ??
        (ogResult.twitterDescription as string | undefined),
      image: ogImage,
      favicon: pickFavicon(target, ogResult),
      siteName: ogResult.ogSiteName as string | undefined,
      fetchedAt: new Date().toISOString(),
    };
    cache[key] = preview;
    await saveCache(cache);
    return new Response(JSON.stringify({ preview, cached: false }), {
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return new Response(JSON.stringify({ error: msg }), {
      status: 502,
      headers: { 'Content-Type': 'application/json' },
    });
  }
};

import { CHART_TEMPLATES } from './templates';

interface ChartInstance {
  destroy: () => void;
  update: () => void;
  data: unknown;
  options: unknown;
  config: { type: string };
}

declare global {
  interface Window {
    Chart: new (canvas: HTMLCanvasElement, config: object) => ChartInstance;
  }
}

const RADIAL = new Set(['pie', 'doughnut', 'radar', 'polarArea']);

interface ThemeColors {
  text: string;
  grid: string;
}

function readThemeColors(): ThemeColors {
  const isDark = document.documentElement.classList.contains('dark');
  return {
    text: isDark ? '#e2e8f0' : '#1e293b',
    grid: isDark ? '#334155' : '#f1f5f9',
  };
}

function buildOptions(
  type: string,
  userOptions: Record<string, unknown> | null,
  colors: ThemeColors,
): Record<string, unknown> {
  const user = (userOptions ?? {}) as Record<string, unknown>;
  const userPlugins = (user.plugins ?? {}) as Record<string, unknown>;
  const userLegend = (userPlugins.legend ?? {}) as Record<string, unknown>;
  const userLegendLabels = (userLegend.labels ?? {}) as Record<string, unknown>;
  const userTooltip = (userPlugins.tooltip ?? {}) as Record<string, unknown>;
  const merged: Record<string, unknown> = {
    responsive: true,
    maintainAspectRatio: false,
    ...user,
    plugins: {
      ...userPlugins,
      legend: {
        position: 'bottom',
        ...userLegend,
        labels: {
          usePointStyle: true,
          font: { size: 11 },
          ...userLegendLabels,
          color: colors.text,
        },
      },
      tooltip: { enabled: true, ...userTooltip },
    },
  };
  if (!RADIAL.has(type)) {
    const userScales = (user.scales ?? {}) as Record<string, Record<string, unknown>>;
    const userX = userScales.x ?? {};
    const userY = userScales.y ?? {};
    merged.scales = {
      ...userScales,
      x: {
        ...userX,
        grid: { ...((userX.grid as object) ?? {}), color: colors.grid },
        ticks: { ...((userX.ticks as object) ?? {}), color: colors.text },
      },
      y: {
        ...userY,
        grid: { ...((userY.grid as object) ?? {}), color: colors.grid },
        ticks: { ...((userY.ticks as object) ?? {}), color: colors.text },
      },
    };
  }
  return merged;
}

export function initChartEditor(): void {
  let chartInstance: ChartInstance | null = null;
  let renderTimer: ReturnType<typeof setTimeout> | null = null;

const byId = <T extends HTMLElement>(id: string): T => document.getElementById(id) as T;
  const typeSel = byId<HTMLSelectElement>('chart-type');
  const titleInput = byId<HTMLInputElement>('chart-title');
  const captionInput = byId<HTMLInputElement>('chart-caption');
  const heightInput = byId<HTMLInputElement>('chart-height');
  const dataInput = byId<HTMLTextAreaElement>('data-input');
  const optionsInput = byId<HTMLTextAreaElement>('options-input');
  const dataError = byId<HTMLElement>('data-error');
  const optionsError = byId<HTMLElement>('options-error');
  const canvas = byId<HTMLCanvasElement>('chart-canvas');
  const canvasContainer = canvas.parentElement as HTMLElement;
  const previewTitle = byId<HTMLElement>('chart-preview-title');
  const previewCaption = byId<HTMLElement>('chart-preview-caption');
  const snippetOutput = byId<HTMLElement>('snippet-output');

function loadTemplate(name: string): void {
    const t = CHART_TEMPLATES[name];
    if (!t) return;
    typeSel.value = t.type;
    dataInput.value = JSON.stringify(t.data, null, 2);
    optionsInput.value = JSON.stringify(t.options, null, 2);
    renderChart();
  }

function applyHeight(): void {
    const h = (heightInput.value || '280px').trim();
    canvasContainer.style.height = h;
  }

function applyTitleCaption(): void {
    const t = titleInput.value.trim();
    const c = captionInput.value.trim();
    if (t) {
      previewTitle.textContent = t;
      previewTitle.hidden = false;
    } else {
      previewTitle.textContent = '';
      previewTitle.hidden = true;
    }
    if (c) {
      previewCaption.textContent = c;
      previewCaption.hidden = false;
    } else {
      previewCaption.textContent = '';
      previewCaption.hidden = true;
    }
  }

function renderChart(): void {
    applyHeight();
    applyTitleCaption();

const type = typeSel.value;
    const dataStr = dataInput.value;
    const optStr = optionsInput.value || '{}';

dataError.textContent = '';
    optionsError.textContent = '';

let data: unknown;
    let options: Record<string, unknown>;
    try {
      data = JSON.parse(dataStr);
    } catch (e) {
      dataError.textContent = 'JSON 파싱 에러: ' + (e as Error).message;
      return;
    }
    try {
      options = JSON.parse(optStr);
    } catch (e) {
      optionsError.textContent = 'JSON 파싱 에러: ' + (e as Error).message;
      return;
    }

const colors = readThemeColors();
    const merged = buildOptions(type, options, colors);

if (chartInstance && chartInstance.config.type === type) {
      chartInstance.data = data;
      chartInstance.options = merged;
      chartInstance.update();
    } else {
      chartInstance?.destroy();
      chartInstance = new window.Chart(canvas, { type, data, options: merged });
    }

generateSnippet(type, data, options);
  }

function scheduleRender(): void {
    if (renderTimer) clearTimeout(renderTimer);
    renderTimer = setTimeout(renderChart, 200);
  }

function generateSnippet(type: string, data: unknown, options: Record<string, unknown>): void {
    const title = titleInput.value.trim();
    const caption = captionInput.value.trim();
    const height = (heightInput.value || '280px').trim();
    const dataStr = JSON.stringify(data);
    const optStr =
      options && Object.keys(options).length ? `\n  options={${JSON.stringify(options)}}` : '';
    const titleStr = title ? `\n  title=${JSON.stringify(title)}` : '';
    const captionStr = caption ? `\n  caption=${JSON.stringify(caption)}` : '';
    const heightStr = height && height !== '280px' ? `\n  height="${height}"` : '';
    snippetOutput.textContent = `<ChartJs
  client:visible
  type="${type}"${titleStr}${captionStr}${heightStr}
  data={${dataStr}}${optStr}
/>`;
  }

function copySnippet(btn: HTMLButtonElement): void {
    const text = snippetOutput.textContent ?? '';
    navigator.clipboard.writeText(text).then(() => {
      const orig = btn.textContent ?? '';
      btn.textContent = '✓ 복사됨!';
      setTimeout(() => {
        btn.textContent = orig;
      }, 1500);
    });
  }

document.querySelectorAll<HTMLButtonElement>('.tpl-btn').forEach((btn) => {
    btn.addEventListener('click', () => loadTemplate(btn.dataset.template ?? ''));
  });
  typeSel.addEventListener('change', renderChart);
  for (const el of [titleInput, captionInput, heightInput, dataInput, optionsInput]) {
    el.addEventListener('input', scheduleRender);
  }
  byId<HTMLButtonElement>('btn-copy').addEventListener('click', (e) =>
    copySnippet(e.currentTarget as HTMLButtonElement),
  );

const themeObserver = new MutationObserver(() => {
    if (chartInstance) renderChart();
  });
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  });

loadTemplate('Line (기본)');
}

