import type { ImageDialogController } from '@/dev-only/editor/ui/image-dialog';

export function setupEditorDropPaste(
  textarea: HTMLTextAreaElement,
  imageDialog: ImageDialogController,
): void {
  textarea.addEventListener('dragover', (e) => {
    e.preventDefault();
    textarea.classList.add('editor-drag-hover');
  });
  textarea.addEventListener('dragleave', () => textarea.classList.remove('editor-drag-hover'));
  textarea.addEventListener('drop', async (e) => {
    e.preventDefault();
    textarea.classList.remove('editor-drag-hover');
    const file = e.dataTransfer?.files?.[0];
    if (file) await imageDialog.handleDroppedFile(file);
  });

textarea.addEventListener('paste', async (e) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const item of items) {
      if (item.kind === 'file' && item.type.startsWith('image/')) {
        e.preventDefault();
        const file = item.getAsFile();
        if (file) await imageDialog.handleDroppedFile(file);
        return;
      }
    }
  });
}

interface Snapshot {
  text: string;
  selStart: number;
  selEnd: number;
}

const MAX_ENTRIES = 100;
const DEBOUNCE_MS = 500;

export class EditorHistory {
  private stack: Snapshot[] = [];
  private pointer = -1;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private pendingFromTextarea = false;
  private textarea: HTMLTextAreaElement;
  private suppress = false;

constructor(textarea: HTMLTextAreaElement) {
    this.textarea = textarea;
    this.snapshot();
    textarea.addEventListener('input', this.handleInput);
  }

private handleInput = (): void => {
    if (this.suppress) return;
    this.pendingFromTextarea = true;
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      if (this.pendingFromTextarea) {
        this.snapshot();
        this.pendingFromTextarea = false;
      }
    }, DEBOUNCE_MS);
  };

snapshot(): void {
    const text = this.textarea.value;
    const last = this.stack[this.pointer];
    if (last && last.text === text) return;
    this.stack = this.stack.slice(0, this.pointer + 1);
    this.stack.push({
      text,
      selStart: this.textarea.selectionStart,
      selEnd: this.textarea.selectionEnd,
    });
    if (this.stack.length > MAX_ENTRIES) {
      this.stack = this.stack.slice(this.stack.length - MAX_ENTRIES);
    }
    this.pointer = this.stack.length - 1;
  }

reset(): void {
    this.stack = [];
    this.pointer = -1;
    this.snapshot();
  }

canUndo(): boolean {
    return this.pointer > 0;
  }

canRedo(): boolean {
    return this.pointer < this.stack.length - 1;
  }

undo(): boolean {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.pendingFromTextarea) {
      this.snapshot();
      this.pendingFromTextarea = false;
    }
    if (!this.canUndo()) return false;
    this.pointer--;
    this.apply(this.stack[this.pointer]);
    return true;
  }

redo(): boolean {
    if (!this.canRedo()) return false;
    this.pointer++;
    this.apply(this.stack[this.pointer]);
    return true;
  }

private apply(snap: Snapshot): void {
    this.suppress = true;
    this.textarea.value = snap.text;
    this.textarea.setSelectionRange(snap.selStart, snap.selEnd);
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
    this.suppress = false;
  }
}

import type { EditorHistory } from '@/dev-only/editor/core/history';
import type { FindReplaceBar } from '@/dev-only/editor/text/find-replace';
import type { GlobalSearch } from '@/dev-only/editor/text/global-search';
import { state } from '@/dev-only/editor/core/state';

interface ShortcutDeps {
  textarea: HTMLTextAreaElement;
  save: () => Promise<void>;
  history: EditorHistory;
  findReplace: FindReplaceBar;
  globalSearch: GlobalSearch;
}

export function bindEditorShortcuts(deps: ShortcutDeps): void {
  const { textarea, save, history, findReplace, globalSearch } = deps;
  document.addEventListener('keydown', (e) => {
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key.toLowerCase() === 's') {
      e.preventDefault();
      if (state.current) void save();
      return;
    }
    const inTextarea = e.target === textarea;
    if (mod && e.shiftKey && e.key.toLowerCase() === 'f') {
      e.preventDefault();
      globalSearch.toggle();
      return;
    }
    if (mod && e.key.toLowerCase() === 'f' && inTextarea) {
      e.preventDefault();
      findReplace.show();
      return;
    }
    if (mod && e.key.toLowerCase() === 'z' && inTextarea) {
      e.preventDefault();
      if (e.shiftKey) history.redo();
      else history.undo();
      return;
    }
    if (mod && e.key.toLowerCase() === 'y' && inTextarea) {
      e.preventDefault();
      history.redo();
    }
  });
}

