export function initEditor(): void {
  const ui = queryEditorUi();
  if (!ui) {
    console.error('[editor] missing required elements');
    return;
  }
  document.body.classList.add('editor-active');
  document.documentElement.classList.add('editor-active');
  const {
    status: statusEl,
    textarea,
    saveBtn,
    pathEl,
    previewToggle,
    previewEl,
    previewContent,
    previewLink,
    splitEl,
    treeRoot,
    toolbarRoot,
    gitPanelRoot,
    gitToggleBtn,
    autosaveIndicator,
  } = ui;

void splitEl;
  initStatus(statusEl);

const referencesPicker = new ReferencesPicker({
    getContent: () => textarea.value,
    setContent: (next) => {
      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      textarea.value = next;
      try {
        textarea.selectionStart = Math.min(start, next.length);
        textarea.selectionEnd = Math.min(end, next.length);
      } catch {
        return;
      }
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    },
  });

const urlPreview = new UrlPreviewController(textarea);

const toolbar = new MarkdownToolbar({
    textarea,
    openImagePicker: () => imageDialog.openFor('body'),
    openImageDialogFor: (purpose) => imageDialog.openFor(purpose),
    openReferencesPicker: () => void referencesPicker.open(),
    insertUrlPreview: () => urlPreview.insertNew(),
    toggleUrlPreviewAtCursor: () => urlPreview.toggleAtCursor(),
  });
  toolbar.bind(toolbarRoot);

const imageDialog = new ImageDialogController(toolbar);
  new AnimationPicker(toolbar).init();

const preview = new PreviewPane({
    container: previewEl,
    content: previewContent,
    toggle: previewToggle,
    split: splitEl,
    textarea,
    getText: () => textarea.value,
    getExt: () => state.current?.ext ?? '.md',
  });

const autosaver = new Autosaver(
    () => state.current,
    () => textarea.value,
    (timestamp) => {
      state.lastSavedAt = timestamp;
      autosaveIndicator.textContent = `자동저장 ${new Date(timestamp).toLocaleTimeString('ko-KR')}`;
    },
    (message) => {
      autosaveIndicator.textContent = `⚠ ${message}`;
      setStatus(message, 'error');
    },
  );
  autosaver.start();

const wikilink = new WikilinkAutocomplete(textarea);
  const history = new EditorHistory(textarea);
  const findReplace = new FindReplaceBar(textarea);
  setupListContinuation(textarea);
  const globalSearch = new GlobalSearch(async (collection, slug, ext, line, column) => {
    void ext;
    await loadFile(collection, slug);
    const value = textarea.value;
    const lines = value.split('\n');
    let offset = 0;
    for (let i = 0; i < Math.min(line - 1, lines.length); i += 1) {
      offset += lines[i].length + 1;
    }
    offset += Math.min(column - 1, lines[line - 1]?.length ?? 0);
    textarea.focus();
    textarea.setSelectionRange(offset, offset);
    const lineHeight = parseFloat(getComputedStyle(textarea).lineHeight || '20');
    textarea.scrollTop = Math.max(0, (line - 1) * lineHeight - textarea.clientHeight / 2);
  });

const frontmatterPanelEl = document.getElementById('editor-frontmatter-panel');
  const frontmatterPanel = frontmatterPanelEl
    ? new FrontmatterPanel(frontmatterPanelEl, textarea, toolbar)
    : null;
  void frontmatterPanel;

const treeSearchInput = document.getElementById('editor-tree-search') as HTMLInputElement | null;
  if (treeSearchInput) setupTreeSearchFilter(treeSearchInput);

function setCurrent(file: CurrentFile | null, caret?: { start: number; end: number; scrollTop: number }): void {
    state.current = file;
    if (file) {
      pathEl.textContent = `${file.collection}/${file.slug}${file.ext}`;
      textarea.disabled = false;
      saveBtn.disabled = false;
      previewLink.style.display = '';
      previewLink.dataset.href = urlFor(file.collection, file.slug);
      tree.setSelection(file);
      tree.expandTo(file);
      autosaver.reset();
    } else {
      pathEl.textContent = '파일을 선택하거나 "새 파일" 을 누르세요';
      textarea.disabled = true;
      saveBtn.disabled = true;
      previewLink.style.display = 'none';
      tree.setSelection(null);
    }
    updateExtToggle();
    textarea.focus();
    if (caret && file) {
      const max = textarea.value.length;
      textarea.selectionStart = Math.min(caret.start, max);
      textarea.selectionEnd = Math.min(caret.end, max);
      textarea.scrollTop = caret.scrollTop;
    }
    void preview.render();
  }

const tree = new FileTree(treeRoot, {
    onSelectFile: (collection, slug) => void loadFile(collection, slug),
    onContextFile: (collection, slug, anchor) => {
      const ext = (anchor.closest('[data-tree-file]') as HTMLElement | null)?.dataset.ext as Ext;
      void fileOps.fileMenu(collection, slug, ext ?? '.md', anchor);
    },
    onContextFolder: (collection, folder, anchor) =>
      void fileOps.folderMenu(collection, folder, anchor),
    onNewFile: (collection, folder) => void handleNewFile(collection, folder),
    onNewFolder: (collection, folder) => void fileOps.newFolder(collection, folder),
    onRenameFileInline: (collection, slug, ext, name) =>
      fileOps.renameFileInline(collection, slug, ext, name),
    onRenameFolderInline: (collection, folder, name) =>
      fileOps.renameFolderInline(collection, folder, name),
    onDropItem: (item, target) => fileOps.dropItem(item, target),
  });
  void tree.refresh();

const fileOps = new FileOpsController({
    onChanged: async () => {
      await tree.refresh();
      await wikilink.refresh();
    },
    onFileChanged: (oldFile, newFile) => {
      if (
        oldFile &&
        state.current &&
        state.current.collection === oldFile.collection &&
        state.current.slug === oldFile.slug
      ) {
        if (newFile)
          setCurrent({ collection: newFile.collection, slug: newFile.slug, ext: newFile.ext });
        else {
          textarea.value = '';
          setCurrent(null);
        }
      }
    },
    onFolderChanged: (oldFolder, newFolder) => {
      const cur = state.current;
      if (!cur || cur.collection !== oldFolder.collection) return;
      const prefix = oldFolder.folder ? `${oldFolder.folder}/` : '';
      if (!prefix || !cur.slug.startsWith(prefix)) return;
      const remainder = cur.slug.slice(prefix.length);
      const newSlug = newFolder.folder ? `${newFolder.folder}/${remainder}` : remainder;
      setCurrent({ collection: cur.collection, slug: newSlug, ext: cur.ext });
    },
  });

const extToggleBtn = document.getElementById('editor-ext-toggle') as HTMLButtonElement | null;
  function updateExtToggle(): void {
    if (!extToggleBtn) return;
    if (!state.current) {
      extToggleBtn.style.display = 'none';
      return;
    }
    extToggleBtn.style.display = '';
    const next: Ext = state.current.ext === '.md' ? '.mdx' : '.md';
    extToggleBtn.textContent = `${state.current.ext} → ${next}`;
    extToggleBtn.title = `현재 ${state.current.ext} · 클릭으로 ${next} 로 변환`;
  }
  extToggleBtn?.addEventListener('click', async () => {
    const cur = state.current;
    if (!cur) return;
    if (state.isDirty) {
      const proceed = await confirmModal({
        title: '변경 사항이 있습니다',
        description: '저장하지 않은 변경 사항이 있습니다. 확장자 변환 전에 저장하시겠습니까?',
        confirmLabel: '저장 후 변환',
        cancelLabel: '취소',
      });
      if (!proceed) return;
      await save();
    }
    const nextExt = await fileOps.toggleExt(cur.collection, cur.slug, cur.ext);
    if (nextExt) updateExtToggle();
  });

const gitPanel = new GitPanel(gitPanelRoot);
  gitToggleBtn.addEventListener('click', () => gitPanel.toggle());

async function handleNewFile(collection: CollectionName, folder: string): Promise<void> {
    const result = await fileOps.newFile(collection, folder);
    if (!result) return;
    if (state.isDirty) {
      const proceed = await confirmModal({
        title: '변경 사항이 있습니다',
        description: '현재 파일을 저장하지 않고 새 파일로 전환할까요?',
        confirmLabel: '버리고 전환',
        danger: true,
      });
      if (!proceed) return;
    }
    textarea.value = newFileTemplate(result.collection, result.slug);
    setCurrent(result);
    state.isDirty = true;
    setStatus('새 파일 (저장 안 됨)', 'ok');
  }

async function loadFile(
    collection: CollectionName,
    slug: string,
    opts?: { silent?: boolean; caret?: { start: number; end: number; scrollTop: number } },
  ): Promise<void> {
    if (state.isDirty && !opts?.silent) {
      const proceed = await confirmModal({
        title: '변경 사항이 있습니다',
        description: '저장하지 않고 다른 파일로 전환할까요?',
        confirmLabel: '버리고 전환',
        danger: true,
      });
      if (!proceed) return;
    }
    setStatus('파일 로딩…');
    try {
      const data = await api.loadFile(collection, slug);
      const file: CurrentFile = { collection, slug, ext: data.ext };
      const draft = readDraft(file);
      let serverContent = data.content;
      let useDraft = false;
      if (draft && draft.content !== serverContent) {
        if (opts?.silent) {
          serverContent = draft.content;
          useDraft = true;
        } else {
          const restore = await confirmModal({
            title: '임시 저장본 발견',
            description: `${new Date(draft.savedAt).toLocaleString('ko-KR')} 에 자동 저장된 미저장 변경 사항이 있습니다. 복원할까요?`,
            confirmLabel: '복원',
            cancelLabel: '버리고 서버 버전 사용',
          });
          if (restore) {
            serverContent = draft.content;
            useDraft = true;
          } else {
            clearDraft(file);
          }
        }
      }
      textarea.value = serverContent;
      state.isDirty = useDraft;
      setCurrent(file, opts?.caret);
      history.reset();
      const okMsg = opts?.silent
        ? useDraft
          ? '세션 복원됨 (미저장 변경 포함)'
          : '세션 복원됨'
        : useDraft
          ? '임시 저장본 복원됨'
          : '로드 완료';
      setStatus(okMsg, 'ok');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('로드 실패: ' + msg, 'error');
    }
  }

function captureUiState(reason: PersistReason): PersistedUiState {
    return {
      current: state.current,
      caretStart: textarea.selectionStart,
      caretEnd: textarea.selectionEnd,
      scrollTop: textarea.scrollTop,
      previewOpen: previewToggle.checked,
      treeSearch: treeSearchInput?.value ?? '',
      gitPanelOpen: !gitPanelRoot.hidden,
      savedAt: Date.now(),
      reason,
    };
  }

function persist(reason: PersistReason): void {
    saveUiState(captureUiState(reason));
  }

async function save(): Promise<void> {
    const file = state.current;
    if (!file) return;
    setStatus('저장 중…');
    try {
      const data = await api.saveFile({
        collection: file.collection,
        slug: file.slug,
        ext: file.ext,
        content: textarea.value,
      });
      state.isDirty = false;
      setStatus(`저장됨 → ${data.path} (${data.bytes}B)`, 'ok');
      clearDraft(file);
      autosaver.reset();
      persist('save');
      await tree.refresh();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('저장 실패: ' + msg, 'error');
    }
  }

saveBtn.addEventListener('click', () => void save());
  textarea.addEventListener('input', () => {
    state.isDirty = true;
    preview.schedule();
  });

bindEditorShortcuts({ textarea, save, history, findReplace, globalSearch });
  setupEditorDropPaste(textarea, imageDialog);

previewLink.addEventListener('click', () => {
    if (previewLink.dataset.href) window.open(previewLink.dataset.href, '_blank', 'noopener');
  });

window.addEventListener('beforeunload', (e) => {
    persist('unload');
    if (state.isDirty) e.preventDefault();
  });

document.documentElement.classList.add('editor-active');

textarea.disabled = true;
  saveBtn.disabled = true;

void restoreSession({ treeSearchInput, previewToggle, gitPanel, loadFile });
}

import type { CurrentFile } from '@/dev-only/editor/core/state';

const STORAGE_KEY = 'editor-ui-state-v1';
const SILENT_RESTORE_AFTER_SAVE_WINDOW_MS = 5_000;

export type PersistReason = 'save' | 'unload' | 'periodic';

export interface PersistedUiState {
  current: CurrentFile | null;
  caretStart: number;
  caretEnd: number;
  scrollTop: number;
  previewOpen: boolean;
  treeSearch: string;
  gitPanelOpen: boolean;
  savedAt: number;
  reason: PersistReason;
}

export function saveUiState(state: PersistedUiState): boolean {
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    return true;
  } catch {
    return false;
  }
}

export function loadUiState(): PersistedUiState | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as PersistedUiState;
    if (!isValid(parsed)) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function clearUiState(): void {
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    return;
  }
}

export function isFreshSaveSnapshot(state: PersistedUiState): boolean {
  if (state.reason !== 'save') return false;
  return Date.now() - state.savedAt < SILENT_RESTORE_AFTER_SAVE_WINDOW_MS;
}

function isValid(s: unknown): s is PersistedUiState {
  if (!s || typeof s !== 'object') return false;
  const o = s as Record<string, unknown>;
  if (typeof o.caretStart !== 'number') return false;
  if (typeof o.caretEnd !== 'number') return false;
  if (typeof o.scrollTop !== 'number') return false;
  if (typeof o.previewOpen !== 'boolean') return false;
  if (typeof o.treeSearch !== 'string') return false;
  if (typeof o.gitPanelOpen !== 'boolean') return false;
  if (typeof o.savedAt !== 'number') return false;
  if (o.reason !== 'save' && o.reason !== 'unload' && o.reason !== 'periodic') return false;
  if (o.current !== null) {
    const c = o.current as Record<string, unknown>;
    if (typeof c.collection !== 'string') return false;
    if (typeof c.slug !== 'string') return false;
    if (c.ext !== '.md' && c.ext !== '.mdx') return false;
  }
  return true;
}

import type { GitPanel } from '@/dev-only/editor/panels/git-panel';
import {
  clearUiState,
  isFreshSaveSnapshot,
  loadUiState,
} from '@/dev-only/editor/core/persistence';
import { COLLECTION_NAMES, type CollectionName } from '@/dev-only/editor/core/state';
import { setStatus } from '@/dev-only/editor/core/status';

interface SessionRestoreDeps {
  treeSearchInput: HTMLInputElement | null;
  previewToggle: HTMLInputElement;
  gitPanel: GitPanel;
  loadFile: (
    collection: CollectionName,
    slug: string,
    opts?: { silent?: boolean; caret?: { start: number; end: number; scrollTop: number } },
  ) => Promise<void>;
}

export async function restoreSession(deps: SessionRestoreDeps): Promise<void> {
  const { treeSearchInput, previewToggle, gitPanel, loadFile } = deps;

const urlParams = new URLSearchParams(window.location.search);
  const qCollection = urlParams.get('collection');
  const qSlug = urlParams.get('slug');

if (qCollection && qSlug && COLLECTION_NAMES.includes(qCollection as CollectionName)) {
    try {
      await loadFile(qCollection as CollectionName, qSlug);
    } catch {
      setStatus(`파일을 찾을 수 없습니다: ${qCollection}/${qSlug}`, 'error');
    }
    return;
  }

const snapshot = loadUiState();
  if (!snapshot) {
    setStatus('준비됨', 'ok');
    return;
  }
  if (snapshot.treeSearch && treeSearchInput) {
    treeSearchInput.value = snapshot.treeSearch;
    treeSearchInput.dispatchEvent(new Event('input', { bubbles: true }));
  }
  if (snapshot.previewOpen && !previewToggle.checked) {
    previewToggle.checked = true;
    previewToggle.dispatchEvent(new Event('change', { bubbles: true }));
  }
  if (snapshot.gitPanelOpen) gitPanel.open();

if (snapshot.current) {
    const silent = isFreshSaveSnapshot(snapshot);
    await loadFile(snapshot.current.collection, snapshot.current.slug, {
      silent,
      caret: {
        start: snapshot.caretStart,
        end: snapshot.caretEnd,
        scrollTop: snapshot.scrollTop,
      },
    });
    if (!silent) clearUiState();
  } else {
    setStatus('준비됨', 'ok');
  }
}

export type Ext = '.md' | '.mdx';
export type CollectionName = 'posts' | 'notes' | 'wiki' | 'sources';
export const COLLECTION_NAMES: CollectionName[] = ['posts', 'notes', 'wiki', 'sources'];

export interface CurrentFile {
  collection: CollectionName;
  slug: string;
  ext: Ext;
}

export interface EditorState {
  current: CurrentFile | null;
  isDirty: boolean;
  lastSavedAt: number | null;
}

export const state: EditorState = {
  current: null,
  isDirty: false,
  lastSavedAt: null,
};

type Listener = (state: EditorState) => void;
const listeners = new Set<Listener>();

export function subscribe(listener: Listener): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function notify(): void {
  for (const l of listeners) l(state);
}

type Kind = 'info' | 'ok' | 'error';

let el: HTMLElement | null = null;

export function initStatus(element: HTMLElement): void {
  el = element;
}

export function setStatus(text: string, kind: Kind = 'info'): void {
  if (!el) return;
  el.textContent = text;
  el.style.color =
    kind === 'error' ? '#ef4444' : kind === 'ok' ? '#10b981' : 'var(--color-fg-muted)';
}

import { todayIsoDate, todayIsoTime } from '@/dev-only/editor/lib/utils';
import type { CollectionName } from '@/dev-only/editor/core/state';

export function newFileTemplate(collection: CollectionName, slug: string): string {
  const filename = slug.split('/').pop() ?? slug;
  if (collection === 'posts') {
    return `---
title: "${filename}"
description: ""
date: ${todayIsoDate()}
tags: []
draft: true
---

`;
  }
  if (collection === 'notes') {
    return `---
date: ${todayIsoTime()}
tags: []
---

`;
  }
  if (collection === 'sources') {
    return `---
title: "${filename}"
type: website
tags: []
---

출처에 대한 간단한 설명을 작성하세요.
`;
  }
  return `---
title: "${filename}"
aliases: []
tags: []
updated: ${todayIsoDate()}
---

## 개요

`;
}

export function setupTreeSearchFilter(treeSearchInput: HTMLInputElement): void {
  const applyFilter = (): void => {
    const q = treeSearchInput.value.trim().toLowerCase();
    const treeRoot = document.getElementById('editor-tree-root');
    if (!treeRoot) return;
    const rows = treeRoot.querySelectorAll<HTMLElement>('.editor-tree-row');
    rows.forEach((row) => {
      if (!q) {
        row.classList.remove('is-filter-hidden');
        return;
      }
      const name = row.querySelector<HTMLElement>('[data-tree-name]')?.textContent?.toLowerCase() ?? '';
      if (name.includes(q)) row.classList.remove('is-filter-hidden');
      else row.classList.add('is-filter-hidden');
    });
  };
  treeSearchInput.addEventListener('input', applyFilter);
  treeSearchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      treeSearchInput.value = '';
      applyFilter();
    }
  });
  new MutationObserver(applyFilter).observe(
    document.getElementById('editor-tree-root') ?? document.body,
    { childList: true, subtree: true },
  );
}

export interface EditorUi {
  status: HTMLElement;
  textarea: HTMLTextAreaElement;
  saveBtn: HTMLButtonElement;
  pathEl: HTMLElement;
  previewToggle: HTMLInputElement;
  previewEl: HTMLElement;
  previewContent: HTMLElement;
  previewLink: HTMLButtonElement;
  splitEl: HTMLElement;
  treeRoot: HTMLElement;
  toolbarRoot: HTMLElement;
  gitPanelRoot: HTMLElement;
  gitToggleBtn: HTMLButtonElement;
  autosaveIndicator: HTMLElement;
}

export function queryEditorUi(): EditorUi | null {
  const status = document.getElementById('editor-status');
  const textarea = document.getElementById('editor-textarea') as HTMLTextAreaElement | null;
  const saveBtn = document.getElementById('editor-save') as HTMLButtonElement | null;
  const pathEl = document.getElementById('editor-current-path');
  const previewToggle = document.getElementById('editor-preview-toggle') as HTMLInputElement | null;
  const previewEl = document.getElementById('editor-preview');
  const previewContent = document.getElementById('editor-preview-content');
  const previewLink = document.getElementById('editor-preview-link') as HTMLButtonElement | null;
  const splitEl = document.getElementById('editor-split');
  const treeRoot = document.getElementById('editor-tree-root');
  const toolbarRoot = document.querySelector<HTMLElement>('.editor-md-toolbar');
  const gitPanelRoot = document.getElementById('editor-git-panel');
  const gitToggleBtn = document.getElementById('editor-git-toggle') as HTMLButtonElement | null;
  const autosaveIndicator = document.getElementById('editor-autosave-indicator');

import type { CurrentFile } from '@/dev-only/editor/core/state';
import { EDITOR_AUTOSAVE_INTERVAL_MS } from '@/shared/config';

const PREFIX = 'editor-draft:';
const AUTOSAVE_INTERVAL = EDITOR_AUTOSAVE_INTERVAL_MS;

function keyFor(file: CurrentFile): string {
  return `${PREFIX}${file.collection}/${file.slug}${file.ext}`;
}

export interface DraftRecord {
  content: string;
  savedAt: number;
}

export function readDraft(file: CurrentFile): DraftRecord | null {
  try {
    const raw = localStorage.getItem(keyFor(file));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as DraftRecord;
    if (typeof parsed.content !== 'string' || typeof parsed.savedAt !== 'number') return null;
    return parsed;
  } catch {
    return null;
  }
}

export function writeDraft(file: CurrentFile, content: string): boolean {
  try {
    const record: DraftRecord = { content, savedAt: Date.now() };
    localStorage.setItem(keyFor(file), JSON.stringify(record));
    return true;
  } catch {
    return false;
  }
}

export function clearDraft(file: CurrentFile): void {
  try {
    localStorage.removeItem(keyFor(file));
  } catch {
    return;
  }
}

export class Autosaver {
  private timer: ReturnType<typeof setInterval> | null = null;
  private lastSnapshot = '';
  private failureNotified = false;
  private fileGetter: () => CurrentFile | null;
  private contentGetter: () => string;
  private onSaved: (timestamp: number) => void;
  private onFailed: ((message: string) => void) | null;

constructor(
    fileGetter: () => CurrentFile | null,
    contentGetter: () => string,
    onSaved: (t: number) => void,
    onFailed?: (message: string) => void,
  ) {
    this.fileGetter = fileGetter;
    this.contentGetter = contentGetter;
    this.onSaved = onSaved;
    this.onFailed = onFailed ?? null;
  }

start(): void {
    if (this.timer) return;
    this.timer = setInterval(() => this.tick(), AUTOSAVE_INTERVAL);
  }

stop(): void {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

reset(): void {
    this.lastSnapshot = this.contentGetter();
  }

forceSave(): void {
    const file = this.fileGetter();
    if (!file) return;
    const content = this.contentGetter();
    this.persist(file, content);
  }

private tick(): void {
    const file = this.fileGetter();
    if (!file) return;
    const content = this.contentGetter();
    if (content === this.lastSnapshot) return;
    this.persist(file, content);
  }

private persist(file: CurrentFile, content: string): void {
    const ok = writeDraft(file, content);
    if (ok) {
      this.lastSnapshot = content;
      this.failureNotified = false;
      this.onSaved(Date.now());
    } else if (!this.failureNotified) {
      this.failureNotified = true;
      this.onFailed?.('초안 자동 저장 실패 (브라우저 저장공간 가득 참)');
    }
  }
}

import { api } from '@/dev-only/editor/core/api';
import { confirmModal, openModal } from '@/dev-only/editor/ui/modal';
import { setStatus } from '@/dev-only/editor/core/status';
import type { DraggedItem, DropTarget } from '@/dev-only/editor/ui/tree';
import type { CollectionName, Ext } from '@/dev-only/editor/core/state';

import { COLLECTION_NAMES } from '@/dev-only/editor/core/state';
const COLLECTION_OPTIONS = COLLECTION_NAMES.map((c) => ({ value: c, label: c }));

function splitNameAndExt(name: string, fallbackExt: Ext): { base: string; ext: Ext } {
  if (name.endsWith('.mdx')) return { base: name.slice(0, -4), ext: '.mdx' };
  if (name.endsWith('.md')) return { base: name.slice(0, -3), ext: '.md' };
  return { base: name, ext: fallbackExt };
}

type FileChangeHandler = (
  oldFile: { collection: CollectionName; slug: string } | null,
  newFile: { collection: CollectionName; slug: string; ext: Ext } | null,
) => void;

type FolderChangeHandler = (
  oldFolder: { collection: CollectionName; folder: string },
  newFolder: { collection: CollectionName; folder: string },
) => void;

export class FileOpsController {
  private onChanged: () => Promise<void>;
  private onFileChanged: FileChangeHandler;
  private onFolderChanged: FolderChangeHandler;

constructor(opts: {
    onChanged: () => Promise<void>;
    onFileChanged: FileChangeHandler;
    onFolderChanged: FolderChangeHandler;
  }) {
    this.onChanged = opts.onChanged;
    this.onFileChanged = opts.onFileChanged;
    this.onFolderChanged = opts.onFolderChanged;
  }

async newFile(
    collection: CollectionName,
    folder: string,
  ): Promise<{ collection: CollectionName; slug: string; ext: '.md' | '.mdx' } | null> {
    const r = await openModal({
      title: '새 파일',
      fields: [
        {
          name: 'collection',
          label: '컬렉션',
          type: 'select',
          value: collection,
          options: COLLECTION_OPTIONS,
        },
        {
          name: 'slug',
          label: '슬러그 (하위 폴더 포함 가능)',
          value: folder ? folder + '/' : '',
          placeholder: 'my-post 또는 sub/folder/name',
          required: true,
        },
        {
          name: 'ext',
          label: '확장자',
          type: 'select',
          value: '.md',
          options: [
            { value: '.md', label: '.md (일반 마크다운)' },
            { value: '.mdx', label: '.mdx (MDX 컴포넌트 사용)' },
          ],
        },
      ],
      confirmLabel: '만들기',
    });
    if (!r.confirmed) return null;
    const slug = r.values.slug.trim();
    if (!slug) return null;
    const targetCollection = r.values.collection as CollectionName;
    const ext = (r.values.ext === '.mdx' ? '.mdx' : '.md') as '.md' | '.mdx';
    return { collection: targetCollection, slug, ext };
  }

async newFolder(collection: CollectionName, parent: string): Promise<void> {
    const r = await openModal({
      title: '새 폴더',
      description: parent ? `상위: ${collection}/${parent}` : `상위: ${collection}/`,
      fields: [
        {
          name: 'name',
          label: '폴더 이름',
          required: true,
          placeholder: 'subfolder 또는 nested/sub',
        },
      ],
    });
    if (!r.confirmed) return;
    const name = r.values.name.trim();
    if (!name) return;
    const target = parent ? `${parent}/${name}` : name;
    try {
      await api.fileOps({ action: 'create-folder', collection, folder: target });
      setStatus(`폴더 생성: ${collection}/${target}`, 'ok');
      await this.onChanged();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('폴더 생성 실패: ' + msg, 'error');
    }
  }

async fileMenu(
    collection: CollectionName,
    slug: string,
    currentExt: '.md' | '.mdx',
    anchor: HTMLElement,
  ): Promise<void> {
    const r = await openModal({
      title: '파일 작업',
      description: `${collection}/${slug}${currentExt}`,
      fields: [
        {
          name: 'action',
          label: '작업',
          type: 'select',
          value: 'rename',
          options: [
            { value: 'rename', label: '이름 변경 / 위치 이동' },
            { value: 'move-collection', label: '다른 컬렉션으로 이동' },
            { value: 'delete', label: '삭제' },
          ],
        },
      ],
    });
    anchor.blur();
    if (!r.confirmed) return;
    if (r.values.action === 'rename') await this.renameFile(collection, slug, currentExt);
    else if (r.values.action === 'move-collection')
      await this.moveFile(collection, slug, currentExt);
    else if (r.values.action === 'delete') await this.deleteFile(collection, slug, currentExt);
  }

async folderMenu(collection: CollectionName, folder: string, anchor: HTMLElement): Promise<void> {
    const r = await openModal({
      title: '폴더 작업',
      description: `${collection}/${folder}`,
      fields: [
        {
          name: 'action',
          label: '작업',
          type: 'select',
          value: 'rename',
          options: [
            { value: 'rename', label: '이름 변경' },
            { value: 'delete', label: '삭제 (내부 파일 모두 삭제)' },
          ],
        },
      ],
    });
    anchor.blur();
    if (!r.confirmed) return;
    if (r.values.action === 'rename') await this.renameFolder(collection, folder);
    else if (r.values.action === 'delete') await this.deleteFolder(collection, folder);
  }

private async renameFile(
    collection: CollectionName,
    slug: string,
    ext: '.md' | '.mdx',
  ): Promise<void> {
    const r = await openModal({
      title: '파일 이름 변경 / 이동',
      fields: [
        { name: 'slug', label: '새 슬러그 (폴더 변경 가능)', value: slug, required: true },
        {
          name: 'ext',
          label: '확장자',
          type: 'select',
          value: ext,
          options: [
            { value: '.md', label: '.md' },
            { value: '.mdx', label: '.mdx' },
          ],
        },
      ],
      confirmLabel: '변경',
    });
    if (!r.confirmed) return;
    const newSlug = r.values.slug.trim();
    const newExt = (r.values.ext === '.mdx' ? '.mdx' : '.md') as '.md' | '.mdx';
    if (!newSlug || (newSlug === slug && newExt === ext)) return;
    try {
      await api.fileOps({
        action: 'rename-file',
        collection,
        slug,
        ext,
        toSlug: newSlug,
        toExt: newExt,
      });
      setStatus(`이름 변경: ${slug}${ext} → ${newSlug}${newExt}`, 'ok');
      await this.onChanged();
      this.onFileChanged({ collection, slug }, { collection, slug: newSlug, ext: newExt });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('이름 변경 실패: ' + msg, 'error');
    }
  }

private async moveFile(
    collection: CollectionName,
    slug: string,
    ext: '.md' | '.mdx',
  ): Promise<void> {
    const r = await openModal({
      title: '컬렉션 이동',
      fields: [
        {
          name: 'toCollection',
          label: '대상 컬렉션',
          type: 'select',
          value: collection,
          options: COLLECTION_OPTIONS,
        },
        { name: 'toSlug', label: '대상 슬러그', value: slug, required: true },
      ],
      confirmLabel: '이동',
    });
    if (!r.confirmed) return;
    const toCollection = r.values.toCollection as CollectionName;
    const toSlug = r.values.toSlug.trim();
    if (!toSlug) return;
    if (toCollection === collection && toSlug === slug) return;
    try {
      await api.fileOps({
        action: 'move-file',
        collection,
        slug,
        ext,
        toCollection,
        toSlug,
      });
      setStatus(`이동: ${collection}/${slug} → ${toCollection}/${toSlug}`, 'ok');
      await this.onChanged();
      this.onFileChanged({ collection, slug }, { collection: toCollection, slug: toSlug, ext });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('이동 실패: ' + msg, 'error');
    }
  }

private async deleteFile(
    collection: CollectionName,
    slug: string,
    ext: '.md' | '.mdx',
  ): Promise<void> {
    const confirmed = await confirmModal({
      title: '파일 삭제',
      description: `${collection}/${slug}${ext} 파일을 정말 삭제할까요? 되돌릴 수 없습니다.`,
      confirmLabel: '삭제',
      danger: true,
    });
    if (!confirmed) return;
    try {
      await api.fileOps({ action: 'delete-file', collection, slug, ext });
      setStatus(`삭제: ${collection}/${slug}${ext}`, 'ok');
      await this.onChanged();
      this.onFileChanged({ collection, slug }, null);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('삭제 실패: ' + msg, 'error');
    }
  }

private async renameFolder(collection: CollectionName, folder: string): Promise<void> {
    const r = await openModal({
      title: '폴더 이름 변경',
      fields: [{ name: 'toFolder', label: '새 경로', value: folder, required: true }],
      confirmLabel: '변경',
    });
    if (!r.confirmed) return;
    const toFolder = r.values.toFolder.trim();
    if (!toFolder || toFolder === folder) return;
    await this.executeFolderRename(collection, folder, toFolder);
  }

async renameFileInline(
    collection: CollectionName,
    slug: string,
    ext: Ext,
    newBaseName: string,
  ): Promise<void> {
    const trimmed = newBaseName.trim();
    if (!trimmed) return;
    const parts = slug.split('/');
    const oldBase = parts[parts.length - 1];
    const { base, ext: parsedExt } = splitNameAndExt(trimmed, ext);
    if (base === oldBase && parsedExt === ext) return;
    parts[parts.length - 1] = base;
    const newSlug = parts.join('/');
    try {
      await api.fileOps({
        action: 'rename-file',
        collection,
        slug,
        ext,
        toSlug: newSlug,
        toExt: parsedExt,
      });
      setStatus(`이름 변경: ${slug}${ext} → ${newSlug}${parsedExt}`, 'ok');
      await this.onChanged();
      this.onFileChanged({ collection, slug }, { collection, slug: newSlug, ext: parsedExt });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('이름 변경 실패: ' + msg, 'error');
    }
  }

async renameFolderInline(
    collection: CollectionName,
    folder: string,
    newName: string,
  ): Promise<void> {
    const trimmed = newName.trim();
    if (!trimmed) return;
    const parts = folder.split('/');
    if (parts[parts.length - 1] === trimmed) return;
    parts[parts.length - 1] = trimmed;
    const newFolder = parts.join('/');
    await this.executeFolderRename(collection, folder, newFolder);
  }

async toggleExt(collection: CollectionName, slug: string, ext: Ext): Promise<Ext | null> {
    const targetExt: Ext = ext === '.md' ? '.mdx' : '.md';
    try {
      await api.fileOps({
        action: 'rename-file',
        collection,
        slug,
        ext,
        toSlug: slug,
        toExt: targetExt,
      });
      setStatus(`확장자 변경: ${slug}${ext} → ${slug}${targetExt}`, 'ok');
      await this.onChanged();
      this.onFileChanged({ collection, slug }, { collection, slug, ext: targetExt });
      return targetExt;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('확장자 변경 실패: ' + msg, 'error');
      return null;
    }
  }

async dropItem(item: DraggedItem, target: DropTarget): Promise<void> {
    if (item.type === 'file') {
      const filename = item.slug.includes('/') ? item.slug.split('/').pop()! : item.slug;
      const toSlug = target.folder ? `${target.folder}/${filename}` : filename;
      if (item.collection === target.collection && item.slug === toSlug) return;
      try {
        if (item.collection === target.collection) {
          await api.fileOps({
            action: 'rename-file',
            collection: item.collection,
            slug: item.slug,
            ext: item.ext,
            toSlug,
            toExt: item.ext,
          });
        } else {
          await api.fileOps({
            action: 'move-file',
            collection: item.collection,
            slug: item.slug,
            ext: item.ext,
            toCollection: target.collection,
            toSlug,
          });
        }
        setStatus(`이동: ${item.collection}/${item.slug} → ${target.collection}/${toSlug}`, 'ok');
        await this.onChanged();
        this.onFileChanged(
          { collection: item.collection, slug: item.slug },
          { collection: target.collection, slug: toSlug, ext: item.ext },
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('이동 실패: ' + msg, 'error');
      }
      return;
    }
    if (item.collection !== target.collection) {
      setStatus('폴더는 같은 컬렉션 안에서만 이동할 수 있습니다', 'error');
      return;
    }
    const folderName = item.folder.includes('/') ? item.folder.split('/').pop()! : item.folder;
    const toFolder = target.folder ? `${target.folder}/${folderName}` : folderName;
    if (item.folder === toFolder) return;
    if (toFolder === item.folder || toFolder.startsWith(item.folder + '/')) {
      setStatus('자기 자신 또는 하위 폴더로는 이동할 수 없습니다', 'error');
      return;
    }
    await this.executeFolderRename(item.collection, item.folder, toFolder);
  }

private async executeFolderRename(
    collection: CollectionName,
    folder: string,
    toFolder: string,
  ): Promise<void> {
    try {
      await api.fileOps({ action: 'rename-folder', collection, folder, toFolder });
      setStatus(`폴더 변경: ${collection}/${folder} → ${collection}/${toFolder}`, 'ok');
      await this.onChanged();
      this.onFolderChanged({ collection, folder }, { collection, folder: toFolder });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('폴더 변경 실패: ' + msg, 'error');
    }
  }

private async deleteFolder(collection: CollectionName, folder: string): Promise<void> {
    const confirmed = await confirmModal({
      title: '폴더 삭제',
      description: `${collection}/${folder} 폴더와 모든 하위 파일을 영구 삭제합니다. 정말로 진행할까요?`,
      confirmLabel: '삭제',
      danger: true,
    });
    if (!confirmed) return;
    try {
      const res = await api.fileOps({ action: 'delete-folder', collection, folder });
      const removed = typeof res.removed === 'number' ? res.removed : 0;
      setStatus(`폴더 삭제: ${folder} (파일 ${removed}개)`, 'ok');
      await this.onChanged();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('폴더 삭제 실패: ' + msg, 'error');
    }
  }
}

import { api, type UrlPreviewResponse } from '@/dev-only/editor/core/api';
import { openModal } from '@/dev-only/editor/ui/modal';
import { setStatus } from '@/dev-only/editor/core/status';

const TAG_RE = /<UrlPreview\s+url=["']([^"']+)["']\s*\/>/g;
const URL_RE = /https?:\/\/[^\s<>"')]+/g;

export class UrlPreviewController {
  private textarea: HTMLTextAreaElement;

constructor(textarea: HTMLTextAreaElement) {
    this.textarea = textarea;
  }

async insertNew(): Promise<void> {
    const result = await openModal({
      title: 'URL 미리보기 삽입',
      description: '외부 URL 의 OG 메타를 즉시 가져와 카드로 삽입합니다.',
      fields: [{ name: 'url', label: 'URL', placeholder: 'https://…', required: true }],
      confirmLabel: '미리보기 카드 삽입',
    });
    if (!result.confirmed) return;
    const url = result.values.url.trim();
    if (!url) return;
    await this.insertCardAtCursor(url);
  }

async toggleAtCursor(): Promise<void> {
    const sel = this.textarea.selectionStart;
    const value = this.textarea.value;
    const tagMatch = this.findEnclosingTag(value, sel);
    if (tagMatch) {
      const { start, end, url } = tagMatch;
      const next = value.slice(0, start) + url + value.slice(end);
      this.setValue(next, start, start + url.length);
      setStatus('URL 미리보기 → 평문 URL 로 변환', 'ok');
      return;
    }
    const urlMatch = this.findUrlAtCursor(value, sel);
    if (urlMatch) {
      await this.insertCardReplacingRange(urlMatch.start, urlMatch.end, urlMatch.url);
      return;
    }
    setStatus('커서 위치에 URL 또는 <UrlPreview/> 가 없습니다', 'error');
  }

private findEnclosingTag(
    value: string,
    cursor: number,
  ): { start: number; end: number; url: string } | null {
    TAG_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = TAG_RE.exec(value)) !== null) {
      if (cursor >= m.index && cursor <= m.index + m[0].length) {
        return { start: m.index, end: m.index + m[0].length, url: m[1] };
      }
    }
    return null;
  }

private findUrlAtCursor(
    value: string,
    cursor: number,
  ): { start: number; end: number; url: string } | null {
    URL_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = URL_RE.exec(value)) !== null) {
      const end = m.index + m[0].length;
      if (cursor >= m.index && cursor <= end) {
        return { start: m.index, end, url: m[0] };
      }
    }
    return null;
  }

private async insertCardAtCursor(url: string): Promise<void> {
    const preview = await this.fetchPreview(url);
    if (!preview) return;
    const tag = `<UrlPreview url="${url}" />`;
    const sel = this.textarea.selectionStart;
    const before = this.textarea.value.slice(0, sel);
    const after = this.textarea.value.slice(this.textarea.selectionEnd);
    const needLead =
      before.length > 0 && !before.endsWith('\n\n') ? (before.endsWith('\n') ? '\n' : '\n\n') : '';
    const needTrail = after.length > 0 && !after.startsWith('\n') ? '\n\n' : '\n';
    const block = needLead + tag + needTrail;
    const next = before + block + after;
    const cursor = before.length + needLead.length + tag.length;
    this.setValue(next, cursor, cursor);
    this.flashStatus(preview);
  }

private async insertCardReplacingRange(start: number, end: number, url: string): Promise<void> {
    const preview = await this.fetchPreview(url);
    if (!preview) return;
    const tag = `<UrlPreview url="${url}" />`;
    const before = this.textarea.value.slice(0, start);
    const after = this.textarea.value.slice(end);
    const next = before + tag + after;
    this.setValue(next, before.length, before.length + tag.length);
    this.flashStatus(preview);
  }

private async fetchPreview(url: string): Promise<UrlPreviewResponse | null> {
    setStatus('URL 메타 가져오는 중…');
    try {
      const res = await api.urlPreview(url);
      if (res.preview.error) {
        setStatus('미리보기 실패 (캐시 없는 상태로 삽입): ' + res.preview.error, 'error');
      }
      return res.preview;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('미리보기 실패 (캐시 없는 상태로 삽입): ' + msg, 'error');
      return { url, fetchedAt: new Date().toISOString(), error: msg };
    }
  }

private flashStatus(preview: UrlPreviewResponse): void {
    if (preview.title) setStatus(`URL 카드 삽입: ${preview.title}`, 'ok');
    else setStatus('URL 카드 삽입됨 (메타 캐시 빈 상태)', 'ok');
  }

private setValue(value: string, selStart: number, selEnd: number): void {
    this.textarea.value = value;
    try {
      this.textarea.selectionStart = selStart;
      this.textarea.selectionEnd = selEnd;
    } catch {
      return;
    }
    this.textarea.focus();
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
  }
}

export function formatBytes(n: number): string {
  if (!n) return '0 B';
  if (n < 1024) return n + ' B';
  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
  return (n / (1024 * 1024)).toFixed(2) + ' MB';
}

export function todayIsoDate(): string {
  const d = new Date();
  return (
    d.getFullYear() +
    '-' +
    String(d.getMonth() + 1).padStart(2, '0') +
    '-' +
    String(d.getDate()).padStart(2, '0')
  );
}

export function todayIsoTime(): string {
  const d = new Date();
  const tz = -d.getTimezoneOffset();
  const sign = tz >= 0 ? '+' : '-';
  const hh = String(Math.floor(Math.abs(tz) / 60)).padStart(2, '0');
  const mm = String(Math.abs(tz) % 60).padStart(2, '0');
  return (
    d.getFullYear() +
    '-' +
    String(d.getMonth() + 1).padStart(2, '0') +
    '-' +
    String(d.getDate()).padStart(2, '0') +
    'T' +
    String(d.getHours()).padStart(2, '0') +
    ':' +
    String(d.getMinutes()).padStart(2, '0') +
    ':00' +
    sign +
    hh +
    ':' +
    mm
  );
}

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function urlFor(collection: string, slug: string): string {
  return '/' + collection + '/' + slug + '/';
}

export type ReferenceItem = Record<string, string | number | boolean>;

const UNQUOTED_SCALAR_RE = /^[\w\-./:가-힣\u3040-\u30ff\u3400-\u9fff_]+$/u;
const RESERVED_RE = /^(true|false|null|yes|no|~|on|off)$/i;
const NUMERIC_RE = /^-?\d+(?:\.\d+)?$/;

export function yamlScalar(value: string | number | boolean): string {
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  const s = String(value);
  if (s === '') return '""';
  if (UNQUOTED_SCALAR_RE.test(s) && !RESERVED_RE.test(s) && !NUMERIC_RE.test(s)) {
    return s;
  }
  return JSON.stringify(s);
}

export function serializeReferencesBlock(items: ReferenceItem[]): string {
  if (items.length === 0) return '';
  const lines = ['references:'];
  for (const item of items) {
    const entries = Object.entries(item).filter(
      ([, v]) => v !== undefined && v !== null && v !== '',
    );
    if (entries.length === 0) continue;
    const [firstKey, firstVal] = entries[0];
    lines.push(`  - ${firstKey}: ${yamlScalar(firstVal)}`);
    for (const [k, v] of entries.slice(1)) {
      lines.push(`    ${k}: ${yamlScalar(v)}`);
    }
  }
  return lines.join('\n');
}

const FM_RE = /^---\n([\s\S]*?)\n---(\n|$)/;

interface YamlListSlice {
  start: number;
  end: number;
}

function findListSlice(fm: string, key: string): YamlListSlice | null {
  const re = new RegExp(`^${key}:\\s*(.*)$`, 'm');
  const m = re.exec(fm);
  if (!m) return null;
  const after = m[1];
  const lineStart = m.index;
  const lineEnd = m.index + m[0].length;
  if (/^\[.*\]\s*$/.test(after) || after.trim() !== '') {
    return { start: lineStart, end: lineEnd };
  }
  const lines = fm.slice(lineEnd + 1).split('\n');
  let consumed = 0;
  for (const ln of lines) {
    if (ln.startsWith(' ') || ln.startsWith('\t')) {
      consumed += ln.length + 1;
      continue;
    }
    break;
  }
  return { start: lineStart, end: lineEnd + 1 + Math.max(0, consumed - 1) };
}

export function upsertReferencesInFrontmatter(content: string, items: ReferenceItem[]): string {
  const fmMatch = content.match(FM_RE);
  const block = serializeReferencesBlock(items);
  if (!fmMatch) {
    const body = content;
    if (items.length === 0) return body;
    return `---\n${block}\n---\n\n${body.replace(/^\n+/, '')}`;
  }
  const fm = fmMatch[1];
  const fmStart = fmMatch[0];
  const slice = findListSlice(fm, 'references');
  let newFm: string;
  if (items.length === 0) {
    if (!slice) return content;
    newFm = (fm.slice(0, slice.start) + fm.slice(slice.end))
      .replace(/\n{3,}/g, '\n\n')
      .replace(/^\n+|\n+$/g, '');
  } else if (slice) {
    newFm = fm.slice(0, slice.start) + block + fm.slice(slice.end);
  } else {
    newFm = fm.replace(/\n*$/, '') + '\n' + block;
  }
  return content.replace(fmStart, `---\n${newFm}\n---\n`);
}

export interface ParsedFrontmatterReferences {
  refs: ReferenceItem[];
  fmText: string;
}

export function parseReferencesFromFrontmatter(content: string): ParsedFrontmatterReferences {
  const fmMatch = content.match(FM_RE);
  if (!fmMatch) return { refs: [], fmText: '' };
  const fm = fmMatch[1];
  const slice = findListSlice(fm, 'references');
  if (!slice) return { refs: [], fmText: fm };
  const sliceText = fm.slice(slice.start, slice.end).trimEnd();
  const refs: ReferenceItem[] = [];
  const lines = sliceText.split('\n');
  if (lines.length === 0) return { refs: [], fmText: fm };
  const firstLineMatch = lines[0].match(/^references:\s*(.*)$/);
  if (firstLineMatch && firstLineMatch[1].startsWith('[') && firstLineMatch[1].endsWith(']')) {
    try {
      const arr = JSON.parse(firstLineMatch[1]);
      if (Array.isArray(arr)) {
        for (const a of arr) if (a && typeof a === 'object') refs.push(a as ReferenceItem);
      }
    } catch {
      return { refs: [], fmText: fm };
    }
    return { refs, fmText: fm };
  }
  let current: ReferenceItem | null = null;
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (/^\s*-\s+/.test(line)) {
      if (current) refs.push(current);
      current = {};
      const rest = line.replace(/^\s*-\s+/, '');
      const kv = rest.match(/^([\w-]+):\s*(.*)$/);
      if (kv) current[kv[1]] = parseScalar(kv[2]);
      continue;
    }
    const kv = line.match(/^\s+([\w-]+):\s*(.*)$/);
    if (kv && current) current[kv[1]] = parseScalar(kv[2]);
  }
  if (current) refs.push(current);
  return { refs, fmText: fm };
}

function parseScalar(raw: string): string | number | boolean {
  const s = raw.trim();
  if (s === 'true') return true;
  if (s === 'false') return false;
  if (/^-?\d+(?:\.\d+)?$/.test(s)) return Number(s);
  return s.replace(/^["']|["']$/g, '');
}

import type { MarkdownToolbar } from '@/dev-only/editor/ui/toolbar';

interface AnimationSummary {
  id: string;
  title: string;
  description: string;
}

export class AnimationPicker {
  private toolbar: MarkdownToolbar;
  private items: AnimationSummary[] = [];
  private loaded = false;

constructor(toolbar: MarkdownToolbar) {
    this.toolbar = toolbar;
  }

init(): void {
    const menuBtn = document.querySelector<HTMLElement>('[data-md-menu="anim"]');
    menuBtn?.addEventListener('click', () => {
      if (!this.loaded) void this.loadList();
    });

const search = document.getElementById('editor-anim-search') as HTMLInputElement | null;
    search?.addEventListener('input', () => this.render(search.value));

document.addEventListener('click', (e) => {
      const item = (e.target as HTMLElement).closest<HTMLElement>('[data-anim-insert-id]');
      if (!item) return;
      e.preventDefault();
      const id = item.dataset.animInsertId ?? '';
      this.toolbar.insertBlock('```anim:' + id + '\n{}\n```');
      this.closeMenu();
    });
  }

private closeMenu(): void {
    const menu = document.querySelector<HTMLElement>('[data-menu="anim"]');
    if (menu) menu.hidden = true;
    const btn = document.querySelector<HTMLElement>('[data-md-menu="anim"]');
    btn?.setAttribute('aria-expanded', 'false');
  }

private async loadList(): Promise<void> {
    const listEl = document.getElementById('editor-anim-saved-list');
    if (!listEl) return;
    listEl.innerHTML = '<div class="editor-anim-empty">로딩…</div>';
    try {
      const res = await fetch('/_studio/api/animations');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = (await res.json()) as { items: AnimationSummary[] };
      this.items = data.items;
      this.loaded = true;
      this.render('');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      listEl.innerHTML = `<div class="editor-anim-empty">실패: ${this.escape(msg)}</div>`;
    }
  }

private render(query: string): void {
    const listEl = document.getElementById('editor-anim-saved-list');
    if (!listEl) return;
    const q = query.trim().toLowerCase();
    const filtered = q
      ? this.items.filter(
          (it) =>
            it.id.toLowerCase().includes(q) ||
            it.title.toLowerCase().includes(q) ||
            (it.description ?? '').toLowerCase().includes(q),
        )
      : this.items;
    if (filtered.length === 0) {
      listEl.innerHTML = '<div class="editor-anim-empty">저장된 애니메이션이 없습니다. 스튜디오에서 만들어 보세요.</div>';
      return;
    }
    listEl.innerHTML = filtered
      .map(
        (it) => `
          <button type="button" data-anim-insert-id="${this.escape(it.id)}" class="editor-anim-saved-item">
            <div class="editor-anim-saved-title">${this.escape(it.title)}</div>
            <div class="editor-anim-saved-id">${this.escape(it.id)}</div>
          </button>
        `,
      )
      .join('');
  }

private escape(s: string): string {
    return s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
}

import { parse as parseYaml } from 'yaml';
import { escapeHtml } from '@/dev-only/editor/lib/utils';
import type { MarkdownToolbar } from '@/dev-only/editor/ui/toolbar';

const FRONTMATTER_RE = /^---\r?\n([\s\S]*?)\r?\n---/;

function extractFrontmatter(raw: string): Record<string, unknown> {
  const m = raw.match(FRONTMATTER_RE);
  if (!m) return {};
  try {
    const parsed = parseYaml(m[1]);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

const KEY_LABEL: Record<string, string> = {
  title: '제목',
  description: '설명',
  date: '날짜',
  updated: '수정일',
  tags: '태그',
  category: '카테고리',
  series: '시리즈',
  cover: '커버',
  coverAlt: '커버 alt',
  thumbnail: '썸네일',
  draft: '비공개',
  references: '출처',
  status: '상태',
  start: '시작일',
  end: '종료일',
  teamSize: '팀 크기',
  role: '역할',
};

function formatValue(value: unknown): string {
  if (value === undefined || value === null || value === '') return '<em class="empty">(없음)</em>';
  if (Array.isArray(value)) {
    if (value.length === 0) return '<em class="empty">(빈 배열)</em>';
    return value
      .map((v) => {
        if (typeof v === 'string') return `<span class="fm-pill">${escapeHtml(v)}</span>`;
        if (v && typeof v === 'object') return `<span class="fm-pill">${escapeHtml(JSON.stringify(v))}</span>`;
        return `<span class="fm-pill">${escapeHtml(String(v))}</span>`;
      })
      .join(' ');
  }
  if (typeof value === 'boolean') return value ? '<span class="fm-pill fm-pill-bool">true</span>' : '<span class="fm-pill">false</span>';
  if (value instanceof Date) return escapeHtml(value.toISOString().slice(0, 10));
  return escapeHtml(String(value));
}

function toIsoDate(value: unknown): string {
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  if (typeof value === 'string') {
    const d = new Date(value);
    if (!Number.isNaN(d.getTime())) return d.toISOString().slice(0, 10);
  }
  return '';
}

export class FrontmatterPanel {
  private root: HTMLElement;
  private textarea: HTMLTextAreaElement;
  private toolbar: MarkdownToolbar;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private editingKey: string | null = null;

constructor(root: HTMLElement, textarea: HTMLTextAreaElement, toolbar: MarkdownToolbar) {
    this.root = root;
    this.textarea = textarea;
    this.toolbar = toolbar;
    this.render();
    this.textarea.addEventListener('input', this.schedule);
    this.root.addEventListener('click', (e) => this.handleRowClick(e));
    this.root.addEventListener('keydown', (e) => this.handleRowKeydown(e));
  }

private handleRowClick(e: Event): void {
    if (this.editingKey) return;
    const target = e.target as HTMLElement;
    if (target.closest('input,select')) return;
    const row = target.closest<HTMLElement>('.fm-row-editable');
    if (!row) return;
    const key = row.dataset.fmKey ?? '';
    const spec = EDITORS[key];
    if (!spec) return;
    const fm = this.parseCurrent();
    this.startEdit(row, key, spec, fm[key]);
  }

private handleRowKeydown(e: Event): void {
    const ke = e as KeyboardEvent;
    if (ke.key !== 'Enter' && ke.key !== ' ') return;
    const target = e.target as HTMLElement;
    const row = target.closest<HTMLElement>('.fm-row-editable');
    if (!row || row !== target) return;
    e.preventDefault();
    this.handleRowClick(e);
  }

private schedule = (): void => {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => this.render(), 250);
  };

private parseCurrent(): Record<string, unknown> {
    const raw = this.textarea.value;
    if (!raw.startsWith('---')) return {};
    return extractFrontmatter(raw);
  }

private render(): void {
    if (this.editingKey) return;
    const fm = this.parseCurrent();
    if (Object.keys(fm).length === 0) {
      this.root.hidden = true;
      this.root.innerHTML = '';
      return;
    }
    this.root.hidden = false;
    const rows: string[] = [];
    for (const key of SUMMARY_KEYS) {
      if (!(key in fm)) continue;
      const label = KEY_LABEL[key] ?? key;
      const value = formatValue(fm[key]);
      const editable = key in EDITORS;
      rows.push(
        `<div class="fm-row${editable ? ' fm-row-editable' : ''}" data-fm-key="${escapeHtml(key)}"${editable ? ' role="button" tabindex="0" title="클릭하여 편집"' : ''}><span class="fm-key">${escapeHtml(label)}</span><span class="fm-val">${value}</span></div>`,
      );
    }
    const otherKeys = Object.keys(fm).filter((k) => !SUMMARY_KEYS.includes(k));
    if (otherKeys.length > 0) {
      const items = otherKeys
        .map((k) => `<div class="fm-row fm-extra"><span class="fm-key">${escapeHtml(k)}</span><span class="fm-val">${formatValue(fm[k])}</span></div>`)
        .join('');
      rows.push(`<details class="fm-extras"><summary>+${otherKeys.length} 추가 필드</summary>${items}</details>`);
    }
    this.root.innerHTML = `
      <details class="fm-panel-details" open>
        <summary class="fm-panel-summary">📑 Frontmatter <span class="fm-panel-hint">(클릭하여 편집)</span></summary>
        <div class="fm-panel-grid">
          ${rows.join('')}
        </div>
      </details>
    `;
  }

private startEdit(row: HTMLElement, key: string, spec: EditorSpec, value: unknown): void {
    if (this.editingKey) return;
    if (spec.kind === 'boolean') {
      const next = !(value === true);
      this.toolbar.upsertFrontmatter({ [key]: next });
      return;
    }
    this.editingKey = key;
    const valSpan = row.querySelector<HTMLElement>('.fm-val');
    if (!valSpan) {
      this.editingKey = null;
      return;
    }
    const original = valSpan.innerHTML;
    const editor = this.buildEditor(spec, value);
    valSpan.innerHTML = '';
    valSpan.appendChild(editor);
    if (editor instanceof HTMLInputElement || editor instanceof HTMLSelectElement) {
      editor.focus();
      if (editor instanceof HTMLInputElement) editor.select();
    }
    let settled = false;
    const clearScheduledRender = (): void => {
      if (this.timer) {
        clearTimeout(this.timer);
        this.timer = null;
      }
    };
    const commit = (): void => {
      if (settled) return;
      settled = true;
      const newVal = this.readEditor(spec, editor);
      this.editingKey = null;
      if (newVal === null) {
        valSpan.innerHTML = original;
        return;
      }
      this.toolbar.upsertFrontmatter({ [key]: newVal });
      clearScheduledRender();
      this.render();
      clearScheduledRender();
    };
    const cancel = (): void => {
      if (settled) return;
      settled = true;
      this.editingKey = null;
      valSpan.innerHTML = original;
      clearScheduledRender();
      this.render();
    };
    editor.addEventListener('keydown', (e) => {
      const ke = e as KeyboardEvent;
      if (ke.key === 'Enter') {
        e.preventDefault();
        commit();
      } else if (ke.key === 'Escape') {
        e.preventDefault();
        cancel();
      }
    });
    editor.addEventListener('blur', () => commit());
  }

private buildEditor(spec: EditorSpec, value: unknown): HTMLElement {
    if (spec.kind === 'select') {
      const sel = document.createElement('select');
      sel.className = 'fm-edit-input';
      for (const opt of spec.options ?? []) {
        const o = document.createElement('option');
        o.value = opt;
        o.textContent = opt;
        if (value === opt) o.selected = true;
        sel.appendChild(o);
      }
      return sel;
    }
    const input = document.createElement('input');
    input.className = 'fm-edit-input';
    if (spec.kind === 'date') {
      input.type = 'date';
      input.value = toIsoDate(value);
    } else if (spec.kind === 'number') {
      input.type = 'number';
      input.value = typeof value === 'number' ? String(value) : '';
    } else if (spec.kind === 'tags') {
      input.type = 'text';
      input.value = Array.isArray(value) ? value.join(', ') : typeof value === 'string' ? value : '';
      input.placeholder = '쉼표로 구분 (예: meta, blog, tip)';
    } else {
      input.type = 'text';
      input.value = value === null || value === undefined ? '' : String(value);
    }
    return input;
  }

private readEditor(spec: EditorSpec, editor: HTMLElement): unknown {
    if (editor instanceof HTMLSelectElement) return editor.value;
    if (!(editor instanceof HTMLInputElement)) return null;
    const raw = editor.value.trim();
    if (spec.kind === 'tags') {
      const tags = raw
        .split(',')
        .map((t) => t.trim())
        .filter((t) => t.length > 0);
      return tags;
    }
    if (spec.kind === 'number') {
      if (!raw) return null;
      const n = Number(raw);
      return Number.isFinite(n) ? n : null;
    }
    if (spec.kind === 'date') {
      return raw || null;
    }
    return raw;
  }

refresh(): void {
    this.render();
  }
}

import { api, type GitFile, type GitStatusPayload } from '@/dev-only/editor/core/api';
import { confirmModal, openModal } from '@/dev-only/editor/ui/modal';
import { setStatus } from '@/dev-only/editor/core/status';
import { escapeHtml } from '@/dev-only/editor/lib/utils';

export class GitPanel {
  private root: HTMLElement;
  private status: GitStatusPayload | null = null;
  private selected = new Set<string>();
  private message = '';
  private amend = false;
  private busy = false;
  private branches: { current: string; all: string[] } | null = null;
  private stashes: { index: number; message: string }[] = [];

constructor(root: HTMLElement) {
    this.root = root;
    this.render();
  }

async refresh(): Promise<void> {
    try {
      const [statusRes, branchesRes, stashesRes] = await Promise.all([
        api.gitStatus(),
        api.gitBranches().catch(() => null),
        api.gitStashList().catch(() => null),
      ]);
      this.status = statusRes.status;
      if (branchesRes) this.branches = branchesRes.branches;
      this.stashes = stashesRes?.stashes ?? [];
      const allowedPaths = new Set(this.status.files.filter((f) => f.allowed).map((f) => f.path));
      for (const p of Array.from(this.selected)) if (!allowedPaths.has(p)) this.selected.delete(p);
      this.render();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      this.root.innerHTML = `<p class="git-panel-error">상태 가져오기 실패: ${escapeHtml(msg)}</p>`;
    }
  }

open(): void {
    this.root.hidden = false;
    void this.refresh();
  }

close(): void {
    this.root.hidden = true;
  }

toggle(): void {
    if (this.root.hidden) this.open();
    else this.close();
  }

private fileLabel(f: GitFile): string {
    const labels: Record<string, string> = {
      modified: '수정',
      added: '추가',
      deleted: '삭제',
      renamed: '이름 변경',
      untracked: '추적 안 됨',
      conflicted: '충돌',
    };
    return `${labels[f.status] ?? f.status}${f.staged ? ' · staged' : ''}`;
  }

private render(): void {
    const s = this.status;
    if (!s) {
      this.root.innerHTML = '<p class="git-panel-loading">git 상태 가져오는 중…</p>';
      return;
    }
    const allowedFiles = s.files.filter((f) => f.allowed);
    const blockedFiles = s.files.filter((f) => !f.allowed);
    const branchInfo = s.branch
      ? `<strong>${escapeHtml(s.branch)}</strong>` +
        (s.ahead || s.behind ? ` <small>(↑${s.ahead} ↓${s.behind})</small>` : '')
      : '<em>(no branch)</em>';

private bind(): void {
    this.root.querySelectorAll<HTMLInputElement>('[data-git-file]').forEach((input) => {
      input.addEventListener('change', () => {
        if (input.checked) this.selected.add(input.value);
        else this.selected.delete(input.value);
        const commitBtn = this.root.querySelector<HTMLButtonElement>('[data-git-commit]');
        if (commitBtn) commitBtn.textContent = `선택한 파일 커밋 (${this.selected.size})`;
      });
    });

const messageEl = this.root.querySelector<HTMLTextAreaElement>('[data-git-message]');
    messageEl?.addEventListener('input', () => {
      this.message = messageEl.value;
    });

const amendEl = this.root.querySelector<HTMLInputElement>('[data-git-amend-toggle]');
    amendEl?.addEventListener('change', () => {
      this.amend = amendEl.checked;
      this.render();
    });

this.root
      .querySelector('[data-git-refresh]')
      ?.addEventListener('click', () => void this.refresh());
    this.root.querySelector('[data-git-close]')?.addEventListener('click', () => this.close());

const branchSelect = this.root.querySelector<HTMLSelectElement>('[data-git-branch-select]');
    branchSelect?.addEventListener('change', async () => {
      const target = branchSelect.value;
      if (!this.branches || target === this.branches.current) return;
      const confirmed = await confirmModal({
        title: `브랜치 전환: ${target}`,
        description: `${this.branches.current} → ${target} 로 체크아웃합니다.\n작업 트리가 깨끗해야 합니다 (커밋 또는 stash 필요).`,
        confirmLabel: '전환',
      });
      if (!confirmed) {
        branchSelect.value = this.branches.current;
        return;
      }
      this.busy = true;
      this.render();
      try {
        const res = await api.gitCheckout(target);
        setStatus(`브랜치 전환됨: ${res.branch}`, 'ok');
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('체크아웃 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelector('[data-git-stash-push]')?.addEventListener('click', async () => {
      const message = window.prompt('stash 메시지 (선택)', '') ?? '';
      this.busy = true;
      this.render();
      try {
        const res = await api.gitStashPush(message);
        setStatus('stash 완료', 'ok');
        this.showOutput(`📦 ${res.output}`);
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('stash 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelectorAll<HTMLElement>('[data-git-stash-pop]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const idx = Number(btn.dataset.stashIndex ?? '0');
        this.busy = true;
        this.render();
        try {
          const res = await api.gitStashPop(idx);
          setStatus(`stash@{${idx}} pop 완료`, 'ok');
          this.showOutput(`📦 ${res.output}`);
          await this.refresh();
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          setStatus('stash pop 실패: ' + msg, 'error');
          this.showOutput(`❌ ${msg}`);
        } finally {
          this.busy = false;
        }
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-git-stash-drop]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const idx = Number(btn.dataset.stashIndex ?? '0');
        const confirmed = await confirmModal({
          title: `stash@{${idx}} drop`,
          description: '이 stash 를 삭제합니다. 되돌릴 수 없습니다.',
          confirmLabel: '삭제',
          danger: true,
        });
        if (!confirmed) return;
        this.busy = true;
        this.render();
        try {
          await api.gitStashDrop(idx);
          setStatus(`stash@{${idx}} 삭제됨`, 'ok');
          await this.refresh();
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          setStatus('stash drop 실패: ' + msg, 'error');
          this.showOutput(`❌ ${msg}`);
        } finally {
          this.busy = false;
        }
      });
    });

this.root.querySelector('[data-git-new-branch]')?.addEventListener('click', async () => {
      const name = window.prompt('새 브랜치 이름 (예: feature/x)', '');
      if (!name) return;
      this.busy = true;
      this.render();
      try {
        const res = await api.gitCreateBranch(name, true);
        setStatus(`새 브랜치 생성/체크아웃: ${res.branch}`, 'ok');
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('브랜치 생성 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelectorAll<HTMLElement>('[data-git-diff]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const file = btn.dataset.file ?? '';
        try {
          const res = await api.gitDiff(file);
          await openModal({
            title: `diff: ${file}`,
            body: `<pre class="editor-modal-diff">${escapeHtml(res.diff || '(변경 없음)')}</pre>`,
            confirmLabel: '닫기',
          });
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          setStatus('diff 실패: ' + msg, 'error');
        }
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-git-hunks]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const file = btn.dataset.file ?? '';
        try {
          const res = await api.gitHunks(file);
          if (res.hunks.length === 0) {
            setStatus('hunk 가 없습니다 (untracked 또는 binary 파일)', 'error');
            return;
          }
          const body = `
            <p class="git-hunks-summary">${res.hunks.length}개 hunk · 체크된 hunk만 별도 커밋합니다.</p>
            <ol class="git-hunks-list">
              ${res.hunks
                .map(
                  (h) => `<li class="git-hunks-item">
                    <label class="git-hunks-label">
                      <input type="checkbox" data-hunk-index="${h.index}" checked />
                      <code>${escapeHtml(h.header)}</code>
                    </label>
                    <pre class="git-hunks-body">${escapeHtml(h.body)}</pre>
                  </li>`,
                )
                .join('')}
            </ol>
            <label class="git-hunks-message">
              <span>커밋 메시지</span>
              <input type="text" data-hunk-message placeholder="요약" />
            </label>
          `;
          const result = await openModal({
            title: `부분 커밋: ${file}`,
            body,
            confirmLabel: '선택한 hunk 커밋',
            cancelLabel: '닫기',
          });
          if (!result.confirmed) return;
          const modalHost = document.getElementById('editor-modal-host');
          const checked = modalHost
            ? Array.from(
                modalHost.querySelectorAll<HTMLInputElement>('[data-hunk-index]:checked'),
              ).map((cb) => Number(cb.dataset.hunkIndex))
            : [];
          const message = (modalHost?.querySelector<HTMLInputElement>('[data-hunk-message]')?.value ?? '').trim();
          if (!message) {
            setStatus('커밋 메시지 필요', 'error');
            return;
          }
          if (checked.length === 0) {
            setStatus('선택된 hunk 없음', 'error');
            return;
          }
          this.busy = true;
          this.render();
          try {
            const commitRes = await api.gitCommitHunks(file, checked, message);
            setStatus(`부분 커밋 완료: ${commitRes.committed}`, 'ok');
            this.showOutput(`✅ partial commit ${commitRes.committed}\n${commitRes.file}`);
            await this.refresh();
          } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            setStatus('hunk 커밋 실패: ' + msg, 'error');
            this.showOutput(`❌ ${msg}`);
          } finally {
            this.busy = false;
          }
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          setStatus('hunks 가져오기 실패: ' + msg, 'error');
        }
      });
    });

this.root.querySelector('[data-git-commit]')?.addEventListener('click', async () => {
      if (this.selected.size === 0) {
        setStatus('커밋할 파일을 선택하세요', 'error');
        return;
      }
      if (this.amend) {
        const confirmed = await confirmModal({
          title: '마지막 커밋 수정 (--amend)',
          description:
            `${this.selected.size}개 파일을 마지막 커밋에 추가합니다.\n` +
            (this.message.trim()
              ? `메시지를 새로 씁니다:\n${this.message.trim()}`
              : '메시지는 그대로 유지합니다.') +
            '\n\n이미 push 된 경우 force-push 가 필요할 수 있습니다.',
          confirmLabel: 'Amend',
        });
        if (!confirmed) return;
        this.busy = true;
        this.render();
        try {
          const res = await api.gitAmend(
            Array.from(this.selected),
            this.message.trim() || undefined,
          );
          setStatus(`amend 완료: ${res.committed}`, 'ok');
          this.selected.clear();
          this.message = '';
          this.amend = false;
          this.showOutput(`✅ amend ${res.committed}\n${res.files.join('\n')}`);
          await this.refresh();
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          setStatus('amend 실패: ' + msg, 'error');
          this.showOutput(`❌ ${msg}`);
        } finally {
          this.busy = false;
        }
        return;
      }
      if (!this.message.trim()) {
        setStatus('커밋 메시지를 입력하세요', 'error');
        return;
      }
      const confirmed = await confirmModal({
        title: '커밋 진행',
        description: `${this.selected.size}개 파일을 커밋합니다.\n\n메시지: ${this.message.trim()}`,
        confirmLabel: '커밋',
      });
      if (!confirmed) return;
      this.busy = true;
      this.render();
      try {
        const res = await api.gitCommit(Array.from(this.selected), this.message.trim());
        setStatus(`커밋 완료: ${res.committed}`, 'ok');
        this.selected.clear();
        this.message = '';
        this.showOutput(`✅ commit ${res.committed}\n${res.files.join('\n')}`);
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('커밋 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelector('[data-git-push]')?.addEventListener('click', async () => {
      const confirmed = await confirmModal({
        title: 'GitHub 으로 push',
        description: '현재 브랜치를 origin 으로 push 합니다. 진행할까요?',
