        setStatus('push 완료', 'ok');
        this.showOutput(`✅ pushed\n${res.output}`);
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('push 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelector('[data-git-fetch]')?.addEventListener('click', async () => {
      this.busy = true;
      this.render();
      try {
        const res = await api.gitFetch();
        setStatus('fetch 완료', 'ok');
        this.showOutput(`✅ fetch\n${res.output}`);
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('fetch 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });

this.root.querySelector('[data-git-pull]')?.addEventListener('click', async () => {
      const confirmed = await confirmModal({
        title: 'origin 에서 pull (ff-only)',
        description:
          '현재 브랜치를 origin 의 같은 브랜치로 fast-forward 합니다.\n' +
          '병합 충돌 시 자동 중단합니다. 진행할까요?',
        confirmLabel: 'Pull',
      });
      if (!confirmed) return;
      this.busy = true;
      this.render();
      try {
        const res = await api.gitPull();
        setStatus('pull 완료', 'ok');
        this.showOutput(`✅ pull\n${res.output}`);
        await this.refresh();
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setStatus('pull 실패: ' + msg, 'error');
        this.showOutput(`❌ ${msg}`);
      } finally {
        this.busy = false;
      }
    });
  }

private showOutput(text: string): void {
    const pre = this.root.querySelector<HTMLElement>('[data-git-output]');
    if (!pre) return;
    pre.hidden = false;
    pre.textContent = text;
  }

private renderStashSection(): string {
    const hasChanges = (this.status?.files.length ?? 0) > 0;
    const stashList = this.stashes.length === 0
      ? ''
      : `<ul class="git-panel-stash-list">
          ${this.stashes
            .map(
              (s) => `<li class="git-panel-stash-item">
                <span class="git-panel-stash-msg" title="stash@{${s.index}}">${escapeHtml(s.message)}</span>
                <span class="git-panel-stash-actions">
                  <button type="button" class="editor-btn editor-btn-small" data-git-stash-pop data-stash-index="${s.index}">pop</button>
                  <button type="button" class="editor-btn editor-btn-small editor-btn-danger" data-git-stash-drop data-stash-index="${s.index}">drop</button>
                </span>
              </li>`,
            )
            .join('')}
        </ul>`;
    if (!hasChanges && this.stashes.length === 0) return '';
    return `<details class="git-panel-stash">
        <summary>📦 Stash (${this.stashes.length})</summary>
        ${hasChanges ? '<button type="button" class="editor-btn editor-btn-small" data-git-stash-push>현재 변경사항 stash</button>' : ''}
        ${stashList}
      </details>`;
  }
}

import { api, type SourceSummary } from '@/dev-only/editor/core/api';
import { confirmModal, ensureHost, openModal } from '@/dev-only/editor/ui/modal';
import { setStatus } from '@/dev-only/editor/core/status';
import { escapeHtml } from '@/dev-only/editor/lib/utils';
import {
  parseReferencesFromFrontmatter,
  upsertReferencesInFrontmatter,
  type ReferenceItem,
} from '@/dev-only/editor/lib/yaml-utils';

interface PickerOptions {
  getContent: () => string;
  setContent: (next: string) => void;
}

function slugifyId(input: string): string {
  return input
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}_-]+/gu, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 48);
}

function describeSource(source: SourceSummary): string {
  const parts = [source.author, source.publisher, source.year ? String(source.year) : null].filter(
    Boolean,
  );
  return parts.length > 0 ? `${source.title} · ${parts.join(' · ')}` : source.title;
}

function badge(source: SourceSummary): string {
  return `<span class="ref-picker-badge ref-picker-badge-${source.type}">${source.type}</span>`;
}

export class ReferencesPicker {
  private opts: PickerOptions;
  private sources: SourceSummary[] = [];
  private selected: ReferenceItem[] = [];
  private dialog: HTMLDialogElement;
  private rendered = false;
  private query = '';

constructor(opts: PickerOptions) {
    this.opts = opts;
    this.dialog = ensureHost();
  }

async open(): Promise<void> {
    this.selected = parseReferencesFromFrontmatter(this.opts.getContent()).refs.slice();
    await this.refreshSources();
    this.query = '';
    this.render();
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

private async refreshSources(): Promise<void> {
    try {
      const res = await api.listSources();
      this.sources = res.sources;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('출처 목록 로드 실패: ' + msg, 'error');
      this.sources = [];
    }
  }

private filteredSources(): SourceSummary[] {
    const q = this.query.trim().toLowerCase();
    if (!q) return this.sources;
    return this.sources.filter((s) => {
      if (s.title.toLowerCase().includes(q)) return true;
      if (s.id.toLowerCase().includes(q)) return true;
      if (s.author?.toLowerCase().includes(q)) return true;
      if (s.aliases.some((a) => a.toLowerCase().includes(q))) return true;
      if (s.tags.some((t) => t.toLowerCase().includes(q))) return true;
      return false;
    });
  }

private isSelected(id: string): boolean {
    return this.selected.some((r) => r.id === id);
  }

private render(): void {
    const filtered = this.filteredSources();
    const selectedHtml =
      this.selected.length === 0
        ? `<p class="ref-picker-empty">선택된 출처가 없습니다.</p>`
        : `<ul class="ref-picker-selected-list">${this.selected
            .map((r, i) => this.renderSelectedItem(r, i))
            .join('')}</ul>`;

const html = `
      <div class="ref-picker">
        <header class="ref-picker-header">
          <h2 class="ref-picker-title">📚 참고 자료 (${this.selected.length})</h2>
          <button type="button" class="editor-modal-close" data-ref-close aria-label="닫기">✕</button>
        </header>
        <section class="ref-picker-section">
          <h3 class="ref-picker-section-title">선택됨</h3>
          ${selectedHtml}
        </section>
        <section class="ref-picker-section">
          <div class="ref-picker-search-row">
            <input type="search" class="ref-picker-search" placeholder="출처 검색 (제목/저자/태그/별칭)" value="${escapeHtml(this.query)}" data-ref-search />
            <button type="button" class="editor-btn editor-btn-small" data-ref-add-inline>+ 인라인</button>
            <button type="button" class="editor-btn editor-btn-small" data-ref-create-source>+ 새 출처</button>
          </div>
          ${
            filtered.length === 0
              ? `<p class="ref-picker-empty">출처가 없습니다. 우측 '+ 새 출처' 로 만들어보세요.</p>`
              : `<ul class="ref-picker-available">${filtered.map((s) => this.renderAvailableItem(s)).join('')}</ul>`
          }
        </section>
        <footer class="ref-picker-footer">
          <button type="button" class="editor-btn" data-ref-close>취소</button>
          <button type="button" class="editor-btn editor-btn-primary" data-ref-save>저장 (${this.selected.length})</button>
        </footer>
      </div>
    `;
    this.dialog.innerHTML = html;
    this.dialog.className = 'editor-modal ref-picker-modal';
    if (!this.rendered) {
      this.dialog.addEventListener('close', () => this.handleClose());
      this.rendered = true;
    }
    this.bind();
  }

private renderSelectedItem(item: ReferenceItem, index: number): string {
    if (item.id) {
      const source = this.sources.find((s) => s.id === item.id);
      const label = source ? describeSource(source) : `${item.id} (출처 미존재)`;
      const meta = item.page ? `p.${item.page}` : '';
      return `<li class="ref-picker-selected-item">
        <div class="ref-picker-selected-main">
          ${source ? badge(source) : '<span class="ref-picker-badge ref-picker-badge-missing">?</span>'}
          <span class="ref-picker-selected-label">${escapeHtml(String(label))}</span>
          ${meta ? `<span class="ref-picker-meta">${escapeHtml(meta)}</span>` : ''}
        </div>
        ${item.note ? `<p class="ref-picker-note">${escapeHtml(String(item.note))}</p>` : ''}
        <button type="button" class="ref-picker-remove" data-ref-remove="${index}" aria-label="제거">✕</button>
      </li>`;
    }
    return `<li class="ref-picker-selected-item">
      <div class="ref-picker-selected-main">
        <span class="ref-picker-badge ref-picker-badge-inline">inline</span>
        <span class="ref-picker-selected-label">${escapeHtml(String(item.title ?? ''))}</span>
      </div>
      ${item.author ? `<p class="ref-picker-note">${escapeHtml(String(item.author))}</p>` : ''}
      ${item.url ? `<p class="ref-picker-note"><a href="${escapeHtml(String(item.url))}" target="_blank" rel="noopener">${escapeHtml(String(item.url))}</a></p>` : ''}
      ${item.note ? `<p class="ref-picker-note">${escapeHtml(String(item.note))}</p>` : ''}
      <button type="button" class="ref-picker-remove" data-ref-remove="${index}" aria-label="제거">✕</button>
    </li>`;
  }

private renderAvailableItem(source: SourceSummary): string {
    const selected = this.isSelected(source.id);
    return `<li class="ref-picker-available-item ${selected ? 'is-selected' : ''}" data-ref-toggle="${escapeHtml(source.id)}">
      <label class="ref-picker-available-label">
        <input type="checkbox" ${selected ? 'checked' : ''} data-ref-checkbox="${escapeHtml(source.id)}" />
        ${badge(source)}
        <span class="ref-picker-available-title">${escapeHtml(source.title)}</span>
        ${source.author ? `<span class="ref-picker-meta">${escapeHtml(source.author)}</span>` : ''}
        ${source.year ? `<span class="ref-picker-meta">${source.year}</span>` : ''}
      </label>
    </li>`;
  }

private bind(): void {
    this.dialog.querySelectorAll<HTMLElement>('[data-ref-close]').forEach((el) => {
      el.addEventListener('click', () => this.dialog.close());
    });
    this.dialog.querySelector<HTMLElement>('[data-ref-save]')?.addEventListener('click', () => {
      this.commit();
      this.dialog.close();
    });
    const searchEl = this.dialog.querySelector<HTMLInputElement>('[data-ref-search]');
    searchEl?.addEventListener('input', () => {
      this.query = searchEl.value;
      this.renderListsOnly();
    });
    this.dialog.querySelectorAll<HTMLInputElement>('[data-ref-checkbox]').forEach((el) => {
      el.addEventListener('change', () => {
        const id = el.dataset.refCheckbox ?? '';
        if (el.checked) this.addShared(id);
        else this.removeById(id);
      });
    });
    this.dialog.querySelectorAll<HTMLElement>('[data-ref-remove]').forEach((el) => {
      el.addEventListener('click', () => {
        const idx = Number(el.dataset.refRemove);
        if (!Number.isNaN(idx)) {
          this.selected.splice(idx, 1);
          this.render();
        }
      });
    });
    this.dialog
      .querySelector<HTMLElement>('[data-ref-add-inline]')
      ?.addEventListener('click', () => {
        void this.handleAddInline();
      });
    this.dialog
      .querySelector<HTMLElement>('[data-ref-create-source]')
      ?.addEventListener('click', () => {
        void this.handleCreateSource();
      });
  }

private renderListsOnly(): void {
    const sections = this.dialog.querySelectorAll<HTMLElement>('.ref-picker-section');
    if (sections.length < 2) {
      this.render();
      return;
    }
    const filtered = this.filteredSources();
    const availableSection = sections[1];
    const existingList = availableSection.querySelector('.ref-picker-available, .ref-picker-empty');
    const newList = document.createElement('div');
    newList.innerHTML =
      filtered.length === 0
        ? `<p class="ref-picker-empty">출처가 없습니다.</p>`
        : `<ul class="ref-picker-available">${filtered.map((s) => this.renderAvailableItem(s)).join('')}</ul>`;
    existingList?.replaceWith(newList.firstElementChild!);
    this.bind();
  }

private addShared(id: string): void {
    if (this.isSelected(id)) return;
    this.selected.push({ id });
    this.render();
  }

private removeById(id: string): void {
    this.selected = this.selected.filter((r) => r.id !== id);
    this.render();
  }

private async handleAddInline(): Promise<void> {
    const r = await openModal({
      title: '인라인 출처 추가',
      description: '한 번만 인용할 자료. 공유 출처가 필요하면 "새 출처" 로 만드세요.',
      fields: [
        { name: 'title', label: '제목', required: true },
        { name: 'url', label: 'URL (선택)' },
        { name: 'author', label: '저자 (선택)' },
        { name: 'note', label: '메모 (선택)' },
      ],
      confirmLabel: '추가',
    });
    if (!r.confirmed) return;
    const item: ReferenceItem = { title: r.values.title.trim() };
    if (!item.title) return;
    if (r.values.url.trim()) item.url = r.values.url.trim();
    if (r.values.author.trim()) item.author = r.values.author.trim();
    if (r.values.note.trim()) item.note = r.values.note.trim();
    this.selected.push(item);
    this.render();
    if (typeof this.dialog.showModal === 'function' && !this.dialog.open) this.dialog.showModal();
  }

private async handleCreateSource(): Promise<void> {
    const r = await openModal({
      title: '새 출처 만들기',
      description: '공유 출처를 만들고 즉시 현재 글에 추가합니다.',
      fields: [
        { name: 'title', label: '제목', required: true },
        {
          name: 'type',
          label: '종류',
          type: 'select',
          value: 'website',
          options: [
            { value: 'book', label: '책' },
            { value: 'article', label: '아티클' },
            { value: 'paper', label: '논문' },
            { value: 'website', label: '웹사이트' },
            { value: 'video', label: '영상' },
            { value: 'talk', label: '강연' },
            { value: 'other', label: '기타' },
          ],
        },
        { name: 'author', label: '저자 (선택)' },
        { name: 'publisher', label: '출판사 (선택)' },
        { name: 'year', label: '연도 (선택)' },
        { name: 'url', label: 'URL (선택)' },
        { name: 'id', label: 'ID (비우면 제목에서 자동 생성)' },
      ],
      confirmLabel: '만들기 + 추가',
    });
    if (!r.confirmed) return;
    const title = r.values.title.trim();
    if (!title) return;
    const id = r.values.id.trim() || slugifyId(title);
    if (this.sources.some((s) => s.id === id)) {
      const ok = await confirmModal({
        title: '같은 ID 의 출처가 이미 있습니다',
        description: `${id}\n\n그 출처를 사용하시겠습니까? (기존 파일을 덮어쓰지 않습니다)`,
        confirmLabel: '기존 출처 사용',
      });
      if (ok) {
        this.addShared(id);
        if (typeof this.dialog.showModal === 'function' && !this.dialog.open)
          this.dialog.showModal();
      }
      return;
    }
    const lines = ['---'];
    lines.push(`title: ${JSON.stringify(title)}`);
    lines.push(`type: ${r.values.type}`);
    if (r.values.author.trim()) lines.push(`author: ${JSON.stringify(r.values.author.trim())}`);
    if (r.values.publisher.trim())
      lines.push(`publisher: ${JSON.stringify(r.values.publisher.trim())}`);
    if (r.values.year.trim()) {
      const y = Number(r.values.year.trim());
      if (!Number.isNaN(y)) lines.push(`year: ${y}`);
    }
    if (r.values.url.trim()) lines.push(`url: ${JSON.stringify(r.values.url.trim())}`);
    lines.push('aliases: []');
    lines.push('tags: []');
    lines.push('---');
    lines.push('');
    lines.push(`${title} 에 대한 짧은 설명을 추가하세요.`);
    lines.push('');
    const content = lines.join('\n');
    try {
      await api.saveFile({ collection: 'sources', slug: id, ext: '.md', content });
      setStatus(`출처 생성: ${id}`, 'ok');
      await this.refreshSources();
      this.addShared(id);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('출처 생성 실패: ' + msg, 'error');
    }
    if (typeof this.dialog.showModal === 'function' && !this.dialog.open) this.dialog.showModal();
  }

private commit(): void {
    const current = this.opts.getContent();
    const next = upsertReferencesInFrontmatter(current, this.selected);
    this.opts.setContent(next);
    setStatus(`참고 자료 ${this.selected.length}건 저장됨`, 'ok');
  }

private handleClose(): void {
    this.dialog.className = 'editor-modal';
  }
}

export function getCaretCoordinates(
  element: HTMLTextAreaElement | HTMLInputElement,
  position: number,
): CaretCoords {
  const div = document.createElement('div');
  div.id = '__caret-mirror';
  document.body.appendChild(div);

const style = div.style;
  const computed = window.getComputedStyle(element);
  const isInput = element.nodeName === 'INPUT';

style.whiteSpace = 'pre-wrap';
  if (!isInput) style.wordWrap = 'break-word';
  style.position = 'absolute';
  style.visibility = 'hidden';

for (const prop of COPIED_PROPS) {
    if (isInput && prop === 'lineHeight') {
      if (computed.boxSizing === 'border-box') {
        const height = parseInt(computed.height, 10);
        const outerHeight =
          parseInt(computed.paddingTop, 10) +
          parseInt(computed.paddingBottom, 10) +
          parseInt(computed.borderTopWidth, 10) +
          parseInt(computed.borderBottomWidth, 10);
        const targetHeight = outerHeight + parseInt(computed.lineHeight, 10);
        if (height > targetHeight) style.lineHeight = height - outerHeight + 'px';
        else if (height === targetHeight) style.lineHeight = computed.lineHeight;
        else style.lineHeight = '0';
      } else {
        style.lineHeight = computed.height;
      }
    } else {
      // @ts-expect-error - dynamic CSS property copy
      style[prop] = computed[prop];
    }
  }

if (isFirefox) {
    if (element.scrollHeight > parseInt(computed.height, 10)) style.overflowY = 'scroll';
  } else {
    style.overflow = 'hidden';
  }

div.textContent = element.value.substring(0, position);
  if (isInput) div.textContent = (div.textContent ?? '').replace(/\s/g, '\u00a0');

const span = document.createElement('span');
  span.textContent = element.value.substring(position) || '.';
  div.appendChild(span);

const coords: CaretCoords = {
    top: span.offsetTop + parseInt(computed.borderTopWidth, 10),
    left: span.offsetLeft + parseInt(computed.borderLeftWidth, 10),
    height: parseInt(computed.lineHeight, 10),
  };

document.body.removeChild(div);
  return coords;
}

interface MatchRange {
  start: number;
  end: number;
}

export class FindReplaceBar {
  private textarea: HTMLTextAreaElement;
  private bar: HTMLElement;
  private findInput: HTMLInputElement;
  private replaceInput: HTMLInputElement;
  private caseToggle: HTMLInputElement;
  private regexToggle: HTMLInputElement;
  private countLabel: HTMLElement;
  private matches: MatchRange[] = [];
  private currentIndex = -1;
  private open = false;

constructor(textarea: HTMLTextAreaElement) {
    this.textarea = textarea;
    this.bar = this.build();
    textarea.parentElement?.insertBefore(this.bar, textarea);
    this.findInput = this.bar.querySelector<HTMLInputElement>('[data-find]')!;
    this.replaceInput = this.bar.querySelector<HTMLInputElement>('[data-replace]')!;
    this.caseToggle = this.bar.querySelector<HTMLInputElement>('[data-case]')!;
    this.regexToggle = this.bar.querySelector<HTMLInputElement>('[data-regex]')!;
    this.countLabel = this.bar.querySelector<HTMLElement>('[data-count]')!;
    this.bindEvents();
  }

toggle(): void {
    if (this.open) this.close();
    else this.show();
  }

show(seed?: string): void {
    this.open = true;
    this.bar.hidden = false;
    if (seed !== undefined) this.findInput.value = seed;
    else if (!this.findInput.value && this.textarea.selectionStart !== this.textarea.selectionEnd) {
      this.findInput.value = this.textarea.value.slice(
        this.textarea.selectionStart,
        this.textarea.selectionEnd,
      );
    }
    this.findInput.focus();
    this.findInput.select();
    this.search();
  }

close(): void {
    this.open = false;
    this.bar.hidden = true;
    this.matches = [];
    this.currentIndex = -1;
    this.textarea.focus();
  }

private build(): HTMLElement {
    const el = document.createElement('div');
    el.className = 'editor-find-bar';
    el.hidden = true;
    el.innerHTML = `
      <div class="editor-find-row">
        <input type="text" data-find class="editor-find-input" placeholder="찾기" aria-label="찾기" />
        <span data-count class="editor-find-count">0/0</span>
        <button type="button" data-find-prev title="이전 (Shift+Enter)" aria-label="이전">↑</button>
        <button type="button" data-find-next title="다음 (Enter)" aria-label="다음">↓</button>
        <label class="editor-find-flag"><input type="checkbox" data-case /> Aa</label>
        <label class="editor-find-flag"><input type="checkbox" data-regex /> .*</label>
        <button type="button" data-find-close class="editor-find-close" aria-label="닫기">✕</button>
      </div>
      <div class="editor-find-row">
        <input type="text" data-replace class="editor-find-input" placeholder="바꿀 텍스트" aria-label="바꿀 텍스트" />
        <button type="button" data-replace-one>바꾸기</button>
        <button type="button" data-replace-all>모두 바꾸기</button>
      </div>
    `;
    return el;
  }

private bindEvents(): void {
    const trigger = () => this.search();
    this.findInput.addEventListener('input', trigger);
    this.caseToggle.addEventListener('change', trigger);
    this.regexToggle.addEventListener('change', trigger);
    this.findInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        if (e.shiftKey) this.gotoPrev();
        else this.gotoNext();
        return;
      }
      if (e.key === 'Escape') {
        e.preventDefault();
        this.close();
      }
    });
    this.replaceInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        this.replaceCurrent();
      }
      if (e.key === 'Escape') this.close();
    });
    this.bar.querySelector('[data-find-next]')?.addEventListener('click', () => this.gotoNext());
    this.bar.querySelector('[data-find-prev]')?.addEventListener('click', () => this.gotoPrev());
    this.bar.querySelector('[data-find-close]')?.addEventListener('click', () => this.close());
    this.bar.querySelector('[data-replace-one]')?.addEventListener('click', () => this.replaceCurrent());
    this.bar.querySelector('[data-replace-all]')?.addEventListener('click', () => this.replaceAll());
  }

private buildRegex(): RegExp | null {
    const needle = this.findInput.value;
    if (!needle) return null;
    const flags = this.caseToggle.checked ? 'g' : 'gi';
    try {
      if (this.regexToggle.checked) return new RegExp(needle, flags);
      return new RegExp(needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), flags);
    } catch {
      return null;
    }
  }

private search(): void {
    const re = this.buildRegex();
    this.matches = [];
    if (!re) {
      this.countLabel.textContent = '0/0';
      return;
    }
    const text = this.textarea.value;
    let match: RegExpExecArray | null;
    while ((match = re.exec(text)) !== null) {
      this.matches.push({ start: match.index, end: match.index + match[0].length });
      if (match.index === re.lastIndex) re.lastIndex++;
    }
    this.currentIndex = this.matches.length > 0 ? 0 : -1;
    this.highlight();
  }

private highlight(): void {
    this.countLabel.textContent = `${this.currentIndex >= 0 ? this.currentIndex + 1 : 0}/${this.matches.length}`;
    if (this.currentIndex < 0) return;
    const m = this.matches[this.currentIndex];
    this.textarea.focus();
    this.textarea.setSelectionRange(m.start, m.end);
    this.scrollIntoView(m.start);
  }

private scrollIntoView(pos: number): void {
    const text = this.textarea.value.slice(0, pos);
    const lineNo = text.split('\n').length - 1;
    const lineHeight = parseFloat(getComputedStyle(this.textarea).lineHeight || '20');
    const target = lineNo * lineHeight;
    if (target < this.textarea.scrollTop || target > this.textarea.scrollTop + this.textarea.clientHeight - lineHeight) {
      this.textarea.scrollTop = Math.max(0, target - this.textarea.clientHeight / 2);
    }
  }

private gotoNext(): void {
    if (this.matches.length === 0) return;
    this.currentIndex = (this.currentIndex + 1) % this.matches.length;
    this.highlight();
  }

private gotoPrev(): void {
    if (this.matches.length === 0) return;
    this.currentIndex = (this.currentIndex - 1 + this.matches.length) % this.matches.length;
    this.highlight();
  }

private replaceCurrent(): void {
    if (this.currentIndex < 0 || !this.matches[this.currentIndex]) return;
    const m = this.matches[this.currentIndex];
    const replaceText = this.replaceInput.value;
    const before = this.textarea.value.slice(0, m.start);
    const after = this.textarea.value.slice(m.end);
    this.textarea.value = before + replaceText + after;
    this.textarea.setSelectionRange(m.start, m.start + replaceText.length);
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
    this.search();
  }

private replaceAll(): void {
    const re = this.buildRegex();
    if (!re || this.matches.length === 0) return;
    const replaceText = this.replaceInput.value;
    this.textarea.value = this.textarea.value.replace(re, replaceText);
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
    this.search();
  }
}

import { api, type GrepMatch } from '@/dev-only/editor/core/api';
import { escapeHtml } from '@/dev-only/editor/lib/utils';
import type { CollectionName, Ext } from '@/dev-only/editor/core/state';

export type GlobalSearchJump = (
  collection: CollectionName,
  slug: string,
  ext: Ext,
  line: number,
  column: number,
) => Promise<void> | void;

export class GlobalSearch {
  private root: HTMLElement;
  private input: HTMLInputElement;
  private regexToggle: HTMLInputElement;
  private caseToggle: HTMLInputElement;
  private statusEl: HTMLElement;
  private resultsEl: HTMLElement;
  private closeBtn: HTMLButtonElement;
  private onJump: GlobalSearchJump;
  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
  private requestToken = 0;
  private isOpen = false;
  private matches: GrepMatch[] = [];

constructor(onJump: GlobalSearchJump) {
    this.onJump = onJump;
    this.root = this.build();
    document.body.appendChild(this.root);
    this.input = this.root.querySelector<HTMLInputElement>('[data-gs-input]')!;
    this.regexToggle = this.root.querySelector<HTMLInputElement>('[data-gs-regex]')!;
    this.caseToggle = this.root.querySelector<HTMLInputElement>('[data-gs-case]')!;
    this.statusEl = this.root.querySelector<HTMLElement>('[data-gs-status]')!;
    this.resultsEl = this.root.querySelector<HTMLElement>('[data-gs-results]')!;
    this.closeBtn = this.root.querySelector<HTMLButtonElement>('[data-gs-close]')!;
    this.bind();
  }

show(seed?: string): void {
    this.isOpen = true;
    this.root.hidden = false;
    document.body.classList.add('editor-global-search-open');
    if (seed !== undefined) this.input.value = seed;
    this.input.focus();
    this.input.select();
    this.scheduleSearch(0);
  }

close(): void {
    this.isOpen = false;
    this.root.hidden = true;
    document.body.classList.remove('editor-global-search-open');
  }

toggle(): void {
    if (this.isOpen) this.close();
    else this.show();
  }

private bind(): void {
    this.input.addEventListener('input', () => this.scheduleSearch());
    this.regexToggle.addEventListener('change', () => this.scheduleSearch(0));
    this.caseToggle.addEventListener('change', () => this.scheduleSearch(0));
    this.input.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        this.close();
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        const first = this.resultsEl.querySelector<HTMLElement>('[data-gs-result]');
        first?.focus();
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const first = this.resultsEl.querySelector<HTMLElement>('[data-gs-result]');
        first?.click();
      }
    });
    this.closeBtn.addEventListener('click', () => this.close());
    this.root.querySelector('[data-gs-backdrop]')?.addEventListener('click', () => this.close());
    document.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.key === 'Escape') this.close();
    });
    this.resultsEl.addEventListener('keydown', (e) => {
      const target = e.target as HTMLElement | null;
      if (!target?.matches('[data-gs-result]')) return;
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const next = target.nextElementSibling as HTMLElement | null;
        next?.focus();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        const prev = target.previousElementSibling as HTMLElement | null;
        if (prev) prev.focus();
        else this.input.focus();
      } else if (e.key === 'Enter') {
        e.preventDefault();
        target.click();
      }
    });
  }

private scheduleSearch(delayMs = 200): void {
    if (this.debounceTimer) clearTimeout(this.debounceTimer);
    this.debounceTimer = setTimeout(() => void this.runSearch(), delayMs);
  }

private async runSearch(): Promise<void> {
    const query = this.input.value.trim();
    if (!query) {
      this.matches = [];
      this.resultsEl.innerHTML = '';
      this.statusEl.textContent = '검색어를 입력하세요';
      return;
    }
    const token = ++this.requestToken;
    this.statusEl.textContent = '검색 중…';
    try {
      const res = await api.grep({
        query,
        regex: this.regexToggle.checked,
        caseSensitive: this.caseToggle.checked,
      });
      if (token !== this.requestToken) return;
      this.matches = res.matches;
      this.renderResults(res);
    } catch (err) {
      if (token !== this.requestToken) return;
      const msg = err instanceof Error ? err.message : String(err);
      this.statusEl.textContent = '오류: ' + msg;
      this.resultsEl.innerHTML = '';
    }
  }

private renderResults(res: { matches: GrepMatch[]; truncated: boolean; scanned: number }): void {
    if (res.matches.length === 0) {
      this.statusEl.textContent = `매치 없음 (${res.scanned}개 파일 검색됨)`;
      this.resultsEl.innerHTML = '';
      return;
    }
    const truncated = res.truncated ? ' (상한 도달, 더 많은 결과 있음)' : '';
    this.statusEl.textContent = `${res.matches.length}개 매치 / ${res.scanned}개 파일${truncated}`;
    const grouped = new Map<string, GrepMatch[]>();
    for (const m of res.matches) {
      const key = `${m.collection}/${m.slug}${m.ext}`;
      const arr = grouped.get(key);
      if (arr) arr.push(m);
      else grouped.set(key, [m]);
    }
    const groups: string[] = [];
    for (const [key, items] of grouped) {
      const fileHtml = items
        .map((m, idx) => {
          const lineLabel = `${m.line}:${m.column}`;
          return `<div class="editor-global-search-result" data-gs-result data-collection="${m.collection}" data-slug="${escapeHtml(m.slug)}" data-ext="${m.ext}" data-line="${m.line}" data-column="${m.column}" tabindex="0" role="option" aria-posinset="${idx + 1}" aria-setsize="${items.length}">
            <span class="editor-global-search-line">${lineLabel}</span>
            <span class="editor-global-search-text">${escapeHtml(m.text)}</span>
          </div>`;
        })
        .join('');
      groups.push(`<div class="editor-global-search-group">
        <div class="editor-global-search-group-header">${escapeHtml(key)} <span class="editor-global-search-group-count">${items.length}</span></div>
        ${fileHtml}
      </div>`);
    }
    this.resultsEl.innerHTML = groups.join('');
    this.resultsEl.querySelectorAll<HTMLElement>('[data-gs-result]').forEach((row) => {
      row.addEventListener('click', () => void this.handleClick(row));
    });
  }

private async handleClick(row: HTMLElement): Promise<void> {
    const collection = row.dataset.collection as CollectionName;
    const slug = row.dataset.slug ?? '';
    const ext = (row.dataset.ext ?? '.md') as Ext;
    const line = Number(row.dataset.line ?? '1');
    const column = Number(row.dataset.column ?? '1');
    this.close();
    await this.onJump(collection, slug, ext, line, column);
  }
}

type Match =
  | { kind: 'task'; indent: string; marker: string; rest: string }
  | { kind: 'unordered'; indent: string; marker: string; rest: string }
  | { kind: 'ordered'; indent: string; num: number; rest: string };

const TASK_RE = /^(\s*)([-*+])\s+\[[ xX]\]\s+(.*)$/;
const UNORDERED_RE = /^(\s*)([-*+])\s+(.*)$/;
const ORDERED_RE = /^(\s*)(\d+)\.\s+(.*)$/;

function classify(line: string): Match | null {
  const task = TASK_RE.exec(line);
  if (task) return { kind: 'task', indent: task[1], marker: task[2], rest: task[3] };
  const unordered = UNORDERED_RE.exec(line);
  if (unordered) return { kind: 'unordered', indent: unordered[1], marker: unordered[2], rest: unordered[3] };
  const ordered = ORDERED_RE.exec(line);
  if (ordered) return { kind: 'ordered', indent: ordered[1], num: Number(ordered[2]), rest: ordered[3] };
  return null;
}

function nextMarker(m: Match): string {
  if (m.kind === 'task') return `${m.indent}${m.marker} [ ] `;
  if (m.kind === 'unordered') return `${m.indent}${m.marker} `;
  return `${m.indent}${m.num + 1}. `;
}

export function setupListContinuation(textarea: HTMLTextAreaElement): void {
  textarea.addEventListener('keydown', (e: KeyboardEvent) => {
    if (e.key !== 'Enter' || e.shiftKey || e.ctrlKey || e.metaKey || e.altKey || e.isComposing) return;
    if (textarea.selectionStart !== textarea.selectionEnd) return;
    const caret = textarea.selectionStart;
    const value = textarea.value;
    const lineStart = value.lastIndexOf('\n', caret - 1) + 1;
    const lineEnd = value.indexOf('\n', caret);
    const lineEndIdx = lineEnd === -1 ? value.length : lineEnd;
    const currentLine = value.slice(lineStart, lineEndIdx);
    const match = classify(currentLine);
    if (!match) return;
    e.preventDefault();
    if (!match.rest.trim()) {
      const before = value.slice(0, lineStart);
      const after = value.slice(lineEndIdx);
      textarea.value = before + after;
      textarea.selectionStart = textarea.selectionEnd = lineStart;
    } else {
      const insert = `\n${nextMarker(match)}`;
      const before = value.slice(0, caret);
      const after = value.slice(caret);
      textarea.value = before + insert + after;
      textarea.selectionStart = textarea.selectionEnd = caret + insert.length;
    }
    textarea.dispatchEvent(new Event('input', { bubbles: true }));
  });
}

type Scrollable = HTMLElement | HTMLTextAreaElement;

export class ScrollSync {
  private a: Scrollable;
  private b: Scrollable;
  private syncing = false;
  private enabled = false;
  private onA = () => this.syncFrom(this.a, this.b);
  private onB = () => this.syncFrom(this.b, this.a);

constructor(a: Scrollable, b: Scrollable) {
    this.a = a;
    this.b = b;
  }

enable(): void {
    if (this.enabled) return;
    this.enabled = true;
    this.a.addEventListener('scroll', this.onA, { passive: true });
    this.b.addEventListener('scroll', this.onB, { passive: true });
  }

disable(): void {
    if (!this.enabled) return;
    this.enabled = false;
    this.a.removeEventListener('scroll', this.onA);
    this.b.removeEventListener('scroll', this.onB);
  }

syncFromA(): void {
    this.syncFrom(this.a, this.b);
  }

private syncFrom(source: Scrollable, target: Scrollable): void {
    if (this.syncing) return;
    const sourceMax = source.scrollHeight - source.clientHeight;
    if (sourceMax <= 0) return;
    const targetMax = target.scrollHeight - target.clientHeight;
    if (targetMax <= 0) return;
    const ratio = source.scrollTop / sourceMax;
    this.syncing = true;
    target.scrollTop = ratio * targetMax;
    requestAnimationFrame(() => {
      this.syncing = false;
    });
  }
}

import { api, type TreeEntry } from '@/dev-only/editor/core/api';
import { getCaretCoordinates } from '@/dev-only/editor/text/caret';
import { escapeHtml } from '@/dev-only/editor/lib/utils';
import type { CollectionName } from '@/dev-only/editor/core/state';
import { WIKILINK_AUTOCOMPLETE_MAX } from '@/shared/config';

interface PageEntry {
  collection: CollectionName;
  slug: string;
  display: string;
  searchKey: string;
}

const MAX_RESULTS = WIKILINK_AUTOCOMPLETE_MAX;

export class WikilinkAutocomplete {
  private textarea: HTMLTextAreaElement;
  private popup: HTMLElement;
  private list: HTMLElement;
  private pages: PageEntry[] = [];
  private filtered: PageEntry[] = [];
  private highlight = 0;
  private active = false;
  private triggerStart = -1;

constructor(textarea: HTMLTextAreaElement) {
    this.textarea = textarea;
    this.popup = this.createPopup();
    this.list = this.popup.querySelector('.wikilink-list') as HTMLElement;
    this.bind();
    void this.refresh();
  }

async refresh(): Promise<void> {
    try {
      const data = await api.files();
      const pages: PageEntry[] = [];
      function walk(collection: CollectionName, entries: TreeEntry[]) {
        for (const e of entries) {
          if (e.type === 'folder') {
            walk(collection, e.children ?? []);
            continue;
          }
          const filename = e.slug.includes('/') ? e.slug.split('/').pop()! : e.slug;
          pages.push({
            collection,
            slug: e.slug,
            display: filename,
            searchKey: (filename + ' ' + e.slug).toLowerCase(),
          });
        }
      }
      for (const c of ['posts', 'wiki', 'notes'] as CollectionName[]) {
        walk(c, data.tree[c] ?? []);
      }
      this.pages = pages;
    } catch {
      this.pages = [];
    }
  }

private createPopup(): HTMLElement {
    const el = document.createElement('div');
    el.className = 'wikilink-popup';
    el.setAttribute('role', 'listbox');
    el.hidden = true;
    el.innerHTML = '<ul class="wikilink-list"></ul>';
    document.body.appendChild(el);
    return el;
  }

private bind(): void {
    this.textarea.addEventListener('input', () => this.handleInput());
    this.textarea.addEventListener('keydown', (e) => this.handleKey(e));
    this.textarea.addEventListener('blur', () => {
      setTimeout(() => this.hide(), 150);
    });
    this.textarea.addEventListener('click', () => this.handleInput());
    window.addEventListener('resize', () => {
      if (this.active) this.position();
    });
  }

private detectTrigger(): { start: number; query: string } | null {
    const pos = this.textarea.selectionStart;
    const before = this.textarea.value.slice(0, pos);
    const open = before.lastIndexOf('[[');
    if (open < 0) return null;
    const segment = before.slice(open + 2);
    if (segment.includes(']]') || segment.includes('\n')) return null;
    return { start: open + 2, query: segment };
  }

private handleInput(): void {
    const trigger = this.detectTrigger();
    if (!trigger) {
      this.hide();
      return;
    }
    this.triggerStart = trigger.start;
    const q = trigger.query.toLowerCase();
    this.filtered = (q ? this.pages.filter((p) => p.searchKey.includes(q)) : this.pages).slice(
      0,
      MAX_RESULTS,
    );
    if (this.filtered.length === 0) {
      this.hide();
      return;
    }
    this.highlight = 0;
    this.renderList();
    this.show();
  }

private handleKey(e: KeyboardEvent): void {
    if (!this.active) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      this.highlight = (this.highlight + 1) % this.filtered.length;
      this.renderList();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      this.highlight = (this.highlight - 1 + this.filtered.length) % this.filtered.length;
      this.renderList();
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault();
      this.commit(this.filtered[this.highlight]);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      this.hide();
    }
  }

private commit(page: PageEntry | undefined): void {
    if (!page) {
      this.hide();
      return;
    }
    const before = this.textarea.value.slice(0, this.triggerStart);
    const after = this.textarea.value.slice(this.textarea.selectionStart);
    const closeIdx = after.indexOf(']]');
    const remaining = closeIdx === 0 ? after.slice(2) : after;
    const insertion = page.display + ']]';
    const next = before + insertion + remaining;
    const cursor = before.length + insertion.length;
    this.textarea.value = next;
    this.textarea.selectionStart = this.textarea.selectionEnd = cursor;
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
    this.hide();
    this.textarea.focus();
  }

private renderList(): void {
    const items = this.filtered
      .map((page, i) => {
        return `
          <li class="wikilink-item${i === this.highlight ? ' is-active' : ''}" data-index="${i}" role="option" aria-selected="${i === this.highlight}">
            <span class="wikilink-display">${escapeHtml(page.display)}</span>
            <span class="wikilink-meta">${page.collection}/${escapeHtml(page.slug)}</span>
          </li>
        `;
      })
      .join('');
    this.list.innerHTML = items;
    this.list.querySelectorAll<HTMLElement>('.wikilink-item').forEach((el) => {
      el.addEventListener('mousedown', (e) => {
        e.preventDefault();
        const idx = Number(el.dataset.index);
        this.commit(this.filtered[idx]);
      });
      el.addEventListener('mouseenter', () => {
        this.highlight = Number(el.dataset.index);
        this.renderList();
      });
    });
  }

private show(): void {
    this.active = true;
    this.popup.hidden = false;
    this.position();
  }

private hide(): void {
    this.active = false;
    this.popup.hidden = true;
    this.triggerStart = -1;
  }

private position(): void {
    const pos = this.textarea.selectionStart;
    const coords = getCaretCoordinates(this.textarea, pos);
    const rect = this.textarea.getBoundingClientRect();
    const top =
      rect.top + coords.top + coords.height + 4 - this.textarea.scrollTop + window.scrollY;
    const left = rect.left + coords.left + window.scrollX;
    this.popup.style.top = `${top}px`;
    this.popup.style.left = `${left}px`;
  }
}

import { api } from '@/dev-only/editor/core/api';
import { setStatus } from '@/dev-only/editor/core/status';
import { formatBytes } from '@/dev-only/editor/lib/utils';
import type { MarkdownToolbar } from '@/dev-only/editor/ui/toolbar';

type Purpose = 'body' | 'cover' | 'thumbnail';
type Source = 'upload' | 'url-fetch' | 'url-direct';

interface PendingImage {
  path: string;
  size: number;
  type?: string;
  sourceUrl?: string;
  originalName?: string;
}

export class ImageDialogController {
  private dialog: HTMLDialogElement;
  private form: HTMLFormElement;
  private previewImg: HTMLImageElement;
  private altInput: HTMLInputElement;
  private urlInput: HTMLInputElement;
  private sourceStatus: HTMLElement;
  private uploadGroup: HTMLElement;
  private urlGroup: HTMLElement;
  private bodyOnlySections: NodeListOf<HTMLElement>;
  private titleEl: HTMLElement;
  private fileInput: HTMLInputElement;
  private toolbar: MarkdownToolbar;
  private pending: PendingImage | null = null;

constructor(toolbar: MarkdownToolbar) {
    this.toolbar = toolbar;
    this.dialog = document.getElementById('editor-image-dialog') as HTMLDialogElement;
    this.form = this.dialog.querySelector('.editor-image-form') as HTMLFormElement;
    this.previewImg = document.getElementById('editor-image-preview-img') as HTMLImageElement;
    this.altInput = document.getElementById('editor-image-alt') as HTMLInputElement;
    this.urlInput = document.getElementById('editor-image-url') as HTMLInputElement;
    this.sourceStatus = document.getElementById('editor-image-source-status') as HTMLElement;
    this.uploadGroup = this.dialog.querySelector('[data-image-source-upload]') as HTMLElement;
    this.urlGroup = this.dialog.querySelector('[data-image-source-url]') as HTMLElement;
    this.bodyOnlySections = this.dialog.querySelectorAll<HTMLElement>(
      '[data-image-section="body-only"]',
    );
    this.titleEl = document.getElementById('editor-image-title') as HTMLElement;
    this.fileInput = document.getElementById('editor-image-input') as HTMLInputElement;

openFor(purpose: Purpose): void {
    this.pending = null;
    this.previewImg.removeAttribute('src');
    this.altInput.value = '';
    this.urlInput.value = '';
    this.sourceStatus.textContent = '';
    this.form
      .querySelectorAll<HTMLInputElement>('input[name="img-purpose"]')
      .forEach((r) => (r.checked = r.value === purpose));
    this.form
      .querySelectorAll<HTMLInputElement>('input[name="img-source"]')
      .forEach((r) => (r.checked = r.value === 'upload'));
    this.form
      .querySelectorAll<HTMLInputElement>('input[name="img-width"]')
      .forEach((r) => (r.checked = r.value === ''));
    this.form
      .querySelectorAll<HTMLInputElement>('input[name="img-align"]')
      .forEach((r) => (r.checked = r.value === ''));
    this.applyMode();
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

async handleDroppedFile(file: File): Promise<void> {
    if (!this.dialog.open) this.openFor('body');
    await this.uploadFile(file);
  }

private currentPurpose(): Purpose {
    return (this.form.querySelector<HTMLInputElement>('input[name="img-purpose"]:checked')?.value ??
      'body') as Purpose;
  }

private currentSource(): Source {
    return (this.form.querySelector<HTMLInputElement>('input[name="img-source"]:checked')?.value ??
      'upload') as Source;
  }

private applyMode(): void {
    const purpose = this.currentPurpose();
    const source = this.currentSource();
    this.titleEl.textContent =
      purpose === 'cover'
        ? '커버 이미지 설정'
        : purpose === 'thumbnail'
          ? '썸네일 이미지 설정'
          : '이미지 삽입 옵션';
    this.bodyOnlySections.forEach((s) => (s.hidden = purpose !== 'body'));
    this.uploadGroup.hidden = source !== 'upload';
    this.urlGroup.hidden = !source.startsWith('url');
  }

private setPending(image: PendingImage): void {
    this.pending = image;
    this.previewImg.src = image.path;
    if (!this.altInput.value) {
      const base = image.originalName?.replace(/\.[^.]+$/, '') ?? '';
      this.altInput.value = base;
    }
  }

private async uploadFile(file: File): Promise<void> {
    setStatus('업로드 중…');
    this.sourceStatus.textContent = '업로드 중…';
    document.body.classList.add('editor-uploading');
    try {
      const data = await api.upload(file);
      this.setPending({ ...data, originalName: file.name });
      this.sourceStatus.textContent = `업로드됨 (${formatBytes(data.size)})`;
      setStatus(`업로드됨 (${formatBytes(data.size)})`, 'ok');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      setStatus('업로드 실패: ' + msg, 'error');
      this.sourceStatus.textContent = '실패: ' + msg;
    } finally {
      document.body.classList.remove('editor-uploading');
    }
  }

private bind(): void {
    this.form
      .querySelector('[data-image-section="purpose"]')
      ?.addEventListener('change', () => this.applyMode());
    this.form.querySelector('[data-image-section="source"]')?.addEventListener('change', () => {
      this.applyMode();
      this.pending = null;
      this.previewImg.removeAttribute('src');
      this.sourceStatus.textContent = '';
    });

this.dialog.querySelector('[data-image-pick]')?.addEventListener('click', () => {
      this.fileInput.value = '';
      this.fileInput.click();
    });

this.dialog.querySelector('[data-image-url-fetch]')?.addEventListener('click', async () => {
      const url = this.urlInput.value.trim();
      if (!url) return;
      if (this.currentSource() === 'url-direct') {
        this.setPending({
          path: url,
          size: 0,
          type: 'external',
          sourceUrl: url,
          originalName: url,
        });
        this.sourceStatus.textContent = '외부 URL 그대로 사용';
        return;
      }
      this.sourceStatus.textContent = '다운로드 중…';
      try {
        const data = await api.fetchImage(url);
        this.setPending({ ...data, originalName: url });
        this.sourceStatus.textContent = `저장됨 (${formatBytes(data.size)})`;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        this.sourceStatus.textContent = '실패: ' + msg;
      }
    });

this.fileInput.addEventListener('change', async () => {
      const file = this.fileInput.files?.[0];
      if (file) await this.uploadFile(file);
    });

this.dialog.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      if (target.dataset.imageCancel !== undefined) this.dialog.close('cancel');
    });

this.altInput.addEventListener('input', () => {
      this.altInput.classList.remove('editor-image-alt-invalid');
    });
    this.form.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!this.pending) {
        this.sourceStatus.textContent = '이미지를 먼저 업로드 또는 가져오기 해주세요';
        return;
      }
      const purpose = this.currentPurpose();
      const alt = this.altInput.value.trim();
      if (purpose !== 'thumbnail' && !alt) {
        this.sourceStatus.textContent = '⚠ 대체 텍스트(alt) 는 필수입니다, 접근성 / SEO';
        this.altInput.classList.add('editor-image-alt-invalid');
        this.altInput.focus();
        return;
      }
      if (purpose === 'cover') {
        const update: Record<string, unknown> = { cover: this.pending.path };
        if (alt) update.coverAlt = alt;
        this.toolbar.upsertFrontmatter(update);
      } else if (purpose === 'thumbnail') {
        this.toolbar.upsertFrontmatter({ thumbnail: this.pending.path });
      } else {
        const width =
          this.form.querySelector<HTMLInputElement>('input[name="img-width"]:checked')?.value ?? '';
        const align =
          this.form.querySelector<HTMLInputElement>('input[name="img-align"]:checked')?.value ?? '';
        let widthClass = '';
        let inlineStyle = '';
        if (width === 'custom') {
          const customRaw =
            (document.getElementById('editor-image-width-custom') as HTMLInputElement | null)?.value.trim() ?? '';
          if (/^\d+\s*(%|px|rem|em|vw)?$/i.test(customRaw)) {
            const styled = /^\d+$/.test(customRaw) ? `${customRaw}px` : customRaw;
            inlineStyle = ` style="width: ${styled.replace(/"/g, '')}"`;
          }
        } else if (width) {
          widthClass = width;
        }
        const classes = [widthClass, align].filter(Boolean).join(' ');
        const altSafe = alt.replace(/"/g, '&quot;');
        const md =
          classes || inlineStyle
            ? `<img src="${this.pending.path}" alt="${altSafe}"${classes ? ` class="${classes}"` : ''}${inlineStyle} />`
            : `![${alt}](${this.pending.path})`;
        this.toolbar.insertBlock(md);
      }
      this.pending = null;
      this.dialog.close();
    });
  }
}

import { escapeHtml } from '@/dev-only/editor/lib/utils';

export interface ModalField {
  name: string;
  label: string;
  type?: 'text' | 'textarea' | 'select';
  value?: string;
  placeholder?: string;
  required?: boolean;
  options?: { value: string; label: string }[];
  rows?: number;
  hint?: string;
}

export interface ModalOptions {
  title: string;
  description?: string;
  fields?: ModalField[];
  confirmLabel?: string;
  cancelLabel?: string;
  danger?: boolean;
  body?: string;
}

export interface ModalResult {
  confirmed: boolean;
  values: Record<string, string>;
}

let host: HTMLDialogElement | null = null;
let suppressNextClose = false;

export function ensureHost(): HTMLDialogElement {
  if (host) return host;
  const dialog = document.createElement('dialog');
  dialog.className = 'editor-modal';
  dialog.id = 'editor-modal-host';
  document.body.appendChild(dialog);
  host = dialog;
  return dialog;
}

function buildField(field: ModalField): string {
  const id = `editor-modal-field-${field.name}`;
  const value = field.value ?? '';
  const hint = field.hint
    ? `<small class="editor-modal-hint">${escapeHtml(field.hint)}</small>`
    : '';
  if (field.type === 'textarea') {
    return `<label class="editor-modal-field"><span>${escapeHtml(field.label)}</span><textarea id="${id}" name="${field.name}" rows="${field.rows ?? 4}" ${field.required ? 'required' : ''} placeholder="${escapeHtml(field.placeholder ?? '')}">${escapeHtml(value)}</textarea>${hint}</label>`;
  }
  if (field.type === 'select') {
    const opts = (field.options ?? [])
      .map(
        (o) =>
          `<option value="${escapeHtml(o.value)}"${o.value === value ? ' selected' : ''}>${escapeHtml(o.label)}</option>`,
      )
      .join('');
    return `<label class="editor-modal-field"><span>${escapeHtml(field.label)}</span><select id="${id}" name="${field.name}" ${field.required ? 'required' : ''}>${opts}</select>${hint}</label>`;
  }
  return `<label class="editor-modal-field"><span>${escapeHtml(field.label)}</span><input id="${id}" name="${field.name}" type="text" value="${escapeHtml(value)}" placeholder="${escapeHtml(field.placeholder ?? '')}" ${field.required ? 'required' : ''} />${hint}</label>`;
}

export function openModal(options: ModalOptions): Promise<ModalResult> {
  const dialog = ensureHost();
  const fields = options.fields ?? [];
  const fieldsHtml = fields.map(buildField).join('');
  const bodyHtml = options.body ? `<div class="editor-modal-body">${options.body}</div>` : '';
  const descriptionHtml = options.description
    ? `<p class="editor-modal-description">${escapeHtml(options.description)}</p>`
    : '';
  const confirmClass = options.danger ? 'editor-btn-danger' : 'editor-btn-primary';
  const html = `
    <form class="editor-modal-form" data-editor-modal-form>
      <header class="editor-modal-header">
        <h2 class="editor-modal-title">${escapeHtml(options.title)}</h2>
        <button type="button" class="editor-modal-close" data-editor-modal-cancel aria-label="닫기">✕</button>
      </header>
      ${descriptionHtml}
      ${bodyHtml}
      ${fieldsHtml}
      <footer class="editor-modal-actions">
        <button type="button" class="editor-btn" data-editor-modal-cancel>${escapeHtml(options.cancelLabel ?? '취소')}</button>
        <button type="submit" class="editor-btn ${confirmClass}" data-editor-modal-confirm>${escapeHtml(options.confirmLabel ?? '확인')}</button>
      </footer>
    </form>
  `;
  dialog.innerHTML = html;

return new Promise<ModalResult>((resolve) => {
    let settled = false;
    function finish(result: ModalResult) {
      if (settled) return;
      settled = true;
      dialog.removeEventListener('close', onClose);
      if (dialog.open) {
        suppressNextClose = true;
        dialog.close();
      }
      resolve(result);
    }
    const onClose = () => {
      if (suppressNextClose) {
        suppressNextClose = false;
        return;
      }
      finish({ confirmed: false, values: {} });
    };
    dialog.addEventListener('close', onClose, { once: true });

dialog.querySelectorAll<HTMLElement>('[data-editor-modal-cancel]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        finish({ confirmed: false, values: {} });
      });
    });
    const form = dialog.querySelector('form') as HTMLFormElement;
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const values: Record<string, string> = {};
      for (const field of fields) {
        const input = form.elements.namedItem(field.name) as
          | HTMLInputElement
          | HTMLTextAreaElement
          | HTMLSelectElement
          | null;
        values[field.name] = input?.value ?? '';
      }
      finish({ confirmed: true, values });
    });

if (typeof dialog.showModal === 'function') dialog.showModal();
    else dialog.setAttribute('open', '');
    const firstInput = dialog.querySelector<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >('input, textarea, select');
    if (firstInput) firstInput.focus();
  });
}

export async function confirmModal(options: {
  title: string;
  description?: string;
  danger?: boolean;
  confirmLabel?: string;
  cancelLabel?: string;
}): Promise<boolean> {
  const result = await openModal({
    title: options.title,
    description: options.description,
    confirmLabel: options.confirmLabel ?? '확인',
    cancelLabel: options.cancelLabel ?? '취소',
    danger: options.danger,
  });
  return result.confirmed;
}

import { api } from '@/dev-only/editor/core/api';
import { ScrollSync } from '@/dev-only/editor/text/scroll-sync';
import type { Ext } from '@/dev-only/editor/core/state';

export class PreviewPane {
  private container: HTMLElement;
  private content: HTMLElement;
  private toggle: HTMLInputElement;
  private getText: () => string;
  private getExt: () => Ext;
  private token = 0;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private sync: ScrollSync | null;

constructor(opts: {
    container: HTMLElement;
    content: HTMLElement;
    toggle: HTMLInputElement;
    split: HTMLElement;
    getText: () => string;
    getExt: () => Ext;
    textarea?: HTMLTextAreaElement;
  }) {
    this.container = opts.container;
    this.content = opts.content;
    this.toggle = opts.toggle;
    this.getText = opts.getText;
    this.getExt = opts.getExt;
    this.sync = opts.textarea ? new ScrollSync(opts.textarea, this.container) : null;
    this.applyToggleState(opts.split);
    this.toggle.addEventListener('change', () => {
      this.applyToggleState(opts.split);
      if (this.toggle.checked) void this.render();
    });
  }

private applyToggleState(split: HTMLElement): void {
    this.container.hidden = !this.toggle.checked;
    split.classList.toggle('has-preview', this.toggle.checked);
    if (this.toggle.checked) this.sync?.enable();
    else this.sync?.disable();
  }

schedule(): void {
    if (!this.toggle.checked) return;
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => void this.render(), 250);
  }

async render(): Promise<void> {
    if (!this.toggle.checked) return;
    const token = ++this.token;
    try {
      const data = await api.render({ content: this.getText(), ext: this.getExt() });
      if (token !== this.token) return;
      this.content.innerHTML = data.html;
      document.dispatchEvent(
        new CustomEvent('preview-updated', { detail: { container: this.content } }),
      );
      requestAnimationFrame(() => this.sync?.syncFromA());
    } catch (err) {
      if (token !== this.token) return;
      const msg = err instanceof Error ? err.message : String(err);
      this.content.innerHTML = `<pre style="color:#ef4444">미리보기 실패: ${msg}</pre>`;
    }
  }
}

import { setStatus } from '@/dev-only/editor/core/status';
import { openModal } from '@/dev-only/editor/ui/modal';

export interface ToolbarDeps {
  textarea: HTMLTextAreaElement;
  openImagePicker: () => void;
  openImageDialogFor: (purpose: 'cover' | 'thumbnail') => void;
  openReferencesPicker: () => void;
  insertUrlPreview: () => Promise<void>;
  toggleUrlPreviewAtCursor: () => Promise<void>;
}

interface Selection {
  start: number;
  end: number;
  before: string;
  selected: string;
  after: string;
}

const CWO_SINGLE = `<CodeWithOutput
  language="bash"
  label="$ bash"
  outputLanguage="text"
  outputLabel="stdout"
  title="제목"
  code={\`echo "Hello"\`}
  output={\`Hello\`}
/>`;

const CWO_MULTI = `<CodeWithOutput
  outputLanguage="text"
  outputLabel="stdout"
  title="멀티 언어 데모"
  output={\`결과\`}
  variants={[
    { label: 'python', language: 'python', code: \`print("hi")\` },
    { label: 'typescript', language: 'ts', code: \`console.log("hi")\` },
  ]}
/>`;

constructor(deps: ToolbarDeps) {
    this.deps = deps;
    this.textarea = deps.textarea;
  }

bind(root: HTMLElement): void {
    root.querySelectorAll<HTMLElement>('[data-md]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const key = btn.dataset.md;
        if (key) void this.handle(key);
        this.closeMenus(root);
      });
    });

root.querySelectorAll<HTMLElement>('[data-md-menu]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const key = btn.dataset.mdMenu;
        const menu = root.querySelector<HTMLElement>(`[data-menu="${key}"]`);
        const willOpen = menu && menu.hidden;
        this.closeMenus(root);
        if (willOpen && menu) {
          menu.hidden = false;
          btn.setAttribute('aria-expanded', 'true');
        }
      });
    });

document.addEventListener('click', (e) => {
      if (!(e.target as HTMLElement).closest('.editor-md-dropdown')) this.closeMenus(root);
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.closeMenus(root);
    });

this.textarea.addEventListener('keydown', (e) => {
      if (!(e.metaKey || e.ctrlKey)) return;
      const key = e.key.toLowerCase();
      if (key === 'b') {
        e.preventDefault();
        this.wrapSel('**', '**', '굵게');
      } else if (key === 'i') {
        e.preventDefault();
        this.wrapSel('*', '*', '기울임');
      } else if (key === 'k') {
        e.preventDefault();
        void this.handleLink();
      }
    });
  }

private closeMenus(root: HTMLElement): void {
    root.querySelectorAll<HTMLElement>('.editor-md-menu').forEach((m) => (m.hidden = true));
    root
      .querySelectorAll<HTMLElement>('[data-md-menu]')
      .forEach((b) => b.setAttribute('aria-expanded', 'false'));
  }

private getSel(): Selection {
    const { selectionStart, selectionEnd, value } = this.textarea;
    return {
      start: selectionStart,
      end: selectionEnd,
      before: value.slice(0, selectionStart),
      selected: value.slice(selectionStart, selectionEnd),
      after: value.slice(selectionEnd),
    };
  }

setValue(newValue: string, selStart?: number, selEnd?: number): void {
    this.textarea.value = newValue;
    if (selStart !== undefined) {
      this.textarea.selectionStart = selStart;
      this.textarea.selectionEnd = selEnd ?? selStart;
    }
    this.textarea.focus();
    this.textarea.dispatchEvent(new Event('input', { bubbles: true }));
  }

wrapSel(prefix: string, suffix: string, placeholder: string): void {
    const s = this.getSel();
    const text = s.selected || placeholder;
    const newValue = s.before + prefix + text + suffix + s.after;
    const startAt = s.start + prefix.length;
    this.setValue(newValue, startAt, startAt + text.length);
  }

prefixLines(prefix: string): void {
    const s = this.getSel();
    const value = this.textarea.value;
    const lineStart = value.lastIndexOf('\n', s.start - 1) + 1;
    let lineEnd = value.indexOf('\n', s.end);
    if (lineEnd < 0) lineEnd = value.length;
    const block = value.slice(lineStart, lineEnd);
    const transformed = block
      .split('\n')
      .map((l) => (l.startsWith(prefix) ? l : prefix + l))
      .join('\n');
    const next = value.slice(0, lineStart) + transformed + value.slice(lineEnd);
    this.setValue(next, lineStart + transformed.length, lineStart + transformed.length);
  }

insertBlock(text: string): void {
    const s = this.getSel();
    const needLead =
      s.before && !s.before.endsWith('

') ? (s.before.endsWith('
') ? '
' : '

') : '';
    const needTrail = s.after && !s.after.startsWith('
') ? '

' : '
';
    const block = needLead + text + needTrail;
    const next = s.before + block + s.after;
    const cursor = s.before.length + needLead.length + text.length;
    this.setValue(next, cursor, cursor);
  }

private async handleLink(): Promise<void> {
    const result = await openModal({
      title: '링크 삽입',
      fields: [
        { name: 'url', label: 'URL', placeholder: 'https://…', required: true },
        { name: 'text', label: '표시 텍스트', placeholder: '비우면 URL 사용' },
      ],
      confirmLabel: '삽입',
    });
    if (!result.confirmed) return;
    const url = result.values.url.trim();
    if (!url) return;
    const s = this.getSel();
    const text = s.selected || result.values.text.trim() || url;
    const next = s.before + '[' + text + '](' + url + ')' + s.after;
    const cursor = s.before.length + text.length + url.length + 4;
    this.setValue(next, cursor, cursor);
  }

upsertFrontmatter(updates: Record<string, unknown>): void {
    const raw = this.textarea.value;
    const fmMatch = raw.match(/^---\n([\s\S]*?)\n---(\n|$)/);
    let existingLines: string[] = [];
    let rest = raw;
    if (fmMatch) {
      existingLines = fmMatch[1].split('\n');
      rest = raw.slice(fmMatch[0].length);
    }
    const updated = new Set<string>();
    const out: string[] = [];
    for (const line of existingLines) {
      const m = line.match(/^([\w-]+)\s*:/);
      if (m && Object.prototype.hasOwnProperty.call(updates, m[1])) {
        const v = updates[m[1]];
        if (v === null || v === undefined) {
          updated.add(m[1]);
          continue;
        }
        out.push(serializeYamlPair(m[1], v));
        updated.add(m[1]);
      } else {
        out.push(line);
      }
    }
    for (const [k, v] of Object.entries(updates)) {
      if (!updated.has(k) && v !== null && v !== undefined) out.push(serializeYamlPair(k, v));
    }
    const newFm = '---\n' + out.join('\n') + '\n---\n';
    const trimmedRest = rest.replace(/^\n+/, '');
    const next = newFm + (trimmedRest ? '\n' + trimmedRest : '\n');
    this.setValue(next, newFm.length, newFm.length);
    setStatus(`frontmatter 갱신: ${Object.keys(updates).join(', ')}`, 'ok');
  }

private async handle(key: string): Promise<void> {
    switch (key) {
      case 'bold':
        this.wrapSel('**', '**', '굵게');
        break;
      case 'italic':
        this.wrapSel('*', '*', '기울임');
        break;
      case 'strike':
        this.wrapSel('~~', '~~', '취소선');
        break;
      case 'code':
        this.wrapSel('`', '`', 'code');
        break;
      case 'link':
        await this.handleLink();
        break;
      case 'image':
        this.deps.openImagePicker();
        break;
      case 'h1':
        this.prefixLines('# ');
        break;
      case 'h2':
        this.prefixLines('## ');
        break;
      case 'h3':
        this.prefixLines('### ');
        break;
      case 'ul':
        this.prefixLines('- ');
        break;
      case 'ol':
        this.prefixLines('1. ');
        break;
      case 'task':
        this.prefixLines('- [ ] ');
        break;
      case 'quote':
        this.prefixLines('> ');
        break;
      case 'codeblock': {
        const r = await openModal({
          title: '코드 블록 삽입',
          fields: [
            { name: 'lang', label: '언어 (예: ts, python, bash)', placeholder: '비우면 일반 코드' },
          ],
          confirmLabel: '삽입',
        });
        if (!r.confirmed) return;
        const lang = r.values.lang.trim();
        const s = this.getSel();
        const text = s.selected || '코드';
        this.insertBlock('```' + lang + '\n' + text + '\n```');
        break;
      }
      case 'table':
        this.insertBlock(
          '| 컬럼1 | 컬럼2 | 컬럼3 |\n|---|---|---|\n| 셀1 | 셀2 | 셀3 |\n| 셀4 | 셀5 | 셀6 |',
        );
        break;
      case 'hr':
        this.insertBlock('---');
        break;
      case 'callout-note':
        this.insertBlock('> [!NOTE]\n> 정보 내용');
        break;
      case 'callout-tip':
        this.insertBlock('> [!TIP]\n> 팁 내용');
        break;
      case 'callout-important':
        this.insertBlock('> [!IMPORTANT]\n> 중요한 내용');
        break;
      case 'callout-warning':
        this.insertBlock('> [!WARNING]\n> 경고 내용');
        break;
      case 'callout-caution':
        this.insertBlock('> [!CAUTION]\n> 주의 내용');
        break;
      case 'cwo-single':
        this.insertBlock(CWO_SINGLE);
        break;
      case 'cwo-multi':
        this.insertBlock(CWO_MULTI);
        break;
      case 'mermaid-flowchart':
      case 'mermaid-sequence':
      case 'mermaid-state':
      case 'mermaid-class':
      case 'mermaid-er': {
        const name = key.replace('mermaid-', '');
        this.insertBlock(MERMAID_TEMPLATES[name]);
        break;
      }
      case 'wikilink':
        this.wrapSel('[[', ']]', '페이지명');
        break;
      case 'fm-cover':
        this.deps.openImageDialogFor('cover');
        break;
      case 'fm-thumbnail':
        this.deps.openImageDialogFor('thumbnail');
        break;
      case 'fm-series': {
        const r = await openModal({
          title: '시리즈 설정',
          fields: [
            { name: 'name', label: '시리즈 이름', required: true },
            {
              name: 'order',
              label: '이 글의 시리즈 순서 (숫자, 비우면 자동)',
              placeholder: '예: 1',
            },
          ],
        });
        if (!r.confirmed || !r.values.name.trim()) return;
        const update: Record<string, unknown> = { series: r.values.name.trim() };
        if (r.values.order.trim()) {
          const n = Number(r.values.order.trim());
          if (!Number.isNaN(n)) update.seriesOrder = n;
        }
        this.upsertFrontmatter(update);
        break;
      }
      case 'fm-category': {
        const r = await openModal({
          title: '카테고리 설정',
          fields: [
            {
              name: 'category',
              label: '카테고리 슬러그',
              placeholder: '폴더명 권장',
              required: true,
            },
          ],
        });
        if (!r.confirmed || !r.values.category.trim()) return;
        this.upsertFrontmatter({ category: r.values.category.trim() });
        break;
      }
      case 'fm-tags': {
        const r = await openModal({
          title: '태그 추가',
          fields: [
            { name: 'tags', label: '태그 (쉼표 구분)', placeholder: 'astro, perf', required: true },
          ],
        });
        if (!r.confirmed) return;
        const tags = r.values.tags
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean);
        if (tags.length > 0) this.upsertFrontmatter({ tags });
        break;
      }
      case 'fm-references':
        this.deps.openReferencesPicker();
        break;
      case 'url-preview':
        await this.deps.insertUrlPreview();
        break;
      case 'url-preview-toggle':
        await this.deps.toggleUrlPreviewAtCursor();
        break;
      default:
        break;
    }
  }
}

function serializeYamlPair(key: string, value: unknown): string {
  if (typeof value === 'string') return `${key}: ${JSON.stringify(value)}`;
  if (typeof value === 'number' || typeof value === 'boolean') return `${key}: ${value}`;
  if (Array.isArray(value)) return `${key}: [${value.map((v) => JSON.stringify(v)).join(', ')}]`;
  return `${key}: ${JSON.stringify(value)}`;
}

import { api, type TreeEntry } from '@/dev-only/editor/core/api';
import { escapeHtml } from '@/dev-only/editor/lib/utils';
import { COLLECTION_NAMES } from '@/dev-only/editor/core/state';
import type { CollectionName, CurrentFile, Ext } from '@/dev-only/editor/core/state';

export interface DraggedFile {
  type: 'file';
  collection: CollectionName;
  slug: string;
  ext: Ext;
}

export interface DraggedFolder {
  type: 'folder';
  collection: CollectionName;
  folder: string;
}

export type DraggedItem = DraggedFile | DraggedFolder;

export interface DropTarget {
  collection: CollectionName;
  folder: string;
}

export interface TreeHandlers {
  onSelectFile: (collection: CollectionName, slug: string) => void;
  onContextFolder: (collection: CollectionName, folder: string, anchor: HTMLElement) => void;
  onContextFile: (collection: CollectionName, slug: string, anchor: HTMLElement) => void;
  onNewFile: (collection: CollectionName, folder: string) => void;
  onNewFolder: (collection: CollectionName, folder: string) => void;
  onRenameFileInline: (
    collection: CollectionName,
    slug: string,
    ext: Ext,
    newBaseName: string,
  ) => Promise<void>;
  onRenameFolderInline: (
    collection: CollectionName,
    folder: string,
    newName: string,
  ) => Promise<void>;
  onDropItem: (item: DraggedItem, target: DropTarget) => Promise<void>;
}

const STORAGE_KEY = 'editor-tree-expanded';
const DRAG_MIME = 'application/x-editor-item';

export class FileTree {
  private root: HTMLElement;
  private handlers: TreeHandlers;
  private expanded: Set<string>;
  private currentSelection: CurrentFile | null = null;
  private treeData: Record<CollectionName, TreeEntry[]> | null = null;
  private inlineEditing: HTMLInputElement | null = null;

constructor(root: HTMLElement, handlers: TreeHandlers) {
    this.root = root;
    this.handlers = handlers;
    this.expanded = this.loadExpanded();
  }

async refresh(): Promise<void> {
    const data = await api.files();
    this.treeData = data.tree;
    this.render();
  }

setSelection(file: CurrentFile | null): void {
    this.currentSelection = file;
    this.updateActiveStates();
  }

private loadExpanded(): Set<string> {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return new Set();
      const arr = JSON.parse(raw) as string[];
      return new Set(Array.isArray(arr) ? arr : []);
    } catch {
      return new Set();
    }
  }

private persistExpanded(): void {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(this.expanded)));
    } catch {
      return;
    }
  }

private folderKey(collection: CollectionName, folder: string): string {
    return `${collection}::${folder}`;
  }

private render(): void {
    if (!this.treeData) return;
    const parts: string[] = [];
    for (const collection of COLLECTION_NAMES) {
      const entries = this.treeData[collection] ?? [];
      parts.push(this.renderCollection(collection, entries));
    }
    this.root.innerHTML = parts.join('');
    this.attachListeners();
    this.updateActiveStates();
  }

private isInsideAction(target: EventTarget | null): boolean {
    return !!(
      target instanceof Element &&
      target.closest(
        '[data-tree-new-file], [data-tree-new-folder], [data-tree-folder-menu], [data-tree-file-menu], .editor-tree-name-input',
      )
    );
  }

private attachListeners(): void {
    this.root.querySelectorAll<HTMLElement>('[data-tree-toggle]').forEach((el) => {
      el.addEventListener('click', (e) => {
        if (this.isInsideAction(e.target)) return;
        if (this.inlineEditing) return;
        const collection = el.dataset.collection as CollectionName;
        const folder = el.dataset.folder ?? '';
        const key = this.folderKey(collection, folder);
        if (this.expanded.has(key)) this.expanded.delete(key);
        else this.expanded.add(key);
        this.persistExpanded();
        this.render();
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-file]').forEach((el) => {
      el.addEventListener('click', (e) => {
        if (this.isInsideAction(e.target)) return;
        if (this.inlineEditing) return;
        const collection = el.dataset.collection as CollectionName;
        const slug = el.dataset.slug ?? '';
        this.handlers.onSelectFile(collection, slug);
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-new-file]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const collection = el.dataset.collection as CollectionName;
        const folder = el.dataset.folder ?? '';
        this.handlers.onNewFile(collection, folder);
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-new-folder]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const collection = el.dataset.collection as CollectionName;
        const folder = el.dataset.folder ?? '';
        this.handlers.onNewFolder(collection, folder);
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-file-menu]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const collection = el.dataset.collection as CollectionName;
        const slug = el.dataset.slug ?? '';
        this.handlers.onContextFile(collection, slug, el);
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-folder-menu]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const collection = el.dataset.collection as CollectionName;
        const folder = el.dataset.folder ?? '';
        this.handlers.onContextFolder(collection, folder, el);
      });
    });

this.root.querySelectorAll<HTMLElement>('[data-tree-name]').forEach((nameEl) => {
      nameEl.addEventListener('dblclick', (e) => {
        e.stopPropagation();
        e.preventDefault();
        this.startInlineEdit(nameEl);
      });
    });

this.root
      .querySelectorAll<HTMLElement>('[data-tree-file], [data-tree-folder]')
      .forEach((el) => {
        el.addEventListener('dragstart', (e) => {
          const data = this.serializeDragSource(el);
          if (!data || !e.dataTransfer) return;
          e.dataTransfer.effectAllowed = 'move';
          e.dataTransfer.setData(DRAG_MIME, JSON.stringify(data));
          el.classList.add('is-dragging');
        });
        el.addEventListener('dragend', () => el.classList.remove('is-dragging'));
      });

this.root.querySelectorAll<HTMLElement>('[data-drop-target]').forEach((el) => {
      el.addEventListener('dragover', (e) => {
        if (!e.dataTransfer?.types.includes(DRAG_MIME)) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        el.classList.add('is-drop-hover');
      });
      el.addEventListener('dragleave', () => el.classList.remove('is-drop-hover'));
      el.addEventListener('drop', (e) => {
        el.classList.remove('is-drop-hover');
        const raw = e.dataTransfer?.getData(DRAG_MIME);
        if (!raw) return;
        e.preventDefault();
        let item: DraggedItem;
        try {
          item = JSON.parse(raw) as DraggedItem;
        } catch {
          return;
        }
        const target: DropTarget = {
          collection: el.dataset.collection as CollectionName,
          folder: el.dataset.folder ?? '',
        };
        void this.handlers.onDropItem(item, target);
      });
    });
  }

private serializeDragSource(el: HTMLElement): DraggedItem | null {
    const collection = el.dataset.collection as CollectionName | undefined;
    if (!collection) return null;
    if (el.dataset.treeFile !== undefined) {
      const slug = el.dataset.slug ?? '';
      const ext = (el.dataset.ext ?? '.md') as Ext;
      return { type: 'file', collection, slug, ext };
    }
    if (el.dataset.treeFolder !== undefined) {
      const folder = el.dataset.folder ?? '';
      return { type: 'folder', collection, folder };
    }
    return null;
  }

private startInlineEdit(nameEl: HTMLElement): void {
    if (this.inlineEditing) return;
    const row = nameEl.closest<HTMLElement>('[data-tree-file], [data-tree-folder]');
    if (!row) return;
    const isFile = row.dataset.treeFile !== undefined;
    const original = nameEl.textContent ?? '';
    const collection = row.dataset.collection as CollectionName;
    const input = document.createElement('input');
    input.type = 'text';
    input.value = original;
    input.className = 'editor-tree-name-input';
    input.spellcheck = false;
    const parent = nameEl.parentElement;
    if (!parent) return;
    parent.replaceChild(input, nameEl);
    this.inlineEditing = input;
    input.focus();
    if (isFile) {
      const ext = (row.dataset.ext ?? '.md') as Ext;
      const dot = original.length - ext.length;
      input.setSelectionRange(0, dot > 0 ? dot : original.length);
    } else {
      input.select();
    }

let settled = false;
    const cleanup = (): void => {
      this.inlineEditing = null;
      input.replaceWith(nameEl);
    };
    const commit = async (): Promise<void> => {
      if (settled) return;
      settled = true;
      const value = input.value.trim();
      cleanup();
      if (!value || value === original) return;
      if (isFile) {
        const slug = row.dataset.slug ?? '';
        const ext = (row.dataset.ext ?? '.md') as Ext;
        await this.handlers.onRenameFileInline(collection, slug, ext, value);
      } else {
        const folder = row.dataset.folder ?? '';
        await this.handlers.onRenameFolderInline(collection, folder, value);
      }
    };
    const cancel = (): void => {
      if (settled) return;
      settled = true;
      cleanup();
    };
    input.addEventListener('blur', () => void commit());
    input.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        void commit();
      } else if (ev.key === 'Escape') {
        ev.preventDefault();
        cancel();
      }
    });
    input.addEventListener('click', (ev) => ev.stopPropagation());
    input.addEventListener('dblclick', (ev) => ev.stopPropagation());
  }

private updateActiveStates(): void {
    const cur = this.currentSelection;
    this.root.querySelectorAll<HTMLElement>('[data-tree-file]').forEach((el) => {
      const match =
        !!cur && el.dataset.collection === cur.collection && el.dataset.slug === cur.slug;
      el.classList.toggle('is-active', match);
    });
  }

expandTo(file: CurrentFile): void {
    const parts = file.slug.split('/');
    parts.pop();
    let acc = '';
    this.expanded.add(this.folderKey(file.collection, ''));
    for (const p of parts) {
      acc = acc ? `${acc}/${p}` : p;
      this.expanded.add(this.folderKey(file.collection, acc));
    }
    this.persistExpanded();
    this.render();
  }
}

import { describe, expect, it } from 'vitest';
