    this.dialog.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      if (target.closest('[data-icon-dialog-close]')) {
        this.close();
        return;
      }
      const catBtn = target.closest<HTMLElement>('[data-icon-cat]');
      if (catBtn) {
        this.categoryFilter = (catBtn.dataset.iconCat ?? 'all') as IconCategory | 'all';
        this.render();
        return;
      }
      const pickBtn = target.closest<HTMLElement>('[data-icon-pick]');
      if (pickBtn) {
        const id = pickBtn.dataset.iconPick ?? '';
        this.insertIcon(id);
        return;
      }
    });
  }

private filtered(): IconEntry[] {
    const list = this.categoryFilter === 'all'
      ? ICON_LIBRARY
      : ICON_GROUPS.find((g) => g.category === this.categoryFilter)?.entries ?? [];
    if (!this.query) return list;
    const q = this.query;
    return list.filter((it) => it.id.toLowerCase().includes(q) || it.title.toLowerCase().includes(q));
  }

private render(): void {
    const filtered = this.filtered();
    this.lastFiltered = filtered;
    const cats: ('all' | IconCategory)[] = ['all', ...ICON_GROUPS.map((g) => g.category)];
    const catBar = cats
      .map((c) => {
        const label = c === 'all' ? '전체' : CATEGORY_LABELS[c];
        const count = c === 'all' ? ICON_LIBRARY.length : (ICON_GROUPS.find((g) => g.category === c)?.entries.length ?? 0);
        return `<button type="button" data-icon-cat="${c}" class="studio-icon-cat-btn ${this.categoryFilter === c ? 'is-active' : ''}">${label} <span class="studio-icon-cat-count">${count}</span></button>`;
      })
      .join('');

if (filtered.length === 0) {
      this.listEl.innerHTML = `
        <div class="studio-icon-cat-bar">${catBar}</div>
        <div class="studio-icon-grid"><div class="studio-icon-empty">검색 결과 없음 (${ICON_LIBRARY.length}개 아이콘)</div></div>
      `;
      return;
    }

this.renderedCount = Math.min(PAGE_SIZE, filtered.length);
    const grid = filtered.slice(0, this.renderedCount).map((it) => this.renderItem(it)).join('');
    const moreCount = Math.max(0, filtered.length - this.renderedCount);

this.listEl.innerHTML = `
      <div class="studio-icon-cat-bar">${catBar}</div>
      <div class="studio-icon-result-info">총 ${filtered.length}개 ${this.query ? `<code>${escapeHtml(this.query)}</code> 검색 결과` : ''}</div>
      <div class="studio-icon-grid" id="studio-icon-grid">${grid}</div>
      ${moreCount > 0 ? `<div class="studio-icon-sentinel" id="studio-icon-sentinel">${moreCount}개 더 표시…</div>` : ''}
    `;

this.observer?.disconnect();
    const sent = document.getElementById('studio-icon-sentinel') as HTMLDivElement | null;
    this.sentinel = sent;
    if (sent) {
      this.observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) this.loadMore();
        }
      }, { root: this.dialog.querySelector('.studio-dialog-body') ?? null, rootMargin: '200px' });
      this.observer.observe(sent);
    }
  }

private loadMore(): void {
    const grid = document.getElementById('studio-icon-grid');
    if (!grid) return;
    const next = Math.min(this.renderedCount + PAGE_SIZE, this.lastFiltered.length);
    const slice = this.lastFiltered.slice(this.renderedCount, next);
    grid.insertAdjacentHTML('beforeend', slice.map((it) => this.renderItem(it)).join(''));
    this.renderedCount = next;
    const remaining = this.lastFiltered.length - next;
    if (this.sentinel) {
      if (remaining > 0) {
        this.sentinel.textContent = `${remaining}개 더 표시…`;
      } else {
        this.observer?.disconnect();
        this.sentinel.remove();
        this.sentinel = null;
      }
    }
  }

private renderItem(it: IconEntry): string {
    return `<button type="button" data-icon-pick="${escapeHtml(it.id)}" class="studio-icon-item" title="${escapeHtml(it.title)} · ${escapeHtml(it.id)}">
      <img loading="lazy" decoding="async" src="${escapeHtml(it.src)}" alt="${escapeHtml(it.title)}" onerror="this.classList.add('is-error')" />
      <span>${escapeHtml(it.title)}</span>
    </button>`;
  }

private insertIcon(iconId: string): void {
    const def = getDef();
    if (!def) return;
    const icon = ICON_LIBRARY.find((i) => i.id === iconId);
    if (!icon) return;
    const cx = def.canvas.width / 2;
    const cy = def.canvas.height / 2;
    const safeBase = iconId.replace(/[^a-z0-9]/gi, '').toLowerCase() || 'icon';
    const id = uniqueElementId(safeBase);
    const el: ImageElement = {
      type: 'image',
      id,
      rotation: 0, appearances: [], tracks: [],
      x: cx - 32,
      y: cy - 32,
      width: 64,
      height: 64,
      src: icon.src,
      preserveAspectRatio: 'xMidYMid meet',
      opacity: 1,
    };
    addElement(el);
    this.close();
  }
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/**
 * Property 8: IME composition guards Enter commits
 *
 * **Validates: Requirements 4.1, 4.2, 4.3, 4.4, 4.5**
 *
 * Tests that:
 * - keydown with isComposing: true does NOT trigger commit
 * - keydown with isComposing: false DOES trigger commit
 *
 * We test the guard logic by simulating the inline text editor (main.ts)
 * and properties panel (properties.ts) IME guard patterns in isolation.
 */
import { describe, it, expect } from 'vitest';
import * as fc from 'fast-check';

// --------------------------------------------------------------------------
// Extract the guard logic pattern used in both main.ts and properties.ts
// --------------------------------------------------------------------------

/**
 * Simulates the inline text editor keydown handler from main.ts startInlineTextEdit().
 * Returns true if the value would be committed, false otherwise.
 */
function inlineTextEditKeydown(params: {
  key: string;
  isComposing: boolean;
  isComposingFallback: boolean;
}): boolean {
  // Guard: exact pattern from main.ts
  if (params.isComposing || params.isComposingFallback) return false;
  if (params.key === 'Enter') {
    return true; // commit() would be called
  }
  return false; // no commit for non-Enter keys
}

/**
 * Simulates the properties panel onKeydown handler from properties.ts.
 * Returns true if the blur (commit) would be triggered, false otherwise.
 */
function propertiesPanelKeydown(params: {
  key: string;
  isComposing: boolean;
  isComposingFallback: boolean;
  inputType: 'text' | 'number';
}): boolean {
  // Guard: exact pattern from properties.ts onKeydown
  if (params.key !== 'Enter') return false;
  if (params.isComposing || params.isComposingFallback) return false;
  // Only text and number inputs trigger blur on Enter
  if (params.inputType === 'text' || params.inputType === 'number') {
    return true; // target.blur() would be called → commit
  }
  return false;
}

/**
 * Simulates the compositionstart/compositionend lifecycle.
 * Returns the isComposingFallback state after composition events.
 */
function compositionLifecycle(events: ('compositionstart' | 'compositionend')[]): boolean {
  let isComposingFallback = false;
  for (const ev of events) {
    if (ev === 'compositionstart') isComposingFallback = true;
    else if (ev === 'compositionend') isComposingFallback = false;
  }
  return isComposingFallback;
}

// --------------------------------------------------------------------------
// Property-Based Tests
// --------------------------------------------------------------------------

describe('Property 8: IME composition guards Enter commits', () => {
  describe('Inline Text Editor (main.ts startInlineTextEdit)', () => {
    it('SHALL NOT commit when isComposing is true (any text)', () => {
      fc.assert(
        fc.property(fc.string(), (_text) => {
          // Simulate: user typed `text`, then presses Enter while IME is composing
          const committed = inlineTextEditKeydown({
            key: 'Enter',
            isComposing: true,
            isComposingFallback: false,
          });
          expect(committed).toBe(false);
        }),
      );
    });

it('SHALL NOT commit when isComposingFallback is true (any text)', () => {
      fc.assert(
        fc.property(fc.string(), (_text) => {
          // Simulate: compositionstart fired, Enter pressed
          const committed = inlineTextEditKeydown({
            key: 'Enter',
            isComposing: false,
            isComposingFallback: true,
          });
          expect(committed).toBe(false);
        }),
      );
    });

it('SHALL NOT commit when both isComposing and isComposingFallback are true', () => {
      fc.assert(
        fc.property(fc.string(), (_text) => {
          const committed = inlineTextEditKeydown({
            key: 'Enter',
            isComposing: true,
            isComposingFallback: true,
          });
          expect(committed).toBe(false);
        }),
      );
    });

it('SHALL commit when isComposing is false and isComposingFallback is false', () => {
      fc.assert(
        fc.property(fc.string(), (_text) => {
          const committed = inlineTextEditKeydown({
            key: 'Enter',
            isComposing: false,
            isComposingFallback: false,
          });
          expect(committed).toBe(true);
        }),
      );
    });

it('for any text, Enter commits iff not composing', () => {
      fc.assert(
        fc.property(
          fc.string(),
          fc.boolean(),
          fc.boolean(),
          (text, isComposing, isComposingFallback) => {
            const committed = inlineTextEditKeydown({
              key: 'Enter',
              isComposing,
              isComposingFallback,
            });
            const shouldBlock = isComposing || isComposingFallback;
            expect(committed).toBe(!shouldBlock);
          },
        ),
      );
    });
  });

describe('Properties Panel (properties.ts onKeydown)', () => {
    it('SHALL NOT commit when isComposing is true (any text input)', () => {
      fc.assert(
        fc.property(
          fc.string(),
          fc.constantFrom('text' as const, 'number' as const),
          (text, inputType) => {
            const committed = propertiesPanelKeydown({
              key: 'Enter',
              isComposing: true,
              isComposingFallback: false,
              inputType,
            });
            expect(committed).toBe(false);
          },
        ),
      );
    });

it('SHALL NOT commit when isComposingFallback is true', () => {
      fc.assert(
        fc.property(
          fc.string(),
          fc.constantFrom('text' as const, 'number' as const),
          (text, inputType) => {
            const committed = propertiesPanelKeydown({
              key: 'Enter',
              isComposing: false,
              isComposingFallback: true,
              inputType,
            });
            expect(committed).toBe(false);
          },
        ),
      );
    });

it('SHALL commit when not composing on text/number inputs', () => {
      fc.assert(
        fc.property(
          fc.string(),
          fc.constantFrom('text' as const, 'number' as const),
          (text, inputType) => {
            const committed = propertiesPanelKeydown({
              key: 'Enter',
              isComposing: false,
              isComposingFallback: false,
              inputType,
            });
            expect(committed).toBe(true);
          },
        ),
      );
    });

it('for any text and input type, Enter commits iff not composing', () => {
      fc.assert(
        fc.property(
          fc.string(),
          fc.constantFrom('text' as const, 'number' as const),
          fc.boolean(),
          fc.boolean(),
          (text, inputType, isComposing, isComposingFallback) => {
            const committed = propertiesPanelKeydown({
              key: 'Enter',
              isComposing,
              isComposingFallback,
              inputType,
            });
            const shouldBlock = isComposing || isComposingFallback;
            expect(committed).toBe(!shouldBlock);
          },
        ),
      );
    });
  });

describe('Composition lifecycle (compositionstart/compositionend)', () => {
    it('compositionend re-enables Enter commit (Req 4.4, 4.5)', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.constantFrom('compositionstart' as const, 'compositionend' as const),
            { minLength: 1, maxLength: 20 },
          ),
          (events) => {
            const fallbackState = compositionLifecycle(events);
            const lastEvent = events[events.length - 1];
            // After compositionend, fallback should be false (allows commit)
            // After compositionstart, fallback should be true (blocks commit)
            if (lastEvent === 'compositionend') {
              expect(fallbackState).toBe(false);
            } else {
              expect(fallbackState).toBe(true);
            }
          },
        ),
      );
    });

it('compositionstart always blocks, compositionend always unblocks', () => {
      fc.assert(
        fc.property(
          fc.array(
            fc.constantFrom('compositionstart' as const, 'compositionend' as const),
            { minLength: 0, maxLength: 30 },
          ),
          fc.string(),
          (events, _text) => {
            const fallbackState = compositionLifecycle(events);
            const committed = inlineTextEditKeydown({
              key: 'Enter',
              isComposing: false,
              isComposingFallback: fallbackState,
            });
            if (events.length === 0) {
              // No composition events → should commit
              expect(committed).toBe(true);
            } else {
              const lastEvent = events[events.length - 1];
              if (lastEvent === 'compositionend') {
                expect(committed).toBe(true);
              } else {
                expect(committed).toBe(false);
              }
            }
          },
        ),
      );
    });
  });
});

import {
