// ---------------------------------------------------------------------------
// Utility: extract element IDs from a Selection
// ---------------------------------------------------------------------------

function getSelectionIds(sel: Selection): string[] {
  if (sel.kind === 'element') return [sel.elementId];
  if (sel.kind === 'elements') return sel.elementIds;
  return [];
}

let panelEl: HTMLElement | null = null;
const closedSections = new Set<string>();
let isComposingFallback = false;

export function initProperties(root: HTMLElement): void {
  panelEl = root;
  subscribe(render);
  root.addEventListener('input', onInput);
  root.addEventListener('change', onChange);
  root.addEventListener('click', onClick);
  root.addEventListener('keydown', onKeydown);
  root.addEventListener('compositionstart', onCompositionStart);
  root.addEventListener('compositionend', onCompositionEnd);
  root.addEventListener('toggle', onSectionToggle, true);
  root.addEventListener('wheel', onNumberWheel, { passive: false });
  render();
}

function onCompositionStart(): void {
  isComposingFallback = true;
}

function onCompositionEnd(): void {
  isComposingFallback = false;
}

function onKeydown(e: KeyboardEvent): void {
  if (e.key !== 'Enter') return;
  if (e.isComposing || isComposingFallback) return;
  const target = e.target as HTMLElement;
  if (!(target instanceof HTMLInputElement)) return;
  if (target.type === 'text' || target.type === 'number') {
    target.blur();
  }
}

function onSectionToggle(e: Event): void {
  const t = e.target as HTMLElement;
  if (!(t instanceof HTMLDetailsElement)) return;
  const name = t.dataset.section;
  if (!name) return;
  if (t.open) closedSections.delete(name);
  else closedSections.add(name);
}

function onNumberWheel(e: WheelEvent): void {
  const target = e.target;
  if (!(target instanceof HTMLInputElement)) return;
  if (target.type !== 'number') return;
  if (document.activeElement !== target) return;
  e.preventDefault();
  const step = Number(target.step) || 1;
  const multiplier = e.shiftKey ? 10 : 1;
  const dir = e.deltaY < 0 ? 1 : -1;
  const newVal = (Number(target.value) || 0) + dir * step * multiplier;
  target.value = String(newVal);
  target.dispatchEvent(new Event('input', { bubbles: true }));
}

function section(name: string, headerInner: string, contentInner: string): string {
  const isOpen = !closedSections.has(name);
  return `<details class="studio-props-section" ${isOpen ? 'open' : ''} data-section="${escapeHtml(name)}">
    <summary class="studio-props-header studio-props-summary">${headerInner}</summary>
    <div class="studio-props-section-body">${contentInner}</div>
  </details>`;
}

function render(): void {
  if (!panelEl) return;
  const focusSnap = captureFocusWithin(panelEl);
  renderInner();
  restoreFocusWithin(panelEl, focusSnap);
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function textField(label: string, key: string, value: string | undefined): string {
  return `<label class="studio-field">
    <span>${escapeHtml(label)}</span>
    <input type="text" data-prop-key="${escapeHtml(key)}" value="${escapeHtml(value ?? '')}" />
  </label>`;
}

function numberField(label: string, key: string, value: number | undefined, step = 1): string {
  return `<label class="studio-field">
    <span>${escapeHtml(label)}</span>
    <input type="number" step="${step}" data-prop-key="${escapeHtml(key)}" value="${value ?? 0}" />
  </label>`;
}

function colorField(label: string, key: string, value: string | undefined): string {
  const v = value ?? '#000000';
  return `<label class="studio-field studio-field-color">
    <span>${escapeHtml(label)}</span>
    <input type="color" data-prop-key="${escapeHtml(key)}" value="${escapeHtml(v.slice(0, 7))}" />
    <input type="text" data-prop-key="${escapeHtml(key)}" value="${escapeHtml(v)}" />
  </label>`;
}

function checkboxField(label: string, key: string, value: boolean): string {
  return `<label class="studio-field studio-field-checkbox">
    <input type="checkbox" data-prop-key="${escapeHtml(key)}" ${value ? 'checked' : ''} />
    <span>${escapeHtml(label)}</span>
  </label>`;
}

function selectField(label: string, key: string, value: string, options: { value: string; label?: string }[]): string {
  return `<label class="studio-field">
    <span>${escapeHtml(label)}</span>
    <select data-prop-key="${escapeHtml(key)}">
      ${options.map((o) => `<option value="${escapeHtml(o.value)}" ${o.value === value ? 'selected' : ''}>${escapeHtml(o.label ?? o.value)}</option>`).join('')}
    </select>
  </label>`;
}

function renderInner(): void {
  if (!panelEl) return;
  const def = getDef();
  const sel = getSelection();
  if (!def) {
    panelEl.innerHTML = '<p class="studio-props-empty">애니메이션을 열거나 새로 만드세요.</p>';
    return;
  }

const timeHint = `<span class="studio-step-hint">📍 t = ${getCurrentTime()} ms / ${def.duration} ms</span>`;

if (sel.kind === 'none') {
    const metaHeader = `<span class="studio-props-header-title">애니메이션 메타</span><span class="studio-props-header-type">${escapeHtml(def.id)}</span>`;
    const metaBody = [
      textField('title', 'meta.title', def.title),
      textField('description', 'meta.description', def.description),
      numberField('duration (ms)', 'meta.duration', def.duration, 100),
      numberField('canvas.width', 'canvas.width', def.canvas.width),
      numberField('canvas.height', 'canvas.height', def.canvas.height),
      colorField('canvas.background', 'canvas.background', def.canvas.background),
    ].join('');
    const settingsHeader = `<span class="studio-props-header-title">설정</span>`;
    const settingsBody = [
      checkboxField('loop', 'settings.loop', def.settings.loop),
      checkboxField('autoplay', 'settings.autoplay', def.settings.autoplay),
      checkboxField('자막 표시 (caption)', 'settings.showCaption', def.settings.showCaption ?? false),
      checkboxField('목차 표시 (chapter list)', 'settings.showChapterList', def.settings.showChapterList ?? false),
    ].join('');
    panelEl.innerHTML = `
      ${timeHint}
      ${section('meta', metaHeader, metaBody)}
      ${section('settings', settingsHeader, settingsBody)}
      <div class="studio-props-header" style="margin-top:0.6rem"><span class="studio-props-header-title">목차 (${def.chapters.length})</span></div>
      <button type="button" class="studio-btn" data-add-chapter>＋ 현재 시간에 chapter 추가</button>
      <div class="studio-props-header" style="margin-top:0.6rem"><span class="studio-props-header-title">효과 (${def.effects.length})</span></div>
      <div class="studio-add-effect-bar">
        <select id="studio-new-effect-type">
          <option value="highlight">highlight</option>
          <option value="pulse">pulse</option>
          <option value="flow">flow</option>
        </select>
        <button type="button" class="studio-btn" data-add-effect>＋ 효과</button>
      </div>
    `;
    return;
  }

if (sel.kind === 'elements') {
    const alignBtn = (kind: string, label: string, title: string): string =>
      `<button type="button" class="studio-btn studio-align-btn" data-align="${kind}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}">${label}</button>`;
    const distributeDisabled = sel.elementIds.length < 3 ? 'disabled' : '';
    panelEl.innerHTML = `
      ${timeHint}
      <div class="studio-props-header"><span class="studio-props-header-title">다중 선택</span><span class="studio-props-header-type">${sel.elementIds.length} elements</span></div>
      <p class="studio-props-empty" style="margin-bottom:0.4rem">${sel.elementIds.length}개 element 선택됨.<br/>
      <span style="font-size:0.72rem;color:var(--color-fg-muted)">캔버스 드래그 / 화살표키 = 함께 이동<br/>Delete = 모두 삭제 · ⌘D = 복제<br/>⌘C / ⌘X = 모두 복사 / 잘라내기</span></p>
      <div class="studio-align-section">
        <div class="studio-align-title">정렬</div>
        <div class="studio-align-row">
          ${alignBtn('left', '⫷', '왼쪽 정렬')}
          ${alignBtn('center-h', '⊟', '가로 중앙')}
          ${alignBtn('right', '⫸', '오른쪽 정렬')}
        </div>
        <div class="studio-align-row">
          ${alignBtn('top', '⫶', '위쪽 정렬')}
          ${alignBtn('middle-v', '⊟', '세로 중앙')}
          ${alignBtn('bottom', '⫶', '아래쪽 정렬')}
        </div>
        <div class="studio-align-title" style="margin-top:0.5rem">분포 (≥3개)</div>
        <div class="studio-align-row">
          <button type="button" class="studio-btn studio-align-btn" data-distribute="horizontal" title="가로 균등 분포" ${distributeDisabled}>↔</button>
          <button type="button" class="studio-btn studio-align-btn" data-distribute="vertical" title="세로 균등 분포" ${distributeDisabled}>↕</button>
        </div>
      </div>
      <ul style="font-family:var(--font-mono);font-size:0.72rem;color:var(--color-fg-muted);padding-left:1rem;margin:0.6rem 0 0">
        ${sel.elementIds.map((id) => `<li>${escapeHtml(id)}</li>`).join('')}
      </ul>
    `;
    return;
  }

if (sel.kind === 'element') {
    const el = def.elements.find((e) => e.id === sel.elementId);
    if (!el) {
      setSelection({ kind: 'none' });
      return;
    }
    renderElementForm(def, el);
    return;
  }

if (sel.kind === 'chapter') {
    const ch = def.chapters.find((c) => c.id === sel.chapterId);
    if (!ch) {
      setSelection({ kind: 'none' });
      return;
    }
    panelEl.innerHTML = `
      ${timeHint}
      <div class="studio-props-header"><span class="studio-props-header-title">${escapeHtml(ch.id)}</span><span class="studio-props-header-type">chapter</span></div>
      ${numberField('time (ms)', 'chapter.time', ch.time, 50)}
      ${textField('label', 'chapter.label', ch.label)}
      ${textField('subtitle', 'chapter.subtitle', ch.subtitle)}
      <button type="button" class="studio-btn studio-btn-danger" data-delete-chapter style="margin-top:0.6rem">🗑 chapter 삭제</button>
    `;
    return;
  }

if (sel.kind === 'effect') {
    const eff = def.effects.find((e) => e.id === sel.effectId);
    if (!eff) {
      setSelection({ kind: 'none' });
      return;
    }
    const elemOpts = def.elements.map((e) => `<option value="${escapeHtml(e.id)}" ${e.id === eff.elementId ? 'selected' : ''}>${escapeHtml(e.id)}</option>`).join('');
    const typeOpts = (['highlight', 'pulse', 'flow'] as const).map((t) => `<option value="${t}" ${t === eff.type ? 'selected' : ''}>${t}</option>`).join('');
    const specific = eff.type === 'highlight'
      ? colorField('color', 'effect.color', eff.color)
      : eff.type === 'pulse'
        ? numberField('scale', 'effect.scale', eff.scale, 0.05)
        : colorField('color', 'effect.color', eff.color) +
          numberField('particles', 'effect.particles', eff.particles, 1) +
          numberField('radius', 'effect.radius', eff.radius, 0.5);
    panelEl.innerHTML = `
      ${timeHint}
      <div class="studio-props-header"><span class="studio-props-header-title">${escapeHtml(eff.id)}</span><span class="studio-props-header-type">effect</span></div>
      <label class="studio-field"><span>type</span><select data-prop-key="effect.type">${typeOpts}</select></label>
      <label class="studio-field"><span>elementId</span><select data-prop-key="effect.elementId">${elemOpts}</select></label>
      ${numberField('time (ms)', 'effect.time', eff.time, 50)}
      ${numberField('duration (ms)', 'effect.duration', eff.duration, 50)}
      ${specific}
      <button type="button" class="studio-btn studio-btn-danger" data-delete-effect style="margin-top:0.6rem">🗑 효과 삭제</button>
    `;
    return;
  }
}

function renderElementForm(def: AnimationDef, el: AnimationElement): void {
  if (!panelEl) return;
  const timeHint = `<span class="studio-step-hint">📍 t = ${getCurrentTime()} ms</span>`;

if (el.type === 'group') {
    panelEl.innerHTML = `
      ${timeHint}
      <div class="studio-props-header"><span class="studio-props-header-title">${escapeHtml(el.name || el.id)}</span><span class="studio-props-header-type">group · ${el.childIds.length} children</span></div>
      ${textField('name (별칭)', 'el.name', el.name ?? '')}
      <div class="studio-props-empty" style="font-size:0.72rem;margin:0.4rem 0">
        그룹은 자식 요소를 함께 이동합니다.<br/>
        Alt+클릭으로 자식을 직접 선택할 수 있습니다.<br/>
        ⌘⇧G 로 그룹 해제.
      </div>
      <button type="button" class="studio-btn studio-btn-danger" data-ungroup style="margin-top:0.4rem">⬚ 그룹 해제 (⌘⇧G)</button>
      <div class="studio-props-header" style="margin-top:0.6rem"><span class="studio-props-header-title">자식 (${el.childIds.length})</span></div>
      <ul style="font-family:var(--font-mono);font-size:0.72rem;color:var(--color-fg-muted);padding-left:1rem;margin:0">
        ${el.childIds.map((cid) => `<li><a href="#" data-select-child="${escapeHtml(cid)}" style="color:inherit">${escapeHtml(cid)}</a></li>`).join('')}
      </ul>
    `;
    return;
  }

const baseFields = renderBaseFields(el);
  const appearances = renderAppearances(def, el);
  const tracks = renderTracks(el);

const baseHeader = `<span class="studio-props-header-title">${escapeHtml(el.id)}</span><span class="studio-props-header-type">${escapeHtml(el.type)}</span>`;
  const apHeader = `<span class="studio-props-header-title">출현 (Appearances)</span><button type="button" class="studio-btn studio-btn-small" data-add-appearance>＋</button>`;
  const tracksHeader = `<span class="studio-props-header-title">키프레임 트랙 (${el.tracks.length})</span>`;

panelEl.innerHTML = `
    ${timeHint}
    ${section('el-base', baseHeader, baseFields)}
    ${section('el-appearances', apHeader, appearances)}
    ${section('el-tracks', tracksHeader, tracks)}
    <div class="studio-props-empty" style="font-size:0.72rem;margin-top:0.5rem">
      base 속성을 변경하면 → t=${getCurrentTime()} ms 에 keyframe 추가<br/>
      트랙이 없는 속성은 base 값이 항상 사용됨
    </div>
  `;
}

function renderBaseFields(el: AnimationElement): string {
  const numberFields: { label: string; key: string; value: number; step?: number }[] = [];
  const colorFields: { label: string; key: string; value: string }[] = [];
  const textFields: { label: string; key: string; value: string }[] = [];
  const e = el as unknown as Record<string, unknown>;

textFields.push({ label: 'name (별칭)', key: 'name', value: (e.name as string | undefined) ?? '' });

if (el.type === 'rect' || el.type === 'image' || el.type === 'text') {
    numberFields.push({ label: 'x', key: 'x', value: e.x as number });
    numberFields.push({ label: 'y', key: 'y', value: e.y as number });
  }
  if (el.type === 'rect' || el.type === 'image') {
    numberFields.push({ label: 'width', key: 'width', value: e.width as number });
    numberFields.push({ label: 'height', key: 'height', value: e.height as number });
  }
  if (el.type === 'circle') {
    numberFields.push({ label: 'cx', key: 'cx', value: e.cx as number });
    numberFields.push({ label: 'cy', key: 'cy', value: e.cy as number });
    numberFields.push({ label: 'r', key: 'r', value: e.r as number });
  }
  if (el.type === 'line' || el.type === 'arrow') {
    if (typeof e.x1 === 'number') {
      numberFields.push({ label: 'x1', key: 'x1', value: e.x1 as number });
      numberFields.push({ label: 'y1', key: 'y1', value: e.y1 as number });
      numberFields.push({ label: 'x2', key: 'x2', value: e.x2 as number });
      numberFields.push({ label: 'y2', key: 'y2', value: e.y2 as number });
    }
  }
  if (el.type === 'text') {
    textFields.push({ label: 'content', key: 'content', value: e.content as string });
    numberFields.push({ label: 'fontSize', key: 'fontSize', value: e.fontSize as number });
  }
  if (el.type === 'rect' || el.type === 'circle' || el.type === 'polygon' || el.type === 'path') {
    colorFields.push({ label: 'fill', key: 'fill', value: e.fill as string });
    colorFields.push({ label: 'stroke', key: 'stroke', value: e.stroke as string });
    numberFields.push({ label: 'strokeWidth', key: 'strokeWidth', value: e.strokeWidth as number, step: 0.5 });
  }
  if (el.type === 'line' || el.type === 'arrow') {
    colorFields.push({ label: 'stroke', key: 'stroke', value: e.stroke as string });
    numberFields.push({ label: 'strokeWidth', key: 'strokeWidth', value: e.strokeWidth as number, step: 0.5 });
  }
  if (el.type === 'rect' || el.type === 'circle') {
    if ((e.label as string | undefined) !== undefined) {
      textFields.push({ label: 'label', key: 'label', value: (e.label as string) ?? '' });
      colorFields.push({ label: 'labelColor', key: 'labelColor', value: (e.labelColor as string) ?? '#000' });
    }
  }
  if (el.type === 'text') {
    colorFields.push({ label: 'color', key: 'color', value: e.color as string });
  }
  numberFields.push({ label: 'rotation', key: 'rotation', value: e.rotation as number, step: 5 });

const html = [
    ...textFields.map((f) => textField(f.label, `el.${f.key}`, f.value)),
    ...numberFields.map((f) => numberField(f.label, `el.${f.key}`, f.value, f.step)),
    ...colorFields.map((f) => colorField(f.label, `el.${f.key}`, f.value)),
  ];
  return html.join('');
}

function renderAppearances(def: AnimationDef, el: AnimationElement): string {
  if (el.appearances.length === 0) {
    return '<p class="studio-props-empty">appearance 없음. 추가하세요.</p>';
  }
  const modes: { value: string; label?: string }[] = [
    { value: 'instant' },
    { value: 'fade' },
    { value: 'slide-left' },
    { value: 'slide-right' },
    { value: 'slide-up' },
    { value: 'slide-down' },
    { value: 'zoom' },
    { value: 'pop' },
  ];
  return el.appearances
    .map((ap, idx) => `
      <div class="studio-appearance-row">
        <div class="studio-appearance-row-head">
          <span class="studio-appearance-row-title">#${idx + 1}</span>
          <button type="button" class="studio-btn studio-btn-small studio-btn-danger" data-remove-appearance="${idx}">✕</button>
        </div>
        ${numberField('start (ms)', `ap.${idx}.start`, ap.start, 50)}
        ${numberField('end (ms)', `ap.${idx}.end`, ap.end, 50)}
        ${selectField('entry', `ap.${idx}.entryMode`, ap.entryMode ?? 'instant', modes)}
        ${numberField('entry dur', `ap.${idx}.entryDuration`, ap.entryDuration, 50)}
        ${selectField('exit', `ap.${idx}.exitMode`, ap.exitMode ?? 'instant', modes)}
        ${numberField('exit dur', `ap.${idx}.exitDuration`, ap.exitDuration, 50)}
      </div>
    `)
    .join('');
}

function renderTracks(el: AnimationElement): string {
  if (el.tracks.length === 0) {
    return '<p class="studio-props-empty" style="font-size:0.72rem">트랙 없음. 시간 t&gt;0 에서 base 속성을 바꾸면 자동 생성됩니다.</p>';
  }
  return el.tracks
    .map((t) => {
      const list = t.keyframes
        .map((kf, idx) => `<li>
          <button type="button" class="studio-tl-kf-btn" data-jump-time="${kf.time}" title="${kf.time}ms 로 이동">t=${kf.time}ms</button>
          <code>${escapeHtml(String(kf.value))}</code>
          <button type="button" class="studio-btn studio-btn-small studio-btn-danger" data-remove-kf-prop="${escapeHtml(t.property)}" data-remove-kf-time="${kf.time}" data-kf-idx="${idx}" title="삭제">✕</button>
        </li>`)
        .join('');
      return `
        <div class="studio-track-row">
          <div class="studio-track-row-head">
            <span class="studio-track-row-prop">${escapeHtml(t.property)}</span>
            <span class="studio-track-row-count">${t.keyframes.length} kf</span>
            <button type="button" class="studio-btn studio-btn-small" data-add-kf="${escapeHtml(t.property)}" title="현재 시간에 keyframe 추가">＋ kf</button>
            <button type="button" class="studio-btn studio-btn-small studio-btn-danger" data-remove-track="${escapeHtml(t.property)}" title="트랙 삭제">✕</button>
          </div>
          <ul class="studio-track-list">${list}</ul>
        </div>
      `;
    })
    .join('');
}

function onInput(e: Event): void {
  const target = e.target as HTMLInputElement;
  const key = target.dataset.propKey;
  if (!key) return;
  // Guard: skip text input events during IME composition
  if (target.type === 'text' && (e as InputEvent).isComposing) return;
  if (target.type === 'text' && isComposingFallback) return;
  let value: string | number | boolean = target.value;
  if (target.type === 'number') value = Number(target.value);
  else if (target.type === 'checkbox') value = target.checked;
  apply(key, value);
}

function onChange(e: Event): void {
  onInput(e);
}

function apply(key: string, value: string | number | boolean): void {
  const def = getDef();
  if (!def) return;
  const sel = getSelection();

if (key === 'meta.title') updateMeta({ title: String(value) });
  else if (key === 'meta.description') updateMeta({ description: String(value) });
  else if (key === 'meta.duration') updateDuration(Number(value));
  else if (key === 'canvas.width') updateCanvas({ width: Number(value) });
  else if (key === 'canvas.height') updateCanvas({ height: Number(value) });
  else if (key === 'canvas.background') updateCanvas({ background: String(value) });
  else if (key === 'settings.loop') updateSettings({ loop: Boolean(value) });
  else if (key === 'settings.autoplay') updateSettings({ autoplay: Boolean(value) });
  else if (key === 'settings.showCaption') updateSettings({ showCaption: Boolean(value) });
  else if (key === 'settings.showChapterList') updateSettings({ showChapterList: Boolean(value) });
  else if (key.startsWith('el.') && sel.kind === 'element') {
    const prop = key.slice(3);
    const time = getCurrentTime();
    const el = def.elements.find((e) => e.id === sel.elementId);
    if (!el) return;
    const hasTrack = el.tracks.some((t) => t.property === prop);
    if (hasTrack) {
      setTrackKeyframe(sel.elementId, prop, time, value);
    } else {
      updateElementBase(sel.elementId, { [prop]: value });
    }
  } else if (key.startsWith('ap.') && sel.kind === 'element') {
    const [, idxStr, prop] = key.split('.');
    const idx = Number(idxStr);
    const patch: Partial<Appearance> = {};
    if (prop === 'start') patch.start = Number(value);
    else if (prop === 'end') patch.end = Number(value);
    else if (prop === 'entryMode') patch.entryMode = value as EntryMode;
    else if (prop === 'entryDuration') patch.entryDuration = Number(value);
    else if (prop === 'exitMode') patch.exitMode = value as ExitMode;
    else if (prop === 'exitDuration') patch.exitDuration = Number(value);
    updateAppearance(sel.elementId, idx, patch);
  } else if (key === 'chapter.time' && sel.kind === 'chapter') {
    updateChapter(sel.chapterId, { time: Number(value) });
  } else if (key === 'chapter.label' && sel.kind === 'chapter') {
    updateChapter(sel.chapterId, { label: String(value) });
  } else if (key === 'chapter.subtitle' && sel.kind === 'chapter') {
    updateChapter(sel.chapterId, { subtitle: String(value) });
  } else if (key.startsWith('effect.') && sel.kind === 'effect') {
    const prop = key.slice(7);
    const patch: Record<string, unknown> = {};
    if (prop === 'time' || prop === 'duration' || prop === 'scale' || prop === 'particles' || prop === 'radius') {
      patch[prop] = Number(value);
    } else {
      patch[prop] = value;
    }
    updateEffect(sel.effectId, patch as Partial<AnimationEffect>);
  }
}

function onClick(e: Event): void {
  const target = e.target as HTMLElement;
  const def = getDef();
  if (!def) return;
  const sel = getSelection();

const alignBtn = target.closest<HTMLElement>('[data-align]');
  if (alignBtn) {
    alignSelected(alignBtn.dataset.align as AlignKind);
    return;
  }
  const distBtn = target.closest<HTMLElement>('[data-distribute]');
  if (distBtn) {
    distributeSelected(distBtn.dataset.distribute as DistributeKind);
    return;
  }

if (target.closest('[data-ungroup]') && sel.kind === 'element') {
    ungroupElement(sel.elementId);
    return;
  }
  const childLink = target.closest<HTMLElement>('[data-select-child]');
  if (childLink) {
    e.preventDefault();
    setSelection({ kind: 'element', elementId: childLink.dataset.selectChild ?? '' });
    return;
  }

if (target.closest('[data-add-chapter]')) {
    const id = uniqueChapterId();
    addChapter({ id, time: getCurrentTime(), label: `Chapter ${id.split('-')[1]}`, subtitle: '' });
    return;
  }
  if (target.closest('[data-delete-chapter]') && sel.kind === 'chapter') {
    deleteChapter(sel.chapterId);
    return;
  }
  if (target.closest('[data-add-effect]')) {
    const typeSel = document.getElementById('studio-new-effect-type') as HTMLSelectElement | null;
    const type = (typeSel?.value ?? 'highlight') as 'highlight' | 'pulse' | 'flow';
    const firstEl = def.elements[0];
    if (!firstEl) return;
    const id = uniqueEffectId();
    const base = { id, elementId: firstEl.id, time: getCurrentTime(), duration: 500 };
    let eff: AnimationEffect;
    if (type === 'highlight') eff = { ...base, type: 'highlight', color: '#facc15' };
    else if (type === 'pulse') eff = { ...base, type: 'pulse', scale: 1.12 };
    else eff = { ...base, type: 'flow', color: '#facc15', particles: 3, radius: 4, duration: 800 };
    addEffect(eff);
    return;
  }
  if (target.closest('[data-delete-effect]') && sel.kind === 'effect') {
    deleteEffect(sel.effectId);
    return;
  }
  const removeAp = target.closest<HTMLElement>('[data-remove-appearance]');
  if (removeAp && sel.kind === 'element') {
    const idx = Number(removeAp.dataset.removeAppearance);
    removeAppearance(sel.elementId, idx);
    return;
  }
  const removeTk = target.closest<HTMLElement>('[data-remove-track]');
  if (removeTk && sel.kind === 'element') {
    removeTrack(sel.elementId, removeTk.dataset.removeTrack ?? '');
    return;
  }
  const removeKf = target.closest<HTMLElement>('[data-remove-kf-prop]');
  if (removeKf && sel.kind === 'element') {
    const prop = removeKf.dataset.removeKfProp ?? '';
    const time = Number(removeKf.dataset.removeKfTime ?? '0');
    removeTrackKeyframe(sel.elementId, prop, time);
    return;
  }
  const addKf = target.closest<HTMLElement>('[data-add-kf]');
  if (addKf && sel.kind === 'element') {
    const prop = addKf.dataset.addKf ?? '';
    const el = def.elements.find((e) => e.id === sel.elementId);
    const baseVal = el ? (el as unknown as Record<string, unknown>)[prop] : undefined;
    if (typeof baseVal === 'string' || typeof baseVal === 'number' || typeof baseVal === 'boolean') {
      setTrackKeyframe(sel.elementId, prop, getCurrentTime(), baseVal);
    }
    return;
  }
  const jumpTime = target.closest<HTMLElement>('[data-jump-time]');
  if (jumpTime) {
    setCurrentTime(Number(jumpTime.dataset.jumpTime ?? '0'));
    return;
  }
  const addAp = target.closest('[data-add-appearance]');
  if (addAp && sel.kind === 'element') {
    addAppearance(sel.elementId, { start: getCurrentTime(), end: def.duration, entryDuration: 300, exitDuration: 300 });
    return;
  }
}

import type { AnimationDef, SnapshotMap } from '@/entities/animation/engine/schema';
import { computeSnapshot } from '@/entities/animation/engine/schema';
import type { Selection } from './types';
import { emit, state, past, future } from './internals';

export function isDraft(): boolean {
  return state.isDraft;
}

export function setDraft(def: AnimationDef): void {
  state.def = def;
  state.dirty = false;
  state.isDraft = true;
  state.selection = { kind: 'none' };
  state.currentTime = 0;
  past.length = 0;
  future.length = 0;
  emit();
}

export function promoteDraftToSaved(): void {
  state.isDraft = false;
  emit();
}

export function getDef(): AnimationDef | null {
  return state.def;
}

export function getSelection(): Selection {
  return state.selection;
}

export function isDirty(): boolean {
  return state.dirty;
}

export function getCurrentTime(): number {
  return state.currentTime;
}

export function setCurrentTime(time: number): void {
  state.currentTime = Math.max(0, Math.round(time));
  emit();
}

export function setDef(def: AnimationDef | null, markDirty = false): void {
  state.def = def;
  state.dirty = markDirty;
  state.isDraft = false;
  state.selection = { kind: 'none' };
  state.currentTime = 0;
  past.length = 0;
  future.length = 0;
  emit();
}

export function markClean(): void {
  state.dirty = false;
  emit();
}

export function setSelection(sel: Selection): void {
  state.selection = sel;
  emit();
}

export function getSelectedElementIds(sel: Selection): string[] {
  if (sel.kind === 'element') return [sel.elementId];
  if (sel.kind === 'elements') return sel.elementIds;
  return [];
}

export function isElementSelected(sel: Selection, id: string): boolean {
  if (sel.kind === 'element') return sel.elementId === id;
  if (sel.kind === 'elements') return sel.elementIds.includes(id);
  return false;
}

export function toggleSelectionFor(sel: Selection, id: string): Selection {
  const cur = getSelectedElementIds(sel);
  if (cur.includes(id)) {
    const next = cur.filter((x) => x !== id);
    if (next.length === 0) return { kind: 'none' };
    if (next.length === 1) return { kind: 'element', elementId: next[0] };
    return { kind: 'elements', elementIds: next };
  }
  const next = [...cur, id];
  if (next.length === 1) return { kind: 'element', elementId: next[0] };
  return { kind: 'elements', elementIds: next };
}

export function getCurrentSnapshot(): SnapshotMap {
  if (!state.def) return new Map();
  return computeSnapshot(state.def, state.currentTime);
}

import type {
  AnimationDef,
  AnimationElement,
  Appearance,
  PropertyTrack,
  TrackKeyframe,
} from '@/entities/animation/engine/schema';
import type { HistoryKind } from './types';
import { emit, mutateDef, state } from './internals';

function ensureAppearance(el: AnimationElement, def: AnimationDef): void {
  if (!el.appearances || el.appearances.length === 0) {
    el.appearances = [{ start: 0, end: def.duration, entryDuration: 300, exitDuration: 300 }];
  }
}

export function addElement(el: AnimationElement): void {
  const kind: HistoryKind = el.type === 'group' ? 'group' : 'add';
  const label =
    el.type === 'group'
      ? `그룹 생성 (${(el as { childIds?: string[] }).childIds?.length ?? 0}개)`
      : `요소 추가: ${el.type}`;
  mutateDef(
    (def) => {
      const cloned = JSON.parse(JSON.stringify(el)) as AnimationElement;
      ensureAppearance(cloned, def);
      if (!cloned.tracks) cloned.tracks = [];
      def.elements.push(cloned);
    },
    label,
    kind,
  );
  state.selection = { kind: 'element', elementId: el.id };
  emit();
}

export function deleteElement(id: string): void {
  const targetEl = state.def?.elements.find((e) => e.id === id);
  const isGroupKind = targetEl?.type === 'group';
  mutateDef(
    (def) => {
      def.elements = def.elements.filter((e) => e.id !== id);
      def.effects = def.effects.filter((e) => e.elementId !== id);
      for (const el of def.elements) {
        if (el.type === 'group' && el.childIds.includes(id)) {
          el.childIds = el.childIds.filter((c) => c !== id);
        }
      }
    },
    isGroupKind ? `그룹 해제` : `요소 삭제: ${id}`,
    isGroupKind ? 'group' : 'delete',
  );
  if (state.selection.kind === 'element' && state.selection.elementId === id) {
    state.selection = { kind: 'none' };
  } else if (state.selection.kind === 'elements') {
    const remaining = state.selection.elementIds.filter((x) => x !== id);
    if (remaining.length === 0) state.selection = { kind: 'none' };
    else if (remaining.length === 1) state.selection = { kind: 'element', elementId: remaining[0] };
    else state.selection = { kind: 'elements', elementIds: remaining };
  }
  emit();
}

function labelForPatch(id: string, patch: Record<string, unknown>): { label: string; kind: HistoryKind } {
  const keys = Object.keys(patch);
  if (keys.length === 0) return { label: `요소 수정: ${id}`, kind: 'other' };
  const posKeys = ['x', 'y', 'cx', 'cy', 'x1', 'y1', 'x2', 'y2', 'points'];
  const sizeKeys = ['width', 'height', 'r', 'fontSize', 'cellWidth'];
  const styleKeys = ['fill', 'stroke', 'strokeWidth', 'color', 'opacity', 'cornerRadius', 'labelColor', 'labelSize'];
  if (keys.some((k) => posKeys.includes(k))) return { label: `이동: ${id}`, kind: 'move' };
  if (keys.some((k) => sizeKeys.includes(k))) return { label: `크기 변경: ${id}`, kind: 'resize' };
  if (keys.includes('rotation')) return { label: `회전: ${id}`, kind: 'rotate' };
  if (keys.some((k) => styleKeys.includes(k))) return { label: `스타일: ${id} (${keys.join(', ')})`, kind: 'style' };
  if (keys.includes('name')) return { label: `이름 변경: ${id}`, kind: 'meta' };
  return { label: `요소 수정: ${id} (${keys.join(', ')})`, kind: 'other' };
}

export function updateElementBase(id: string, patch: Record<string, unknown>): void {
  const { label, kind } = labelForPatch(id, patch);
  mutateDef(
    (def) => {
      const idx = def.elements.findIndex((e) => e.id === id);
      if (idx < 0) return;
      const baseEl = def.elements[idx];
      const merged: Record<string, unknown> = { ...(baseEl as unknown as Record<string, unknown>) };
      for (const [k, v] of Object.entries(patch)) {
        if (v === null || v === undefined) delete merged[k];
        else merged[k] = v;
      }
      def.elements[idx] = merged as unknown as AnimationElement;
    },
    label,
    kind,
  );
}

export function reorderElement(sourceId: string, targetId: string, position: 'before' | 'after'): void {
  mutateDef(
    (def) => {
      const srcIdx = def.elements.findIndex((e) => e.id === sourceId);
      if (srcIdx < 0) return;
      const [moved] = def.elements.splice(srcIdx, 1);
      let targetIdx = def.elements.findIndex((e) => e.id === targetId);
      if (targetIdx < 0) {
        def.elements.push(moved);
        return;
      }
      if (position === 'after') targetIdx += 1;
      def.elements.splice(targetIdx, 0, moved);
    },
    `순서 변경: ${sourceId}`,
    'reorder',
  );
}

export function moveElementToEnd(id: string): void {
  mutateDef(
    (def) => {
      const idx = def.elements.findIndex((e) => e.id === id);
      if (idx < 0) return;
      const [moved] = def.elements.splice(idx, 1);
      def.elements.push(moved);
    },
    `맨 앞으로: ${id}`,
    'reorder',
  );
}

export function moveElementToFront(id: string): void {
  mutateDef(
    (def) => {
      const idx = def.elements.findIndex((e) => e.id === id);
      if (idx < 0) return;
      const [moved] = def.elements.splice(idx, 1);
      def.elements.unshift(moved);
    },
    `맨 뒤로: ${id}`,
    'reorder',
  );
}

export function addAppearance(id: string, ap: Appearance): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === id);
      if (!el) return;
      el.appearances.push(ap);
      el.appearances.sort((a, b) => a.start - b.start);
    },
    `출현 추가: ${id}`,
    'appearance',
  );
}

export function updateAppearance(id: string, apIdx: number, patch: Partial<Appearance>): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === id);
      if (!el || !el.appearances[apIdx]) return;
      el.appearances[apIdx] = { ...el.appearances[apIdx], ...patch };
      el.appearances.sort((a, b) => a.start - b.start);
    },
    `출현 조정: ${id}`,
    'appearance',
  );
}

export function removeAppearance(id: string, apIdx: number): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === id);
      if (!el) return;
      el.appearances.splice(apIdx, 1);
      if (el.appearances.length === 0) ensureAppearance(el, def);
    },
    `출현 삭제: ${id}`,
    'appearance',
  );
}

function findTrack(el: AnimationElement, property: string): PropertyTrack | undefined {
  return el.tracks.find((t) => t.property === property);
}

export function setTrackKeyframe(
  elementId: string,
  property: string,
  time: number,
  value: TrackKeyframe['value'],
): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === elementId);
      if (!el) return;
      let track = findTrack(el, property);
      if (!track) {
        track = { property, keyframes: [] };
        el.tracks.push(track);
      }
      const existing = track.keyframes.find((k) => k.time === time);
      if (existing) {
        existing.value = value;
      } else {
        track.keyframes.push({ time, value });
        track.keyframes.sort((a, b) => a.time - b.time);
      }
    },
    `keyframe ${property} @ ${time}ms`,
    'track',
  );
}

export function removeTrackKeyframe(elementId: string, property: string, time: number): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === elementId);
      if (!el) return;
      const track = findTrack(el, property);
      if (!track) return;
      track.keyframes = track.keyframes.filter((k) => k.time !== time);
      if (track.keyframes.length === 0) {
        el.tracks = el.tracks.filter((t) => t.property !== property);
      }
    },
    `keyframe 삭제 ${property} @ ${time}ms`,
    'track',
  );
}

export function setElementValueAtTime(elementId: string, patch: Record<string, unknown>): void {
  const time = state.currentTime;
  if (time <= 0) {
    updateElementBase(elementId, patch);
    return;
  }
  if (!state.def) return;
  const el = state.def.elements.find((e) => e.id === elementId);
  if (!el) return;
  for (const [prop, value] of Object.entries(patch)) {
    if (value === null || value === undefined) continue;
    if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean') continue;
    const hasTrack = el.tracks.some((t) => t.property === prop);
    if (!hasTrack) {
      const baseVal = (el as unknown as Record<string, unknown>)[prop];
      if (typeof baseVal === 'string' || typeof baseVal === 'number' || typeof baseVal === 'boolean') {
        setTrackKeyframe(elementId, prop, 0, baseVal);
      }
    }
    setTrackKeyframe(elementId, prop, time, value);
  }
}

export function removeTrack(elementId: string, property: string): void {
  mutateDef(
    (def) => {
      const el = def.elements.find((e) => e.id === elementId);
      if (!el) return;
      el.tracks = el.tracks.filter((t) => t.property !== property);
    },
    `트랙 삭제: ${property}`,
    'track',
  );
}

import type { HistoryEntry, HistoryKind } from './types';
import {
  emit,
  future,
  past,
  pushHistory,
  setInTransient,
  snapshotJson,
  state,
} from './internals';

export function beginTransient(label = 'edit', kind: HistoryKind = 'other'): void {
  if (!state.def) return;
  pushHistory(label, kind);
  setInTransient(true);
}

export function endTransient(): void {
  setInTransient(false);
}

export function canUndo(): boolean {
  return past.length > 0;
}

export function canRedo(): boolean {
  return future.length > 0;
}

export function undo(): void {
  if (past.length === 0) return;
  const prev = past[past.length - 1]!;
  const cur = snapshotJson();
  if (cur !== null) {
    future.push({ snap: cur, label: prev.label, kind: prev.kind, timestamp: prev.timestamp });
  }
  past.pop();
  state.def = JSON.parse(prev.snap);
  state.dirty = true;
  emit();
}

export function redo(): void {
  if (future.length === 0) return;
  const next = future[future.length - 1]!;
  const cur = snapshotJson();
  if (cur !== null) {
    past.push({ snap: cur, label: next.label, kind: next.kind, timestamp: next.timestamp });
  }
  future.pop();
  state.def = JSON.parse(next.snap);
  state.dirty = true;
  emit();
}

export function resetHistory(): void {
  past.length = 0;
  future.length = 0;
}

export function getHistory(): { past: readonly HistoryEntry[]; future: readonly HistoryEntry[] } {
  return { past, future };
}

export function jumpBack(steps: number): void {
  if (steps <= 0 || past.length === 0) return;
  const n = Math.min(steps, past.length);
  for (let i = 0; i < n; i += 1) undo();
}

export function jumpForward(steps: number): void {
  if (steps <= 0 || future.length === 0) return;
  const n = Math.min(steps, future.length);
  for (let i = 0; i < n; i += 1) redo();
}

import type { AnimationDef } from '@/entities/animation/engine/schema';
import { animationDefSchema } from '@/entities/animation/engine/schema';
import type { HistoryEntry, HistoryKind, InternalState, Listener } from './types';

const listeners = new Set<Listener>();

export const state: InternalState = {
  def: null,
  dirty: false,
  selection: { kind: 'none' },
  currentTime: 0,
  isDraft: false,
};

const HISTORY_LIMIT = 60;

export const past: HistoryEntry[] = [];
export const future: HistoryEntry[] = [];

let inTransient = false;

export function snapshotJson(): string | null {
  return state.def ? JSON.stringify(state.def) : null;
}

export function pushHistory(label: string, kind: HistoryKind): void {
  const snap = snapshotJson();
  if (snap === null) return;
  past.push({ snap, label, kind, timestamp: Date.now() });
  if (past.length > HISTORY_LIMIT) past.shift();
  future.length = 0;
}

export function setInTransient(value: boolean): void {
  inTransient = value;
}

export function subscribe(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function emit(): void {
  for (const fn of listeners) fn();
}

export function mutateDef(
  fn: (def: AnimationDef) => void,
  label = 'edit',
  kind: HistoryKind = 'other',
): void {
  if (!state.def) return;
  if (!inTransient) pushHistory(label, kind);
  const cloned = JSON.parse(JSON.stringify(state.def));
  fn(cloned);
  const parsed = animationDefSchema.safeParse(cloned);
  if (!parsed.success) {
    past.pop();
    console.warn('[studio.state] invalid mutation', parsed.error.issues);
    return;
  }
  state.def = parsed.data;
  state.dirty = true;
  emit();
}

import type { AnimationDef } from '@/entities/animation/engine/schema';
import { mutateDef, state } from './internals';

export function updateMeta(patch: Partial<Pick<AnimationDef, 'title' | 'description'>>): void {
  const keys = Object.keys(patch).join(', ');
  mutateDef(
    (def) => {
      Object.assign(def, patch);
    },
    `메타 수정: ${keys}`,
    'meta',
  );
}

export function updateCanvas(patch: Partial<AnimationDef['canvas']>): void {
  const keys = Object.keys(patch).join(', ');
  mutateDef(
    (def) => {
      def.canvas = { ...def.canvas, ...patch };
    },
    `캔버스: ${keys}`,
    'canvas',
  );
}

export function updateSettings(patch: Partial<AnimationDef['settings']>): void {
  const keys = Object.keys(patch).join(', ');
  mutateDef(
    (def) => {
      def.settings = { ...def.settings, ...patch };
    },
    `설정: ${keys}`,
    'settings',
  );
}

export function uniqueElementId(type: string): string {
  if (!state.def) return type + '-1';
  const used = new Set(state.def.elements.map((e) => e.id));
  let i = 1;
  while (used.has(`${type}-${i}`)) i += 1;
  return `${type}-${i}`;
}

export function uniqueChapterId(): string {
  if (!state.def) return 'chapter-1';
  const used = new Set(state.def.chapters.map((c) => c.id));
  let i = 1;
  while (used.has(`chapter-${i}`)) i += 1;
  return `chapter-${i}`;
}

export function uniqueEffectId(): string {
  if (!state.def) return 'effect-1';
  const used = new Set(state.def.effects.map((e) => e.id));
  let i = 1;
  while (used.has(`effect-${i}`)) i += 1;
  return `effect-${i}`;
}

import type {
  AnimationEffect,
  Chapter,
} from '@/entities/animation/engine/schema';
import { emit, mutateDef, state } from './internals';

export function addChapter(c: Chapter): void {
  mutateDef(
    (def) => {
      def.chapters.push(c);
      def.chapters.sort((a, b) => a.time - b.time);
    },
    `Chapter 추가: ${c.label || c.id}`,
    'chapter',
  );
  state.selection = { kind: 'chapter', chapterId: c.id };
  emit();
}

export function updateChapter(id: string, patch: Partial<Chapter>): void {
  const keys = Object.keys(patch).join(', ');
  mutateDef(
    (def) => {
      const idx = def.chapters.findIndex((c) => c.id === id);
      if (idx < 0) return;
      def.chapters[idx] = { ...def.chapters[idx], ...patch };
      def.chapters.sort((a, b) => a.time - b.time);
    },
    `Chapter 수정: ${id} (${keys})`,
    'chapter',
  );
}

export function deleteChapter(id: string): void {
  mutateDef(
    (def) => {
      def.chapters = def.chapters.filter((c) => c.id !== id);
    },
    `Chapter 삭제: ${id}`,
    'chapter',
  );
  if (state.selection.kind === 'chapter' && state.selection.chapterId === id) {
    state.selection = { kind: 'none' };
  }
  emit();
}

export function addEffect(eff: AnimationEffect): void {
  mutateDef(
    (def) => {
      def.effects.push(eff);
      def.effects.sort((a, b) => a.time - b.time);
    },
    `효과 추가: ${eff.type}`,
    'effect',
  );
}

export function updateEffect(id: string, patch: Partial<AnimationEffect>): void {
  mutateDef(
    (def) => {
      const idx = def.effects.findIndex((e) => e.id === id);
      if (idx < 0) return;
      def.effects[idx] = { ...def.effects[idx], ...patch } as AnimationEffect;
      def.effects.sort((a, b) => a.time - b.time);
    },
    `효과 수정: ${id}`,
    'effect',
  );
}

export function deleteEffect(id: string): void {
  mutateDef(
    (def) => {
      def.effects = def.effects.filter((e) => e.id !== id);
    },
    `효과 삭제: ${id}`,
    'effect',
  );
  if (state.selection.kind === 'effect' && state.selection.effectId === id) {
    state.selection = { kind: 'none' };
  }
  emit();
}

export function updateDuration(ms: number): void {
  mutateDef(
    (def) => {
      def.duration = Math.max(0, Math.round(ms));
      for (const el of def.elements) {
        for (const ap of el.appearances) {
          if (ap.end > def.duration) ap.end = def.duration;
          if (ap.start > def.duration) ap.start = def.duration;
        }
      }
      for (const ch of def.chapters) {
        if (ch.time > def.duration) ch.time = def.duration;
      }
      for (const eff of def.effects) {
        if (eff.time > def.duration) eff.time = def.duration;
      }
    },
    `duration: ${ms} ms`,
    'meta',
  );
  if (state.currentTime > ms) state.currentTime = ms;
}

import type { AnimationDef } from '@/entities/animation/engine/schema';

export type Selection =
  | { kind: 'none' }
  | { kind: 'element'; elementId: string }
  | { kind: 'elements'; elementIds: string[] }
  | { kind: 'chapter'; chapterId: string }
  | { kind: 'effect'; effectId: string };

export interface InternalState {
  def: AnimationDef | null;
  dirty: boolean;
  selection: Selection;
  currentTime: number;
  isDraft: boolean;
}

export type HistoryKind =
  | 'meta'
  | 'canvas'
  | 'settings'
  | 'add'
  | 'delete'
  | 'move'
  | 'style'
  | 'rotate'
  | 'resize'
  | 'reorder'
  | 'track'
  | 'appearance'
  | 'chapter'
  | 'effect'
  | 'group'
  | 'other';

export interface HistoryEntry {
  snap: string;
  label: string;
  kind: HistoryKind;
  timestamp: number;
}

export type Listener = () => void;

import type { AnimationElement } from '@/entities/animation/engine/schema';
import { getDef, getSelection, getSelectedElementIds, updateElementBase } from './state';

export type AlignKind = 'left' | 'center-h' | 'right' | 'top' | 'middle-v' | 'bottom';
export type DistributeKind = 'horizontal' | 'vertical';

interface Bbox { x: number; y: number; w: number; h: number }

function elementBbox(el: AnimationElement): Bbox | null {
  if (el.type === 'rect' || el.type === 'image') return { x: el.x, y: el.y, w: el.width, h: el.height };
  if (el.type === 'circle') return { x: el.cx - el.r, y: el.cy - el.r, w: el.r * 2, h: el.r * 2 };
  if (el.type === 'text') return { x: el.x - 40, y: el.y - (el.fontSize ?? 16), w: 80, h: el.fontSize ?? 16 };
  if (el.type === 'line' || el.type === 'arrow') {
    if (typeof el.x1 !== 'number' || typeof el.x2 !== 'number' || typeof el.y1 !== 'number' || typeof el.y2 !== 'number') return null;
    return {
      x: Math.min(el.x1, el.x2),
      y: Math.min(el.y1, el.y2),
      w: Math.abs(el.x2 - el.x1),
      h: Math.abs(el.y2 - el.y1),
    };
  }
  if (el.type === 'polygon') {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    let any = false;
    for (const pair of el.points.trim().split(/\s+/)) {
      const [x, y] = pair.split(',').map(Number);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      any = true;
      if (x < minX) minX = x; if (y < minY) minY = y;
      if (x > maxX) maxX = x; if (y > maxY) maxY = y;
    }
    return any ? { x: minX, y: minY, w: maxX - minX, h: maxY - minY } : null;
  }
  if (el.type === 'path') return { x: el.x ?? 0, y: el.y ?? 0, w: 60, h: 60 };
  return null;
}

function shiftBy(el: AnimationElement, dx: number, dy: number): void {
  if (dx === 0 && dy === 0) return;
  if (el.type === 'rect' || el.type === 'image' || el.type === 'text') {
    updateElementBase(el.id, { x: el.x + dx, y: el.y + dy });
  } else if (el.type === 'circle') {
    updateElementBase(el.id, { cx: el.cx + dx, cy: el.cy + dy });
  } else if (el.type === 'line' || el.type === 'arrow') {
    const patch: Record<string, unknown> = {};
    if (typeof el.x1 === 'number') patch.x1 = el.x1 + dx;
    if (typeof el.y1 === 'number') patch.y1 = el.y1 + dy;
    if (typeof el.x2 === 'number') patch.x2 = el.x2 + dx;
    if (typeof el.y2 === 'number') patch.y2 = el.y2 + dy;
    updateElementBase(el.id, patch);
  } else if (el.type === 'path') {
    updateElementBase(el.id, { x: (el.x ?? 0) + dx, y: (el.y ?? 0) + dy });
  } else if (el.type === 'polygon') {
    const shifted = el.points.trim().split(/\s+/).map((pair) => {
      const [x, y] = pair.split(',').map(Number);
      if (Number.isFinite(x) && Number.isFinite(y)) return `${(x + dx).toFixed(1)},${(y + dy).toFixed(1)}`;
      return pair;
    }).join(' ');
    updateElementBase(el.id, { points: shifted });
  }
}

function selectedElementsWithBbox(): Array<{ el: AnimationElement; bbox: Bbox }> {
  const def = getDef();
  if (!def) return [];
  const sel = getSelection();
  const ids = getSelectedElementIds(sel);
  if (ids.length < 2) return [];
  const out: Array<{ el: AnimationElement; bbox: Bbox }> = [];
  for (const id of ids) {
    const el = def.elements.find((e) => e.id === id);
    if (!el) continue;
    const bbox = elementBbox(el);
    if (bbox) out.push({ el, bbox });
  }
  return out;
}

export function alignSelected(kind: AlignKind): boolean {
  const items = selectedElementsWithBbox();
  if (items.length < 2) return false;
  const xs = items.map((it) => it.bbox.x);
  const ys = items.map((it) => it.bbox.y);
  const rights = items.map((it) => it.bbox.x + it.bbox.w);
  const bottoms = items.map((it) => it.bbox.y + it.bbox.h);
  const left = Math.min(...xs);
  const right = Math.max(...rights);
  const top = Math.min(...ys);
  const bottom = Math.max(...bottoms);
  const centerH = (left + right) / 2;
  const middleV = (top + bottom) / 2;
  for (const { el, bbox } of items) {
    let dx = 0; let dy = 0;
    if (kind === 'left') dx = left - bbox.x;
    else if (kind === 'right') dx = right - (bbox.x + bbox.w);
    else if (kind === 'center-h') dx = centerH - (bbox.x + bbox.w / 2);
    else if (kind === 'top') dy = top - bbox.y;
    else if (kind === 'bottom') dy = bottom - (bbox.y + bbox.h);
    else if (kind === 'middle-v') dy = middleV - (bbox.y + bbox.h / 2);
    shiftBy(el, Math.round(dx), Math.round(dy));
  }
  return true;
}

export function distributeSelected(kind: DistributeKind): boolean {
  const items = selectedElementsWithBbox();
  if (items.length < 3) return false;
  if (kind === 'horizontal') {
    items.sort((a, b) => a.bbox.x + a.bbox.w / 2 - (b.bbox.x + b.bbox.w / 2));
    const firstCenter = items[0].bbox.x + items[0].bbox.w / 2;
    const lastCenter = items[items.length - 1].bbox.x + items[items.length - 1].bbox.w / 2;
    const step = (lastCenter - firstCenter) / (items.length - 1);
    for (let i = 1; i < items.length - 1; i += 1) {
      const targetCenter = firstCenter + step * i;
      const currentCenter = items[i].bbox.x + items[i].bbox.w / 2;
      shiftBy(items[i].el, Math.round(targetCenter - currentCenter), 0);
    }
  } else {
    items.sort((a, b) => a.bbox.y + a.bbox.h / 2 - (b.bbox.y + b.bbox.h / 2));
    const firstCenter = items[0].bbox.y + items[0].bbox.h / 2;
    const lastCenter = items[items.length - 1].bbox.y + items[items.length - 1].bbox.h / 2;
    const step = (lastCenter - firstCenter) / (items.length - 1);
    for (let i = 1; i < items.length - 1; i += 1) {
      const targetCenter = firstCenter + step * i;
      const currentCenter = items[i].bbox.y + items[i].bbox.h / 2;
      shiftBy(items[i].el, 0, Math.round(targetCenter - currentCenter));
    }
  }
  return true;
}

import type { AnimationElement } from '@/entities/animation/engine/schema';
import {
  addElement,
  getDef,
  getSelectedElementIds,
  getSelection,
  setSelection,
  uniqueElementId,
  updateElementBase,
} from './state';
import { isGroup, moveGroupBy } from './studio-groups';

let clipboard: AnimationElement[] = [];

function shiftCloneCoords(el: AnimationElement, dx: number, dy: number): AnimationElement {
  const clone = JSON.parse(JSON.stringify(el)) as AnimationElement;
  if (clone.type === 'rect' || clone.type === 'image' || clone.type === 'text') {
    clone.x += dx;
    clone.y += dy;
  } else if (clone.type === 'circle') {
    clone.cx += dx;
    clone.cy += dy;
  } else if (clone.type === 'line' || clone.type === 'arrow') {
    if (typeof clone.x1 === 'number') clone.x1 += dx;
    if (typeof clone.y1 === 'number') clone.y1 += dy;
    if (typeof clone.x2 === 'number') clone.x2 += dx;
    if (typeof clone.y2 === 'number') clone.y2 += dy;
  } else if (clone.type === 'path') {
    clone.x = (clone.x ?? 0) + dx;
    clone.y = (clone.y ?? 0) + dy;
  } else if (clone.type === 'polygon') {
    const pts = clone.points.trim().split(/\s+/).map((pair: string) => {
      const [x, y] = pair.split(',').map(Number);
      if (Number.isFinite(x) && Number.isFinite(y)) return `${x + dx},${y + dy}`;
      return pair;
    });
    clone.points = pts.join(' ');
  }
  return clone;
}

export function copySelection(): boolean {
  const sel = getSelection();
  const ids = getSelectedElementIds(sel);
  if (ids.length === 0) return false;
  const def = getDef();
  if (!def) return false;
  const copies: AnimationElement[] = [];
  for (const id of ids) {
    const el = def.elements.find((e) => e.id === id);
    if (el) copies.push(JSON.parse(JSON.stringify(el)));
  }
  if (copies.length === 0) return false;
  clipboard = copies;
  return true;
}

export function pasteFromClipboard(): boolean {
  if (clipboard.length === 0) return false;
  const newIds: string[] = [];
  for (const item of clipboard) {
    const newId = uniqueElementId(item.type);
    const shifted = shiftCloneCoords(item, 20, 20);
    shifted.id = newId;
    addElement(shifted);
    newIds.push(newId);
  }
  if (newIds.length === 1) {
    setSelection({ kind: 'element', elementId: newIds[0] });
  } else if (newIds.length > 1) {
    setSelection({ kind: 'elements', elementIds: newIds });
  }
  return true;
}

export function duplicateSelection(): boolean {
  const sel = getSelection();
  const ids = getSelectedElementIds(sel);
  if (ids.length === 0) return false;
  const def = getDef();
  if (!def) return false;
  const newIds: string[] = [];
  for (const id of ids) {
    const el = def.elements.find((e) => e.id === id);
    if (!el) continue;
    const newId = uniqueElementId(el.type);
    const cloned = JSON.parse(JSON.stringify(el)) as AnimationElement;
    const shifted = shiftCloneCoords(cloned, 20, 20);
    shifted.id = newId;
    addElement(shifted);
    newIds.push(newId);
  }
  if (newIds.length === 1) {
    setSelection({ kind: 'element', elementId: newIds[0] });
  } else if (newIds.length > 1) {
    setSelection({ kind: 'elements', elementIds: newIds });
  }
  return newIds.length > 0;
}

function moveOneElement(el: AnimationElement, dx: number, dy: number): boolean {
  if (isGroup(el)) {
    moveGroupBy(el.id, dx, dy);
    return true;
  }
  const patch: Record<string, unknown> = {};
  if (el.type === 'rect' || el.type === 'image' || el.type === 'text') {
    patch.x = el.x + dx;
    patch.y = el.y + dy;
  } else if (el.type === 'circle') {
    patch.cx = el.cx + dx;
    patch.cy = el.cy + dy;
  } else if (el.type === 'line' || el.type === 'arrow') {
    if (typeof el.x1 === 'number') patch.x1 = el.x1 + dx;
    if (typeof el.y1 === 'number') patch.y1 = el.y1 + dy;
    if (typeof el.x2 === 'number') patch.x2 = el.x2 + dx;
    if (typeof el.y2 === 'number') patch.y2 = el.y2 + dy;
  } else if (el.type === 'path') {
    patch.x = (el.x ?? 0) + dx;
    patch.y = (el.y ?? 0) + dy;
  } else if (el.type === 'polygon') {
    const pts = el.points.trim().split(/\s+/).map((pair) => {
      const [x, y] = pair.split(',').map(Number);
      if (Number.isFinite(x) && Number.isFinite(y)) return `${x + dx},${y + dy}`;
      return pair;
    });
    patch.points = pts.join(' ');
  } else {
    return false;
  }
  updateElementBase(el.id, patch);
  return true;
}

export function moveSelectedElement(dx: number, dy: number): boolean {
  const sel = getSelection();
  const ids = getSelectedElementIds(sel);
  if (ids.length === 0) return false;
  const def = getDef();
  if (!def) return false;
  let moved = false;
  for (const id of ids) {
    const el = def.elements.find((e) => e.id === id);
    if (el && moveOneElement(el, dx, dy)) moved = true;
  }
  return moved;
}

/**
 * Focus capture / restore for panels that rebuild their DOM via innerHTML on
 * every state change. Without this, typing a character into an input fires a
 * state update → subscribe() → render() → innerHTML rewrite → the focused
 * input is destroyed mid-keystroke and focus is lost.
 *
 * Usage:
 *
 *   function render(): void {
 *     if (!panelEl) return;
 *     const snap = captureFocusWithin(panelEl);
 *     renderInner();                  // existing innerHTML-rewriting body
 *     restoreFocusWithin(panelEl, snap);
 *   }
 *
 * The snapshot is keyed on a stable attribute (preferring `data-prop-key`,
 * falling back to `id`). Inputs that share the same `data-prop-key` are
 * disambiguated by `type` (e.g. color field has two inputs: type="color"
 * and type="text").
 */

export interface FocusSnapshot {
  selector: string;
  selectionStart: number | null;
  selectionEnd: number | null;
}

export function captureFocusWithin(root: HTMLElement): FocusSnapshot | null {
  const active = document.activeElement;
  if (!(active instanceof HTMLElement) || !root.contains(active)) return null;
  const selector = focusSelectorFor(active);
  if (!selector) return null;
  let selectionStart: number | null = null;
  let selectionEnd: number | null = null;
  if (active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement) {
    // selectionStart / setSelectionRange throw DOMException on input
    // types color / number / range / date / etc.; null means "skip caret restore".
    try {
      selectionStart = active.selectionStart;
      selectionEnd = active.selectionEnd;
    } catch { /* see note above */ }
  }
  return { selector, selectionStart, selectionEnd };
}

export function restoreFocusWithin(root: HTMLElement, snap: FocusSnapshot | null): void {
  if (!snap) return;
  let target: HTMLElement | null;
  try {
    target = root.querySelector<HTMLElement>(snap.selector);
  } catch {
    return;
  }
  if (!target) return;
  try {
    target.focus({ preventScroll: true });
  } catch {
    return;
  }
  if (
    (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) &&
    snap.selectionStart !== null &&
    snap.selectionEnd !== null
  ) {
    try {
      target.setSelectionRange(snap.selectionStart, snap.selectionEnd);
    } catch { /* same DOMException as capture above */ }
  }
}

function focusSelectorFor(el: HTMLElement): string | null {
  const propKey = el.dataset.propKey;
  if (propKey !== undefined) {
    const tag = el.tagName.toLowerCase();
    const type = el instanceof HTMLInputElement ? el.type : '';
    const keyEsc = cssEscape(propKey);
    if (type) return `${tag}[type="${cssEscape(type)}"][data-prop-key="${keyEsc}"]`;
    return `${tag}[data-prop-key="${keyEsc}"]`;
  }
  if (el.id) return `#${cssEscape(el.id)}`;
  return null;
}

function cssEscape(s: string): string {
  const fn = (globalThis as { CSS?: { escape?: (s: string) => string } }).CSS?.escape;
  if (typeof fn === 'function') return fn(s);
  // Fallback escape (sufficient for our keys, alphanumerics + dots + dashes).
  return s.replace(/[!"#$%&'()*+,./:;<=>?@[\\\]^`{|}~]/g, '\\$&');
}

import type { AnimationElement, GroupElement } from '@/entities/animation/engine/schema';
import {
  addElement,
  deleteElement,
  getDef,
  setSelection,
  uniqueElementId,
  updateElementBase,
} from './state';

export function isGroup(el: AnimationElement): el is GroupElement {
  return el.type === 'group';
}

export function findContainingGroup(elementId: string): GroupElement | null {
  const def = getDef();
  if (!def) return null;
  for (const el of def.elements) {
    if (isGroup(el) && el.childIds.includes(elementId)) {
      const outer = findContainingGroup(el.id);
      return outer ?? el;
    }
  }
  return null;
}

export function expandToLeafIds(ids: string[]): string[] {
  const def = getDef();
  if (!def) return ids;
  const seen = new Set<string>();
  const stack = [...ids];
  while (stack.length) {
    const id = stack.pop()!;
    if (seen.has(id)) continue;
    seen.add(id);
    const el = def.elements.find((e) => e.id === id);
    if (el && isGroup(el)) {
      for (const childId of el.childIds) stack.push(childId);
    }
  }
  const out: string[] = [];
  for (const id of seen) {
    const el = def.elements.find((e) => e.id === id);
    if (el && !isGroup(el)) out.push(id);
  }
  return out;
}

export function groupBbox(groupId: string): { x: number; y: number; w: number; h: number } | null {
  const def = getDef();
  if (!def) return null;
  const leafIds = expandToLeafIds([groupId]);
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  let any = false;
  for (const id of leafIds) {
    const el = def.elements.find((e) => e.id === id);
    if (!el) continue;
    const b = elementBbox(el);
    if (!b) continue;
    any = true;
    if (b.x < minX) minX = b.x;
    if (b.y < minY) minY = b.y;
    if (b.x + b.w > maxX) maxX = b.x + b.w;
    if (b.y + b.h > maxY) maxY = b.y + b.h;
  }
  return any ? { x: minX, y: minY, w: maxX - minX, h: maxY - minY } : null;
}

function elementBbox(el: AnimationElement): { x: number; y: number; w: number; h: number } | null {
  if (el.type === 'rect' || el.type === 'image') return { x: el.x, y: el.y, w: el.width, h: el.height };
  if (el.type === 'circle') return { x: el.cx - el.r, y: el.cy - el.r, w: el.r * 2, h: el.r * 2 };
  if (el.type === 'text') return { x: el.x - 40, y: el.y - (el.fontSize ?? 16), w: 80, h: el.fontSize ?? 16 };
  if (el.type === 'line' || el.type === 'arrow') {
    if (typeof el.x1 !== 'number' || typeof el.x2 !== 'number' || typeof el.y1 !== 'number' || typeof el.y2 !== 'number') return null;
    return {
      x: Math.min(el.x1, el.x2),
      y: Math.min(el.y1, el.y2),
      w: Math.abs(el.x2 - el.x1),
      h: Math.abs(el.y2 - el.y1),
    };
  }
  if (el.type === 'polygon') {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    let any = false;
    for (const pair of el.points.trim().split(/\s+/)) {
      const [x, y] = pair.split(',').map(Number);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      any = true;
      if (x < minX) minX = x; if (y < minY) minY = y;
      if (x > maxX) maxX = x; if (y > maxY) maxY = y;
    }
    return any ? { x: minX, y: minY, w: maxX - minX, h: maxY - minY } : null;
  }
  if (el.type === 'path') return { x: el.x ?? 0, y: el.y ?? 0, w: 60, h: 60 };
  return null;
}

function shiftLeafBy(el: AnimationElement, dx: number, dy: number): void {
  if (dx === 0 && dy === 0) return;
  if (el.type === 'rect' || el.type === 'image' || el.type === 'text') {
    updateElementBase(el.id, { x: el.x + dx, y: el.y + dy });
  } else if (el.type === 'circle') {
    updateElementBase(el.id, { cx: el.cx + dx, cy: el.cy + dy });
  } else if (el.type === 'line' || el.type === 'arrow') {
    const patch: Record<string, unknown> = {};
    if (typeof el.x1 === 'number') patch.x1 = el.x1 + dx;
    if (typeof el.y1 === 'number') patch.y1 = el.y1 + dy;
    if (typeof el.x2 === 'number') patch.x2 = el.x2 + dx;
    if (typeof el.y2 === 'number') patch.y2 = el.y2 + dy;
    updateElementBase(el.id, patch);
  } else if (el.type === 'path') {
    updateElementBase(el.id, { x: (el.x ?? 0) + dx, y: (el.y ?? 0) + dy });
  } else if (el.type === 'polygon') {
    const shifted = el.points.trim().split(/\s+/).map((pair) => {
      const [x, y] = pair.split(',').map(Number);
      if (Number.isFinite(x) && Number.isFinite(y)) return `${(x + dx).toFixed(1)},${(y + dy).toFixed(1)}`;
      return pair;
    }).join(' ');
    updateElementBase(el.id, { points: shifted });
  }
}

export function moveGroupBy(groupId: string, dx: number, dy: number): void {
  const def = getDef();
  if (!def) return;
  const leafIds = expandToLeafIds([groupId]);
  for (const id of leafIds) {
    const el = def.elements.find((e) => e.id === id);
    if (el) shiftLeafBy(el, dx, dy);
  }
  const group = def.elements.find((e) => e.id === groupId);
  if (group && isGroup(group)) {
    updateElementBase(groupId, { x: group.x + dx, y: group.y + dy });
  }
}

export function groupElements(ids: string[]): string | null {
  if (ids.length < 2) return null;
  const def = getDef();
  if (!def) return null;
  const valid = ids.filter((id) => def.elements.some((e) => e.id === id));
  if (valid.length < 2) return null;
  const newId = uniqueElementId('group');
  const bbox = (() => {
    let minX = Infinity, minY = Infinity;
    for (const id of valid) {
      const el = def.elements.find((e) => e.id === id);
      if (!el) continue;
      const b = elementBbox(el);
      if (!b) continue;
      if (b.x < minX) minX = b.x;
      if (b.y < minY) minY = b.y;
    }
    return { x: Number.isFinite(minX) ? minX : 0, y: Number.isFinite(minY) ? minY : 0 };
  })();
  const group: GroupElement = {
    type: 'group',
    id: newId,
    name: `Group ${newId.split('-')[1] ?? ''}`.trim(),
    rotation: 0,
    appearances: [],
    tracks: [],
    x: bbox.x,
    y: bbox.y,
    childIds: valid,
  };
  addElement(group);
  setSelection({ kind: 'element', elementId: newId });
  return newId;
}

export function ungroupElement(groupId: string): string[] {
  const def = getDef();
  if (!def) return [];
  const group = def.elements.find((e) => e.id === groupId);
  if (!group || !isGroup(group)) return [];
  const childIds = [...group.childIds];
  deleteElement(groupId);
  if (childIds.length === 1) {
    setSelection({ kind: 'element', elementId: childIds[0] });
  } else if (childIds.length > 1) {
    setSelection({ kind: 'elements', elementIds: childIds });
  } else {
    setSelection({ kind: 'none' });
  }
  return childIds;
}

import {
  getHistory,
  jumpBack,
  jumpForward,
  subscribe,
  type HistoryEntry,
  type HistoryKind,
} from './state';

const KIND_ICON: Record<HistoryKind, string> = {
  meta: '✎',
  canvas: '⬚',
  settings: '⚙',
  add: '＋',
  delete: '🗑',
  move: '↔',
  style: '🎨',
  rotate: '↻',
  resize: '⤡',
  reorder: '⇅',
  track: '⌒',
  appearance: '◐',
  chapter: '📍',
  effect: '✨',
  group: '⬚',
  other: '·',
};

let dialogEl: HTMLDialogElement | null = null;
let listEl: HTMLUListElement | null = null;

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function formatTimeAgo(ts: number): string {
  const secs = Math.round((Date.now() - ts) / 1000);
  if (secs < 5) return '방금';
  if (secs < 60) return `${secs}초 전`;
  const mins = Math.round(secs / 60);
  if (mins < 60) return `${mins}분 전`;
  const hours = Math.round(mins / 60);
  return `${hours}시간 전`;
}

export function initHistoryPanel(): void {
  dialogEl = document.getElementById('studio-history-dialog') as HTMLDialogElement | null;
  listEl = document.getElementById('studio-history-list') as HTMLUListElement | null;
  if (!dialogEl || !listEl) return;
  listEl.addEventListener('click', onListClick);
  subscribe(() => {
    if (dialogEl?.open) renderList();
  });
}

export function openHistoryPanel(): void {
  if (!dialogEl) return;
  renderList();
  if (typeof dialogEl.showModal === 'function') dialogEl.showModal();
  else dialogEl.setAttribute('open', '');
}

function renderList(): void {
  if (!listEl) return;
  const { past, future } = getHistory();
  if (past.length === 0 && future.length === 0) {
    listEl.innerHTML = '<li class="studio-history-empty">아직 이력이 없습니다</li>';
    return;
  }
  const pastReversed = [...past].slice().reverse();
  const items: string[] = [];
  for (let i = 0; i < future.length; i += 1) {
    const entry = future[future.length - 1 - i];
    items.push(renderEntry(entry, 'future', i + 1));
  }
  items.push('<li class="studio-history-current">현재 위치</li>');
  for (let i = 0; i < pastReversed.length; i += 1) {
    const entry = pastReversed[i];
    items.push(renderEntry(entry, 'past', i + 1));
  }
  listEl.innerHTML = items.join('');
}

function renderEntry(entry: HistoryEntry, side: 'past' | 'future', stepCount: number): string {
  const icon = KIND_ICON[entry.kind] ?? '·';
  return `<li class="studio-history-item studio-history-item-${side}" data-side="${side}" data-steps="${stepCount}">
    <span class="studio-history-icon" aria-hidden="true">${icon}</span>
    <span class="studio-history-label">${escapeHtml(entry.label)}</span>
    <span class="studio-history-time">${escapeHtml(formatTimeAgo(entry.timestamp))}</span>
  </li>`;
}

function onListClick(e: Event): void {
  const item = (e.target as HTMLElement).closest<HTMLElement>('[data-side]');
  if (!item) return;
  const side = item.dataset.side as 'past' | 'future';
  const steps = Number(item.dataset.steps);
  if (!Number.isFinite(steps) || steps <= 0) return;
  if (side === 'past') jumpBack(steps);
  else jumpForward(steps);
  if (dialogEl?.open) renderList();
}

import { addElement, getDef, uniqueElementId } from './state';

export type SetStatus = (text: string, kind?: 'ok' | 'warn' | 'error') => void;

export interface ImageUploadHost {
  app: HTMLElement;
  setStatus: SetStatus;
}

function loadImageSize(src: string): Promise<{ w: number; h: number } | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve({ w: img.naturalWidth, h: img.naturalHeight });
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

export async function uploadAndInsertImage(file: File, host: ImageUploadHost): Promise<void> {
  const def = getDef();
  if (!def) {
    host.setStatus('먼저 애니메이션을 열거나 만드세요', 'warn');
    return;
  }
  try {
    host.setStatus('이미지 업로드 중…');
    const fd = new FormData();
    fd.append('file', file);
    const res = await fetch('/_editor/api/upload', { method: 'POST', body: fd });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = (await res.json()) as { path: string };
    const cx = def.canvas.width / 2;
    const cy = def.canvas.height / 2;
    const tempImg = await loadImageSize(data.path);
    const maxDim = Math.min(def.canvas.width, def.canvas.height) * 0.5;
    let w = tempImg?.w ?? 200;
    let h = tempImg?.h ?? 200;
    if (w > maxDim || h > maxDim) {
      const s = maxDim / Math.max(w, h);
      w = Math.round(w * s);
      h = Math.round(h * s);
    }
    const id = uniqueElementId('img');
    addElement({
      type: 'image', id, rotation: 0, appearances: [], tracks: [],
      x: Math.round(cx - w / 2), y: Math.round(cy - h / 2),
      width: w, height: h, src: data.path,
      preserveAspectRatio: 'xMidYMid meet', opacity: 1,
    });
    host.setStatus(`업로드 완료: ${data.path}`, 'ok');
  } catch (err) {
    host.setStatus('업로드 실패: ' + (err instanceof Error ? err.message : String(err)), 'error');
  }
}

export function setupImageDropAndPaste(host: ImageUploadHost): void {
  const canvasWrap = host.app.querySelector<HTMLElement>('.studio-canvas-wrap');
  if (canvasWrap) {
    canvasWrap.addEventListener('dragover', (e) => {
      if (!e.dataTransfer) return;
      const hasFiles = Array.from(e.dataTransfer.items ?? []).some((it) => it.kind === 'file');
      if (hasFiles) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        canvasWrap.classList.add('is-drop-target');
      }
    });
    canvasWrap.addEventListener('dragleave', () => canvasWrap.classList.remove('is-drop-target'));
    canvasWrap.addEventListener('drop', (e) => {
      canvasWrap.classList.remove('is-drop-target');
      const file = e.dataTransfer?.files?.[0];
      if (file && file.type.startsWith('image/')) {
        e.preventDefault();
        void uploadAndInsertImage(file, host);
      }
    });
  }
  document.addEventListener('paste', (e) => {
    if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) {
      return;
    }
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.kind === 'file' && item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (file) {
          e.preventDefault();
          void uploadAndInsertImage(file, host);
          return;
        }
      }
    }
  });
}

import { getDef, setSelection } from './state';
import { friendlyElementLabel } from './element-list';

export interface PaletteCommand {
  id: string;
  label: string;
  hint?: string;
  run: () => void;
}

type Entry =
  | { kind: 'element'; id: string; label: string; type: string; rawId: string }
  | { kind: 'command'; id: string; label: string; hint?: string; run: () => void };

let dialogEl: HTMLDialogElement | null = null;
let inputEl: HTMLInputElement | null = null;
let listEl: HTMLUListElement | null = null;
let commands: PaletteCommand[] = [];
let currentEntries: Entry[] = [];
let activeIndex = 0;
function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function registerCommands(cmds: PaletteCommand[]): void {
  commands = cmds;
}

export function initPalette(): void {
  dialogEl = document.getElementById('studio-palette-dialog') as HTMLDialogElement | null;
  inputEl = document.getElementById('studio-palette-input') as HTMLInputElement | null;
  listEl = document.getElementById('studio-palette-list') as HTMLUListElement | null;
  if (!dialogEl || !inputEl || !listEl) return;
  inputEl.addEventListener('input', renderList);
  inputEl.addEventListener('keydown', onKeydown);
  listEl.addEventListener('click', onListClick);
  dialogEl.addEventListener('close', () => {
    if (inputEl) inputEl.value = '';
    activeIndex = 0;
  });
}

export function openPalette(): void {
  if (!dialogEl) return;
  if (typeof dialogEl.showModal === 'function') dialogEl.showModal();
  else dialogEl.setAttribute('open', '');
  activeIndex = 0;
  if (inputEl) {
    inputEl.value = '';
    setTimeout(() => inputEl?.focus(), 0);
  }
  renderList();
}

function gatherEntries(query: string): Entry[] {
  const q = query.trim().toLowerCase();
  const entries: Entry[] = [];
  for (const c of commands) {
    entries.push({ kind: 'command', id: c.id, label: c.label, hint: c.hint, run: c.run });
  }
  const def = getDef();
  if (def) {
    for (const el of def.elements) {
      entries.push({
        kind: 'element',
        id: `el-${el.id}`,
        label: friendlyElementLabel(el),
        type: el.type,
        rawId: el.id,
      });
    }
  }
  if (!q) return entries;
  return entries.filter((e) => {
    const hay = e.kind === 'element'
      ? `${e.label} ${e.type} ${e.rawId}`.toLowerCase()
      : `${e.label} ${e.hint ?? ''}`.toLowerCase();
    return hay.includes(q);
  });
}

function renderList(): void {
  if (!listEl || !inputEl) return;
  currentEntries = gatherEntries(inputEl.value);
  if (activeIndex >= currentEntries.length) activeIndex = Math.max(0, currentEntries.length - 1);
  if (currentEntries.length === 0) {
    listEl.innerHTML = '<li class="studio-palette-empty">결과 없음</li>';
    return;
  }
  listEl.innerHTML = currentEntries.map((e, i) => {
    const isActive = i === activeIndex;
    if (e.kind === 'command') {
      return `<li class="studio-palette-item ${isActive ? 'is-active' : ''}" data-idx="${i}">
        <span class="studio-palette-icon">⚡</span>
        <span class="studio-palette-label">${escapeHtml(e.label)}</span>
        ${e.hint ? `<span class="studio-palette-hint">${escapeHtml(e.hint)}</span>` : ''}
      </li>`;
    }
    return `<li class="studio-palette-item ${isActive ? 'is-active' : ''}" data-idx="${i}">
      <span class="studio-palette-icon">📐</span>
      <span class="studio-palette-label">${escapeHtml(e.label)}</span>
      <span class="studio-palette-hint">${escapeHtml(e.type)} · ${escapeHtml(e.rawId)}</span>
    </li>`;
  }).join('');
}

function activate(entry: Entry): void {
  if (entry.kind === 'command') {
    entry.run();
  } else {
    setSelection({ kind: 'element', elementId: entry.rawId });
  }
  dialogEl?.close();
}

function onKeydown(e: KeyboardEvent): void {
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    activeIndex = Math.min(activeIndex + 1, currentEntries.length - 1);
    renderList();
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    activeIndex = Math.max(activeIndex - 1, 0);
    renderList();
  } else if (e.key === 'Enter') {
    e.preventDefault();
    const entry = currentEntries[activeIndex];
    if (entry) activate(entry);
  }
}

function onListClick(e: Event): void {
  const item = (e.target as HTMLElement).closest<HTMLElement>('[data-idx]');
  if (!item) return;
  const idx = Number(item.dataset.idx);
  const entry = currentEntries[idx];
  if (entry) activate(entry);
}

