}

interface StepLabelProps {
  step: number;
  def: AnimationDef;
}

function StepLabel({ step, def }: StepLabelProps) {
  if (def.chapters.length === 0) return null;
  const label = def.chapters[step]?.label;
  return (
    <div className="anim-wrapper-step">
      {`Chapter ${step + 1} / ${def.chapters.length}`}
      {label ? `, ${label}` : ''}
    </div>
  );
}

function PlayerWrapper({ def }: PlayerProps) {
  const [speed, setSpeed] = useState(1);
  const [playing, setPlaying] = useState(def.settings.autoplay);
  const [step, setStep] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);
  const [restartKey, setRestartKey] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

useEffect(() => {
    if (typeof window === 'undefined') return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);

useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === 'undefined') return;
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) setPlaying(e.isIntersecting && def.settings.autoplay);
      },
      { threshold: 0.1 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [def.settings.autoplay]);

useEffect(() => {
    if (!modalOpen) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setModalOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      document.body.style.overflow = prevOverflow;
      window.removeEventListener('keydown', onKey);
    };
  }, [modalOpen]);

const restart = useCallback(() => {
    setRestartKey((k) => k + 1);
    setStep(0);
  }, []);

const togglePlay = useCallback(() => setPlaying((p) => !p), []);

const handleTimeChange = useCallback(
    (t: number) => {
      const ch = currentChapter(def, t);
      setStep(ch ? ch.index : 0);
    },
    [def],
  );

return (
    <div ref={ref} className="anim-wrapper not-prose">
      <div className="anim-wrapper-header">
        <div className="anim-wrapper-title">
          <span aria-hidden="true">⚡</span>
          <span>{def.title}</span>
        </div>
        <div className="anim-wrapper-actions">
          <ControlsBar
            playing={playing}
            onTogglePlay={togglePlay}
            onRestart={restart}
            speed={speed}
            onSpeedChange={setSpeed}
          />
          <button
            type="button"
            className="anim-wrapper-btn"
            onClick={() => setModalOpen(true)}
            title="확대 보기"
            aria-label="확대 보기"
          >
            ⛶
          </button>
        </div>
      </div>
      <div className="anim-wrapper-body">
        {reducedMotion ? (
          <div className="anim-wrapper-reduced">
            <p>
              <strong>{def.title}</strong>
              {def.description ? `, ${def.description}` : ''}
            </p>
            <p style={{ fontSize: '0.8rem', marginTop: '0.5rem' }}>
              모션 줄이기 설정으로 자동 재생을 멈췄습니다.
            </p>
          </div>
        ) : (
          <AnimationEngine
            key={restartKey}
            def={def}
            speedMultiplier={speed}
            playing={playing}
            onTimeChange={handleTimeChange}
          />
        )}
        {!reducedMotion && <StepLabel step={step} def={def} />}
      </div>
      {modalOpen && !reducedMotion && (
        <AnimationModal
          def={def}
          restartKey={restartKey}
          speed={speed}
          playing={playing}
          step={step}
          onSpeedChange={setSpeed}
          onTogglePlay={togglePlay}
          onRestart={restart}
          onTimeChange={handleTimeChange}
          onClose={() => setModalOpen(false)}
        />
      )}
    </div>
  );
}

interface ModalProps {
  def: AnimationDef;
  restartKey: number;
  speed: number;
  playing: boolean;
  step: number;
  onSpeedChange: (next: number) => void;
  onTogglePlay: () => void;
  onRestart: () => void;
  onTimeChange: (t: number) => void;
  onClose: () => void;
}

function AnimationModal({
  def,
  restartKey,
  speed,
  playing,
  step,
  onSpeedChange,
  onTogglePlay,
  onRestart,
  onTimeChange,
  onClose,
}: ModalProps) {
  return (
    <div
      className="anim-modal-backdrop"
      role="dialog"
      aria-modal="true"
      aria-label={def.title}
      onClick={onClose}
    >
      <div
        className="anim-modal-content"
        onClick={(e: MouseEvent) => e.stopPropagation()}
      >
        <button
          type="button"
          className="anim-modal-close"
          onClick={onClose}
          title="닫기 (Esc)"
          aria-label="닫기"
        >
          ✕
        </button>
        <h3 className="anim-modal-title">{def.title}</h3>
        <div className="anim-modal-controls">
          <ControlsBar
            playing={playing}
            onTogglePlay={onTogglePlay}
            onRestart={onRestart}
            speed={speed}
            onSpeedChange={onSpeedChange}
          />
        </div>
        <AnimationEngine
          key={`modal-${restartKey}`}
          def={def}
          speedMultiplier={speed}
          playing={playing}
          onTimeChange={onTimeChange}
        />
        <StepLabel step={step} def={def} />
      </div>
    </div>
  );
}

import { createRoot, type Root } from 'react-dom/client';
import { createElement } from 'react';
import {
  animationDefSchema,
  type AnimationDef,
} from '@/entities/animation/engine/schema';
import PlayerWrapper from './AnimationPlayer';

const HYDRATED = new WeakSet<HTMLElement>();
const ROOTS = new WeakMap<HTMLElement, Root>();
const CACHE = new Map<string, Promise<AnimationDef | null>>();

async function fetchAnimation(id: string): Promise<AnimationDef | null> {
  if (CACHE.has(id)) return CACHE.get(id)!;
  const p = (async () => {
    try {
      const res = await fetch(`/animations/${id}.json`, {
        cache: import.meta.env.DEV ? 'no-store' : 'force-cache',
      });
      if (!res.ok) return null;
      const json = await res.json();
      const parsed = animationDefSchema.safeParse(json);
      return parsed.success ? parsed.data : null;
    } catch {
      return null;
    }
  })();
  CACHE.set(id, p);
  return p;
}

function fail(el: HTMLElement, msg: string): void {
  el.outerHTML = `<div class="anim-error">${msg}</div>`;
}

async function hydrate(el: HTMLElement): Promise<void> {
  if (HYDRATED.has(el)) return;
  HYDRATED.add(el);
  const id = el.dataset.animId ?? '';
  const def = await fetchAnimation(id);
  if (!def) {
    fail(el, `애니메이션 로드 실패: "${id}" (/animations/${id}.json 없음)`);
    return;
  }
  const root = createRoot(el);
  ROOTS.set(el, root);
  el.classList.remove('anim-placeholder');
  root.render(createElement(PlayerWrapper, { def }));
}

export function hydrateAllAnimations(): void {
  const els = document.querySelectorAll<HTMLElement>('.anim-placeholder');
  if (els.length === 0) return;
  if (typeof IntersectionObserver === 'undefined') {
    els.forEach((el) => void hydrate(el));
    return;
  }
  const io = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          io.unobserve(entry.target);
          void hydrate(entry.target as HTMLElement);
        }
      }
    },
    { rootMargin: '200px 0px' },
  );
  els.forEach((el) => io.observe(el));
}

interface AnimEntry {
  id: string;
  title: string;
  description: string;
  category: string;
  categoryLabel: string;
  tags: string[];
  elements: number;
  chapters: number;
  duration: number;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function norm(s: string): string {
  return s.normalize('NFC').toLowerCase();
}

function renderCard(e: AnimEntry): string {
  const title = escapeHtml(e.title);
  const desc = e.description
    ? `<p class="mb-2 line-clamp-2 text-sm text-fg-muted">${escapeHtml(e.description)}</p>`
    : '';
  const tagsRow =
    e.tags.length > 0
      ? `<div class="mt-2 flex flex-wrap gap-1 text-[11px] text-fg-muted">${e.tags
          .slice(0, 4)
          .map(
            (t) =>
              `<span class="rounded-md border border-border px-1.5 py-0.5">#${escapeHtml(t)}</span>`,
          )
          .join('')}${e.tags.length > 4 ? `<span class="opacity-60">+${e.tags.length - 4}</span>` : ''}</div>`
      : '';
  // Encode each path segment individually to preserve `/` as a path separator
  // in case animation IDs ever gain a directory prefix.
  const idPath = e.id.split('/').map(encodeURIComponent).join('/');
  return `<a href="/animations/${idPath}/" class="anim-card group block rounded-lg border border-border bg-surface-elevated p-4 no-underline transition-colors hover:border-accent">
    <div class="mb-1 flex items-start justify-between gap-2">
      <span class="text-base font-semibold text-fg group-hover:text-accent">${title}</span>
      <span class="shrink-0 text-xs text-fg-muted tabular-nums">${(e.duration / 1000).toFixed(1)}s</span>
    </div>
    ${desc}
    <div class="mt-1 flex flex-wrap items-center gap-2 text-xs text-fg-muted">
      <span class="rounded-md border border-border px-1.5 py-0.5 text-[10px]">${escapeHtml(e.categoryLabel)}</span>
      <span class="font-mono opacity-70">${escapeHtml(e.id)}</span>
    </div>
    <div class="mt-1 flex flex-wrap items-center gap-2 text-[11px] text-fg-muted">
      <span>${e.elements} elements</span>
      <span>·</span>
      <span>${e.chapters} chapters</span>
    </div>
    ${tagsRow}
  </a>`;
}

export function setupAnimFilter(): void {
  const filterUi = document.querySelector<HTMLElement>('[data-anim-filter-ui]');
  if (!filterUi || filterUi.dataset.animFilterReady === '1') return;

const dataEl = document.getElementById('anim-index-data');
  const searchInput = document.querySelector<HTMLInputElement>('[data-anim-search]');
  const defaultList = document.querySelector<HTMLElement>('[data-anim-default-list]');
  const paginationWrap = document.querySelector<HTMLElement>('[data-anim-pagination-wrap]');
  const filteredView = document.querySelector<HTMLElement>('[data-anim-filtered]');
  const filteredCount = document.querySelector<HTMLElement>('[data-anim-filtered-count]');
  const filteredList = document.querySelector<HTMLElement>('[data-anim-filtered-list]');
  const filteredEmpty = document.querySelector<HTMLElement>('[data-anim-filtered-empty]');
  const catButtons = Array.from(
    document.querySelectorAll<HTMLButtonElement>('[data-anim-category]'),
  );
  const tagButtons = Array.from(
    document.querySelectorAll<HTMLButtonElement>('[data-anim-tag]'),
  );
  const tagLabel = document.querySelector<HTMLElement>('[data-anim-active-tag-label]');
  const tagPanel = document.querySelector<HTMLDetailsElement>('[data-anim-tag-panel]');

if (
    !dataEl ||
    !searchInput ||
    !filteredView ||
    !filteredCount ||
    !filteredList ||
    !filteredEmpty
  ) {
    return;
  }

let allEntries: AnimEntry[] = [];
  try {
    allEntries = JSON.parse(dataEl.textContent ?? '[]') as AnimEntry[];
  } catch {
    return;
  }

filterUi.dataset.animFilterReady = '1';

const params = new URLSearchParams(window.location.search);
  let query = params.get('search') ?? '';
  let activeCategory = params.get('category') ?? '';
  let activeTag = params.get('tag') ?? '';

if (query) searchInput.value = query;
  if (activeTag && tagPanel) tagPanel.open = true;

function syncUrl(): void {
    const url = new URL(window.location.href);
    if (query) url.searchParams.set('search', query);
    else url.searchParams.delete('search');
    if (activeCategory) url.searchParams.set('category', activeCategory);
    else url.searchParams.delete('category');
    if (activeTag) url.searchParams.set('tag', activeTag);
    else url.searchParams.delete('tag');
    window.history.replaceState({}, '', url.toString());
  }

function setFilterState(active: boolean): void {
    if (defaultList) defaultList.hidden = active;
    if (paginationWrap) paginationWrap.hidden = active;
    filteredView!.hidden = !active;
  }

function render(): void {
    const hasFilter =
      query.trim().length > 0 || activeCategory.length > 0 || activeTag.length > 0;

for (const btn of catButtons) {
      const v = btn.dataset.animCategory ?? '';
      btn.setAttribute('aria-pressed', v === activeCategory ? 'true' : 'false');
    }
    for (const btn of tagButtons) {
      btn.setAttribute(
        'aria-pressed',
        btn.dataset.animTag === activeTag && activeTag.length > 0 ? 'true' : 'false',
      );
    }

if (tagLabel) {
      if (activeTag) {
        tagLabel.textContent = `· #${activeTag}`;
        tagLabel.classList.remove('hidden');
      } else {
        tagLabel.textContent = '';
        tagLabel.classList.add('hidden');
      }
    }

syncUrl();

if (!hasFilter) {
      setFilterState(false);
      filteredList!.innerHTML = '';
      return;
    }

const q = norm(query.trim());
    const filtered = allEntries.filter((e) => {
      if (activeCategory && e.category !== activeCategory) return false;
      if (activeTag && !e.tags.includes(activeTag)) return false;
      if (q) {
        const haystack = norm(
          `${e.title} ${e.description} ${e.id} ${e.tags.join(' ')} ${e.categoryLabel}`,
        );
        return haystack.includes(q);
      }
      return true;
    });

setFilterState(true);

if (filtered.length === 0) {
      filteredList!.innerHTML = '';
      filteredCount!.textContent = `검색 결과 없음 · 전체 ${allEntries.length}개`;
      filteredEmpty!.classList.remove('hidden');
      return;
    }

filteredEmpty!.classList.add('hidden');
    filteredCount!.textContent = `검색 결과 ${filtered.length}개 · 전체 ${allEntries.length}개`;
    filteredList!.innerHTML = filtered.map(renderCard).join('');
  }

let debounceId: ReturnType<typeof setTimeout> | null = null;
  searchInput.addEventListener('input', () => {
    if (debounceId !== null) clearTimeout(debounceId);
    debounceId = setTimeout(() => {
      query = searchInput.value;
      render();
    }, 80);
  });

searchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && searchInput.value) {
      e.preventDefault();
      searchInput.value = '';
      query = '';
      render();
    }
  });

for (const btn of catButtons) {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.animCategory ?? '';
      activeCategory = activeCategory === cat ? '' : cat;
      render();
    });
  }

for (const btn of tagButtons) {
    btn.addEventListener('click', () => {
      const tag = btn.dataset.animTag ?? '';
      activeTag = activeTag === tag ? '' : tag;
      render();
    });
  }

render();
}

