export const CATEGORY_LABELS: Record<string, string> = {
  network: '🌐 네트워크',
  cache: '⚡ 캐시',
  algorithm: '🔢 알고리즘',
  architecture: '🏛 아키텍처',
  flow: '🔀 흐름',
  protocol: '📡 프로토콜',
  general: '🎬 일반',
};

export const CATEGORY_ORDER = [
  'algorithm',
  'architecture',
  'flow',
  'protocol',
  'network',
  'cache',
  'general',
];

export function catRank(c: string): number {
  const i = CATEGORY_ORDER.indexOf(c);
  return i === -1 ? CATEGORY_ORDER.length : i;
}

export function categoryLabel(category: string | undefined): string {
  const c = category ?? 'general';
  return CATEGORY_LABELS[c] ?? `🎬 ${c}`;
}

interface StoredProgress {
  completed: number[];
  startedAt: number;
  completedAt?: number;
}

declare global {
  interface Window {
    __courseProgressBound?: string;
  }
}

function storageKey(courseId: string): string {
  return `course-progress:${courseId}`;
}

function load(courseId: string): StoredProgress {
  try {
    const raw = localStorage.getItem(storageKey(courseId));
    if (!raw) return { completed: [], startedAt: Date.now() };
    const parsed = JSON.parse(raw) as StoredProgress;
    if (!Array.isArray(parsed.completed)) parsed.completed = [];
    return parsed;
  } catch {
    return { completed: [], startedAt: Date.now() };
  }
}

function save(courseId: string, state: StoredProgress): void {
  try {
    localStorage.setItem(storageKey(courseId), JSON.stringify(state));
  } catch {
    // localStorage disabled
  }
}

function setupWithCourseId(courseId: string, root: HTMLElement): void {
  const chapters = Array.from(
    root.querySelectorAll<HTMLElement>('[data-course-chapter-index]'),
  );
  if (chapters.length === 0) return;
  const total = chapters.length;
  const wrap = root.querySelector<HTMLElement>('[data-course-progress-wrap]');
  const label = root.querySelector<HTMLElement>('[data-course-progress-label]');
  const percentEl = root.querySelector<HTMLElement>('[data-course-progress-percent]');
  const fill = root.querySelector<HTMLElement>('[data-course-progress-fill]');
  const bar = root.querySelector<HTMLElement>('[role="progressbar"]');
  const celebrate = root.querySelector<HTMLElement>('[data-course-celebrate]');

if (wrap) wrap.hidden = false;

const state = load(courseId);
  const completedSet = new Set<number>(state.completed);

function render(): void {
    for (const el of chapters) {
      const idx = Number(el.dataset.courseChapterIndex);
      const done = completedSet.has(idx);
      el.classList.toggle('is-completed', done);
      const checkbox = el.querySelector<HTMLInputElement>('[data-course-chapter-checkbox]');
      if (checkbox) checkbox.checked = done;
    }
    const count = completedSet.size;
    if (label) label.textContent = `${count}/${total} 완료`;
    const percent = Math.round((count / total) * 100);
    if (percentEl) percentEl.textContent = `${percent}%`;
    if (fill) fill.style.width = `${percent}%`;
    if (bar) bar.setAttribute('aria-valuenow', String(count));
    if (celebrate) celebrate.hidden = count < total;
  }

render();

for (const el of chapters) {
    const checkbox = el.querySelector<HTMLInputElement>('[data-course-chapter-checkbox]');
    if (!checkbox) continue;
    checkbox.addEventListener('change', () => {
      const idx = Number(el.dataset.courseChapterIndex);
      if (checkbox.checked) {
        completedSet.add(idx);
        if (!state.completedAt && completedSet.size === total) {
          state.completedAt = Date.now();
        }
      } else {
        completedSet.delete(idx);
        if (completedSet.size < total) state.completedAt = undefined;
      }
      state.completed = Array.from(completedSet).sort((a, b) => a - b);
      save(courseId, state);
      render();
    });
  }
}

function setupBadgeAutoComplete(): void {
  const badges = document.querySelectorAll<HTMLAnchorElement>('[data-course-badge]');
  if (badges.length === 0) return;
  for (const badge of badges) {
    const courseId = badge.dataset.courseBadge;
    const idxStr = badge.dataset.courseChapterIndex;
    if (!courseId || idxStr === undefined) continue;
    const idx = Number(idxStr);
    if (Number.isNaN(idx)) continue;
    const total = Number(badge.dataset.courseChapterTotal ?? 0);
    if (total <= 0) continue;
    const state = load(courseId);
    if (state.completed.includes(idx)) continue;
    state.completed = [...new Set([...state.completed, idx])].sort((a, b) => a - b);
    if (!state.completedAt && state.completed.length === total) {
      state.completedAt = Date.now();
    }
    save(courseId, state);
  }
}

export function setupCourseProgress(): void {
  const detailRoot = document.querySelector<HTMLElement>('[data-course-id]');
  if (detailRoot) {
    const courseId = detailRoot.dataset.courseId;
    if (courseId && window.__courseProgressBound !== courseId) {
      window.__courseProgressBound = courseId;
      setupWithCourseId(courseId, detailRoot);
    }
  }
  setupBadgeAutoComplete();
}

import { getPublishedWiki } from '@/shared/lib/content/content-queries';
import {
  canonicalId,
  getContentGraph,
  type Collection,
} from '@/shared/lib/content/content-graph';
import { previewOf } from '@/shared/lib/content/wikilink-preview';

const SUMMARY_MAX = 100;

export interface GlossaryTerm {
  id: string;
  slug: string;
  title: string;
  url: string;
  summary: string;
  category?: string;
}

export interface GlossaryEntry extends GlossaryTerm {
  aliases: string[];
  backlinksCount: number;
  firstChar: string;
}

let outboundCache: Promise<Map<string, GlossaryTerm[]>> | null = null;
let fullIndexCache: Promise<GlossaryEntry[]> | null = null;

async function buildWikiTermMap(): Promise<Map<string, GlossaryTerm>> {
  const wiki = await getPublishedWiki();
  const map = new Map<string, GlossaryTerm>();
  for (const w of wiki) {
    const body = (w as { body?: string }).body ?? '';
    const id = canonicalId('wiki', w.id);
    let category: string | undefined = w.data.category;
    if (!category) {
      const parts = w.id.split('/');
      if (parts.length >= 2) category = parts[0];
    }
    map.set(id, {
      id,
      slug: w.id,
      title: w.data.title,
      url: `/wiki/${w.id}/`,
      summary: previewOf(body, SUMMARY_MAX),
      category,
    });
  }
  return map;
}

async function buildOutboundIndex(): Promise<Map<string, GlossaryTerm[]>> {
  const [graph, terms] = await Promise.all([getContentGraph(), buildWikiTermMap()]);

const out = new Map<string, GlossaryTerm[]>();
  const seenPerSource = new Map<string, Set<string>>();

for (const link of graph.links) {
    if (link.kind !== 'wikilink') continue;
    const src = String(link.source);
    const tgt = String(link.target);
    if (!tgt.startsWith('wiki:')) continue;

const term = terms.get(tgt);
    if (!term) continue;

let seen = seenPerSource.get(src);
    if (!seen) {
      seen = new Set();
      seenPerSource.set(src, seen);
    }
    if (seen.has(tgt)) continue;
    seen.add(tgt);

let list = out.get(src);
    if (!list) {
      list = [];
      out.set(src, list);
    }
    list.push(term);
  }

for (const list of out.values()) {
    list.sort((a, b) => a.title.localeCompare(b.title, 'ko'));
  }

return out;
}

export function getOutboundGlossary(): Promise<Map<string, GlossaryTerm[]>> {
  if (!outboundCache) outboundCache = buildOutboundIndex();
  return outboundCache;
}

export async function getGlossaryFor(
  collection: Collection,
  slug: string,
): Promise<GlossaryTerm[]> {
  const idx = await getOutboundGlossary();
  return idx.get(canonicalId(collection, slug)) ?? [];
}

function firstCharOf(title: string): string {
  const ch = title.trim().charAt(0);
  if (!ch) return '#';
  const code = ch.charCodeAt(0);
  if (code >= 0xac00 && code <= 0xd7a3) {
    const HANGUL_INITIALS = [
      '\u3131', '\u3132', '\u3134', '\u3137', '\u3138', '\u3139',
      '\u3141', '\u3142', '\u3143', '\u3145', '\u3146', '\u3147',
      '\u3148', '\u3149', '\u314a', '\u314b', '\u314c', '\u314d', '\u314e',
    ];
    const idx = Math.floor((code - 0xac00) / 588);
    return HANGUL_INITIALS[idx];
  }
  const upper = ch.toUpperCase();
  if (/[A-Z]/.test(upper)) return upper;
  return '#';
}

async function buildFullIndex(): Promise<GlossaryEntry[]> {
  const [graph, wiki] = await Promise.all([getContentGraph(), getPublishedWiki()]);
  const out: GlossaryEntry[] = [];
  for (const w of wiki) {
    const body = (w as { body?: string }).body ?? '';
    const id = canonicalId('wiki', w.id);
    let category: string | undefined = w.data.category;
    if (!category) {
      const parts = w.id.split('/');
      if (parts.length >= 2) category = parts[0];
    }
    const backlinks = graph.backlinks.get(id) ?? [];
    out.push({
      id,
      slug: w.id,
      title: w.data.title,
      url: `/wiki/${w.id}/`,
      summary: previewOf(body, SUMMARY_MAX),
      category,
      aliases: w.data.aliases ?? [],
      backlinksCount: backlinks.length,
      firstChar: firstCharOf(w.data.title),
    });
  }
  out.sort((a, b) => a.title.localeCompare(b.title, 'ko'));
  return out;
}

export function getFullGlossary(): Promise<GlossaryEntry[]> {
  if (!fullIndexCache) fullIndexCache = buildFullIndex();
  return fullIndexCache;
}

function norm(s: string): string {
  return s.normalize('NFC').toLowerCase().trim();
}

function itemMatches(item: HTMLElement, query: string): boolean {
  if (!query) return true;
  const title = item.dataset.title ?? '';
  const aliases = item.dataset.aliases ?? '';
  const summary = item.dataset.summary ?? '';
  const category = item.dataset.category ?? '';
  return (
    title.includes(query) ||
    aliases.includes(query) ||
    summary.includes(query) ||
    category.includes(query)
  );
}

function activePanel(root: HTMLElement): HTMLElement | null {
  return root.querySelector<HTMLElement>('[data-glossary-view-panel]:not([hidden])');
}

function updateCount(root: HTMLElement, total: number, visible: number): void {
  const el = root.querySelector<HTMLElement>('[data-glossary-count]');
  if (el) {
    el.textContent = visible === total ? `총 ${total}개의 용어` : `${visible} / ${total}개 표시 중`;
  }
  const empty = root.querySelector<HTMLElement>('[data-glossary-empty]');
  if (empty) empty.hidden = visible > 0;
}

function applyFilter(root: HTMLElement, rawQuery: string): void {
  const query = norm(rawQuery);
  const panel = activePanel(root);
  if (!panel) return;

const items = Array.from(panel.querySelectorAll<HTMLElement>('.glossary-item'));
  let visible = 0;
  for (const item of items) {
    const shown = itemMatches(item, query);
    item.hidden = !shown;
    if (shown) visible++;
  }

for (const section of panel.querySelectorAll<HTMLElement>('.glossary-section')) {
    const hasVisible = Array.from(section.querySelectorAll<HTMLElement>('.glossary-item')).some(
      (i) => !i.hidden,
    );
    section.hidden = !hasVisible;
  }

for (const d of panel.querySelectorAll<HTMLDetailsElement>('.glossary-category')) {
    const hasVisible = Array.from(d.querySelectorAll<HTMLElement>('.glossary-item')).some(
      (i) => !i.hidden,
    );
    d.hidden = !hasVisible;
    if (hasVisible && query) d.open = true;
  }

updateCount(root, items.length, visible);
}

function switchView(root: HTMLElement, view: 'alpha' | 'category', query: string): void {
  const panels = root.querySelectorAll<HTMLElement>('[data-glossary-view-panel]');
  for (const p of panels) {
    p.hidden = p.dataset.glossaryViewPanel !== view;
  }
  const btns = root.querySelectorAll<HTMLButtonElement>('[data-glossary-view]');
  for (const b of btns) {
    b.setAttribute('aria-selected', b.dataset.glossaryView === view ? 'true' : 'false');
  }
  const nav = root.querySelector<HTMLElement>('[data-glossary-nav]');
  if (nav) nav.hidden = view !== 'alpha';
  applyFilter(root, query);
}

export function setupGlossary(): void {
  const root = document.querySelector<HTMLElement>('[data-glossary]');
  if (!root || root.dataset.glossaryReady === '1') return;
  root.dataset.glossaryReady = '1';

let currentQuery = '';
  const input = root.querySelector<HTMLInputElement>('[data-glossary-search]');
  if (input) {
    input.addEventListener('input', () => {
      currentQuery = input.value;
      applyFilter(root, currentQuery);
    });
    const params = new URLSearchParams(window.location.search);
    const initial = params.get('q');
    if (initial) {
      input.value = initial;
      currentQuery = initial;
    }
  }

applyFilter(root, currentQuery);

const toggle = root.querySelector<HTMLElement>('.glossary-view-toggle');
  if (toggle) {
    toggle.addEventListener('click', (e) => {
      const t = e.target;
      if (!(t instanceof HTMLElement)) return;
      const btn = t.closest<HTMLButtonElement>('[data-glossary-view]');
      if (!btn) return;
      const view = btn.dataset.glossaryView === 'category' ? 'category' : 'alpha';
      switchView(root, view, currentQuery);
    });
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { exportPng, exportSvg } from './mermaid-export';

function makeSvg(withBbox = true): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg') as SVGSVGElement;
  if (withBbox) {
    (svg as unknown as { getBBox: () => { width: number; height: number } }).getBBox = () => ({
      width: 400,
      height: 300,
    });
  } else {
    (svg as unknown as { getBBox?: () => unknown }).getBBox = undefined;
  }
  return svg;
}

describe('exportSvg', () => {
  let createObjectURL: ReturnType<typeof vi.fn>;
  let revokeObjectURL: ReturnType<typeof vi.fn>;
  let clickSpy: ReturnType<typeof vi.fn>;

beforeEach(() => {
    createObjectURL = vi.fn(() => 'blob:mock');
    revokeObjectURL = vi.fn();
    vi.stubGlobal('URL', {
      createObjectURL,
      revokeObjectURL,
    });
    clickSpy = vi.fn();
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(clickSpy as unknown as () => void);
  });

afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

it('serializes the SVG and triggers a download', () => {
    exportSvg(makeSvg());
    expect(createObjectURL).toHaveBeenCalledTimes(1);
    expect(clickSpy).toHaveBeenCalledTimes(1);
    expect(revokeObjectURL).toHaveBeenCalledWith('blob:mock');
  });

it('names the file with mermaid- prefix and svg suffix', () => {
    exportSvg(makeSvg());
    const blobArg = createObjectURL.mock.calls[0][0];
    expect(blobArg).toBeInstanceOf(Blob);
  });
});

describe('exportPng', () => {
  let createObjectURL: ReturnType<typeof vi.fn>;
  let revokeObjectURL: ReturnType<typeof vi.fn>;

beforeEach(() => {
    createObjectURL = vi.fn(() => 'blob:mock');
    revokeObjectURL = vi.fn();
    vi.stubGlobal('URL', {
      createObjectURL,
      revokeObjectURL,
    });
  });

afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

it('creates an object URL for the source SVG', () => {
    exportPng(makeSvg());
    expect(createObjectURL).toHaveBeenCalledTimes(1);
  });

it('handles svg without getBBox by falling back to default dimensions', () => {
    expect(() => exportPng(makeSvg(false))).not.toThrow();
  });

it('renders canvas and triggers download on image load', () => {
    const drawImage = vi.fn();
    const fillRect = vi.fn();
    const toBlob = vi.fn();
    const canvas = {
      width: 0,
      height: 0,
      getContext: () => ({
        fillStyle: '',
        fillRect,
        drawImage,
      }),
      toBlob,
    };
    vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
      if (tag === 'canvas') return canvas as unknown as HTMLCanvasElement;
      return document.createElementNS('http://www.w3.org/1999/xhtml', tag) as HTMLElement;
    });
    const captured: { onload?: () => void } = {};
    class FakeImage {
      set onload(fn: () => void) {
        captured.onload = fn;
      }
      set src(_v: string) {
        void _v;
      }
      set onerror(_v: () => void) {
        void _v;
      }
    }
    vi.stubGlobal('Image', FakeImage);
    exportPng(makeSvg());
    captured.onload?.();
    expect(fillRect).toHaveBeenCalled();
    expect(drawImage).toHaveBeenCalled();
    expect(toBlob).toHaveBeenCalled();
  });

it('respects dark mode fill style when documentElement has dark class', () => {
    document.documentElement.classList.add('dark');
    const drawImage = vi.fn();
    const fillRect = vi.fn();
    let capturedFillStyle = '';
    const canvas = {
      width: 0,
      height: 0,
      getContext: () => {
        const ctx = {
          fillRect,
          drawImage,
          set fillStyle(v: string) {
            capturedFillStyle = v;
          },
        };
        return ctx;
      },
      toBlob: vi.fn(),
    };
    vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
      if (tag === 'canvas') return canvas as unknown as HTMLCanvasElement;
      return document.createElementNS('http://www.w3.org/1999/xhtml', tag) as HTMLElement;
    });
    const captured: { onload?: () => void } = {};
    class FakeImage {
      set onload(fn: () => void) {
        captured.onload = fn;
      }
      set src(_v: string) {
        void _v;
      }
      set onerror(_v: () => void) {
        void _v;
      }
    }
    vi.stubGlobal('Image', FakeImage);
    exportPng(makeSvg());
    captured.onload?.();
    expect(capturedFillStyle).toBe('#0b0b0f');
    document.documentElement.classList.remove('dark');
  });

it('bails out gracefully when canvas 2d context is unavailable', () => {
    const canvas = {
      width: 0,
      height: 0,
      getContext: () => null,
      toBlob: vi.fn(),
    };
    vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
      if (tag === 'canvas') return canvas as unknown as HTMLCanvasElement;
      return document.createElementNS('http://www.w3.org/1999/xhtml', tag) as HTMLElement;
    });
    const captured: { onload?: () => void } = {};
    class FakeImage {
      set onload(fn: () => void) {
        captured.onload = fn;
      }
      set src(_v: string) {
        void _v;
      }
      set onerror(_v: () => void) {
        void _v;
      }
    }
    vi.stubGlobal('Image', FakeImage);
    exportPng(makeSvg());
    captured.onload?.();
    expect(canvas.toBlob).not.toHaveBeenCalled();
  });

it('revokes URL when image loading errors', () => {
    const captured: { onerror?: () => void } = {};
    class FakeImage {
      set onload(_v: () => void) {
        void _v;
      }
      set onerror(fn: () => void) {
        captured.onerror = fn;
      }
      set src(_v: string) {
        void _v;
      }
    }
    vi.stubGlobal('Image', FakeImage);
    exportPng(makeSvg());
    captured.onerror?.();
    expect(revokeObjectURL).toHaveBeenCalled();
  });
});

function downloadBlob(name: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: name });
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

export function exportSvg(svg: SVGSVGElement): void {
  const xml = new XMLSerializer().serializeToString(svg);
  downloadBlob(
    `mermaid-${Date.now()}.svg`,
    new Blob(['<?xml version="1.0" encoding="UTF-8"?>\n', xml], { type: 'image/svg+xml' }),
  );
}

export function exportPng(svg: SVGSVGElement): void {
  const xml = new XMLSerializer().serializeToString(svg);
  const bbox = svg.getBBox ? svg.getBBox() : { width: 1024, height: 768 };
  const w = Math.max(320, Math.ceil(bbox.width)) * 2;
  const h = Math.max(240, Math.ceil(bbox.height)) * 2;
  const blob = new Blob([xml], { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const img = new Image();
  img.onload = () => {
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.fillStyle = document.documentElement.classList.contains('dark') ? '#0b0b0f' : '#ffffff';
    ctx.fillRect(0, 0, w, h);
    ctx.drawImage(img, 0, 0, w, h);
    canvas.toBlob((b) => {
      if (b) downloadBlob(`mermaid-${Date.now()}.png`, b);
      URL.revokeObjectURL(url);
    }, 'image/png');
  };
  img.onerror = () => URL.revokeObjectURL(url);
  img.src = url;
}

interface MermaidApi {
  initialize: (opts: object) => void;
  run: (opts: { nodes: Element[] }) => Promise<void>;
}

let mermaidPromise: Promise<MermaidApi> | null = null;

function loadMermaid(): Promise<MermaidApi> {
  if (!mermaidPromise) {
    const cdnUrl = 'https://cdn.jsdelivr.net/npm/mermaid@11.6.0/dist/mermaid.esm.min.mjs';
    mermaidPromise = import(/* @vite-ignore */ cdnUrl).then(
      (m: { default: MermaidApi }) => m.default,
    );
  }
  return mermaidPromise;
}

function renderInlineError(el: HTMLElement, source: string, err: unknown): void {
  const msg = err instanceof Error ? err.message : String(err);
  el.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.className = 'mermaid-error';
  wrap.setAttribute('role', 'alert');
  const heading = document.createElement('p');
  heading.className = 'mermaid-error-heading';
  heading.textContent = '다이어그램 렌더 실패';
  const detail = document.createElement('pre');
  detail.className = 'mermaid-error-detail';
  detail.textContent = msg;
  const sourceBlock = document.createElement('pre');
  sourceBlock.className = 'mermaid-error-source';
  sourceBlock.textContent = source;
  wrap.append(heading, detail, sourceBlock);
  el.append(wrap);
}

let renderToken = 0;
let initialized = false;

function snapshotSources(): void {
  document.querySelectorAll<HTMLElement>('.mermaid[data-mermaid-source]').forEach((el) => {
    if (!el.hasAttribute('data-mermaid-original')) {
      el.setAttribute('data-mermaid-original', el.textContent || '');
    }
  });
}

export async function renderNodes(
  nodes: HTMLElement[],
  onRendered: () => void,
): Promise<void> {
  if (!nodes || nodes.length === 0) return;
  const token = ++renderToken;
  const mermaid = await loadMermaid();
  if (token !== renderToken) return;

if (!initialized) {
    const isDark = document.documentElement.classList.contains('dark');
    mermaid.initialize({
      startOnLoad: false,
      theme: isDark ? 'dark' : 'default',
      securityLevel: 'strict',
      fontFamily:
        'ui-sans-serif,system-ui,-apple-system,"Apple SD Gothic Neo","Noto Sans KR",sans-serif',
    });
    initialized = true;
  }

for (const el of nodes) {
    const source = el.getAttribute('data-mermaid-original') || el.textContent || '';
    el.setAttribute('data-mermaid-original', source);
    el.removeAttribute('data-processed');
    el.textContent = source;
    el.classList.add('is-loading');
  }

for (const el of nodes) {
    const source = el.getAttribute('data-mermaid-original') || el.textContent || '';
    try {
      await mermaid.run({ nodes: [el] });
      el.setAttribute('data-mermaid-rendered', '1');
      el.classList.remove('is-loading');
    } catch (err) {
      console.error('[mermaid] render failed:', err);
      el.classList.remove('is-loading');
      el.setAttribute('data-mermaid-rendered', 'error');
      renderInlineError(el, source, err);
    }
  }
  onRendered();
}

let viewportObserver: IntersectionObserver | null = null;

export function setupLazyMermaid(onRendered: () => void): void {
  const all = Array.from(
    document.querySelectorAll<HTMLElement>('.mermaid[data-mermaid-source]'),
  );
  if (all.length === 0) return;
  snapshotSources();

if (viewportObserver) viewportObserver.disconnect();
  viewportObserver = new IntersectionObserver(
    (entries) => {
      const candidates: HTMLElement[] = [];
      for (const entry of entries) {
        if (entry.isIntersecting) {
          const el = entry.target as HTMLElement;
          viewportObserver!.unobserve(el);
          if (!el.hasAttribute('data-mermaid-rendered')) candidates.push(el);
        }
      }
      if (candidates.length > 0) void renderNodes(candidates, onRendered);
    },
    { rootMargin: '300px 0px' },
  );
  for (const el of all) {
    if (!el.hasAttribute('data-mermaid-rendered')) viewportObserver.observe(el);
  }
}

export async function reRenderForTheme(onRendered: () => void): Promise<void> {
  const all = Array.from(
    document.querySelectorAll<HTMLElement>('.mermaid[data-mermaid-source]'),
  );
  if (all.length === 0) return;
  const rendered = all.filter((el) => el.hasAttribute('data-mermaid-rendered'));
  if (rendered.length > 0) {
    initialized = false;
    for (const el of rendered) el.removeAttribute('data-mermaid-rendered');
    await renderNodes(rendered, onRendered);
  }
}

import { exportPng, exportSvg } from './mermaid-export';

const dialog = (): HTMLDialogElement | null =>
  document.getElementById('mermaid-zoom') as HTMLDialogElement | null;
const viewport = (): HTMLElement | null =>
  dialog()?.querySelector<HTMLElement>('.mermaid-zoom-viewport') ?? null;
const content = (): HTMLElement | null =>
  dialog()?.querySelector<HTMLElement>('.mermaid-zoom-content') ?? null;

let zoomScale = 1;
let panX = 0;
let panY = 0;

function applyTransform(): void {
  const c = content();
  if (!c) return;
  c.style.transform = `translate(${panX}px, ${panY}px) scale(${zoomScale})`;
}

function resetTransform(): void {
  zoomScale = 1;
  panX = 0;
  panY = 0;
  applyTransform();
}

function openZoom(sourceEl: HTMLElement): void {
  const d = dialog();
  const c = content();
  const svg = sourceEl.querySelector('svg');
  if (!d || !c || !svg) return;
  c.innerHTML = '';
  const clone = svg.cloneNode(true) as SVGSVGElement;
  clone.removeAttribute('width');
  clone.removeAttribute('height');
  c.appendChild(clone);
  resetTransform();
  if (typeof d.showModal === 'function') d.showModal();
  else d.setAttribute('open', '');
}

function closeZoom(): void {
  const d = dialog();
  const c = content();
  if (!d) return;
  if (typeof d.close === 'function') d.close();
  else d.removeAttribute('open');
  if (c) c.innerHTML = '';
}

function getZoomSvg(): SVGSVGElement | null {
  return content()?.querySelector('svg') ?? null;
}

export function attachZoomHandlers(): void {
  document.querySelectorAll<HTMLElement>('.mermaid[data-mermaid-source]').forEach((el) => {
    if (el.dataset.zoomBound === '1') return;
    el.dataset.zoomBound = '1';
    el.addEventListener('click', (e) => {
      e.preventDefault();
      openZoom(el);
    });
  });
}

export function bindZoomDialogListeners(): void {
  document.addEventListener('click', (e) => {
    const target = e.target as HTMLElement;
    if (target.closest('[data-zoom-export-svg]')) {
      const svg = getZoomSvg();
      if (svg) exportSvg(svg);
      return;
    }
    if (target.closest('[data-zoom-export-png]')) {
      const svg = getZoomSvg();
      if (svg) exportPng(svg);
      return;
    }
    if (target.closest('[data-zoom-close]')) {
      closeZoom();
      return;
    }
    const d = dialog();
    if (d && d.open && target === d) closeZoom();
  });

document.addEventListener('keydown', (e) => {
    const d = dialog();
    if (!d || !d.open) return;
    if (e.key === '+' || e.key === '=') {
      e.preventDefault();
      zoomScale = Math.min(zoomScale * 1.2, 6);
      applyTransform();
    } else if (e.key === '-') {
      e.preventDefault();
      zoomScale = Math.max(zoomScale / 1.2, 0.3);
      applyTransform();
    } else if (e.key === '0') {
      e.preventDefault();
      resetTransform();
    }
  });

document.addEventListener(
    'wheel',
    (e) => {
      const v = viewport();
      const d = dialog();
      if (!v || !d || !d.open) return;
      const target = e.target as Node;
      if (!v.contains(target) && target !== v) return;
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
      zoomScale = Math.max(0.3, Math.min(6, zoomScale * factor));
      applyTransform();
    },
    { passive: false },
  );

let dragging = false;
  let startX = 0;
  let startY = 0;
  let startPanX = 0;
  let startPanY = 0;
  document.addEventListener('mousedown', (e) => {
    const v = viewport();
    const d = dialog();
    if (!v || !d || !d.open || !v.contains(e.target as Node)) return;
    dragging = true;
    startX = e.clientX;
    startY = e.clientY;
    startPanX = panX;
    startPanY = panY;
  });
  document.addEventListener('mousemove', (e) => {
    if (!dragging) return;
    panX = startPanX + (e.clientX - startX);
    panY = startPanY + (e.clientY - startY);
    applyTransform();
  });
  document.addEventListener('mouseup', () => {
    dragging = false;
  });
}

import { reRenderForTheme, setupLazyMermaid } from './mermaid-render';
import { attachZoomHandlers, bindZoomDialogListeners } from './mermaid-zoom';

declare global {
  interface Window {
    __mermaidBound?: boolean;
  }
}

export function setupMermaid(): void {
  if (window.__mermaidBound) return;
  window.__mermaidBound = true;

bindZoomDialogListeners();
  setupLazyMermaid(attachZoomHandlers);

new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.attributeName === 'class') {
        void reRenderForTheme(attachZoomHandlers);
        return;
      }
    }
  }).observe(document.documentElement, { attributes: true });

document.addEventListener('astro:after-swap', () => {
    setupLazyMermaid(attachZoomHandlers);
  });
  document.addEventListener('preview-updated', () => {
    setupLazyMermaid(attachZoomHandlers);
  });
}

