import {
  SITE_AUTHOR,
  SITE_DESCRIPTION,
  SITE_KEYWORDS,
  SITE_LOCALE,
  SITE_SOCIAL,
  SITE_TITLE,
  SITE_URL,
} from '@/shared/config';

type SchemaObject = Record<string, unknown>;

export function personSchema(): SchemaObject {
  return {
    '@context': 'https://schema.org',
    '@type': 'Person',
    '@id': `${SITE_URL}/#person`,
    name: SITE_AUTHOR,
    alternateName: 'shinkeonkim',
    url: SITE_URL,
    image: `${SITE_URL}/apple-touch-icon.png`,
    sameAs: SITE_SOCIAL,
    knowsAbout: SITE_KEYWORDS,
  };
}

// SearchAction is intentionally omitted. The site has no server-side `?q=`
// endpoint (the Pagefind modal opens client-side, invisible to crawlers),
// and Google's sitelinks search box guidance now treats the schema as a
// no-op for most blogs. Keeping it caused GSC to report
// `/?q={search_term_string}` under "Page with redirect".
export function websiteSchema(): SchemaObject {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    '@id': `${SITE_URL}/#website`,
    name: SITE_TITLE,
    alternateName: 'shinkeonkim',
    url: SITE_URL,
    inLanguage: SITE_LOCALE,
    description: SITE_DESCRIPTION,
    publisher: { '@id': `${SITE_URL}/#person` },
  };
}

export interface BreadcrumbItem {
  name: string;
  url: string;
}

export function breadcrumbSchema(items: BreadcrumbItem[]): SchemaObject {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: item.name,
      item: item.url,
    })),
  };
}

export interface CollectionPageOptions {
  name: string;
  description: string;
  url: string;
  itemCount?: number;
}

export function collectionPageSchema(opts: CollectionPageOptions): SchemaObject {
  return {
    '@context': 'https://schema.org',
    '@type': 'CollectionPage',
    name: opts.name,
    description: opts.description,
    url: opts.url,
    inLanguage: SITE_LOCALE,
    isPartOf: { '@id': `${SITE_URL}/#website` },
    ...(opts.itemCount !== undefined && {
      mainEntity: {
        '@type': 'ItemList',
        numberOfItems: opts.itemCount,
      },
    }),
  };
}

export function absoluteUrl(pathname: string): string {
  return new URL(pathname, SITE_URL).toString();
}

describe('parseField', () => {
  it('parses unquoted value', () => {
    expect(parseField('cover: /img/a.png\n', 'cover')).toBe('/img/a.png');
  });
  it('parses double-quoted value', () => {
    expect(parseField('cover: "https://example.com/a.png"\n', 'cover')).toBe(
      'https://example.com/a.png',
    );
  });
  it('parses single-quoted value', () => {
    expect(parseField("title: 'hello world'\n", 'title')).toBe('hello world');
  });
  it('strips inline comments on unquoted values', () => {
    expect(parseField('cover: /img/a.png # the cover\n', 'cover')).toBe('/img/a.png');
  });
  it('returns undefined for missing field', () => {
    expect(parseField('title: foo\n', 'cover')).toBeUndefined();
  });
  it('returns undefined for empty / null sentinel', () => {
    expect(parseField('cover:\n', 'cover')).toBeUndefined();
    expect(parseField('cover: ~\n', 'cover')).toBeUndefined();
    expect(parseField('cover: null\n', 'cover')).toBeUndefined();
  });
  it('matches only at line start (no partial-key match)', () => {
    expect(parseField('coverAlt: alt only\n', 'cover')).toBeUndefined();
  });
});

