.code-with-output .cwo-subpane {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.code-with-output .cwo-case[data-has-input='true'] .cwo-subpane-stdin {
  flex: 0 1 auto;
  max-height: 45%;
  border-bottom: 1px solid var(--color-border);
}
.code-with-output .cwo-case[data-has-input='true'] .cwo-subpane-stdout {
  flex: 1 1 auto;
}
.code-with-output .cwo-case[data-has-input='true'] .cwo-subpane > .cwo-body {
  overflow: auto;
}
.code-with-output .cwo-variant {
  display: none;
}
.code-with-output .cwo-variant.is-active {
  display: block;
}
.code-with-output .cwo-body pre {
  margin: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  padding: 0.75rem 1rem !important;
  background: transparent !important;
  font-size: 0.85rem;
  overflow-x: auto;
}
.code-with-output .cwo-body pre code {
  background: transparent;
  padding: 0;
}

@media (max-width: 640px) {
  .code-with-output .cwo-panes {
    display: flex;
    flex-direction: column;
    gap: 0;
    max-height: none;
  }
  .code-with-output .cwo-splitter {
    display: none;
  }
  .code-with-output .cwo-pane-code {
    border-radius: 0.5rem 0.5rem 0 0;
    border-right: 1px solid var(--color-border);
    border-bottom: 0;
  }
  .code-with-output .cwo-pane-output {
    border-radius: 0 0 0.5rem 0.5rem;
    border-left: 1px solid var(--color-border);
    border-top: 0;
  }
  .code-with-output .cwo-case[data-has-input='true'] .cwo-subpane-stdin {
    max-height: none;
  }
}

