Chart.register(
  CategoryScale,
  LinearScale,
  LogarithmicScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Filler,
  Legend,
  Title,
  Tooltip,
  BarController,
  LineController,
  PieController,
  DoughnutController,
  RadarController,
  PolarAreaController,
  ScatterController,
  BubbleController,
  RadialLinearScale,
);

type SupportedType = 'bar' | 'line' | 'pie' | 'doughnut' | 'radar' | 'polarArea' | 'scatter' | 'bubble';

interface ChartJsProps {
  type: SupportedType;
  data: unknown;
  options?: unknown;
  height?: string;
  title?: string;
  caption?: string;
}

const RADIAL_TYPES: ReadonlySet<SupportedType> = new Set(['pie', 'doughnut', 'radar', 'polarArea']);

function readThemeColors(): { text: string; grid: string } {
  const isDark =
    typeof document !== 'undefined' && document.documentElement.classList.contains('dark');
  return {
    text: isDark ? '#e2e8f0' : '#1e293b',
    grid: isDark ? '#334155' : '#f1f5f9',
  };
}

function buildOptions(
  type: SupportedType,
  userOptions: Record<string, unknown> | undefined,
  colors: { text: string; grid: string },
): ChartOptions {
  const user = userOptions ?? {};
  const userPlugins = (user.plugins as Record<string, unknown> | undefined) ?? {};
  const userLegend = (userPlugins.legend as Record<string, unknown> | undefined) ?? {};
  const userLegendLabels = (userLegend.labels as Record<string, unknown> | undefined) ?? {};
  const userTooltip = (userPlugins.tooltip as Record<string, unknown> | undefined) ?? {};

const merged: Record<string, unknown> = {
    responsive: true,
    maintainAspectRatio: false,
    ...user,
    plugins: {
      ...userPlugins,
      legend: {
        position: 'bottom',
        ...userLegend,
        labels: {
          usePointStyle: true,
          font: { size: 11 },
          ...userLegendLabels,
          color: colors.text,
        },
      },
      tooltip: { enabled: true, ...userTooltip },
    },
  };

if (!RADIAL_TYPES.has(type)) {
    const userScales = (user.scales as Record<string, Record<string, unknown>> | undefined) ?? {};
    const userX = userScales.x ?? {};
    const userY = userScales.y ?? {};
    const userXGrid = (userX.grid as Record<string, unknown> | undefined) ?? {};
    const userXTicks = (userX.ticks as Record<string, unknown> | undefined) ?? {};
    const userYGrid = (userY.grid as Record<string, unknown> | undefined) ?? {};
    const userYTicks = (userY.ticks as Record<string, unknown> | undefined) ?? {};

merged.scales = {
      ...userScales,
      x: {
        ...userX,
        grid: { ...userXGrid, color: colors.grid },
        ticks: { ...userXTicks, color: colors.text },
      },
      y: {
        ...userY,
        grid: { ...userYGrid, color: colors.grid },
        ticks: { ...userYTicks, color: colors.text },
      },
    };
  }

return merged as ChartOptions;
}

export default function ChartJs({
  type,
  data,
  options,
  height = '320px',
  title,
  caption,
}: ChartJsProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const chartRef = useRef<Chart | null>(null);

const dataKey = useMemo(() => JSON.stringify(data ?? null), [data]);
  const optionsKey = useMemo(() => JSON.stringify(options ?? null), [options]);

useEffect(() => {
    if (!canvasRef.current) return;

const colors = readThemeColors();
    const parsedData = JSON.parse(dataKey) as ChartData;
    const parsedOptions = JSON.parse(optionsKey) as Record<string, unknown> | null;
    const builtOptions = buildOptions(type, parsedOptions ?? undefined, colors);

chartRef.current = new Chart(canvasRef.current, {
      type: type as ChartType,
      data: parsedData,
      options: builtOptions,
    });

return () => {
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [type]);

useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const colors = readThemeColors();
    const parsedData = JSON.parse(dataKey) as ChartData;
    const parsedOptions = JSON.parse(optionsKey) as Record<string, unknown> | null;
    const builtOptions = buildOptions(type, parsedOptions ?? undefined, colors);
    chart.data = parsedData;
    chart.options = builtOptions;
    chart.update();
  }, [dataKey, optionsKey, type]);

useEffect(() => {
    const observer = new MutationObserver(() => {
      const chart = chartRef.current;
      if (!chart) return;
      const colors = readThemeColors();
      const parsedOptions = JSON.parse(optionsKey) as Record<string, unknown> | null;
      chart.options = buildOptions(type, parsedOptions ?? undefined, colors);
      chart.update('none');
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    return () => observer.disconnect();
  }, [type, optionsKey]);

return (
    <div className="my-6 rounded-xl border border-gray-200 bg-gray-50 p-4 dark:border-gray-700 dark:bg-gray-800/50">
      {title && <div className="mb-1 text-sm font-bold text-gray-900 dark:text-gray-100">{title}</div>}
      <div style={{ height, position: 'relative', width: '100%' }}>
        <canvas ref={canvasRef} />
      </div>
      {caption && (
        <div className="mt-2 border-t border-gray-200 pt-2 text-xs italic text-gray-500 dark:border-gray-700 dark:text-gray-400">
          {caption}
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import * as d3 from 'd3';
import type { GraphLink, GraphLinkKind, GraphNode } from '@/shared/types/graph';

interface Props {
  nodes: GraphNode[];
  links: GraphLink[];
  height?: number;
  query?: string;
}

type SimNode = GraphNode & d3.SimulationNodeDatum;
type SimLink = d3.SimulationLinkDatum<SimNode> & { kind?: GraphLinkKind };

const GROUP_COLORS: Record<string, string> = {
  posts: '#4f46e5',
  notes: '#10b981',
  wiki: '#f59e0b',
};
const TAG_FILL_LIGHT = '#94a3b8';
const TAG_FILL_DARK = '#475569';
const DIM_COLOR = '#a1a1aa';

function tagFill(isDark: boolean): string {
  return isDark ? TAG_FILL_DARK : TAG_FILL_LIGHT;
}

function nodeColor(node: GraphNode, isDark: boolean): string {
  if (node.kind === 'tag') return tagFill(isDark);
  return GROUP_COLORS[node.group ?? ''] ?? '#6b7280';
}

const TAG_NODE_SIZE = 10;
const TAG_LABEL_GAP = 6;

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));

// Below this zoom scale, node labels hide so structure stays legible.
const LABEL_ZOOM_THRESHOLD = 0.55;

function seededRandom(seed: number): () => number {
  let s = seed | 0 || 1;
  return () => {
    s = Math.imul(s ^ (s >>> 15), 1 | s);
    s ^= s + Math.imul(s ^ (s >>> 7), 61 | s);
    return ((s ^ (s >>> 14)) >>> 0) / 0xffffffff;
  };
}

// Golden-spiral seeding. densityScale (sqrt(n/80)) widens the outer radius as
// n grows so dense graphs start pre-spread instead of piled at the center.
function seedInitialLayout(nodes: SimNode[], width: number, height: number): void {
  const n = nodes.length;
  if (n === 0) return;
  const cx = width / 2;
  const cy = height / 2;
  const densityScale = Math.max(1, Math.sqrt(n / 80));
  const maxRadius = Math.min(width, height) * 0.45 * densityScale;
  const scale = maxRadius / Math.sqrt(n);
  const jitter = Math.max(scale * 0.3, 1);
  const rand = seededRandom(n * 9973 + 7);
  for (let i = 0; i < n; i++) {
    const r = scale * Math.sqrt(i + 0.5);
    const theta = i * GOLDEN_ANGLE;
    nodes[i].x = cx + r * Math.cos(theta) + (rand() - 0.5) * jitter;
    nodes[i].y = cy + r * Math.sin(theta) + (rand() - 0.5) * jitter;
  }
}

interface ForceParams {
  linkDistance: number;
  docCharge: number;
  tagCharge: number;
  docCollide: number;
  centerStrength: number;
  preTicks: number;
}

function computeForceParams(n: number): ForceParams {
  const sizeFactor = Math.max(1, Math.sqrt(n / 60));
  return {
    linkDistance: Math.round(Math.max(80, 60 * sizeFactor)),
    docCharge: -Math.round(Math.max(200, 220 * sizeFactor)),
    tagCharge: -Math.round(Math.max(300, 330 * sizeFactor)),
    docCollide: Math.round(Math.min(50, Math.max(28, 24 * sizeFactor))),
    centerStrength: Math.max(0.03, 0.08 / sizeFactor),
    preTicks: Math.min(80, 30 + Math.floor(n / 10)),
  };
}

export default function Graph({ nodes, links, height = 560, query = '' }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const [isDark, setIsDark] = useState(
    typeof document !== 'undefined' && document.documentElement.classList.contains('dark'),
  );

useEffect(() => {
    const root = document.documentElement;
    const update = () => setIsDark(root.classList.contains('dark'));
    update();
    const mo = new MutationObserver(update);
    mo.observe(root, { attributes: true, attributeFilter: ['class'] });
    return () => mo.disconnect();
  }, []);

const normalizedQuery = query.trim().toLowerCase();

const matchedIds = useMemo(() => {
    if (!normalizedQuery) return null;
    return new Set(
      nodes.filter((n) => n.title.toLowerCase().includes(normalizedQuery)).map((n) => n.id),
    );
  }, [nodes, normalizedQuery]);

useEffect(() => {
    if (!svgRef.current || !containerRef.current) return;

const svgEl = svgRef.current;
    const width = containerRef.current.clientWidth || 800;

const svg = d3.select(svgEl);
    svg.selectAll('*').remove();
    svg.attr('viewBox', `0 0 ${width} ${height}`);

const simNodes: SimNode[] = nodes.map((n) => ({ ...n }));
    seedInitialLayout(simNodes, width, height);
    const idSet = new Set(simNodes.map((n) => n.id));
    const simLinks: SimLink[] = links
      .filter((l) => idSet.has(l.source) && idSet.has(l.target))
      .map((l) => ({ source: l.source, target: l.target, kind: l.kind }));

const root = svg.append('g');

const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.2, 4])
      .on('zoom', (event) => {
        root.attr('transform', event.transform.toString());
        const showLabels = event.transform.k >= LABEL_ZOOM_THRESHOLD;
        root
          .selectAll<SVGTextElement, SimNode>('.graph-nodes text')
          .style('display', showLabels ? '' : 'none');
      });
    svg.call(zoom);

const link = root
      .append('g')
      .attr('class', 'graph-links')
      .attr('stroke', 'currentColor')
      .attr('stroke-opacity', 0.25)
      .selectAll<SVGLineElement, SimLink>('line')
      .data(simLinks)
      .join('line')
      .attr('stroke-width', (d) => (d.kind === 'tag' ? 0.8 : 1))
      .attr('stroke-dasharray', (d) => (d.kind === 'tag' ? '2 3' : null));

const nodeGroup = root
      .append('g')
      .attr('class', 'graph-nodes')
      .selectAll<SVGGElement, SimNode>('g')
      .data(simNodes)
      .join('g')
      .attr('data-kind', (d) => d.kind ?? 'doc')
      .style('cursor', 'pointer')
      .on('click', (_, d) => {
        if (d.url) window.location.href = d.url;
      });

const docNodes = nodeGroup.filter((d) => d.kind !== 'tag');
    const tagNodes = nodeGroup.filter((d) => d.kind === 'tag');

docNodes
      .append('circle')
      .attr('r', 7)
      .attr('fill', (d) => nodeColor(d, isDark))
      .attr('stroke', 'currentColor')
      .attr('stroke-opacity', 0.3)
      .attr('stroke-width', 1);

if (simNodes.length > 20) {
      let minX = Infinity;
      let maxX = -Infinity;
      let minY = Infinity;
      let maxY = -Infinity;
      for (const node of simNodes) {
        const x = node.x ?? 0;
        const y = node.y ?? 0;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
      const bboxW = maxX - minX;
      const bboxH = maxY - minY;
      if (bboxW > 0 && bboxH > 0) {
        const labelOverhang = 160;
        const padding = 32;
        const kx = (width - padding * 2) / (bboxW + labelOverhang);
        const ky = (height - padding * 2) / bboxH;
        const k = Math.max(0.25, Math.min(1, kx, ky));
        if (k < 1) {
          const centerX = (minX + maxX) / 2;
          const centerY = (minY + maxY) / 2;
          const tx = width / 2 - centerX * k;
          const ty = height / 2 - centerY * k;
          const initialTransform = d3.zoomIdentity.translate(tx, ty).scale(k);
          svg.call(zoom.transform, initialTransform);
        }
      }
    }

const drag = d3
      .drag<SVGGElement, SimNode>()
      .on('start', (event, d) => {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
      })
      .on('drag', (event, d) => {
        d.fx = event.x;
        d.fy = event.y;
      })
      .on('end', (event, d) => {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
      });

nodeGroup.call(drag);

simulation.on('tick', () => {
      link
        .attr('x1', (d) => (d.source as SimNode).x ?? 0)
        .attr('y1', (d) => (d.source as SimNode).y ?? 0)
        .attr('x2', (d) => (d.target as SimNode).x ?? 0)
        .attr('y2', (d) => (d.target as SimNode).y ?? 0);
      nodeGroup.attr('transform', (d) => `translate(${d.x ?? 0},${d.y ?? 0})`);
    });

return () => {
      simulation.stop();
    };
  }, [nodes, links, height]);

useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg
      .selectAll<SVGCircleElement, SimNode>('.graph-nodes g circle')
      .attr('fill', (d) => {
        if (matchedIds && !matchedIds.has(d.id)) return DIM_COLOR;
        return nodeColor(d, isDark);
      })
      .attr('fill-opacity', (d) => (matchedIds && !matchedIds.has(d.id) ? 0.3 : 1));
    svg
      .selectAll<SVGRectElement, SimNode>('.graph-nodes g rect')
      .attr('fill', (d) => (matchedIds && !matchedIds.has(d.id) ? DIM_COLOR : nodeColor(d, isDark)))
      .attr('fill-opacity', (d) => (matchedIds && !matchedIds.has(d.id) ? 0.3 : 0.9));
    svg
      .selectAll<SVGTextElement, SimNode>('.graph-nodes g text')
      .attr('fill-opacity', (d) => (matchedIds && !matchedIds.has(d.id) ? 0.3 : 1));
    svg.selectAll<SVGLineElement, SimLink>('.graph-links line').attr('stroke-opacity', (l) => {
      const s = typeof l.source === 'object' ? (l.source as SimNode).id : (l.source as string);
      const t = typeof l.target === 'object' ? (l.target as SimNode).id : (l.target as string);
      if (!matchedIds) return 0.25;
      return matchedIds.has(s) && matchedIds.has(t) ? 0.5 : 0.08;
    });
  }, [matchedIds, isDark]);

return (
    <div ref={containerRef} className="w-full">
      <svg ref={svgRef} width="100%" height={height} aria-label="Knowledge graph" />
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import ForceGraph3D, { type ForceGraphMethods } from 'react-force-graph-3d';
import * as THREE from 'three';
import type { GraphLink, GraphNode } from '@/shared/types/graph';

interface Props {
  nodes: GraphNode[];
  links: GraphLink[];
  height?: number;
  query?: string;
}

const GROUP_COLORS: Record<string, string> = {
  posts: '#818cf8',
  notes: '#34d399',
  wiki: '#fbbf24',
};
const TAG_COLOR_3D_LIGHT = '#475569';
const TAG_COLOR_3D_DARK = '#cbd5e1';

function nodeBaseColor(node: GraphNode, isDark: boolean): string {
  if (node.kind === 'tag') return isDark ? TAG_COLOR_3D_DARK : TAG_COLOR_3D_LIGHT;
  return GROUP_COLORS[node.group ?? ''] ?? '#6b7280';
}

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));

function seededRandom(seed: number): () => number {
  let s = seed | 0 || 1;
  return () => {
    s = Math.imul(s ^ (s >>> 15), 1 | s);
    s ^= s + Math.imul(s ^ (s >>> 7), 61 | s);
    return ((s ^ (s >>> 14)) >>> 0) / 0xffffffff;
  };
}

interface SeededNode extends GraphNode {
  x: number;
  y: number;
  z: number;
}

function fibonacciSphereLayout(nodes: GraphNode[]): SeededNode[] {
  const n = nodes.length;
  if (n === 0) return [];
  const radius = Math.max(120, 22 * Math.cbrt(n));
  const jitter = radius * 0.05;
  const rand = seededRandom(n * 31337 + 11);
  return nodes.map((node, i) => {
    const phi = Math.acos(1 - (2 * (i + 0.5)) / n);
    const theta = i * GOLDEN_ANGLE;
    return {
      ...node,
      x: radius * Math.sin(phi) * Math.cos(theta) + (rand() - 0.5) * jitter,
      y: radius * Math.sin(phi) * Math.sin(theta) + (rand() - 0.5) * jitter,
      z: radius * Math.cos(phi) + (rand() - 0.5) * jitter,
    };
  });
}

export default function Graph3D({ nodes, links, height = 560, query = '' }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const fgRef = useRef<ForceGraphMethods<GraphNode, GraphLink> | undefined>(undefined);
  const [width, setWidth] = useState(800);
  const [isDark, setIsDark] = useState(false);

useEffect(() => {
    if (!containerRef.current) return;
    const ro = new ResizeObserver((entries) => {
      for (const entry of entries) setWidth(entry.contentRect.width);
    });
    ro.observe(containerRef.current);
    return () => ro.disconnect();
  }, []);

useEffect(() => {
    const root = document.documentElement;
    const update = () => setIsDark(root.classList.contains('dark'));
    update();
    const mo = new MutationObserver(update);
    mo.observe(root, { attributes: true, attributeFilter: ['class'] });
    return () => mo.disconnect();
  }, []);

const normalizedQuery = query.trim().toLowerCase();

const data = useMemo(
    () => ({ nodes: fibonacciSphereLayout(nodes), links: links.map((l) => ({ ...l })) }),
    [nodes, links],
  );

const matchedIds = useMemo(() => {
    if (!normalizedQuery) return null;
    return new Set(
      nodes.filter((n) => n.title.toLowerCase().includes(normalizedQuery)).map((n) => n.id),
    );
  }, [nodes, normalizedQuery]);

const backgroundColor = isDark ? '#0b0b0f' : '#ffffff';

return (
    <div ref={containerRef} className="w-full" style={{ minHeight: height }}>
      <ForceGraph3D
        ref={fgRef}
        graphData={data}
        width={width}
        height={height}
        backgroundColor={backgroundColor}
        nodeLabel={(n) => (n as GraphNode).title}
        nodeRelSize={4}
        nodeThreeObject={(n: GraphNode) => {
          const node = n;
          const dimmed = matchedIds ? !matchedIds.has(node.id) : false;
          const color = dimmed ? (isDark ? '#3f3f46' : '#d4d4d8') : nodeBaseColor(node, isDark);
          if (node.kind === 'tag') {
            const size = Math.min(10, 4 + Math.sqrt(node.degree ?? 1) * 1.2);
            const mesh = new THREE.Mesh(
              new THREE.BoxGeometry(size, size * 0.5, size),
              new THREE.MeshLambertMaterial({
                color,
                transparent: true,
                opacity: dimmed ? 0.5 : 0.85,
              }),
            );
            return mesh;
          }
          const sphere = new THREE.Mesh(
            new THREE.SphereGeometry(4, 20, 16),
            new THREE.MeshLambertMaterial({
              color,
              transparent: true,
              opacity: dimmed ? 0.5 : 0.95,
            }),
          );
          return sphere;
        }}
        linkColor={(l) => {
          if ((l as GraphLink).kind === 'tag') return isDark ? '#52525b' : '#cbd5e1';
          return isDark ? '#3f3f46' : '#d4d4d8';
        }}
        linkOpacity={matchedIds ? 0.15 : 0.4}
        linkWidth={(l) => {
          const isTag = (l as GraphLink).kind === 'tag';
          if (!matchedIds) return isTag ? 0.5 : 1;
          const s =
            typeof l.source === 'object' ? (l.source as GraphNode).id : (l.source as string);
          const t =
            typeof l.target === 'object' ? (l.target as GraphNode).id : (l.target as string);
          return matchedIds.has(s) && matchedIds.has(t) ? 2 : 0.3;
        }}
        onNodeClick={(node) => {
          const n = node as GraphNode;
          if (n.url) window.location.href = n.url;
        }}
        warmupTicks={30}
        cooldownTicks={120}
        d3AlphaDecay={0.035}
        showNavInfo={false}
      />
    </div>
  );
}

import { lazy, Suspense, useEffect, useMemo, useState } from 'react';
import Graph2D from './Graph';
import type { GraphLink, GraphNode } from '@/shared/types/graph';

const Graph3D = lazy(() => import('./Graph3D'));

interface Props {
  nodes: GraphNode[];
  links: GraphLink[];
}

type CollectionFilter = 'posts' | 'notes' | 'wiki';
const ALL_COLLECTIONS: CollectionFilter[] = ['posts', 'notes', 'wiki'];
const COLLECTION_LABELS: Record<CollectionFilter, string> = {
  posts: '글',
  notes: '노트',
  wiki: '위키',
};

function downloadBlob(filename: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

export default function GraphView({ nodes, links }: Props) {
  const [mode, setMode] = useState<'2d' | '3d'>('2d');
  const [query, setQuery] = useState('');
  const [showTags, setShowTags] = useState(true);
  const [enabledCollections, setEnabledCollections] = useState<Set<CollectionFilter>>(
    new Set(ALL_COLLECTIONS),
  );
  const [wikiCategory, setWikiCategory] = useState<string | null>(null);

useEffect(() => {
    if (typeof window === 'undefined') return;
    const url = new URL(window.location.href);
    const cat = url.searchParams.get('category');
    if (cat) setWikiCategory(cat);
  }, []);

useEffect(() => {
    if (typeof window === 'undefined') return;
    const url = new URL(window.location.href);
    if (wikiCategory) url.searchParams.set('category', wikiCategory);
    else url.searchParams.delete('category');
    window.history.replaceState({}, '', url.toString());
  }, [wikiCategory]);

const collectionCounts = useMemo(() => {
    const out: Record<CollectionFilter, number> = { posts: 0, notes: 0, wiki: 0 };
    for (const n of nodes) {
      if (n.kind === 'tag') continue;
      const g = n.group as CollectionFilter | undefined;
      if (g && g in out) out[g]++;
    }
    return out;
  }, [nodes]);

const wikiCategoryCounts = useMemo(() => {
    const out = new Map<string, number>();
    for (const n of nodes) {
      if (n.kind === 'tag' || n.group !== 'wiki' || !n.category) continue;
      out.set(n.category, (out.get(n.category) ?? 0) + 1);
    }
    return Array.from(out.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  }, [nodes]);

const { visibleNodes, visibleLinks } = useMemo(() => {
    const tagOk = (n: GraphNode) => showTags || n.kind !== 'tag';
    const colOk = (n: GraphNode) =>
      n.kind === 'tag' || (n.group && enabledCollections.has(n.group as CollectionFilter));
    const catOk = (n: GraphNode) => {
      if (!wikiCategory) return true;
      if (n.kind === 'tag') return true;
      if (n.group !== 'wiki') return false;
      return n.category === wikiCategory;
    };
    const filteredNodes = nodes.filter((n) => tagOk(n) && colOk(n) && catOk(n));
    const ids = new Set(filteredNodes.map((n) => n.id));
    const filteredLinks = links.filter((l) => ids.has(l.source) && ids.has(l.target));
    return { visibleNodes: filteredNodes, visibleLinks: filteredLinks };
  }, [nodes, links, showTags, enabledCollections, wikiCategory]);

const filteredCounts = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return null;
    const matches = visibleNodes.filter((n) => n.title.toLowerCase().includes(q));
    return { matches: matches.length, total: visibleNodes.length };
  }, [visibleNodes, query]);

const tagCount = useMemo(() => nodes.filter((n) => n.kind === 'tag').length, [nodes]);

const toggleCollection = (c: CollectionFilter): void => {
    setEnabledCollections((prev) => {
      const next = new Set(prev);
      if (next.has(c)) next.delete(c);
      else next.add(c);
      return next;
    });
  };

const exportJSON = (): void => {
    const data = JSON.stringify({ nodes: visibleNodes, links: visibleLinks }, null, 2);
    downloadBlob('content-graph.json', new Blob([data], { type: 'application/json' }));
  };

const exportSVG = (): void => {
    const stage = document.querySelector('.graph-stage svg, .react-force-graph-2d svg, svg[width][height]') as
      | SVGSVGElement
      | null;
    if (!stage) return;
    const xml = new XMLSerializer().serializeToString(stage);
    downloadBlob(
      'content-graph.svg',
      new Blob(['<?xml version="1.0" encoding="UTF-8"?>\n', xml], { type: 'image/svg+xml' }),
    );
  };

return (
    <div className="space-y-3 graph-stage">
      <div className="flex flex-wrap items-center gap-2">
        <input
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="노드 이름으로 검색…"
          className="flex-1 min-w-[200px] rounded-md border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
        />
        {tagCount > 0 && (
          <label className="inline-flex items-center gap-1.5 rounded-md border border-border px-2.5 py-1.5 text-sm cursor-pointer select-none">
            <input
              type="checkbox"
              checked={showTags}
              onChange={(e) => setShowTags(e.target.checked)}
              className="accent-[color:var(--color-accent)]"
            />
            <span>🏷️ 태그 ({tagCount})</span>
          </label>
        )}
        <div
          className="inline-flex overflow-hidden rounded-md border border-border"
          role="tablist"
        >
          <button
            type="button"
            role="tab"
            aria-selected={mode === '2d'}
            onClick={() => setMode('2d')}
            className={
              mode === '2d'
                ? 'bg-surface-elevated px-3 py-2 text-sm text-accent'
                : 'px-3 py-2 text-sm text-fg-muted hover:text-fg'
            }
          >
            2D
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={mode === '3d'}
            onClick={() => setMode('3d')}
            className={
              mode === '3d'
                ? 'bg-surface-elevated px-3 py-2 text-sm text-accent'
                : 'px-3 py-2 text-sm text-fg-muted hover:text-fg'
            }
          >
            3D
          </button>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2 text-xs">
        <span className="text-fg-muted">컬렉션:</span>
        {ALL_COLLECTIONS.map((c) => {
          const enabled = enabledCollections.has(c);
          return (
            <button
              key={c}
              type="button"
              aria-pressed={enabled}
              onClick={() => toggleCollection(c)}
              className={
                enabled
                  ? 'rounded-full border border-accent bg-surface-elevated px-2.5 py-0.5 text-accent'
                  : 'rounded-full border border-border px-2.5 py-0.5 text-fg-muted hover:border-accent'
              }
            >
              {COLLECTION_LABELS[c]} ({collectionCounts[c]})
            </button>
          );
        })}
        <span className="ml-auto inline-flex gap-1">
        </span>
      </div>
      {wikiCategoryCounts.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5 text-xs">
          <span className="text-fg-muted">위키 카테고리:</span>
          <button
            type="button"
            aria-pressed={wikiCategory === null}
            onClick={() => setWikiCategory(null)}
            className={
              wikiCategory === null
                ? 'rounded-full border border-accent bg-surface-elevated px-2.5 py-0.5 text-accent'
                : 'rounded-full border border-border px-2.5 py-0.5 text-fg-muted hover:border-accent'
            }
          >
            전체
          </button>
          {wikiCategoryCounts.map(([cat, count]) => (
            <button
              key={cat}
              type="button"
              aria-pressed={wikiCategory === cat}
              onClick={() => setWikiCategory(wikiCategory === cat ? null : cat)}
              className={
                wikiCategory === cat
                  ? 'rounded-full border border-accent bg-surface-elevated px-2.5 py-0.5 text-accent'
                  : 'rounded-full border border-border px-2.5 py-0.5 text-fg-muted hover:border-accent'
              }
            >
              {cat} ({count})
            </button>
          ))}
        </div>
      )}
      <div className="flex flex-wrap items-center gap-2 text-xs">
        <span className="ml-auto inline-flex gap-1">
          <button
            type="button"
            onClick={exportSVG}
            className="rounded-md border border-border px-2 py-1 hover:border-accent"
            title="SVG 다운로드"
          >
            ⤓ SVG
          </button>
          <button
            type="button"
            onClick={exportJSON}
            className="rounded-md border border-border px-2 py-1 hover:border-accent"
            title="JSON 다운로드 (nodes + links)"
          >
            ⤓ JSON
          </button>
        </span>
      </div>
      {filteredCounts && (
        <p className="text-xs text-fg-muted">
          {filteredCounts.matches}개 노드가 "{query}" 와 일치 (총 {filteredCounts.total}개 중)
        </p>
      )}
      <div className="rounded-lg border border-border bg-surface-elevated p-2">
        {mode === '2d' ? (
          <Graph2D nodes={visibleNodes} links={visibleLinks} query={query} />
        ) : (
          <Suspense
            fallback={
              <div className="flex h-[560px] items-center justify-center text-sm text-fg-muted">
                3D 뷰를 불러오는 중…
              </div>
            }
          >
            <Graph3D nodes={visibleNodes} links={visibleLinks} query={query} />
          </Suspense>
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { DEFAULT_WORDS, readTheme } from './theme';
import { buildKeyboard } from './keyboard';
import { buildWordPool, repaintFloatingWords, spawnWordTop } from './words';
import { createScreen, drawScreen, LINE_HEIGHT, VISIBLE_LINES, type ScreenState } from './screen';

interface Props {
  titles: string[];
  words?: string[];
  prompt?: string;
  height?: number;
}

export default function Hero3D({
  titles,
  words = DEFAULT_WORDS,
  prompt = '~/koa/log $',
  height = 460,
}: Props) {
  const containerRef = useRef<HTMLDivElement>(null);

useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

const prefersReduced =
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;

const scene = new THREE.Scene();
    const initialWidth = container.clientWidth || 800;
    const camera = new THREE.PerspectiveCamera(42, initialWidth / height, 0.1, 100);
    camera.position.set(1.2, 2.6, 6.0);
    camera.lookAt(0, 1.2, -0.3);

const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(initialWidth, height);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    container.appendChild(renderer.domElement);

let theme = readTheme();

const ambient = new THREE.AmbientLight(0xffffff, 0.55);
    scene.add(ambient);
    const keyLight = new THREE.DirectionalLight(0xffffff, 1.1);
    keyLight.position.set(4, 7, 5);
    scene.add(keyLight);
    const rim = new THREE.DirectionalLight(theme.rimColor, 0.55);
    rim.position.set(-5, 2, -3);
    scene.add(rim);

const laptop = new THREE.Group();
    scene.add(laptop);

const baseGeometry = new THREE.BoxGeometry(4, 0.18, 2.8);
    const baseMaterial = new THREE.MeshStandardMaterial({
      color: theme.baseColor,
      metalness: theme.baseMetal,
      roughness: theme.baseRough,
    });
    const base = new THREE.Mesh(baseGeometry, baseMaterial);
    laptop.add(base);

const keyMaterial = new THREE.MeshStandardMaterial({
      color: theme.keyColor,
      metalness: 0.2,
      roughness: 0.7,
    });
    const { keys, keyGeometries, keyOffsets, backEdge } = buildKeyboard(laptop, keyMaterial);

const trackpadDepth = 0.85;
    const trackpadGap = 0.16;
    const trackpadCenterZ = backEdge + trackpadGap + trackpadDepth / 2;
    const trackpad = new THREE.Mesh(
      new THREE.BoxGeometry(1.6, 0.005, trackpadDepth),
      new THREE.MeshStandardMaterial({
        color: theme.keyColor,
        metalness: 0.4,
        roughness: 0.5,
      }),
    );
    trackpad.position.set(0, 0.095, trackpadCenterZ);
    laptop.add(trackpad);

const screenPivot = new THREE.Group();
    screenPivot.position.set(0, 0.09, -1.4);
    laptop.add(screenPivot);

const screenShell = new THREE.Mesh(
      new THREE.BoxGeometry(4, 2.5, 0.08),
      new THREE.MeshStandardMaterial({
        color: theme.baseColor,
        metalness: theme.baseMetal,
        roughness: theme.baseRough,
      }),
    );
    screenShell.position.set(0, 1.25, -0.04);
    screenPivot.add(screenShell);

const { canvas: screenCanvas, ctx: screenCtx, texture: screenTexture } = createScreen();
    void screenCanvas;
    const screenFace = new THREE.Mesh(
      new THREE.PlaneGeometry(3.8, 2.32),
      new THREE.MeshBasicMaterial({ map: screenTexture }),
    );
    screenFace.position.set(0, 1.25, 0.005);
    screenPivot.add(screenFace);

const closedRotation = (95 * Math.PI) / 180;
    const openRotation = -(15 * Math.PI) / 180;
    screenPivot.rotation.x = closedRotation;

const titleWords = titles.flatMap((t) =>
      t.split(/[\s,(){}[\]:;。、,.()]+/u).filter((w) => w.length > 0 && w.length <= 14),
    );
    const wordPool = Array.from(new Set([...titleWords, ...words])).slice(0, 80);
    const wordCount = prefersReduced ? 0 : Math.min(wordPool.length, 28);
    const floatingWords = buildWordPool(scene, theme, wordCount, wordPool);

const screenState: ScreenState = {
      lines: (titles.length > 0 ? titles : ['일단 기록을 하자.']).slice(0, 6),
      displayLines: [],
      currentLineIdx: 0,
      currentChar: 0,
      cursorBlink: 0,
      scrollOffset: 0,
    };

let frameId = 0;
    let elapsed = 0;
    let lastT = performance.now();
    let charTimer = 0;
    let lineWait = 0;
    const charPerSec = 30;
    const lineDelay = 0.45;
    const hingeOpenSec = prefersReduced ? 0 : 1.4;

let pointerX = 0;
    let pointerY = 0;
    const onPointerMove = (e: MouseEvent) => {
      const rect = container.getBoundingClientRect();
      pointerX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      pointerY = ((e.clientY - rect.top) / rect.height) * 2 - 1;
    };
    container.addEventListener('mousemove', onPointerMove);

function tick(t: number) {
      const dt = Math.min(0.05, (t - lastT) / 1000);
      lastT = t;
      elapsed += dt;

if (prefersReduced) {
        screenPivot.rotation.x = openRotation;
      } else {
        const p = Math.min(1, elapsed / hingeOpenSec);
        const eased = 1 - Math.pow(1 - p, 3);
        screenPivot.rotation.x = closedRotation + eased * (openRotation - closedRotation);
      }

if (!prefersReduced) {
        const orbitT = elapsed * 0.18;
        const targetX = 1.2 + Math.sin(orbitT) * 0.5 + pointerX * 0.6;
        const targetY = 2.6 + Math.sin(elapsed * 0.22) * 0.12 + pointerY * 0.25;
        camera.position.x += (targetX - camera.position.x) * Math.min(1, dt * 4);
        camera.position.y += (targetY - camera.position.y) * Math.min(1, dt * 4);
      }
      camera.lookAt(0, 1.2, -0.3);

laptop.rotation.y = Math.sin(elapsed * 0.15) * 0.06 + pointerX * 0.04;

if (elapsed > hingeOpenSec + 0.2 && screenState.currentLineIdx < screenState.lines.length) {
        if (lineWait > 0) {
          lineWait -= dt;
        } else {
          charTimer += dt * charPerSec;
          while (
            charTimer >= 1 &&
            screenState.currentChar < screenState.lines[screenState.currentLineIdx].length
          ) {
            screenState.currentChar++;
            charTimer--;
            const ki = (screenState.currentLineIdx * 7 + screenState.currentChar) % keys.length;
            keys[ki].position.y = 0.1;
          }
          if (screenState.currentChar >= screenState.lines[screenState.currentLineIdx].length) {
            screenState.displayLines.push(screenState.lines[screenState.currentLineIdx]);
            screenState.currentLineIdx++;
            screenState.currentChar = 0;
            charTimer = 0;
            lineWait = lineDelay;
            if (screenState.displayLines.length > VISIBLE_LINES) {
              screenState.scrollOffset =
                (screenState.displayLines.length - VISIBLE_LINES) * LINE_HEIGHT;
            }
          }
        }
      }

for (let i = 0; i < keys.length; i++) {
        const target = 0.13;
        keys[i].position.y += (target - keys[i].position.y) * Math.min(1, dt * 8);
        keys[i].position.y += Math.sin(elapsed * 2 + keyOffsets[i]) * 0.0008;
      }

for (const w of floatingWords) {
        w.sprite.position.y -= w.speed * dt;
        w.sprite.position.x = w.baseX + Math.sin(elapsed * 0.6 + w.phase) * w.sway;
        const y = w.sprite.position.y;
        let opacity: number;
        if (y > 3.2) opacity = ((4.8 - y) / 1.6) * 0.7;
        else if (y < 0.6) opacity = Math.max(0, (y - 0.1) / 0.5) * 0.7;
        else opacity = 0.7;
        w.material.opacity = Math.max(0, Math.min(0.7, opacity));
        if (y < 0.1) spawnWordTop(w);
      }

drawScreen(screenCtx, theme, screenState, prompt);
      screenTexture.needsUpdate = true;
      renderer.render(scene, camera);
      frameId = requestAnimationFrame(tick);
    }
    frameId = requestAnimationFrame(tick);

const onResize = () => {
      const w = container.clientWidth;
      if (w === 0) return;
      camera.aspect = w / height;
      camera.updateProjectionMatrix();
      renderer.setSize(w, height);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(container);

function applyTheme() {
      theme = readTheme();
      baseMaterial.color.setHex(theme.baseColor);
      baseMaterial.metalness = theme.baseMetal;
      baseMaterial.roughness = theme.baseRough;
      keyMaterial.color.setHex(theme.keyColor);
      rim.color.setHex(theme.rimColor);
      repaintFloatingWords(floatingWords, theme);
    }
    const themeObs = new MutationObserver(() => applyTheme());
    themeObs.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });

return () => {
      cancelAnimationFrame(frameId);
      ro.disconnect();
      themeObs.disconnect();
      container.removeEventListener('mousemove', onPointerMove);
      renderer.dispose();
      baseGeometry.dispose();
      for (const g of keyGeometries) g.dispose();
      baseMaterial.dispose();
      keyMaterial.dispose();
      screenShell.geometry.dispose();
      (screenShell.material as THREE.Material).dispose();
      screenFace.geometry.dispose();
      (screenFace.material as THREE.Material).dispose();
      for (const w of floatingWords) {
        scene.remove(w.sprite);
        w.material.dispose();
        w.texture.dispose();
      }
      screenTexture.dispose();
      if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
    };
  }, [titles, words, prompt, height]);

import * as THREE from 'three';
import {
  FUNCTION_ROW_Z_SCALE,
  KEY_BASE_Y,
  KEY_DEPTH,
  KEY_GAP,
  KEY_THICKNESS,
  KEY_U,
  KEYBOARD_ROWS,
  ROW_DEPTH_GAP,
  ROW_U,
} from './theme';

export interface KeyboardBuild {
  keys: THREE.Mesh[];
  keyGeometries: THREE.BufferGeometry[];
  keyOffsets: number[];
  backEdge: number;
}

export function buildKeyboard(
  laptop: THREE.Group,
  keyMaterial: THREE.MeshStandardMaterial,
): KeyboardBuild {
  const keys: THREE.Mesh[] = [];
  const keyGeometries: THREE.BufferGeometry[] = [];
  const keyOffsets: number[] = [];

const rowDepths = KEYBOARD_ROWS.map((r) =>
    r[0]?.shortRow ? KEY_DEPTH * FUNCTION_ROW_Z_SCALE : KEY_DEPTH,
  );
  const rowOffsetX = -((ROW_U * KEY_U + (ROW_U - 1) * KEY_GAP) / 2);
  const keyboardBackZ = -0.85;
  let backEdge = keyboardBackZ;

KEYBOARD_ROWS.forEach((rowDef, rowIndex) => {
    const depth = rowDepths[rowIndex];
    const rowCenterZ = backEdge + depth / 2;
    const rowUnits = rowDef.reduce((sum, k) => sum + k.width, 0);
    const padU = (ROW_U - rowUnits) / 2;
    let cursorX = rowOffsetX + padU * (KEY_U + KEY_GAP);
    rowDef.forEach((keyDef) => {
      const keyW = keyDef.width * KEY_U;
      const geo = new THREE.BoxGeometry(keyW * 0.92, KEY_THICKNESS, depth * 0.88);
      keyGeometries.push(geo);
      const key = new THREE.Mesh(geo, keyMaterial);
      key.position.set(cursorX + keyW / 2, KEY_BASE_Y, rowCenterZ);
      laptop.add(key);
      keys.push(key);
      keyOffsets.push(Math.random() * Math.PI * 2);
      cursorX += keyW + KEY_GAP;
    });
    backEdge += depth + ROW_DEPTH_GAP;
  });

return { keys, keyGeometries, keyOffsets, backEdge };
}

import * as THREE from 'three';
import type { ThemeColors } from './theme';

export const SCREEN_W = 1024;
export const SCREEN_H = 640;

export interface ScreenResources {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  texture: THREE.CanvasTexture;
}

export function createScreen(): ScreenResources {
  const canvas = document.createElement('canvas');
  canvas.width = SCREEN_W;
  canvas.height = SCREEN_H;
  const ctx = canvas.getContext('2d')!;
  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.colorSpace = THREE.SRGBColorSpace;
  return { canvas, ctx, texture };
}

export interface ScreenState {
  lines: string[];
  displayLines: string[];
  currentLineIdx: number;
  currentChar: number;
  cursorBlink: number;
  scrollOffset: number;
}

export const LINE_HEIGHT = 38;
export const START_Y = 152;
export const VISIBLE_LINES = 5;

export function drawScreen(
  ctx: CanvasRenderingContext2D,
  theme: ThemeColors,
  state: ScreenState,
  prompt: string,
): void {
  ctx.fillStyle = theme.screenBg;
  ctx.fillRect(0, 0, SCREEN_W, SCREEN_H);

ctx.fillStyle = theme.screenChrome;
  ctx.fillRect(0, 0, SCREEN_W, 56);
  ctx.fillStyle = '#ff5f57';
  ctx.beginPath();
  ctx.arc(34, 28, 9, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#febc2e';
  ctx.beginPath();
  ctx.arc(64, 28, 9, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#28c840';
  ctx.beginPath();
  ctx.arc(94, 28, 9, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = theme.screenMuted;
  ctx.font = '18px ui-monospace, "JetBrains Mono", monospace';
  ctx.textAlign = 'center';
  ctx.fillText('shinkeonkim.com', SCREEN_W / 2, 34);
  ctx.textAlign = 'left';

ctx.fillStyle = theme.screenMuted;
  ctx.font = '22px ui-monospace, "JetBrains Mono", monospace';
  ctx.fillText(prompt, 28, 108);

ctx.save();
  ctx.beginPath();
  ctx.rect(0, 130, SCREEN_W, SCREEN_H - 130);
  ctx.clip();

ctx.font = '22px ui-monospace, "JetBrains Mono", monospace';
  const offsetY = -state.scrollOffset;
  state.displayLines.forEach((l, i) => {
    ctx.fillStyle = theme.screenFg;
    ctx.fillText('› ' + l, 28, START_Y + i * LINE_HEIGHT + offsetY);
  });

if (state.currentLineIdx < state.lines.length) {
    const target = state.lines[state.currentLineIdx];
    const visible = target.slice(0, state.currentChar);
    ctx.fillStyle = theme.screenAccent;
    const y = START_Y + state.displayLines.length * LINE_HEIGHT + offsetY;
    ctx.fillText('› ' + visible, 28, y);
    state.cursorBlink = (state.cursorBlink + 1) % 60;
    if (state.cursorBlink < 30) {
      const cursorX = 28 + ctx.measureText('› ' + visible).width + 4;
      ctx.fillRect(cursorX, y - 22, 12, 26);
    }
  }
  ctx.restore();
}

